(window.GIM_TP=window.GIM_TP||{})["Keritot.0"]={"from":0,"a":[[["מתני׳ \u0001שלשים\u0002 ושש כריתות בתורה הבא על האם ועל אשת אב ועל הכלה הבא על הזכור ועל הבהמה ואשה המביאה הבהמה עליה הבא על אשה ובתה ואשת איש הבא על אחותו ועל אחות אביו ועל אחות אמו ועל אחות אשתו ועל אשת אחיו ועל אשת אחי אביו ועל אשת אחי אמו ועל הנדה","והמגדף ועובד עבודת כוכבים והנותן מזרעו למולך ובעל אוב ומחלל שבת וטמא שאכל קדש והבא אל המקדש טמא והאוכל חלב ודם ונותר ופיגול והשוחט ומעלה בחוץ","והאוכל חמץ בפסח והאוכל והעושה מלאכה ביום הכפורים והמפטם את השמן והמפטם את הקטרת והסך את השמן המשחה והפסח והמילה מצות עשה","על אלו חייבין על זדונו כרת ועל שגגתו חטאת ועל לא הודע שלהם אשם תלוי חוץ מן המטמא מקדש וקדשיו מפני שהוא בעולה ויורד דברי רבי מאיר","וחכמים אומרים אף המגדף שנאמר (במדבר טו, כט) תורה אחת יהיה לכם לעושה בשגגה יצא מגדף שאינו עושה מעשה:"],[[0,"מתני'","\u0003כל\u0004 הנך כריתות במזיד בלא התראה אבל אי איכא התראה יש מהן בחנק ויש מהן בסקילה ויש מהן במלקות ובשוגג בחטאת. והאי דנקט ואיירי למיתני ברישא עריות דאם ודאשת אב כו' והדר פסיק ותני ביני וביני הבא על הזכור ועל הבהמה והמביאה את הבהמה עליה והדר מתחיל למיתני אשה ובתה ולא קתני כולהו בהדי הדדי בקמייתא משום דקים לן בסנהדרין (דף נג.) דכל הני דנקט ברישא אם ואשת אב וכלה והבא על הזכור ועל הבהמה דינייהו בסקילה ולהכי תננהו ברישא משום דחמורות משאר מיתות ב\"ד (ולהכי תננהו ברישא):"],[0,"אשה ובתה","ובת בתה ובת בנה בכלל (ובן) [וכן] בתו ובת בתו ובת בנו חמותו ואם חמותו ואם חמיו בכלל זה:"],[1,"מגדף","איכא למאן דאמר (סנהדרין דף נו) מברך את השם ואיכא למ\"ד מזמר ומשורר לעבודת כוכבים:"],[1,"","כרת דנותר מפרש לקמן (כריתות דף ה.) בהאי פירקא ואוכליו עונו ישא כי את קדש ה' חלל ונכרתה ומוקמינן ליה לקמן בנותר:"],[1,"","וכרת דפיגול נמי מפרש לקמן בפירקא (שם) דילף עון עון מנותר דבפיגול כתיב ואם האכל יאכל מבשר זבח שלמיו ביום השלישי לא ירצה המקריב אותו לא יחשב לו פגול יהיה והנפש האוכלת ממנו עונה תשא וכתיב בנותר ואוכליו עונו ישא מה התם כרת בנותר דכתיב ביה עון אף בפגול דכתיב ביה עונה תשא כרת:"],[1,"","שוחט קדשים בחוץ בכרת אפי' לא העלן דכתיב (ויקרא י״ז:ד׳) ואל פתח אהל מועד לא הביאו וגו' דם יחשב לאיש ההוא דם שפך ונכרתה ומעלה נמי בכרת דכתיב (שם) אשר יעלה עולה או זבח ואל פתח אהל מועד לא יביאנו וגו' ואם שגג ושחט והעלה בשוגג חייב שתי חטאות:"],[2,"ופסח ומילה מצות עשה","ובכרת. פסח בכרת דכתיב (במדבר ט) והאיש אשר הוא טהור וגו'. מילה בכרת דכתיב (בראשית יז) וערל זכר אשר לא ימול וגו' ונכרתה. והני פסח ומילה מצות עשה [ואין קרבן על שגגתן] אבל אינך כולהו מצות לא תעשה נינהו וחייבים בקרבן דאין קרבן אלא על לאו כדמפרש לקמן וכגון לאוי דעריות דמפורשין הן. ובמגדף מצינו לאו (שמות כב) אלהים לא תקלל וכרת נמי דכתיב (במדבר טו) והנפש אשר תעשה ביד רמה וגו' את ה' הוא מגדף ונכרתה. ובכל הני עריות דלעיל כתיב כרת דכולל להו בסיפא ונכרתו הנפשות העושות ולאו נמי כתיב בהו בעריות כולהו (ויקרא יח) ערות אמך לא תגלה ובכולהו נמי לא תגלה כתיב. ובנדה נמי לאו (שם) ואל אשה בנדת טומאתה לא תקרב וכרת דנדה כולל עם אחריני דלבתר עריות כולהו כתיב ונכרתו הנפשות העושות. והאי דלא כתיב כרת לא באשת אחי אמו ולא באם אם חמותו דשניות הן מדברי סופרים דלא כתיבי באורייתא. והעובד עבודת כוכבים נמי לאו וכרת לאו דכתיב (שמות לד) לא תשתחוה לאל אחר וכרת דכתיב (במדבר טו) כי דבר ה' בזה ואת מצותו הפר הכרת תכרת ובעבודת כוכבים מיירי דבזה דבר ה' כדאמר מר בסנהדרין (דף צט.) אנכי ולא יהיה לך מפי הגבורה שמענום ולא יהיה לך בעבודת כוכבים מדבר. לאו דמולך (ויקרא יח) ומזרעך לא תתן להעביר למולך א\"נ לא ימצא בך מעביר בנו ובתו באש כרת נמי אית בהו דכתיב (ויקרא כ) ואל בני ישראל תאמר איש איש מבני ישראל וגו' אשר יתן מזרעו למולך מות יומת וכתיב בתריה ושמתי אני את פני באיש ההוא והכרתי אותו וגו'. ובעל אוב נמי אית ביה אזהרה דכתיב (שם יט) אל תפנו אל האובות וגו' וכרת נמי דכתיב (שם כ) והנפש אשר תפנה אל האובות ונכרתה ובגמרא מפרש מאי טעמא לא תני הכא ידעוני. והמחלל את השבת אזהרה אית ביה דכתיב (שמות כ) לא תעשה כל מלאכה וכרת נמי דכתיב (שם לא) כי כל העושה בה מלאכה ונכרתה וגו'. וטמא שאכל את הקדש בלאו ולא יאכל עד אשר יטהר ובכרת דכתיב (ויקרא כב) אמור אליהם לדורותיכם כל איש אשר יקרב וגו' וטומאתו עליו ונכרתה. הבא אל המקדש טמא לאו דכתיב (שם יב) ואל המקדש לא תבא ולא יטמאו את מחניהם כרת כי את משכן ה' טמא ונכרתה. אוכל חלב ודם בלאו דכתיב (ויקרא ג) כל חלב וכל דם לא תאכלו כרת בחלב (שם ז) כי כל אוכל חלב ונכרתה כרת בדם (שם יז) כי נפש כל בשר דמו בנפשו הוא וגו' כל אוכליו יכרת. אזהרה דנותר (שמות כט) ושרפת את הנותר באש לא יאכל כרת כדאמרן ואוכליו עונו ישא כי את קדש ה' חלל ונכרתה. אזהרה בפגול נפקא לן מהאי קרא ואם יותר מבשר זבח שלמיו לא יאכל כי קדש הם כדגמרינן בפסחים בפ\"ב (דף כד.) לא יאכל כי קדש הם כל שבקדש פסול בא הכתוב ליתן לא תעשה על אכילתו וכרת כדאמרן יליף עון עון מנותר. שוחט בחוץ מפרש בהאי פירקא (דף ג:) בלאו למאן דגמיר בגזירה שוה הבאה [הבאה דכתיב] בהעלאה ואל פתח אהל מועד לא יביאנו ונאמר כאן בשחיטה הבאה ואל פתח אהל מועד לא הביאו וגו' מה להלן לא ענש אא\"כ הזהיר אף כאן נמי לא ענש אא\"כ הזהיר ולמאן דמייתי לה בהיקשא אמר קרא שם תעלה עולותיך ושם תעשה מה העלאה לא ענש אא\"כ הזהיר אף שחיטה נמי. מעלה בחוץ בלאו השמר לך פן תעלה וגו' (דברים יב) וכל מקום שנאמר פן ואל אינו אלא לא תעשה וכרת כדאמרן לעיל אשר יעלה עולה או זבח וגו' ונכרתה. אוכל חמץ בלאו כל מחמצת לא תאכלו (שמות יב) כרת כל אוכל חמץ ונכרתה (שם). והאוכל ביוה\"כ בלאו מפרש ביומא (דף פא.) כל הנפש אשר לא תעונה וגמר עינוי עינוי מהתם על דבר אשר עינה את אשת רעהו (דברים כב) מה התם לא ענש אא\"כ הזהיר ה\"נ לא ענש אא\"כ הזהיר וכרת נמי אית ביה באוכל דכתיב ביה ונכרתה באוכל ביוה\"כ (ויקרא כג) כל הנפש אשר לא תעונה ונכרתה והאי לא תעונה בעינוי אכילה קמיירי דגמר (יומא עד:) עינוי עינוי מהתם דכתיב (דברים ח) ויענך וירעיבך מה להלן עינוי רעבון אף כאן עינוי רעבון. העושה מלאכה ביוה\"כ אית ביה אזהרה וכל מלאכה לא תעשו בעצם היום הזה (ויקרא כג) כרת דכתיב (שם) והאבדתי וזהו כרת. והמפטם את השמן לאו ובמתכנתו לא תעשו כמוהו כרת אשר ירקח כמוהו ונכרתה וגו' (שמות ל). והמפטם את הקטרת לצרכו להריח. מפטם את השמן [כעין שעשה משה במדבר דכתיב] ואתה קח לך בשמים ראש (שם). מפטם את הקטרת [מערב י\"א סממני הקטרת כמו דכתיב] קח לך סמים נטף ושחלת וחלבנה. הסך שמן המשחה נמי לאו על בשר אדם לא ייסך (שם) כרת אשר יתן ממנו על זר ונכרת מעמיו (שם) מאותו שעשה משה לשמן המשחה. מפטם את הקטרת אזהרה במתכנתה לא תעשו לכם (שם) כרת אשר יעשה כמוה להריח בה ונכרת (שם) אבל המריח בקטרת של בית המקדש לא אזהרה ולא כרת דריח אין בו משום מעילה ולא דמי לסך שמן המשחה דהתם אית ביה מעשה מש\"ה אית ביה לאו וכרת:"],[2,"פסח ומילה מצות עשה","פסח דכתיב (דברים ט״ז:ב׳) וזבחת פסח ומילה (ויקרא י״ב:ג׳) וביום השמיני ימול וגו' וכרת בהו כדאמרן. ובהני אית בהו חייבי מיתות ב\"ד כגון העובד עבודת כוכבים והמחלל את השבת ואפ\"ה חייבי כריתות הן במזיד בלא התראה ואי אתרו בהן יש מהן בחנק ויש מהן בסקילה כדאמרן ברישא ואי לא אתרו בהו מידי מיתת ב\"ד יצאו מידי כרת לא יצאו וכרת הוא שמת בלא בנים:"],[3,"על שגגתו חטאת","דמפיק ליה מעבודת כוכבים דכתיב בה (במדבר ט״ו:כ״ב) וכי תשגו ולא תעשו את כל המצות האלה וגו' ואמר מר (הוריות דף ח.) שקולה עבודת כוכבים כנגד כל התורה דהא כתיב בה מצות וכתיב בה קרבן (במדבר ט״ו:כ״ז) והקריבה עז בת שנתה וגמרינן מה עבודת כוכבים שחייבין על זדונה כרת חייבין על שגגתה חטאת אף כל שחייבין על זדונו כרת חייבין על שגגתו חטאת כגון הני כריתות. שוגג דעריות כסבור שהיא אשתו והבא על הזכר ועל הבהמה בשוגג כסבור לבא על אשתו שלא כדרכה ובא על הזכר או על הבהמה ואחר כך נודע לו דזכר הוא או בהמה היא מביא חטאת:"],[3,"ועל לא הודע שלהן אשם תלוי","דלא אתיידע אי בא על אשתו שלא כדרכה או זכר או בהמה והוא הדין לאחריתי. והאשה המביאה בהמה עליה נמי דסבורה להביא אדם והביאה בהמה. ונדה דסבור טהורה היא. מגדף כסבור מברך הוא שם בן שתי אותיות וברך שם בן ד' אותיות דאינו חייב אלא על שם של ד' אותיות כדאמרינן בפ\"ד מיתות (סנהדרין נו.). עבודת כוכבים כסבור זבוח וקיטור אסרה תורה ולא השתחואה וניסוך דד' אלה עבודות הן. מולך כסבור להעביר אדם אחר והעביר את בנו. בעל אוב נתכוין לכשוף אחר. שבת כסבור חול הוא. קדש כסבור בשר חולין הוא. מקדש כסבור בית אחר הוא. חלב כסבור שומן. ודם כסבור טחול ל\"א דם כסבור שדם חגבים או דם דגים הוא לשון מורי. נותר ופגול כסבור כשר הוא. שוחט בחוץ כסבור בהמת חולין היא. מעלה לאחר איסור הבמות הקריב בבמה וכסבור במות אלו של צבור מותרות ומוקים לקרא בבמת יחיד. פסח ויום כפור כסבור ימות החול הן. שמן וקטרת נתכוין לסממנין אחרים ונמצאו שהן הסממנין הכתובין. אבל אומר מותר לגמרי דעוקר כל הגוף לאו שוגג הוא אלא אנוס הוא ופטור:"],[3,"לא הודע","אשתו ואחותו במטה וכסבור לבוא על אשתו ולא ידע על איזו מהן בא:"],[3,"שהוא בעולה ויורד","ואין שם אשם תלוי אלא בספק קבוע כדאמרינן בפרק בתרא (לקמן כריתות כה.) אין אשם בא אלא על דבר שזדונו כרת ושגגתו חטאת קבועה:"],[4,"אף המגדף","מפרש בגמ' מאי קאמר:"]],[]],[["\u0001גמ׳\u0002 מניינא למה לי א\"ר יוחנן שאם עשאן כולן בהעלם אחת חייב על כל אחת ואחת","ותו הא דתנן אבות מלאכות מ' חסר אחת מניינא למה לי שאם עשאן כולן בהעלם אחת חייב על כל אחת ואחת","תו הא דתנן ד' מחוסרי כפרה מניינא למה לי","לאפוקי מדר' אליעזר בן יעקב דאמר ה' הוי דתניא ר' אליעזר בן יעקב אומר גר מחוסר כפרה עד שיזרק דם עליו אהכי תנא ד'","תו הא דתנן ד' מביאין על הזדון כשגגה מניינא למה לי","לאפוקי מדרבי שמעון דתניא רבי שמעון אומר שבועת הפקדון לא ניתן זדונה לכפרה אהכי תנא ד'","תו הא דתנן ה' מביאין קרבן אחד על עבירות הרבה מניינא למה לי","משום דקא בעי למיתנא סיפא נזיר אם נטמא טומאות הרבה ומשכחת לה כגון דאיטמי בשביעי וחזר ונטמא בשביעי ומני ר' יוסי בר' יהודה היא דאמר נזירות דטהרה מן שביעי הוא דחייל עליה","דאי תאמר רבי היא כיון דנזירות דטהרה עד שמיני לא חיילא עליה היכי משכחת לה","אי דנטמא בז' וחזר ונטמא בז' כולה חדא טומאה אריכתא היא","ואי דנטמא בח' וחזר ונטמא בח' כיון דיצא בשעה הראויה להביא בה קרבן חייב על כל אחת ואחת אלא ש\"מ רבי יוסי בר' יהודה היא","מאי רבי ומאי ר' יוסי בר' יהודה דתניא (במדבר ו, יא) וקדש את ראשו ביום ההוא ביום הבאת קרבנותיו דברי רבי ר' יוסי בר' יהודה אומר ביום תגלחתו","תו הא דתנן ה' מביאין קרבן עולה ויורד מניינא למה לי","משום דקתני סיפא נשיא כיוצא בהן ה' לאפוקי מדר\"א דאמר נשיא מביא שעיר","תו הא דתנן ד' אבות נזיקין מנינא למה לי","לאפוקי מדרבי אושעיא דאמר י\"ג אבות נזיקין הן ולר' אושעיא מניינא למה לי לאפוקי מדרבי חייא דאמר כ\"ד אבות נזיקין ולר' חייא מנינא למה לי לאפוקי מסור ומפגל","אמר מר שאם עשאן כולן בהעלם אחת חייב על כל אחת ואחת","בשלמא פטור לגמרי לא מצית אמרת דכתיב (ויקרא יח, כט) כי כל אשר יעשה מכל התועבות האלה ונכרתו אלא אימא עבר חדא נתחייב חדא עבר כולהו בהעלם אחת אינו חייב אלא אחת","אמר רבי יוחנן לכך יצאה כרת באחותו לחלק","מתקיף לה רב ביבי בר אביי אימא אחותו דפרט קרא ניחייב חדא עלה וכולן כיון דבהעלם אחת לא ניחייב אלא אחת","ולרב ביבי בר אביי מי לית ליה הדא דתניא כל דבר שהיה בכלל ויצא מן הכלל ללמד לא ללמד על עצמו יצא אלא ללמד על הכלל כולו יצא","כיצד (ויקרא ז, כ) והנפש אשר תאכל בשר וגו' והלא שלמים בכלל הקדשים היו למה יצאו","להקיש אליהן מה שלמים שהן קדשי מזבח וחייבין עליהן אף כל שהן קדשי מזבח חייבין עליהן יצאו קדשי בדק הבית","אמר ליה רב ביבי בר מינה לאו מי אמרת התם יצאו קדשי בדק הבית","הכא נמי מה אחותו מיוחדת שהיא ערוה ואין לה היתר בחיי אוסרה אף כל שאין לה היתר בחיי אוסרה יצאה אשת איש שיש לה היתר בחיי בעלה","א\"ר יונה ואיתימא רב הונא בריה דרב יהושע אמר קרא כי כל אשר יעשה מכל התועבות וגו' הואיל וכך הקיש הוא הוקשו כל העריות כולן לאחותו מה אחותו חייבין עליה בפני עצמה אף כל חייבין עליה בפני עצמה","ולרבי יצחק דאמר חייבי כריתות בכלל היו ולמה יצאה כרת באחותו לדונה בכרת ולא במלקות","לחלק מנא ליה נפקא ליה (ויקרא יח, יט) מואל אשה בנדת טומאתה לא תקרב לחלק על כל אשה ואשה","ורבנן נמי תיפוק להו מואל אשה בנדת טומאתה אין ה\"נ אלא כרת דאחותו למאי אתא מיבעי ליה לחלק על אחותו ועל אחות אביו ועל אחות אמו","הני למה להו לחלק הרי שמות מוחלקין והרי גופים מוחלקים אלא אימא לחלק על אחותו שהיא אחות אביו ושהיא אחות אמו","ורבי יצחק הא מילתא מנ\"ל נפקא ליה מן סיפא דקרא דכתיב (ויקרא כ, יז) ערות אחותו גלה","ורבנן אחותו דסיפא דקרא מאי עבדי ליה מיבעי ליה"],[[0,"גמ' מניינא","שלשים ושש:"],[2,"מחוסרי כפרה","דאינן אוכלים בקדשים עד שיביאו כפרה ובפ\"ב (לקמן כריתות ח:) מפרש להו:"],[3,"עד שיזרוק הדם","כדמפרש בפ\"ב (שם ט.) ככם כגר יהיה מה אבותיכם לא נכנסו לברית אלא במילה וטבילה והרצאת דמים כו':"],[3,"אהכי תנא ארבעה","וכל היכא דתני חושבנא דוקא קתני ולא תימא תנא ושייר:"],[4,"ארבעה מביאין על הזדון","מפרש בפ' ב' (שם):"],[7,"ר' יוסי בר' יהודה","דאמר לקמן (שם:):"],[7,"נזירות דטהרה","נזיר שנטמא וספר ז' לחזור ולהתחיל ולמנות נזירות טהרה מז' חיילא ומשכחת לה דמביא קרבן א' על טומאות הרבה כגון שנטמא בשביעי וחזר ונטמא בז' דכיון דבז' טהור הוה הוו להו ג' טומאות וקרבן אחת הוא ולא על כל טומאה וטומאה משום דבשתי טומאות הראשונות לא יצתה שעה ראויה להביא קרבן דאין הבאת קרבן אלא בשמיני הלכך אינו מביא אלא על האחרונה. להכי נקט תרי זימני נטמא בז' דמהדר אג' טומאות משום דתנא במתניתין טומאות הרבה:"],[9,"חדא טומאה אריכתא","דלא בא לכלל טהרה:"],[10,"אלא שמע מינה כו'","ולהכי תנא מניינא לאשמועינן דדוקא הוא ולא תימא רבי היא וסמי מכאן נזיר:"],[11,"וקדש את ראשו","לנזירות טהרה שניה:"],[12,"ה' מביאין קרבן עולה ויורד","כלומר על חמש עבירות מביאין קרבן עולה ויורד בפ\"ב (שם):"],[12,"מניינא למה לי","ליתני אלו:"],[13,"משום דקתני סיפא","בהוריות בפ\"ב (דף ח:) ואיירי בהנך ה' וקתני הכי אין ב\"ד חייבין על שמיעת הקול ועל בטוי שפתים כו' ונשיא כיוצא בהן נמי דפטור אכל הנך משום [דלא] שייך בהו קרבן עולה ויורד ועניות בנשיא לא שכיחא ר\"א אומר נשיא מביא שעיר כדינו בכל המצות שבתורה ואמרי' בגמ' לא אמר ר' אליעזר אלא בטומאת מקדש וקדשיו הואיל ונאמר בהן כרת כבקבועה להכי תנא הכא ה' לאשמועינן דדוקא נקט דכל המביא על ה' עבירות הללו אינו מביא קבועה אלא עולה ויורד ולא תימא סמי מכאן טומאת מקדש וקדשיו לאוקומה כר' אליעזר דאמר מביא נשיא עליה קרבן קבועה אלא אינו מביא קבועה אלא אי ר' יוסי הגלילי דפטר ליה לגמרי אי ר' עקיבא ור' שמעון דמחייבו ליה בעולה ויורד דהיינו כשבה או שעירה או תורים ובני יונה:"],[15,"","שלש עשרה ועשרים וד' מפרש התם בפרק ד' אבות נזיקין (ב\"ק ד:) ולשלם ממיטב כדמפרש התם:"],[15,"מסור","מלשין:"],[15,"ומפגל","כהן שפגל בקרבנו של ישראל לאוכלו חוץ לזמנו דחייב אינו משלם ממיטב דהאי היזקא דיבורא בעלמא היא והיזק שאינו ניכר נינהו:"],[18,"אחותו","בכלל עריות היתה דכתיב בהו (ויקרא יח) ונכרתו הנפשות העושות והדר כתיב בקדושים תהיו איש אשר יקח את אחותו וגו' ונכרתו לעיני בני עמם:"],[19,"אחותו דפרט בה קרא","כי עביד לה בהדי אינך ליחייב עלה דידה חדא ואאידך כולהו חדא. ואי תיבעי לך אשכחן אחותו דיצאת לחלק אבל שאר עריות למה יצאו תריץ לאשמועינן דאיתנהו במיתת ב\"ד עריות שיצאו דכתי' בהו (שם) מות יומת [יש מהן בסקילה ויש מהן בחנק] ויש מהן דכתיב בהו שריפה והני דאיתנהו בכרת מפרש להו ביבמות (דף נד.) דפרט בה קרא ואחותו דבעי הכא לא מפרש:"],[21,"בכלל כל הקדשים","אמור אליהם לדורותיכם כל איש אשר יקרב מכל זרעכם אל הקדשים (ויקרא כב) והאי יקרב ליכא למימר דנגיעה היא ממש דבנגיעה ליכא נטילת נשמה כדגרסינן במסכת מכות (דף יד:) מבכל קדש לא תגע והיינו אכילה ולא נגיעה והאי יקרב נמי מפרש במסכת מעילה (דף י:) דאינו נגיעה אלא דבר המוכשר ליקרב א\"ר אלעזר וכי יש נוגע שהוא חייב אם כן למה נאמר אשר יקרב לומר שאין חייבין עליו עד שיוכשר ליקרב כלומר אינו חייב על אכילתו משום טומאה עד שיוכשר ליקרב:"],[22,"יצאו קדשי בדק הבית","שאינו ענוש כרת האוכלן בטומאת הגוף והכא נמי ליגמר כולהו מאחותו:"],[24,"אשת איש שיש לה היתר בחיי אוסרה","שמתגרשת בגט הלכך לא גמרי לה מאחותו ולא משכחת בה בחטאת בהעלם:"],[25,"בפני עצמה","אפי' עשאה עם האחרים:"],[26,"לדונו בכרת ולא במלקות","והיה מלמד על הכלל כולו דלית ליה חייבי כריתות שלקו נפטרו מידי כריתתן באלו הן הלוקין (מכות כג.):"],[27,"ואל אשה","הוה ליה למיכתב ולנדה לא תקרב:"],[28,"ורבנן","דאית להו נפטרו מידי כריתתן ומפקי כרת דאחותו לחלק:"],[28,"תיפוק להו מואל אשה","לחלק:"],[28,"על אחותו ועל אחות אביו ועל אחות אמו","דסד\"א הואיל ואיסור חד דאחוה אכולהו לא נחייב אלא חדא:"],[29,"הרי שמות וגופים מוחלקין","מואל אשה נפקא מקראות מוחלקין דמתלתא קראי נפקי אחותו ואחות אביו ואחות אמו:"],[29,"אחותו שהיא אחות אביו ואחות אמו","מפרש לקמן בפ' אמרו לו (כריתות דף טו.) ברשיעא בר רשיעא (כותי) הבא על אמו והוליד שתי בנות ובא על אחת מהן והוליד בן ובא הבן על אחותו שהיא אחות אביו ואחות אמו ועלה איצטריך קרא לחלק משום דגוף אחד הוא:"],[31,"מאחותו דסיפיה","דקרא דכרת דלעיל נמי עלה קאי:"]],[]],[["לאחותו שהיא בת אביו ובת אמו לומר שאין עונשין מן הדין","ור' יצחק סבר עונשין מן הדין ואיבעית אימא יליף עונש מאזהרה","א\"ר אלעזר א\"ר הושעיא כל מקום שאתה מוצא ב' לאוין וכרת אחד חלק חטאת ביניהן ומאי היא מפטם וסך דכתיב (שמות ל, לב) על בשר אדם לא ייסך ובמתכונתו וגו' כרת אחד דכתיב (שמות ל, לג) אשר ירקח כמוהו ואשר יתן ממנו על זר ונכרת מעמיו","וכי מאחר דלאוין מוחלקים כרת דאחותו דכתב רחמנא ל\"ל","לר\"י כדאית ליה לרבנן מיבעיא להו לומר שאין עונשין מן הדין לר' יצחק מפיק ליה לחייב על אחותו שהיא אחות אביו ושהיא אחות אמו","ורבנן דנפקא להון מן אחותו דרישא ור' יצחק סבר אחותו דרישא אורחיה דקרא היא ומפיק לחלק מאחותו דסיפיה דקרא לחלק על אחותו שהיא אחות אביו ושהיא אחות אמו","אמר רנב\"י אף אנן נמי תנינא המפטם את השמן המפטם את הקטרת והסך בשמן המשחה","ל\"ל דתניא המפטם את הקטרת במיצעא לאו הא קמ\"ל מה קטרת לאו בפני עצמו וחייבים עליה כרת בפני עצמו אף מפטם שמן וסך נמי כיון דלאו בפני עצמו חייבים עליו בפני עצמה","וכ\"ת דקא בעי למיתנא פיטומין בהדי הדדי ניתנהו איפוך המפטם את הקטרת והמפטם את השמן והסך שמן המשחה אמאי פלגיה לשמן לאו הא קמשמע לן דיש חילוק חטאות ביניהן ש\"מ:","הבא על הזכור: תנא במאי קא חשיב","אי בגברי דל האשה הנרבעת ובצרא לה חדא אי בנשי קחשיב דל מינהון הבא על הזכור ועל הבהמה ובצרי להו תרתי","א\"ר יוחנן לעולם תנא גברי קחשיב ותני הכי הבא על הזכור והביא זכור עליו ור' ישמעאל היא דאמר חייב שתים","והא מדקתני מגדף בסיפיה ומוקמינן לה כר\"ע רישא נמי ר' עקיבא","וכ\"ת ר\"ע היא וברישא סבר לה כר' ישמעאל והאמר ר' אבהו הבא על הזכור והביא זכור עליו לר' ישמעאל דמפיק ליה מתרתי קראי (ויקרא יח, כב) מואת זכר לא תשכב (דברים כג, יח) ומולא יהיה קדש מבני ישראל חייב שתים","לר\"ע אינו חייב אלא אחת דמחד קרא נפיק ליה את זכר לא תשכב קרי ביה לא תשכיב","אלא רישא ר' ישמעאל ובמגדף סבר לה כר\"ע אי הכי ניתני נמי הבא על הבהמה והביא בהמה עליו","הא אמר אביי הבא על הבהמה והביא בהמה עליו אף לר' ישמעאל אינו חייב אלא אחת דכי כתיב קרא בגברי כתיב","ר\"א משמיה דרב אמר תנא תני שלשים ושלש חטאות ותני שלש כריתות לסיומינהו בכריתות","דקתני סיפא פסח ומילה במצות עשה פסח ומילה אמאי קתני להו","ואיתימא לאיתויי קרבן עליהון מי מייתי והתני' הוקשה כל התורה כולה לעבודת כוכבים דכתיב (במדבר טו, כט) תורה אחת יהיה לכם לעושה בשגגה והנפש אשר תעשה ביד רמה","מה עבודת כוכבים שב ואל תעשה אף כל שב ואל תעשה","אלא לאו ש\"מ תנא שלשים ושלש חטאות מאן דעבדי בשוגג והדר תנא שלש כריתות לסיומינהו לכריתות ש\"מ:","המחלל את השבת: אמרי שבת מ' חסר אחת הוויין א\"ר יוחנן תנא שגגת שבת וזדון מלאכות דלא מחייב אלא חדא","דתניא הנה שהיא אחת שגגת שבת וזדון מלאכות","וניתני זדון שבת ושגגת מלאכות דמחייב מ' חסר אחת","דתניא (ויקרא ד, ב) ועשה מאחת מהנה פעמים שחייב אחת על כולן ופעמים שחייב על כל אחת ואחת דתניא אחת שהיא הנה זדון שבת ושגגת מלאכות","תנא שגגת שבת וזדון מלאכות עדיפא ליה דמחטאת מיהא לא מיפטר","וכן אתה מוצא גבי עבודת כוכבים דקתני שגגת עבודת כוכבים וזדון עבודות","שגגת עבודת כוכבים היכי דמי אילימא דעמד בבית עבודת כוכבים וסבר בית הכנסת היא והשתחוה הרי לבו לשמים","ואלא דחזא אנדרטא וסגיד לה אי דקבליה עליה באלוה בר סקילה הוא ואי דלא קבליה באלוה לאו מידי הוא","אלא מאהבה ומיראה","הניחא לאביי דאמר חייב אלא לרבא דאמר פטור מאי איכא למימר"],[[0,"שאין עונשין מן הדין","דלא אמרינן מה אחותו מן האב גרידא או מן האם גרידתא ענש עליה מן האב ומן האם לא כ\"ש:"],[1,"אי בעית אימא","לר\"י אין עונשין מן הדין ועונש באחותו מן האב ומן האם לר' יצחק נפקא ליה דיליף עונש מאזהרה כשם שהזהיר עליה כשאר עריות כך ענש עליה ואזהרה דידה מפרש במסכת מכות (דף יד.) דאמר קרא ערות בת אביך או בת אמך אין לי אלא בת אביך שלא בת אמך ובת אמך שלא בת אביך בת אביך ואמך מנין ת\"ל אחותך היא לא תגלה ערותה וכשם שהזהיר עליה כך ענש עליה:"],[2,"א\"ר אלעזר חלוק חטאות","שאם עשאן שניהם בהעלם אחת חייב שתים:"],[3,"כרת באחותו","דפרט בה קרא למאי אתא:"],[3,"","\u0003הגה\"ה \u0004כיון דלאוין מחלקין לא מיבעי ליה לחלק על אחותו שהיא אחות אביו ואחות אמו שהרי יש בה ג' לאוין:"],[3,"ה\"ג לר' יצחק כדאית ליה לרבנן מיבעי להו לאחותו בת אביו ואמו לומר שאין עונשין מן הדין","וכוליה קרא משום אחותו דסיפא אתא ובשביל חדוש אחד דרך לשנות פרשה שנאמרה:"],[3,"","לרבי יצחק מיבעי ליה כו' עד סיפא ל\"ג לה ופירוש משובש הוא מתלמידים טועין \u0003עד כאן הגה\"ה\u0004:"],[7,"וחייבין עליהן בפני עצמה","על כל אחד כי עביד להו בהעלם אחת:"],[9,"תנא מאי קחשיב","מכדי אמרן לעיל מניינא להכי אתא שאם עשאן כולן כו' היכי משכחת לה לשלשים וארבע חטאות בחד:"],[10,"גברא","הוא דרבע לבהמה:"],[10,"איתתא","כגון שנבעלה לבנה ולבן בעלה ולחמיה ולחתנה ולבהמה וכן כולם:"],[10,"הבא על הזכור ועל הבהמה","דאין כאן צד אשה. פסח ומילה לא מצי למיפרך דלאו משום חטאות נקט להו דהא לאו בני קרבן נינהו דאין קרבן אלא על לאו כדמפרש לקמן:"],[11,"ור' ישמעאל היא","בפרק ד' מיתות:"],[12,"והא מדקתני","בכלל כריתות מגדף לאשמועינן דמביא קרבן ומוקמי לה לקמן כר״ע דאמר בסוף פירקין (כריתות דף ז.) מגדף מביא קרבן רישא נמי ר״ע:"],[13,"דאמר רבי אבהו","בפרק ד' מיתות (סנהדרין נד:) לא יהיה קדש אזהרה לנשכב ועונש מגזירה שוה דכתיב וגם קדש היה בארץ. ואי קשיא גבי עריות היכן מצינו אזהרה לאשה כמו לזכר דאשכחן בכולהו לאו פריק הכי שאני התם כיון דאיהי נמי מיתהנייא משכיבה קרינא בה הנפשות העושות אבל משכב זכר דלא מתהני בעי אזהרה. ובגברי כתיב דאין זכור לבהמה ולא מיקרי קדישות:"],[17,"ר\"א אמר","בגברי חשיב ודקא קשיא לך דאשה נרבעת תנא ל\"ג חטאות חשיב בחד גברא בהעלם אחד ותנא אשה נרבעת ופסח ומילה לסיומינהו לכריתות:"],[19,"והנפש אשר תעשה ביד רמה","בעבודת כוכבים הכתוב מדבר:"],[20,"מה עבודת כוכבים שב ואל תעשה","וחייבין על זדונו כרת ועל שגגתו חטאת כדכתיב לעיל מיניה עז בת שנתה לחטאת:"],[20,"אף כל שב ואל תעשה","שזדונו כרת ושגגתו חטאת:"],[22,"מ' חסר אחת הן","ליתני ע\"ה כריתות:"],[22,"תנא שגגת שבת","דסבור שהיום חול:"],[22,"וזדון מלאכות","שיודע שמלאכות הללו אסורות בשבת דא\"נ עביד לכולהו אבות מלאכות אינו חייב אלא אחת דליכא אלא חדא שגגה ומתניתין בתר חיוב חטאת נקטינהו לכריתות:"],[23,"הנה שהיא אחת","דכתיב ועשה מאחת מהנה וה\"ל למיכתב אחת מהנה מאי מאחת משמע פעמים שחייב מעבירה אחת הנה כלומר כמה חטאות ומהנה מעבירות הרבה חטאת אחת:"],[23,"שגגת שבת וזדון מלאכות","ועשה מלאכות הרבה אינו חייב אלא אחת:"],[24,"זדון שבת","דיודע שהיום שבת:"],[24,"ושגגת מלאכות","דאינו יודע שמלאכות הללו אסורות אבל יודע מצות שבת בדבר אחד כגון דידע שאסור לצאת חוץ לתחום:"],[25,"אחת שהיא הנה","על מצוה אחת כגון שבת חייב כמה חטאות:"],[26,"שגגת שבת וזדון מלאכות עדיפא ליה","למיתני לאשמעינן חדוש דאע\"ג דהזיד במלאכות לא מפטר מחד חטאת: לישנא אחרינא שגגת שבת וזדון מלאכות עדיפא ליה דמילתא פסיקא ליה דמכי שגג אשבת לא מיפטר מיהא מחד חיובא חטאת דא\"נ שגג אף במלאכות מחייב חדא אבל שגגת מלאכות דליחייב בכל חדא וחדא לא פסיקא ליה דזימנין דמיפטר מהך חיובא כגון שגג אף בשבת דהעלם זה וזה בידו ואמרינן במסכת שבת (דף ע:) דלא מחייב אלא חדא והכי מסתברא דבשגגת שבת קמיירי מדחשיב גבי עבודת כוכבים במתני' חדא ותו לא מכלל דבשגגת עבודת כוכבים וזדון עבודות קמיירי דאי בשגגת עבודה איכא ד' חטאות בד' עבודות זיבח וקיטור וניסך והשתחוה:"],[28,"הרי לבו לשמים","דאי נמי בבית עבודת כוכבים השתחוה לשמים לאו איסורא עבד וליכא חטאת:"],[29,"ה\"ג אי דלא קבליה עליה באלוה לאו כלום הוא","דכיון דלא נעשה לשם עבודת כוכבים השתחואה דידיה לאו כלום היא:"],[30,"אלא","השתחוה לעבודת כוכבים מאהבת אדם ומיראת אדם דסבר מותר לעבוד עבודת כוכבים מאהבה ומיראה וזדון מלאכות קרי משמתכוין לעבוד:"]],[]],[["אלא באומר מותר דעד כאן לא קבעי מיניה רבא מרב נחמן אלא חדא מחייב אי תרתי מחייב אבל מיפטר לגמרי לא בעא מיניה","רב פפא אמר משכחת לה בתינוק שנשבה לבין העובדי כוכבים דידע דאסירא עבודת כוכבים והני עבודת כוכבים לא ידע דאסירן","ואי בעית אימא אפי' תימא בגדול כגון דקא טעי בהדין קרא (שמות כ, כ) לא תעשון אתי אלהי כסף ואלהי זהב וגו' סבר כי אסירא השתחואה לעבודה זרה דכסף וזהב אבל דמיני אחריני שריא דהיינו שגגת עבודת כוכבים וזדון עבודות","רב אחא בריה דרב איקא משמיה דרב ביבי אמר תנא שם שבת ושם עבודת כוכבים קתני ממאי מדקתני הבא על אשה ובתה ועל אשת איש והא יש בתו מאנוסתו דלא קתני לה","אמרי דכתיבן קתני דלא כתיבן לא קתני","והאיכא בת אשתו ובת בתה ובת בנה דכתיבא ולא קתני אלא שם אשה ובתה קתני ה\"נ שם שבת ושם עבודת כוכבים קתני","רב אחא בריה דרב איקא רמי דיליה אדיליה מי אמר רב ביבי בר אביי הכי שם שבת קתני ושם עבודת כוכבים קתני והאיתמר המעלה אברי פנים בחוץ חייב אברי חוץ בחוץ חייב","וקשיא ליה לרב ביבי בר אביי אי הכי הא דתנן שלשים ושש כריתות בתורה תלתין ושבע נינהו דאיכא המעלה והמעלה מאי קשיא ליה נישני שם העלאה קתני","מי דמי שבת ועבודת כוכבים תנא יתהון אבינכיהון גבי כריתות דאיריא משני שם שבת קתני שם עבודת כוכבים קתני גבי העלאה מי תנא יתהון בינכיהון דשני הכי","בעא מיניה ר' ירמיה מר' זירא ב' כריתות ולאו אחד מהו א\"ל שוחט והעלה קאמרת הני שני לאוין נינהו","אי למאן דגמר מגז\"ש נאמר כאן הבאה ונאמר להלן הבאה","מה להלן לא ענש אלא א\"כ הזהיר אף כאן לא ענש אא\"כ הזהיר","למאן דמייתי לה בהיקש אמר קרא (דברים יב, יד) שם תעלה ושם תעשה מקיש שחיטה להעלאה מה העלאה לא ענש אא\"כ הזהיר אף שחיטה לא ענש אא\"כ הזהיר","דלמא ב' מיתות ולאו אחד קאמרת מה היא אוב וידעוני","א\"ל דהא פלוגתא דר' יוחנן ור\"ל דתנו גבי סנהדרין בעל אוב וידעוני וקשיא לן ומ\"ש גבי סקילות תני ידעוני וגבי כריתות לא תני ידעוני","א\"ר יוחנן הואיל ושניהם בלאו אחד נאמרו ונימא ידעוני ולא נימא בעל אוב קסבר הואיל ופתח הכתוב בבעל אוב","ור\"ל אמר הואיל ואין בו מעשה ור\"ל מאי טעמא לא אמר כר' יוחנן","א\"ר פפא דהא חלוקין הן במיתות ור' יוחנן אמר לך חלוקה דלאו הוי חלוקה חלוקה דמיתה לא הויא חלוקה","ור' יוחנן מ\"ט לא אמר כר\"ל קסבר מאן תנא כריתות ר\"ע היא דאמר לא בעינן מעשה","ור\"ל נהי דר\"ע לא בעי מעשה רבה מעשה זוטא בעי","בעל אוב מאי מעשה אית ביה הקשת זרועותיו הוי מעשה מגדף מאי מעשה אית ביה עקימת שפתיו הוי מעשה","קס\"ד הקשת זרועותיו הוי מעשה זוטא אפי' לרבנן מיתיבי בעבודת כוכבים אינו חייב אלא על דבר שיש בו מעשה כגון שזיבח וקיטר וניסך והשתחוה וקשיא לן השתחואה לית בה מעשה","ואמר ר\"ל הא מני ר\"ע היא דאמר לא בעינן מעשה ור' יוחנן אמר אפי' תימא רבנן כפיפת קומתו הוי מעשה מכלל דסבירא ליה לר\"ל אליבא דרבנן כפיפת קומתו לרבנן לא הוי מעשה הקשת זרועותיו הוי מעשה","ואלא כי קאמר ר\"ל הקשת זרועותיו הוי מעשה זוטא אליבא דר\"ע אבל לרבנן לא הוי מעשה","א\"ה אמאי תני יצא מגדף שאין בו מעשה ניתני יצא מגדף ובעל אוב חדא מתרתי קתני","וליתני בעל אוב ולא ליתני מגדף מגדף איצטריך ליה סד\"א הואיל וכתיב כרת דיליה במקום קרבן אימא מודה ליה לרבי עקיבא קמ\"ל דלא","עולא אמר בעל אוב דקתני במקטר לשד מתקיף לה רבא א\"כ היינו עובד עבודת כוכבים אלא אמר רבא מקטר לשד ע\"מ לחברו","א\"ל אביי א\"כ היינו חובר חבר א\"ל התורה אמרה חובר חבר כגון זה בסקילה ואלא חובר חבר דבלאו הדין הוא","א\"ל כדתניא וחובר חבר אחד חובר גדול ואחד חובר קטן ואפי' חובר לנחשים ועקרבים חייב אמר אביי האי מאן דבעי למיצמד זיבורא ועקרבא אסור ואי קאתו בתריה שרי","לר' יוחנן דאמר כפיפת קומתו הוי מעשה עקימת"],[[0,"אלא באומר מותר","לעבוד עבודת כוכבים דהיינו שגגת עבודת כוכבים ושגגת עבודות:"],[0,"דעד כאן לא בעא מיניה רבא מר\"נ","העלם זה וזה בידו מהו בפ' ד' מיתות (סנהדרין סב.):"],[1,"רב פפא אמר משכחת לה בתינוק שנשבה לבין העובדי כוכבים","שגגת עבודת כוכבים וזדון עבודות כגון שחזר ושמע שאותה עבודת כוכבים שישנה שם אסורה בד' עבודות הללו והני עבודות הרוב ידעי דאסירן:"],[2,"שגגת עבודת כוכבים","דסבור אין עבודת כוכבים של עץ:"],[3,"רב אחא בריה דרב איקא משמיה דרב ביבי אמר","לעולם זדון שבת ושגגת מלאכות נמי קחשיב ודקאמרת ליחשיב טפי תנא לא מהדר אלא על מצות שחייבין עליהן כרת:"],[3,"שם שבת קתני שם עבודת כוכבים קתני","ולעולם בכל חדא וחדא איכא טובא:"],[3,"והאיכא בתו מאנוסתו דלא כתיבא","אלא אתיא הנה הנה אתיא זמה זמה במסכת חגיגה בשילהי פ\"ק (דף יא.):"],[6,"רב אחא רמי","דרב ביבי אדרב ביבי:"],[6,"והאיתמר","במס' זבחים בפ' השוחט (דף קז.):"],[6,"אברי פנים","שנשחטה בעזרה:"],[6,"אברי חוץ","בהמת קדשים שנשחטה בחוץ:"],[7,"וקשיא ליה לרב ביבי","התם בזבחים א\"כ דתרי גווני העלאה איכא ניתני בכריתות המעלה חוץ לעזרה אברי פנים והמעלה נמי אברי חוץ:"],[8,"מי דמי שבת","חשבון חיובי' תנא במס' שבת (דף עג.) ודעבודת כוכבים במס' סנהדרין (דף ס:):"],[8,"בנכיהון","במקומותן:"],[8,"וגבי כריתות דאיריא","הוא גררא בעלמא דחשיב להו למצות שחייבין עליהן כרת איכא לשנויי שם שבת שם עבודת כוכבים:"],[8,"אבל גבי העלאה","לא אשכחן ביה נכא דליתני במשנה תרי גווני העלאה:"],[9,"בעא מיניה ר' ירמיה [וכו'] מהו","אם עשאן בהעלם אחת חייב אחת או ב' מי מיחלקן כריתות לחטאות כלאוין אי לא:"],[9,"","שוחט ומעלה איכא ב' כריתות באחרי מות וחד לאו בראה אנכי השמר לך פן תעלה עולותיך בכל מקום [וכו' וכל מקום] שנאמר השמר פן ואל אינו אלא לא תעשה אבל בשחיטה ליכא לאו בהדיא דהאי דכתיב בפרשת (ויקרא י״ז:ז׳) ולא יזבחו עוד את זבחיהם וגו' מוקים ליה בזבחים בפרק השוחט והמעלה (זבחים דף קו.) בזובח בהמה למרקוליס:"],[10,"ג\"ש","התם בזבחים בשחיטה נאמר הבאה ואל פתח אהל מועד לא הביאו ובהעלאה נאמר (ויקרא י״ז:ט׳) ואל פתח אהל מועד לא יביאנו מה להלן בהעלאה ענש והזהיר:"],[12,"ושם תעשה","[ה\"נ] שוחט:"],[13,"אוב וידעוני","איכא ב' מיתות דכתיב (ויקרא כ׳:כ״ז) אוב או ידעוני מות יומת דאו מחלק אי זו שיעשה ימות ולאו אחד דכתיב לא ימצא בך וגו' ושואל אוב וידעוני ובני קרבן נינהו דכתיב בהו כרת (שם) והנפש אשר תפנה אל האובות וקמיבעי לך אי מיתות מחלקות לחטאות והעושן בהעלם אחד חייב שתים אי לא:"],[14,"הא פלוגתא דר' יוחנן וריש לקיש","באלו הן הנסקלין בד' מיתות (סנהדרין דף סה.) דשמעינן דתרווייהו דאין חייבין עליהן אלא אחת הואיל בלאו אחד נאמרו הלכך אין חילוק חטאות ביניהן להכי לא חשיב אלא חד מינייהו דכולהו כריתות דתנן במתני' למניינא דחטאות תננהו כדאמרי' בריש פירקין אם עשאן כולן בהעלם אחת חייב על כל אחת ואחת:"],[16,"הואיל ואין בו מעשה","הילכך לאו בר קרבן הוא אבל אוב יש בו מעשה שמנקש בזרועותיו ומדבר משחיו:"],[16,"","ידעוני מכניס עצם חיה ששמה ידוע לתוך פיו ומדבר:"],[17,"דהא חלוקין הן במיתות","ואי לאו הטעם דלית ביה מעשה מיתות מחלקן לחטאות דהא חלוקין הן במיתות וה\"ל למיתנינהו אי הוה בר קרבן:"],[18,"ר\"ע היא דאמר","לקמן (כריתות דף ד.) מגדף מביא קרבן דלא בעינן מעשה:"],[19,"נהי דלא בעי מעשה רבה","מדקתני מגדף:"],[21,"קס\"ד","מדקאמר ר\"ל הקשת זרועותיו הוי מעשה וחזינן במתני' דפליגי רבנן אמגדף ולא פליגי אבעל אוב ש\"מ דאפי' לרבנן חשיב מעשה:"],[25,"כרת דיליה","כרת דמגדף. מישתעי קרא בקרבן עבודת כוכבים בסדר שלח לך נפש כי תחטא בשגגה והקריבה עז בת שנתה וגו' ובההיא פרשתא כתיב והנפש אשר תעשה ביד רמה וגו' ונכרתה דמישתעי במגדף וקסד\"א הואיל וכתיב במקום קרבן ליחייב קרבן אע\"ג דלית ביה מעשה קמ\"ל יצא מגדף:"],[26,"עולא אמר","היינו טעמא דלא פליגי רבנן אבעל אוב דלאו בהקשת זרועותיו מיירי אלא מקטר לשר השדים:"],[26,"על מנת לחברו","שיתחבר אליו ויסייענו בכשפיו ולא קיטר לו לשם אלוה:"],[27,"היינו חובר חבר","ולא בכרת הוא ולא במיתה הוא אלא בלאו:"],[27,"חובר חבר כגון זה","שמקטר לשר השדים הוא:"],[28,"אחד חבר גדול","שמחבר חיות גדולות ומצמדן יחד:"],[28,"חבר קטן","לחיות קטנות לוחש ומחברן בכשפים יחד:"],[28,"אפילו זיבורא ועקרבא","דלא חשיבי אסור ללוחשן:"]],[]],[["שפתיו נהוי מעשה גבי מגדף אמר רבא שאני מגדף הואיל וישנו בלב אבל בעלמא עקימת שפתיו הוי מעשה","מתיב רבי זירא יצאו עדים זוממין שאין בו מעשה ואמאי הא על פי כתיב בהן אמר רבא שאני עדים זוממין הואיל וישנן בראייה:","האוכל חלב: ת\"ר (ויקרא ז, כג) כל חלב שור וכשב ועז לא תאכלו לחייב על כל אחת ואחת דברי ר' ישמעאל וחכ\"א אינו חייב אלא אחת","נימא בהא קמיפלגי דר' ישמעאל סבר לוקין על לאו שבכללות ורבנן סברי אין לוקין על לאו שבכללות","לעולם סבר ר' ישמעאל אין לוקין על לאו שבכללות ושאני הכא דמייתרי ליה קראי נכתוב קרא כל חלב לא תאכלו שור וכשב ועז למה לי ש\"מ לחלק","ורבנן אי לא כתיב שור וכשב ועז ה\"א אפילו חלב חיה במשמע להכי כתב שור כשב ועז למימרא דחלב שור וכשב ועז הוא דאסור אבל דחיה שרי","שפיר קאמרי ליה אלא היינו טעמא דרבי ישמעאל דקסבר א\"כ לכתוב כל חלב שור לא תאכלו כשב ועז למה לי ש\"מ לחלק","ורבנן סברי אי כתב רחמנא כל חלב שור ה\"א נילף שור שור מסיני","מה גבי סיני חיה ועוף כיוצא בהן אף גבי אכילה חיה ועוף כיוצא בהן להכי כתב רחמנא שור וכשב ועז למימרא דהני דאסור אבל חיה ועוף שרי","שפיר קא\"ל אלא היינו טעמא דקסבר נכתוב כל חלב כשב לא תאכלו א\"נ כל חלב עז לא תאכלו שור וכשב ועז למה לי ש\"מ לחלק","ורבנן סברי אי כתב כל חלב כשב ה\"א חלב כשב אסור ושור ועז שרי וכ\"ת מאי אולמיה דכשב משום דנתרבה באליה","וכדתנא ר' חנניא למה מנה הכתוב אימורין בשור ואימורים בכשב ואימורים בעז דכתיב (במדבר יח, יז) אך בכור שור וגו'","צריכי דאי כתב שור ה\"א כשב ועז לא ילפינן מיניה דאיכא למיפרך מה לשור שכן נתרבה בנסכים","נכתוב רחמנא בכשב ונילף שור ועז מכשב איכא למיפרך מה לכשב שכן נתרבה באליה","נכתוב רחמנא עז ונילף שור וכשב מיניה איכא למיפרך מה לעז שכן נתרבה אצל עבודת כוכבים","מן חד לא ילפינן נכתוב תרתי ונילף חדא מתרתי הי דין נילף שור מכשב ועז אית להון פירכא מה לכשב ועז שכן נתרבו אצל הפסח","לא נכתוב כשב ונילף משור ועז אית להון פירכא מה לשור ועז שכן נתרבה אצל עבודת כוכבים","לא נכתוב עז ונילף משור וכשב אית להון פירכא מה לשור וכשב שכן יש בו צד ריבוי הלכך לא ילפי מהדדי","שפיר קא\"ל אלא לעולם טעמא דרבי ישמעאל כדאמרינן מעיקרא דאם כן נכתוב כל חלב ולישתוק מאי אמרת האי דכתב שור וכשב ועז למשרי חלב חיה","הא כי כתב קרא בעניינא דקדשים ודבר למד מעניינו","מכלל דרבנן סברי לא ילפינן דבר למד מעניינו לא דכולי עלמא ילפינן דבר הלמד מעניינו והכא בהא פליגי רבי ישמעאל סבר למידין לאו מלאו בין מלאו ובין מלאו דכרת","דכל חלב שור וכשב ועז מלאו (ויקרא ג, יז) דחוקת עולם לדורותיכם בכל מושבותיכם כל חלב וכל דם לא תאכלו דכתיב בעניינא דקדשים ובקדשים לא אית בהון חיה אף כל חלב שור כי כתיב ליה סתמא ליכא לספוקי בחיה הלכך שור וכשב ועז לחלק הוא דאתא לחייב על כל אחת ואחת","וילפינן לאו דכל חלב ולאו דחוקת עולם מכרת (ויקרא ז, כה) דכי כל אוכל חלב מן הבהמה אשר יקריבו ממנה מה ההוא לחלק אף הדין לחלק","ורבנן לאו מלאו ילפינן לאו מכרת לא ילפינן","ואיבעית אימא היינו טעמייהו דרבנן כדאמר ליה רב מרי לרב זביד אלא מעתה אליה דחולין תיתסר אמר ליה עליך אמר קרא (ויקרא ז, כג) כל חלב שור וכשב ועז דבר השוה בשלשתן בעינן וליכא","הלכך כי אתא שור וכשב ועז למישרי אליה דחולין הוא דאתא ור' ישמעאל אמר לך א\"כ לימא קרא כל חלב שור וכשב עז למה לי ש\"מ לחלק","א\"ר חנינא מודה רבי ישמעאל לענין קרבן שאין מביא אלא חטאת אחת מ\"ט דלא דמי הדין לאו ללאו דעריות","ת\"ר ועשה אחת ועשה הנה לחייב על כל אחת ואחת","שאם אכל חלב וחלב שם אחד בשני העלמות חייב שתים שתי שמות בהעלם אחת חייב שתים","א\"ל רמי בר חמא לרב חסדא בשלמא שם אחד בשני העלמות חייב שתים משום דהעלמות מחלקין אלא שני שמות בהעלם אחת אמאי חייב שתים הא בעינן העלמות מוחלקין וליכא","א\"ל הכא במאי עסקינן כגון דאכל חלב דנותר דמחייב משום נותר ומשום חלב א\"ל א\"כ ניחייב נמי משום קודש","אלא אמר רב ששת כגון דאכל חלב דהקדש ור' יהודה היא דתניא אכל חלב נבלה אכל חלב מוקדשין חייב שתים ר' יהודה אומר חלב מוקדשין לוקה שלש","מחייכו עלה במערבא ונוקמה כגון חלב דשור וכשב ועז ור' ישמעאל היא דאמר לוקה שלש"],[[0,"וישנו בלב","עיקר איסורו תלוי ברוע לבו ידע למי גידף הילכך לא חשיב מעשה אבל השתחואה אנו רואין משתחוה לעבודת כוכבים:"],[0,"גליון: הואיל וישנו בלב","עיקר איסורו במחשבת הלב ואין כאן מעשה ומה שמדבר אינו אלא משמיע איסורו אבל כפיפת קומתו היינו עיקר איסורו דאילו היה מדבר במקבל עבודת כוכבים בלא השתחואה לא מחייב דאין עיקר בלב אלא כפיפה היא החיוב. נראה לי:"],[1,"יצאו עדים זוממין","בתורת כהנים גבי פר כהן משיח והכי אמרינן אחר שריבינו דברים שהן בעבודת כוכבים ודברים שאינן בעבודת כוכבים יכול שאני מרבה המסית והמדיח ועדים זוממין ת\"ל ועשה יצאו אלו שאין בהן מעשה יצאו מכלל חטאת:"],[1,"והא על פי כתיב בהו","ונימא עקימת פיו הוי מעשה:"],[1,"הואיל וישנן בראייה","עיקר עדותן בראיית העין שמעידין מה שראו הילכך לא חשיב מעשה:"],[2,"חייב על כל אחת ואחת","מלקות אם אכלן בהתראה אחת:"],[3,"לוקין על לאו שבכללות","על כל אחד ואחד:"],[3,"ורבנן סברי אין לוקין","ואי תיקשי לא לילקי אפילו חדא דחדא מיהא לקי:"],[7,"ויליף שור שור משבת","למען ינוח שורך (שמות כ״ג:י״ב) מה התם חיה ועוף כיוצא בו דהכי מוקמינן בב\"ק בפרק שור שנגח את הפרה (בבא קמא דף נד: ע\"ש):"],[9,"כל חלב כשב","דליכא השתא ג\"ש:"],[12,"שור נתרבה בנסכים","חצי ההין יהיה לפר:"],[14,"עז נתרבה בעבודת כוכבים","ביחיד:"],[15,"חד מתרי","הצד השוה שבהן שהן מין בהמה וחלבו אסור ואימורי בכוריהם קריבים:"],[16,"נתרבו אצל עבודת כוכבים","פר בצבור ועז ביחיד:"],[17,"","ה\"ג מה לשור וכשב שכן יש בהן ריבוי אצל מזבח שור בנסכים וכשב באליה אבל עז אין בקרבנו ריבוי אצל מזבח:"],[19,"הא כי כתיב קרא בעניינא דקדשים כתיב","דכתיב (ויקרא ז) כי כל אוכל חלב מן הבהמה וגו' והואיל ובעניינא דקדשים כתיב ודאי אין חיה נוהגת בהו הלכך לא איצטריך שור וכבש למישרי חיה:"],[20,"מכלל דרבנן סברי","לא ילפינן לאו דכל חלב מעניינו בתמיה:"],[20,"דכולי עלמא ילפינן דבר למד מעניינו","בעלמא אבל הכא לאו עניינו דהאי לאו והאי כרת:"],[20,"והכא בהא קמיפלגי כו'","גירסא זו הכתובה בספרים משובשת היא ועל ידי פרשנים טועין שלא היו בקיאין בשמועה ופירשוה בשיבוש בתוך הגירסא וכך הצעה ולא יותר והכא בהא קמיפלגי מר סבר למידין לאו מלאו ולאו מכרת ומר סבר לאו מלאו ילפינן לאו מכרת לא ילפינן והכי פירושא ר' ישמעאל סבר למידין דבר מעניינו בין לאו מלאו בין לאו מכרת:"],[23,"ורבנן סברי","לאו מלאו למידין זה מזה כשהן בפרשה אחת דבר למד מעניינו כי ההיא דבשר בחלב השנויה בפ' כל הבשר (חולין קטו:) לא תאכלנו בבשר בחלב הכתוב מדבר אבל לאו מכרת כעין הכא לא ילפינן דבר למד מעניינו הלכך אי לא כתיב שור וכשב ועז ה\"א חיה במשמע:"],[24,"ואי בעית אימא טעמייהו דרבנן","משום דהאי שור וכשב ועז מיבעי להו לכדרב מרי:"],[24,"אליה דחולין תיתסר","דחלב איקרי בפרק כל הבשר (חולין קיז.):"],[24,"ששוה בשלשתן","שנקרא חלב בשלשתן ואליה לא איקרי חלב אלא בכשב:"],[25,"א\"כ נכתוב כל חלב שור וכשב","ומהתם ממעיטנא אליה דבעינן דבר השוה בשניהן:"],[26,"לאו דעריות","להכי נקט עריות דאיכא מילי טובא ואיכא לאו בכל חדא:"],[27,"מאחת מהנה","משמע מאחת חייב הנה כמה חטאות:"],[28,"חלב וחלב","שני זיתי חלב:"],[28,"שם אחד","חלב הכליות או חלב הדקין שם אחד בהעלם אחד ל\"ג:"],[28,"שני שמות","כזית משעל הכוליא וכזית משעל הדקין:"],[29,"דהעלמות מחלקין","דכיון דנודע לו בינתים הרי הן שתי שגגות וחטאת בידיעה תלה רחמנא דכתיב (ויקרא ד) או הודע אליו:"],[30,"חלב דנותר","דאיכא שתי שגגות משתי כריתות חלב ונותר וחייב שתי חטאות:"],[30,"ניחייב נמי משום קדש","אשם מעילות:"],[31,"אלא אמר רב ששת כגון שאכל חלב דקודש","ולעולם משום חלב חייב שתים ולהכי לא חשיב אשם מעילות אלא של שם אחד ורבי יהודה היא דמחייב אחלב מוקדשין שתים משום חלב ושני שמות דקתני משום דבחלב מוקדשין כתיבי תרי קראי:"],[31,"חלב נבלה לוקה שתים","משום חלב ומשום נבלה והמוקדשין משום חלב ומשום זרות:"],[31,"ג'","ב' משום חלב כדמפ' לקמן וא' משום זרות:"],[32,"ונוקמה","להא דלעיל דקתני ב' שמות כלומר משתי בהמות משני מינין ור' ישמעאל היא:"]],[]],[["אלמא לא אוקמה כר' ישמעאל דא\"ר חנינא מודה היה רבי ישמעאל לענין קרבן שאינו חייב אלא חטאת אחת השתא נמי כר' יהודה לא מתוקמא דהא א\"ר אליעזר מודה היה רבי יהודה לענין קרבן שאין מביא אלא חטאת אחת","אלא אמר ר\"ל משום בר תאוטני הכא במאי עסקינן כגון שאכלן בשני תמחויין ואליבא דרבי יהושע דאמר תמחויין מחלקים","גופא אכל חלב נבילה לוקה שתים חלב מוקדשין לוקה שתים רבי יהודה אומר חלב מוקדשין לוקה שלש","אמר ליה רב שיזבי לרבא בשלמא לר' יהודה היינו דכתיבי קראי (ויקרא ג, יז) חקת עולם (ויקרא ז, כג) כל חלב שור וכשב ועז לא תאכלו (ויקרא כב, י) וכל זר לא יאכל קדש הא תלתא לאוין אלא לרבנן מ\"ט","קסברי לאו דחוקת עולם בקדשים ולאו דחלב שור בחולין וצריכי","דאי כתב רחמנא בקדשים הוה אמינא קדשים הוא דחמירי דאסור חלבו אבל חולין אימא לא משום הכי כתב רחמנא כל חלב שור","ואי כתב כל חלב שור ה\"א חלב דחולין הוא דאסור משום דלא הותר מכללו אבל חלב מוקדשין דהותר מכללו ה\"א מדהותר בשרן אישתרי נמי חלבן צריכי","ורבי יהודה סבר כי כתיב חלב שור בעניינא דקדשים כתיב","אלא מכלל דרבנן סברי לא ילפינן דבר הלמד מעניינו","לא דכ\"ע דבר הלמד מעניינו ובהא קמיפלגי רבי יהודה סבר למידין לאו מלאו ולאו מכרת ורבנן סברי לאו מלאו ילפינן לאו מכרת לא ילפינן","אלא לר' יהודה כל חלב וכל דם לא תאכלו למאי אתא מיבעי ליה להקיש תניא (ויקרא ג, יז) כל חלב וכל דם לא תאכלו מה חלב לוקה שתים אף דם לוקה שתים דברי ר' יהודה וחכ\"א אין בו אלא אזהרה אחת","ומ\"ש חלב דלוקה שתים בלא היקישא דכתב ביה תרי קראי כל חלב וכל דם לא תאכלו כל חלב שור וכשב דם נמי בלאו היקישא נילקי שתים דכתיב ביה תרי לאוין כל חלב וכל דם לא תאכלו (ויקרא ז, כו) וכל דם לא תאכלו בכל מושבותיכם לעוף ולבהמה","אלא אימא מה חלב לוקה שלש אף דם לוקה ג'","ומאי שנא חלב דלוקה שלש דכתיב ביה הלין תרי לאוין ולאו דזרות הא תלתא דם נמי","איצטריך ס\"ד אמינא הואיל ואיתמעיט דם מטומאה ליתמעיט מזרות קמ\"ל היקישא","ואלא לרבנן הקישא למאי אתא","מיבעי ליה לכדתניא כל חלב וכל דם לא תאכלו מה חלב מיוחד שחלבו חלוק מבשרו ואין מצטרפין זה עם זה אף דם שדמו חלוק מבשרו","אוציא דם שרצים הואיל דאין דמן חלוק מבשרן מצטרפין","והא מהכא נפקא מהתם נפקא (ויקרא יא, כט) וזה לכם הטמא לימד על דם השרץ והשרץ שמצטרפין זה עם זה","אי לאו היקישא ס\"ד אמינא ה\"מ לטומאה אבל לאכילה אימא לא אשמעינן היקישא לאכילה","אמר רבינא הילכך דם נחש ובשרו מצטרפין מאי קמ\"ל היינו היקישא סד\"א שרץ דאיתרבי לטומאה איתרבי לאכילה נחש דלא איתרבי לטומאה לא איתרבי לאכילה קמ\"ל היקישא כל מילי דאין דמו חלוק מבשרו משמע","אמר רבא שלש כריתות האמורות בדם למאי אחת לדם חולין ואחת לדם קדשים ואחת לדם התמצית","הניחא לר' יהודה דתניא דם התמצית באזהרה ר' יהודה אומר בכרת","אלא לרבנן ההיא למאי אתא ואפילו לר' יהודה כרת נפקא ליה מן כל דם","דתניא רבי יהודה אומר דם מה תלמוד לומר כל דם","אין לי אלא דם קדשים שהנפש יוצא בו דם חולין ודם התמצית מנין ת\"ל כל דם","אלא אימא אחד לדם חולין ואחד לדם קדשים ואחד לדם כיסוי","ואמר רבא חמשה לאוין האמורין בדם למה אחת לדם חולין ואחת לדם קדשים ואחת לדם כיסוי ואחת לדם איברין ואחת לדם התמצית","א\"ר אילא אכל מעשר דגן ותירוש ויצהר לוקה שלש והא אין לוקין על לאו שבכללות שאני הכא דמייתרי קראי","מכדי כתב רחמנא (דברים יד, כג) ואכלת לפני ה' אלהיך מעשר דגנך תירושך ויצהרך בפנים אין בחוץ לא ל\"ל דכתב רחמנא (דברים יב, יז) לא תוכל לאכול בשעריך מעשר דגנך ותירושך ויצהרך לחלק","אי מההוא ה\"א ה\"מ בעשה אבל בלאו אימא לא אמטו להכי"],[[0,"לענין קרבן","וברייתא דלעיל בקרבן קמיירי דגבי חטאות כתיב ועשה מאחת מהנה:"],[1,"הב\"ע","הא דקתני ב' שמות כגון שאכלן בב' תמחוין ב' מאכלין דהיינו ב' שמות כגון תבשיל וצלי:"],[1,"","(ל\"א \u0003חייב ב' -\u0004 א' משום חלב וא' משום קדש אשם מעילה ודלא כר' יהודה דמחייב משום חלב שתים משום ב' לאוין דכתיבי בחלב בתרי פסוקי):"],[1,"דרבי יהושע","בפרק אמרו לו (לקמן כריתות טו:):"],[3,"תרי קראי","חד בקדשים חוקת עולם וחד בין בחולין בין בקדשים הילכך בחלב המוקדשים איכא שני לאוין משום חלב וחלב חולין נפקא ליה לר' יהודה כדאמרינן בפ' אלו עוברין (פסחים מג:) כי כל אוכל חלב מן הבהמה אין לי אלא חלב תמימין הראוי ליקרב חלב בעלי מומין מנין תלמוד לומר כל חלב חולין מנין תלמוד לומר כי כל:"],[4,"קסברי רבנן לאו דחקת עולם בקדשים","דהא בעניינא דקדשים כתיב ולאו דכל חלב בחולין ולא בקדשים:"],[5,"ה\"ג אבל דחולין דאסור חלבו אימא לא","והכי פירושא אבל חולין דקילי אימא לא אסיר חלבו. דאסור חלבו אימא לא כלומר אימא לא אסור חלבו ולשון הפוך היא לשון גרסא ירושלמית:"],[6,"חלב מוקדשין הותר מכללו","דהא אליה איקרי חלב בכבש ואישתראי בשור ועז:"],[7,"ור' יהודה סבר כי כתיב נמי כו'","כדאמרן לעיל:"],[8,"מכלל דרבנן לא ילפי","בתמיה:"],[9,"לאו מלאו ולאו מכרת למידין","דבר מעניינו בין לאו מלאו כגון בעלמא גבי אבר מן חי בפ' (כל הבשר) (חולין קב.) בין לאו מכרת כגון הכא מה כרת בקדשים אף לאו בקדשים:"],[9,"ורבנן סברי לאו מלאו הוא דילפינן","כי התם אבל לאו מכרת לא ילפינן הלכך בחולין כתיב. ואף בזו הספרים משובשים וכולה גרסא ליתא:"],[10,"","ה\"ג ת\"ר כל חלב וכל דם לא תאכלו ר' יהודה אומר מה חלב לוקה שתים אף דם לוקה שתים וחכ\"א אין בו אלא אזהרה אחת:"],[11,"מאי שנא חלב","כלומר מ\"ט כתביה לדם בהדי חלב ליכתביה באנפי נפשיה ואנא ידענא דלוקה ב' דמ\"ש חלב דלוקה שתים בלא הקישא כלומר דם נמי כתיבי ב' קראי אי הוה כתיב באנפי נפשיה כגון כל דם לא תאכלו לכתוב בחקת עולם ל\"ל דכתיב בהדי חלב:"],[14,"","דם אימעיט ממעילה בסוף כל הבשר בשחיטת חולין (דף קיז:) ואימא כי היכי דאימעיט מזרות קרבן מעילה אימעיט נמי ממלקות דזרות קמ\"ל:"],[14,"","ה\"ג \u0003ס\"ד אמינא הואיל ואימעיט ממעילה אימעיט נמי מזרות קמ\"ל\u0004:"],[15,"אלא לרבנן","כיון דתרצינן דלר' יהודה לא בעי הקישא אלא משום זרות ורבנן פליגי עליה ואמרי אין בו אלא אזהרה אחת מכלל דסבירא להו מזרות נמי אימעיט ולדידהו הקישא ל\"ל:"],[16,"מה חלב מיוחד שחלבו חלוק מבשרו","שלא נאמר איסור חלב אלא בשור וכשב ועז שחלבן אסור ובשרן מותר:"],[16,"ואינן מצטרפין זה עם זה","לאיסור שבה שהרי אין כאן אלא איסור החלב לבדו ואין היתר מצטרף לאיסור חוץ מאיסורי נזיר:"],[16,"אף דם","אע\"פ שאיסורו נוהג בטמאין וראוי להצטרף הדם והבשר להתחייב בכזית משניהן משום טמא לא יצטרפו שנלמד דם מחלב מה החלב על כרחיה לחלקו מפרידו מלהצטרף שהרי חלוקין זה לאיסור וזה להיתר דאין איסור והיתר מצטרפים אף דם הטמאים הואיל ודמן חלוק מבשרן שיש על הדם איסור כרת משום דם מה שאין כן בבשר אינו מצטרף אפילו לענין (איסור) לטמא:"],[17,"יצאו שרצים","מדין ההיקש הזה הואיל ואין דמן חלוק מבשרן שאינו מוזהר על דמן משום דם אלא משום שרץ כדאמרי' בפר' דם שחיטה (לקמן כריתות כא:) יצאו שרצים שאין בהן טומאה קלה כו' הילכך מצטרפין זה עם זה שהרי שם אחד להן הילכך דם נחש ובשרו מצטרפין דאין מוזהר על דמן משום דם כדאמרינן בפרק דם שחיטה (שם) שאין אזהרת דם אלא בבהמה חיה ועוף כו':"],[18,"דם שרץ מוזה נפקא","דאי ללמוד לשרץ גופיה הא כתיב אלה הטמאים לכם:"],[19,"לטומאה","לכעדשה:"],[19,"לאכילה","בכזית:"],[20,"הילכך","דאמרת כל שאין דמו חלוק מבשרו מצטרפין:"],[20,"נחש נמי","אע\"ג דלאו בר טומאה הוא מצטרף דמו לבשרו לכזית לאכילה דאין מוזהרין על דמו אלא משום בשרו:"],[20,"דאיתרבו לטומאה","כדאמרן וזה לכם הטמא לימד על דם השרץ ובשרו שמצטרפין לטומאה:"],[21,"ג' כריתות","תרין באחרי מות וחד בצו את אהרן:"],[23,"ואפי' לר' יהודה","לא נפקא ליה דם התמצית מחד מהנך כריתות:"],[24,"דם","הוה ליה למיכתב:"],[24,"מה ת\"ל כל דם","באחרי מות איש איש מבית ישראל ומן הגר הגר בתוכם אשר יאכל כל דם ונתתי פני וגו' אין לי שיהא בכרת אלא דם קדשים שהנפש יוצאה בו שמתכפר בו שראוי לכפרה על המזבח דהא כפרה כתיבא הכא ואני נתתיו לכם על המזבח לכפר והני הוא דראויין לכפרה:"],[25,"דם חולין ודם התמצית","לקדשים דאינם ראוין לכפרה כדאמרינן בסוף תמיד נשחט בפסחים (דף סה.):"],[26,"אלא","לעולם רבנן דלא נפקא לחולין מריבויא דקרא דכל ואע\"ג דלית להו כרת בדם התמצית מיבעי להו חד כרת לדם כיסוי לדם חיה ועוף שכיסהו ונתגלה סד\"א בטלה אגב ארעא ואי הדר אכלה עפרא בעלמא הוא ולא ליחייב קמ\"ל:"],[27,"ה' לאוין","הנך דלא אתו לדרשה חד (ויקרא ג׳:י״ז) דחקת עולם וחד בצו את אהרן (שם ז) כל דם לא תאכלו בכל מושבותיכם וחד באחרי מות (שם יז) דם כל בשר לא תאכלו וחד בראה אנכי (דברים י״ב:ט״ז) לא תאכלו על הארץ תשפכנו כמים הרי ה' ודכתיב לעיל מיניה לא תאכל הנפש עם הבשר באבר מן החי משתעי ודכתיב בתריה לא תאכלנו מוקמינן בפרק כל הבשר בשחיטת חולין (דף קטו:) אזהרה לבשר בחלב ועוד כתיב בראה אנכי רק את דמו לא תאכלו ומוקמינן ליה בפרק שני דבכורות (דף טו.) לחלב פסולי המוקדשים ודכתיב באחרי מות כל נפש מכם לא תאכל דם מוקים ליה תורת כהנים להזהיר גדולים על הקטנים:"],[28,"א\"ר אילא אכל מעשר","שני של דגן ותירוש ויצהר לוקה ג' משום לא תוכל לאכול בשעריך וגו':"],[30,"בעשה","לאו הבא מכלל עשה עשה:"]],[]],[["כתב רחמנא לא תוכל לאוקמה בלאו","ועדיין לאו שבכללות הוא אם כן נימא קרא לא תוכל לאכלם בשעריך מעשר דגנך תירושך ויצהרך למ\"ל ליחודי אכילה דכל חד וחד","א\"ר יצחק האוכל לחם קלי וכרמל לוקה ג' והא אין לוקין על לאו שבכללות שאני הכא דמייתר קראי","לימא קרא לחם ונילף קלי וכרמל מיניה איכא למיפרך מה ללחם שכן נתרבה אצל חלה","נכתוב קלי ולא לכתוב לחם ונילף מקלי לחם מקלי לא אתי משום דקלי איתיה בעיניה לחם לא איתיה בעיניה כרמל מקלי לא אתי משום דקלי נתרבה אצל מנחות כרמל לא נתרבה אצל מנחות","נכתוב כרמל ונילף לחם וקלי מיניה איכא למיפרך מה לכרמל שכן לא נשתנה מברייתו מן חד לא ילפי נילף חדא מן תרין","לא נכתוב קרא לחם ונילף מקלי וכרמל איכא למיפרך מה לקלי וכרמל דאיתנהון בעיניהון לא נכתוב קרא כרמל ונילף מלחם וקלי איכא למיפרך מה ללחם וקלי שכן נתרבו אצל מנחות","אמר לך רבי יצחק לא נכתוב קרא קלי ונילף מלחם וכרמל מאי פרכת אי פרכת מה ללחם שכן נתרבה אצל חלה כרמל יוכיח ואי משום דכרמל לא נשתנה מברייתו לחם יוכיח הלכך לוקה דמייתר","ואימא קלי דמייתר מחייב חדא אכולהון מחייב חדא אם כן נכתוב קרא לחם כרמל וקלי אי נמי נכתוב קלי ולחם וכרמל אמאי כתב לקלי באמצע הכי קאמר לחם בקלי נחייב וכרמל נחייב בקלי","א\"ר ינאי לעולם אל תהי גזירה שוה קלה בעיניך שהרי פיגול אחד מגופי תורה ולא לימדו הכתוב אלא מגזירה שוה","דאמר רבי יוחנן תני זבדא בר לוי נאמר להלן (ויקרא יט, ח) ואוכליו עונו ישא ונאמר כאן (ויקרא ז, יח) והנפש האוכלת ממנו עונה תשא מה להלן כרת אף כאן כרת","א\"ר סימאי לעולם אל תהי גזירה שוה קלה בעיניך שהרי נותר אחד מגופי תורה ולא לימדו הכתוב אלא מג\"ש","מאי היא יליף קדש קדש ואוכליו עונו ישא כי את קדש ה' חלל וכתיב (שמות כט, לד) ושרפת את הנותר באש כי קדש וגו'","אמר אביי לעולם אל תהי ג\"ש קלה בעיניך שהרי בתו מאנוסתו הן הן גופי תורה ולא לימדה הכתוב אלא מג\"ש","דאמר רבא אמר לי ר' יצחק בר אבדימי אתיא הנה הנה לאיסורא","אתיא זמה זמה לשרפה","אמר רב אשי אל תהי ג\"ש קלה בעיניך שהרי נסקלים הן הן גופי תורה ולא לימדה הכתוב אלא מג\"ש","דתניא נאמר כאן דמיהם בם ונאמר באוב וידעוני דמיהם בם מה להלן בסקילה אף כאן בסקילה:","המפטם את השמן כו': ת\"ר המפטם את השמן ללמוד בו למוסרו לציבור פטור לסוך חייב והסך ממנו פטור לפי שאין חייבין אלא על סיכת שמן המשחה שעשה משה בלבד","אמר מר ללמוד בו ע\"מ למוסרו לציבור פטור מנלן אתיא מתכונתו מן במתכונתה דקטרת וכתיב לגבי קטרת (שמות ל, לז) לא תעשו לכם לכם הוא דאסור אבל למוסרו לציבור פטור גבי שמן נמי למוסרו לציבור פטור","ותיהדר קטרת ונילף משמן מה שמן כי מפטם לחציין פטור אף קטרת נמי כי מפטם לחציין פטור אלמה אמר רבא קטרת שפטמה לחציין חייב שמן שפטמו לחציין פטור","אמר לך רבא גבי שמן כתיב ובמתכונתו לא תעשו כמוהו כמוהו הוא דאסור אבל חציו שפיר דמי גבי קטרת דכתיב והקטרת אשר תעשה כל עשייה דקטרת אפשר דמקטיר פרס שחרית ופרס בין הערבים","ת\"ר שמן המשחה מר דרור ה' מאות קדה ה' מאות קנמן בשם ה' מאות וקנה בשם חמשים ומאתים נמצאו כולם אלף ושבעה מאות וחמשים","תנא מניינא קמ\"ל תנא הא קא קשיא ליה אימא קנה בשם כקנמן בשם מה קנמן בשם מחציתו בחמשים ומאתים אף קנה בשם מחציתו חמשים ומאתים דהוו להו תרין אלפים","ואימא ה\"נ אם כן נכתוב קרא קנמן בשם וקנה בשם מחצה ומחצה חמשים ומאתים","אמר ליה רב פפא לאביי כשהוא שוקל בהכרע הוא שוקל או עין בעין הוא שוקל אמר ליה רחמנא כתב בד בבד ואת אמרת בהכרע והאמר רב יהודה הקב\"ה יודע הכרעות אלמא דאית בהו הכרע","אלא אמר רב יהודה דקנמן בשם אמאי מייתי מחציתו דחמש מאות חמשים ומאתים בחד זימנא וחמשים ומאתים בחד זימנא כיון דכולהון ה' מאות הויין נייתי ה' מאות בבת אחת ש\"מ מדקמייתי לה לקנמן בשם בתרי זימני הכרע אית ביה והקב\"ה יודע בהכרעות","ומאי בד בבד אמר רבינא שלא יניח משקל במשקל וישקול","ת\"ר שמן המשחה שעשה משה במדבר משלקו העיקרין דברי ר' יהודה א\"ל רבי יוסי והלא לסוך העיקרין אינו סיפק כיצד עושה הביאו העיקרין ושלקום במים והציף עליהן שמן המשחה וקלט את הריח וקיפחו","אמר לו ר' יהודה"],[[1,"נכתוב לא תוכל לאכלם","דהא איירי לעיל עולותיכם וזבחיכם מעשרותיכם וגו':"],[2,"לחם וקלי וכרמל","לפני העומר:"],[2,"קלי","שנתייבש בתנור:"],[2,"כרמל","שנתמולל ביד ולא הובהב באור:"],[4,"","קלי וכרמל איתנהו בעינייהו דלא טחנן:"],[4,"קלי נתרבה","במנחת העומר דכתיב גביה (ויקרא ב) קלוי באש ואף על גב דבההוא קרא כתיב כרמל לא הוכשר אלא על ידי האור כדאמרינן במנחות (דף סו:) אבוב של קליות היה שם מנוקב ככברה שיהא האור שולט בכולן ולשון כרמל רך ומל רך שנמלל:"],[5,"","לחם ישנו במנחות דלחם הפנים איקרי מנחה ושתי הלחם של עצרת דכתיב בהו (במדבר כח) בהקריבכם מנחה חדשה:"],[6,"שכן איתנהו בעינייהו","הלכך לא מצית ילפת לה דהא כי אמרינן מה לקלי דאיתיה בעיניה ליכא למימר כרמל יוכיח:"],[6,"שכן נתרבו אצל מנחות","וכי פרכת מה לקלי שכן נתרבה על ידי מנחות ליכא למימר לחם יוכיח:"],[9,"הפגול א' מגופי תורה","דחייבין עליו כרת ולא למדוה הכתוב שיהא בכרת אלא נאמר בקדושים תהיו ואוכליו עונו ישא ואע\"ג דכתיב ביה פגול לא בפיגול גמור קמיירי אלא במחשב בשחיטה חוץ למקומו דהכי דרשינן בתורת כהנים ובשחיטת קדשים (דף כח:) אם אינו ענין לחוץ לזמנו תנהו ענין לחוץ למקומו וליכא למימר דהאי כרת עליה קאי דכתיב בפגול גמור בצו את אהרן והנפש האוכלת ממנו עונה תשא ודרשינן בתורת כהנים ממנו עונה תשא ולא מחברו דהיינו חוץ למקומו דכתיב ביה מחשבה כותיה:"],[10,"ונאמר להלן","גבי נותר בפרשת קדושים תהיו ואוכליו עונו ישא וגו' מה (כאן) [להלן] בקדושים תהיו כרת דכתיב ונכרת:"],[10,"נאמר כאן","בצו את אהרן בפגול גמור והנפש האוכלת וגו' והתם כתיב לא יחשב דהיינו פגול גמור חוץ לזמנו:"],[11,"ולא למדו הכתוב","לנותר בכרת אלא בגזירה שוה דלא ידעינן דהאי כרת דקדושים תהיו בנותר קמיירי דהא בתר דקרא דחוץ למקומו כתיב ומשמע דעליה קאי אלא משום דאתיא קדש קדש:"],[13,"בתו מאנוסתו אחד מגופי תורה","דבשריפה:"],[14,"אתיא הנה הנה","כתיב באשתו (ויקרא י״ח:י״ז) ערות אשה ובתה לא תגלה דמשמע בתה ממנו ובתה מאחר סיפיה דקרא שארה הנה זמה היא וכתיב (שם) ערות בת בנך או בת בתך ובאנוסה כתיב דהא בת בתו מאשתו נפקא לו מקרא דלעיל ערות אשה ובתה ובתו לא כתיבא באנוסתו אלא אתיא הנה הנה מאשתו כתיב באשתו שארה הנה זמה היא וכתיב באנוסתו כי ערותך הנה מה התם כתיבא בתו דכתיב אשה ובתה אף כאן נמי באנוסה עשה בתו כבת בתו. וא\"ת קל וחומר הוא אין מזהירין מן הדין:"],[15,"זמה זמה לשריפה","כי יקח איש את אשה ואת אמה זמה היא (ויקרא כ׳:י״ד):"],[16,"נסקלין","רוב חייבי סקילה כגון הבא על האם ועל הכלה לא כתיבא סקילה אלא דמיהם בם (שם):"],[18,"המפטם","לסוך ממנו חייב דכתיב (שמות ל׳:ל״ג) אשר ירקח כמוהו:"],[18,"והסך ממנו","אחר שלא פטמו:"],[18,"","ואשר יתן ממנו מאותו של משה:"],[20,"לחצאין","כגון ו' לוגין דההוא דמשה הוה הין י\"ב לוגין:"],[20,"","חצאין דקטרת קפ\"ד מנין דבכל יום היה מקטיר מנה כדאמרינן לקמן (כריתות ד' ו.) שס\"ה מנין (כמנין ימות החמה):"],[21,"פרס שחרית","חצי מנה:"],[22,"ה' מאות","שקלים:"],[22,"קנמן בשם ה' מאות","דהכי אמר קרא מחציתו חמשים ומאתים דלהכי נקט מחציתו שלא יהו שוקלים אותו הכל ביחד אלא לחצאין כדי שיהו שם שתי הכרעות:"],[23,"תנא הכי קשיא ליה","כלומר להכי אשמעינן ברייתא דאי ממשמעותא דקרא הוה אמינא קנה בושם כקנמן בשם דמחציתו דקרא אתרוייהו קאי קמ\"ל:"],[24,"מחצה למחצה","שהיו שוקלין לחצאין:"],[25,"עין בעין","שאין הבשם מכריע:"],[25,"(ע\"א) המקום יודע בהכרעות","שלא היה שוקל ההכרעות לבד אלא מניחן כמות שהן והמקום יודע מה משקלו. פירוש רומי:"],[26,"","\u0003אלא אמר רב יהודה הכי קשיא ליה כו' \u0004- ה\"ג \u0003אלא אמר רב יהודה \u0004- מדקא מייתי ליה תרי זימני ודאי לאפושי הוא דעבד:"],[27,"שלא יניח משקל כו'","שישקול כל בשם ובשם כנגד הברזל ולא ישקול במניין דמר דרור ויחזור וישקול קדה כנגד מר דרור:"],[28,"העקרין","בבשמים:"],[28,"אינו סיפק","דשמן לא הוה אלא י\"ב לוגין ועיקרין הוו טובא:"],[28,"ושראן במים","שיבלעו המים ולכשיציף עליהן השמן לא יבלעוהו:"],[28,"וקלט השמן את הריח וקפחו","קנחו וחברו קפחת את הרועה ביומא (דף פג:) קנחו משה לשמן מעל העיקרין ונתנו בצלוחית:"]],[]],[["וכי נס אחד נעשה בשמן המשחה והלא נסים הרבה נעשו בו מתחלתו ועד סופו תחלתו לא היה אלא י\"ב לוג ובו נמשח המשכן וכליו ואהרן ובניו כל שבעת ימי המלואים ובו נמשחו כהנים גדולים ומלכים וכולו קיים לעתיד לבא","שנאמר (שמות ל, לא) שמן משחת קדש יהיה זה לי לדורותיכם זה בגימטריא י\"ב לוגין הויין","ת\"ר (ויקרא ח, י) ויקח משה את שמן המשחה וימשח את המשכן וגו' רבי יהודה אומר שמן המשחה שעשה משה במדבר הרבה נסים נעשו בו מתחלתו ועד סופו תחלתו לא היה אלא י\"ב לוגין כמה יורה בולעת כמה עיקרין בולעין כמה האור שורף ובו נמשח משכן וכליו אהרן ובניו כל ז' ימי המלואים","ובו נמשחו כהנים גדולים ומלכים ואפי' כהן גדול בן כ\"ג טעון משיחה ואין מושחין מלך בן מלך ואם תאמר מפני מה משחו את שלמה מפני מחלוקת אדוניה ואת יהואש מפני עתליה ואת יהואחז מפני יהויקים אחיו שהיה גדול מאחיו שתי שנים","אמר מר ואפי' כ\"ג בן כ\"ג טעון משיחה מנלן דכתיב (ויקרא ו, טו) והכהן המשיח תחתיו מבניו נימא קרא והכהן שתחתיו מבניו מאי המשיח הא קמ\"ל דאפי' מבניו ההוא דמשח הוי כ\"ג ואי לא משח לא הוי כ\"ג","אמר מר אין מושחין מלך בן מלך מנלן אמר רב אחא בר יעקב דכתיב (דברים יז, כ) למען יאריך ימים על ממלכתו הוא ובניו כל הימים ירושה היא","ומפני מה משחו את שלמה מפני מחלוקת אדוניה מנלן דכי אתי מחלוקת בעי משיחה ולא כל דבעי מלכא מורית ליה מלכותא אמר רב פפא אמר קרא (דברים יז, כ) בקרב ישראל בזמן ששלום בישראל","תנא אף יהוא בן נמשי לא נמשח אלא מפני מחלוקת יורם בן אחאב אמאי תיפוק ליה דמלך ראשון הוא חסורי מיחסרא והכי קתני מלכי בית דוד מושחין מלכי ישראל אין מושחין ואם תאמר מפני מה משחו יהוא בן נמשי מפני מחלוקת יורם בן אחאב","אמר מר מלכי בית דוד מושחין ואין מלכי ישראל מושחין מנלן דכתיב (שמואל א טז, יב) קום משחהו כי זה הוא זה טעון משיחה ואין אחר טעון משיחה","אמר מר מפני מחלוקת יורם ומשום מחלוקת יורם בן אחאב נמעל בשמן המשחה כדאמר רב פפא באפרסמא דכיא ה\"נ באפרסמא דכיא","ואת יהואחז מפני יהויקים שהיה גדול ממנו שתי שנים ומי קשיש והכתיב (דברי הימים א ג, טו) ובני יאשיה הבכור יוחנן והשני יהויקים והשלישי צדקיהו והרביעי שלום וא\"ר יוחנן הוא יהואחז הוא צדקיהו הוא שלום","אלא לעולם יהויקים קשיש ואמאי קרי ליה בכור שהוא בכור למלכות ומי מוקמינן זוטא קמי קשישא והכתיב (דברי הימים ב כא, ג) ואת הממלכה נתן ליהורם כי הוא הבכור ההוא ממלא מקום אבותיו הוה","אמר מר הוא שלום הוא צדקיה והא בדרי קחשיב ומאי קרי ליה שלישי שהוא שלישי לבנים ומאי קרי ליה רביעי שהוא רביעי למלכות משום דמלך יכניה קמיה בתחלה מלך יהואחז וסוף מלך יהויקים וסוף מלך יכניה וסוף מלך צדקיה","ת\"ר הוא שלום הוא צדקיה ולמה נקרא שמו שלום שהיה שלם במעשיו דבר אחר שלום ששלם מלכות בית דוד בימיו ומה שמו מתניה שמו שנאמר (מלכים ב כד, יז) וימלך את מתניה דודו תחתיו ויסב שמו צדקיה","דאמר לו יה יצדיק עליך את הדין אם תמרוד בי שנאמר (דברי הימים ב לו, י) ויביאהו בבלה וכתיב (דברי הימים ב לו, יג) וגם במלך נבוכדנאצר מלך בבל מרד אשר השביעו באלהים","ומי הוה שמן המשחה והתניא משנגנז ארון נגנז צנצנת המן וצלוחית שמן המשחה ומקלו של אהרן שקדים ופרחים","וארגז ששגרו פלשתים דורון לאלהי ישראל שנאמר (שמואל א ו, ח) ואת כלי הזהב אשר השיבותם לו אשם תשימו בארגז מצדו ומי גנזו יאשיה מלך יהודה גנזו שנאמר (דברי הימים ב לה, ג) ויאמר המלך אל הכהנים תנו את ארון הקדש","ואמר רבי אלעזר אתיא שם שם","אתיא דורות דורות","אתיא משמרת משמרת אמר רב פפא באפרסמא דכיא","ת\"ר מושחין את המלכים כמין נזר ואת הכהנים כמין כי אמר רב מנשיה כמין כי יוני תני חדא בתחלה מציק שמן על ראשו ואחר כך נותן לו שמן בין ריסי עיניו ותני אחריתי בתחלה נותן לו שמן בין ריסי עיניו ואחר כך מציק לו שמן על ראשו","תנאי היא איכא למאן דאמר משיחה עדיפא ואיכא למאן דאמר יציקה עדיפא מאי טעמא דמ\"ד יציקה עדיפא שנאמר (ויקרא ח, יב) ויצק משמן המשחה על ראש אהרן ומאן דאמר משיחה עדיפא קסבר שכן נתרבה אצל כלי שרת","והכתיב ויצק ולבסוף וימשח ה\"ק מה טעם ויצק משום וימשח אותו לקדשו","ת\"ר (תהילים קלג, ב) כשמן הטוב היורד על הראש וגו' כמין שתי טיפין מרגליות היו תלויות לאהרן בזקנו אמר רב כהנא תנא כשהוא מספר עולות ויושבות בעיקרי זקנו ועל דבר זה היה משה רבינו דואג שמא חס ושלום מעלתי בשמן המשחה","יצתה בת קול ואמרה (תהילים קלג, ג) כטל חרמון שיורד על הררי ציון מה טל אין בו מעילה אף שמן שיורד על זקן אהרן אין בו מעילה","ועדיין אהרן היה דואג שמא משה לא מעל ואני מעלתי יצתה בת קול ואמרה לו (תהילים קלג, א) הנה מה טוב ומה נעים שבת אחים גם יחד מה משה לא מעל אף אתה לא מעלת","ת\"ר אין מושחין את המלכים אלא על המעיין כדי שתימשך מלכותן שנאמ' (מלכים א א, לג-לד) ויאמר המלך (אל בניהו) וגו' והורדתם אותו על גיחון (וגו') ומשח אותו שם","אמר רב אמי האי מאן דבעי לידע אי משכא שתא אי לא מייתי שרגא בהלין עשרה יומין דבין ריש שתא ליומא דכיפורי וניתלי בביתא דלא נשיב זיקא אי משיך נהוריה נידע דמסיק שתיה","ומאן דבעי נעביד עיסקי ובעי דנידע אי מצלח עיסקי אי לא נירבי תרנגולא אי שמין ושפר נידע דמצלח","האי מאן דבעי ניפוק באורחא ובעי דנידע אי הדר לביתיה ניעול ניקום בביתא דבהתא אם חזי"],[[0,"וכי נס א' נעשה בו","שאתה מתמיה שאינו ספק אפילו לסוך אהרן ובניו כל ז' ימי המלואים כדמפרש בפ\"ק דיומא (דף ה.) שבעת ימים ימלא את ידכם (ויקרא ח׳:ל״ג) ואיתקש משיחה לריבוי דכתיב למשחה בהם ולמלא בם את ידם (שמות כ״ט:כ״ט):"],[1,"זה לי לדורותיכם","אלמא כולהו י\"ב לוגין דקיימי לעתיד לבוא:"],[3,"יהויקים","היה גדול מיהואחז ב' שנים דכתיב בו (מלכים ב כ״ג:ל״א) יהואחז בן עשרים ושלש שנה היה במלכו וג' חדשים מלך וביהויקים כתיב (שם) בן עשרים וחמש שנה היה במלכו נמצא יהויקים גדול מיהואחז ב' שנים כך שנויה בסדר עולם:"],[6,"בזמן ששלום בישראל","הוי המלכות ירושה ולא בעי משיחה אבל כי איכא מחלוקת לאו ירושה היא ובעי משיחה בתחלה:"],[7,"ולא מלכי ישראל","משבא דוד אבל שאול נמשח:"],[9,"ומפני מחלוקתו של יורם נמשח כו'","דבשלמא מלך בן מלך דבית דוד כי איכא מחלוקת נפקא לן מקראי דהדר למילתיה קמייתא למשיחה אבל מלכי ישראל לא חזו למשיחה כלל:"],[9,"באפרסמא דכיא","נמשח ולא בשמן המשחה:"],[10,"","ה\"ג [ואמר רבי] יוחנן הוא יהואחז צדקיהו הוא שלום:"],[12,"והא בדרי חשיב ליה","דחשיב שלישי ורביעי:"],[12,"דמלך יכניהו","בן יהויקים תחת יהויקים אביו קמי צדקיהו:"],[16,"שנאמר ואת כלי הזהב וגו'","מדכתיב בארגז מצדו אלמא כל היכא דהוי ארון הוי ארגז בהדיה וכי איגניז איגניז בהדיה:"],[16,"תנו את הארון","בבית אשר בנה שלמה כי אין לכם משא בכתף וגרסינן במסכת שקלים (פ\"ו ה\"א) אמר להם אם גלה עמכם לבבל שוב אין אתם מחזירין אותו בכתפיכם וגנזו:"],[17,"צנצנת אתיא שמה שמה","כתיב בארון (שמות ל׳:ו׳) אשר אועד לך שמה ובצנצנת כתיב (שם טז) ותן שמה מלא העומר מן:"],[18,"ושמן המשחה אתיא דורות דורות","מצנצנת:"],[19,"מקלו של אהרן אתיא משמרת משמרת","מצנצנת. כתיב במקל (במדבר י״ז:כ״ה) למשמרת לאות לבני מרי בצנצנת למשמרת לדורותיכם:"],[20,"כמו נזר","סביב על ראשו:"],[20,"כמין כי","אות יוונית ועשוי כזה x דמציק שמן על ראשו ואח\"כ בין ריסי עיניו ומצרפן באצבעו דרך הפדחת:"],[23,"מספר","מדבר. ל\"א מסתפר דשקיל במזייה:"],[23,"שמא מעלתי","ששמתי שם יותר מדאי:"],[25,"ואני מעלתי","שבגדי נהנים מריח השמן שבזקני:"],[26,"גיחון","מעיין קטן סמוך לירושלים ולא זהו גיחון הגדול היוצא מעדן:"],[28,"נייתי תרנגולתא","לשם כך:"],[29,"בביתא דבהתא","אפל במקצת:"]],[]],[["בבואה לבבואה דבבואה נידע דאתי לביתיה ולאו מילתא היא דילמא חלשא דעתיה ומתרע מזליה","אמר אביי השתא דאמרת סימנא מילתא היא יהא רגיל איניש למיכל ריש שתא קרא ורוביא כרתי סילקא ותמרי","א\"ל רב משרשיא לבניה כי בעיתו למיזל למגמר קמיה רבכון גרוסו מעיקרא מתני' והדר עולו קמי רבכון וכי יתביתו קמי רבכון חזו לפומיה דרבכון שנאמר (ישעיהו ל, כ) והיו עיניך רואות את מוריך וכי גריסיתו שמעתא גרוסו על מיא דכי היכי דמשכי מיא תמשוך שמעתכון","אקילקי דמתא מחסיא ולא אפדני דפומבדיתא טב גילדנא סריא למיכל מכותחא דרמי כיפי","(שמואל א ב, א) ותתפלל חנה ותאמר עלץ לבי בה' רמה קרני רמה קרני ולא רמה פכי דוד ושלמה שנמשחו בקרן נמשכה מלכותם שאול ויהוא שנמשחו מן הפך לא נמשכה מלכותם:","המפטם את הקטרת: ת\"ר המפטם את הקטרת ללמד בה או למוסרה לציבור פטור להריח בה חייב והמריח בה פטור אלא שמעל","ומי איכא מעילה והאמר ר\"ש בן פזי א\"ר יהושע ב\"ל משום בר קפרא קול ומראה וריח אין בהן משום מעילה","ריח אחר שתעלה תמרתו אין בו משום מעילה [שהרי] אין לך דבר אחר שנעשה מצותו ומועלין בו","אלמה לא והרי תרומת הדשן דנעשית מצותה ומועלין בה","משום דהוי תרומת הדשן ובגדי כהונה שני כתובים הבאים כאחד וכל שני כתובין הבאין כאחד אין מלמדים","הניחא לרבנן אלא לר' דוסא מאי איכא למימר דתניא (ויקרא טז, כג) והניחם שם מלמד שטעונין גניזה","רבי דוסא אומר כשירין הן לכהן הדיוט ומה תלמוד לומר והניחם שם שלא ישתמש בהן ביום הכפורים אחר","משום דהוי תרומת הדשן ועגלה ערופה שני כתובין הבאין כאחד וכל שני כתובין הבאין כאחד אין מלמדין תרומת הדשן מאי היא דתניא (ויקרא ו, ג) ושמו אצל המזבח מלמד שטעונין גניזה עגלה ערופה מאי היא דתניא (דברים כא, ד) וערפו שם את העגלה בנחל מלמד שטעונין גניזה","ולמ\"ד שני כתובין הבאים כאחד מלמדין הכא ודאי אין מלמדין משום דהוי תרי מיעוטי בתרומת הדשן כתיב ושמו הדין אין מידי אחרינא לא גבי עגלה ערופה כתיב הערופה ערופה אין מידי אחרינא לא","ת\"ר פיטום הקטרת הצרי והציפורן והחלבנה והלבונה משקל שבעי' של שבעים מנה מור וקציעה שיבולת נרד וכרכום משקל ששה עשר של ששה עשר מנה הקושט שנים עשר קילופה שלשה וקנמון תשעה בורית כרשינה תשעה קבין יין קפריסין סאין תלתא קבין תלתא אם אין לו יין קפריסין מביא חמר חיוריין עתיק מלח סדומית רובע מעלה עשן כל שהוא ר' נתן אומר אף כיפת הירדן כל שהוא","ואם נתן בה דבש פסלה חיסר אחת מכל סממניה חייב מיתה רש\"א הצרי אינו אלא שרף [הנוטף] מעצי הקטף בורית כרשינה ששפין בה את הציפורן כדי שתהא נאה יין קפריסין ששורין בו את הציפורן כדי שתהא עזה והלא מי רגלים יפין לה אלא שאין מכניסין מי רגלים למקדש","מסייע ליה לר' יוסי בר\"ח דאמר (שמות ל, לב) קדש היא קדש תהיה לכם כל מעשיה לא יהו אלא בקדש","מיתיבי המקדיש נכסיו והיו בה דברים הראויין לקרבנות הציבור ינתנו לאומנין בשכרן","הני דברים הראויין מאי נינהו אי בהמה וחיה תנא ליה אי יינות שמנים וסלתות תנא ליה אלא לאו קטרת","א\"ר אושעיא באותה הניתנת לאומנים בשכרן דתניא מותר הקטרת מה היו עושין בה היו מפרישין (ממנה) שכר האומנין ומחללין אותה על מעות האומנין ונותנין אותן לאומנין בשכרן וחוזרים ולוקחין אותה מתרומה חדשה","מתקיף לה רב יוסף הא בכולהו מותרות תני חוזרין ולוקחין אותה מתרומה חדשה והכא לא תני","אלא אמר רב יוסף באחד מסממני הקטרת","ת\"ר קטרת היתה נעשית שס\"ח מנה שס\"ה כנגד ימות החמה שלשה מנין יתירין שמהן מכניס כהן גדול מלא חפניו ביום הכיפורים והשאר ניתנת לאומנין בשכרן","כדתניא מותר הקטרת מה היו עושין בה מפרישין (ממנה) שכר האומנין ומחללין אותה על מעות האומנין ונותנין אותן לאומנין בשכרן וחוזרין ולוקחין אותה מתרומת הלשכה"],[[0,"בבואה לבבואה","צל לצלו:"],[0,"ולאו מילתא היא","דלא ליעביד איניש הכי דלמא הוי סימנא בישא ומצער נפשיה ומיתרע מזליה:"],[1,"קרא","דלעת:"],[1,"רוביא","תלתן. והני איכא דגדלי מהר ואיכא דמתקי:"],[3,"קלקי","אשפות:"],[3,"ולא על אפדני דפומבדיתא","שלסטין היו כדאמרינן בהעור והרוטב (חולין קכז.) פומבדיתאה אלוייך אשני אושפיזך:"],[3,"גילדנא סריא","דג קטן מוסרח כדאמרי' בפ\"ק דמועד קטן (דף יא.) כוורא סמוך למיסרחיה מעלי:"],[3,"מכותחא דרמי כיפי","אפילו כותח שהוא משובח וחזק שמשבר את האבן כששופכין הימנו ע\"ג האבן אעפ\"כ לא תאכלו הימנו כדאמרי' בפ' אלו עוברין (פסחים מב.) שלשה דברים נאמרו בכותח מטמטם את הלב כו':"],[3,"כיפי","סלע כדמתרגמינן סלע כיפא:"],[5,"ואם הריח בה","בקטרת של ציבור פטור:"],[6,"קול","הנהנה מקול הכנורות ונבלים של כלי שרת:"],[6,"ומראה","הנהנה ממראה יפה של היכל:"],[6,"וריח","הקטרת:"],[7,"ומשני ריח","דקאמר אין בו מעילה לאחר שעלתה תמרתו שנעשה מצוותו וכי קאמר מעל קודם לכן:"],[8,"תרומת הדשן","מועלין בה דכתיב ושמו דמשמע שם תהא גניזתו:"],[12,"שם את העגלה","שם תהא קבורתה לעולם:"],[13,"הערופה","משמע היא אין אחרינא לא:"],[14,"הצרי","שרף נטף כדמפרש לקמן שרף [הנוטף] מעצי הקטף ושרף היינו מידי דמנטף מן העץ וקורין גומ\"א:"],[14,"צפורן","שחלת דמתרגמינן טופרא שחלקה כצפורן:"],[14,"חלבנה","גלבנ\"א:"],[14,"שבולת נרד","חד הוא ובלעז שפיג\"א:"],[14,"קילופה","בשם וזהו ששמו קנמון:"],[14,"(ט' קבין)","סך הכל שס\"ח מנין:"],[14,"בורית","סאבו\"ן:"],[14,"כרשינא","הבא מאותו מקום. ל\"א עשב הנקרא אירב\"ה שנוטי\"א שעושין ממנו בורית שקורין ספוני מפי הרב הגדול:"],[14,"יין קפריסין","שבא ממקום ששמו קפרס. \u0003ע\"א בגליון\u0004 יין קפריסין שעושין מקפרא של אילן הוא ששמו קפרס כגון הצלף והקפרס מ\"ר:"],[14,"רובע","הקב:"],[14,"מעלה עשן","שם עשב:"],[14,"כיפת הירדן","עשב הגדל על שפת הירדן:"],[15,"פסלה","דכתיב כי כל שאור וכל דבש (ויקרא ב׳:י״א):"],[15,"חייב מיתה","כי עייל ביוה\"כ דכתיב (שם טז) ואל יבא בכל עת אל הקודש וגו' ולא ימות וגו' בזאת יבא אהרן וגו' וכי מעייל קטרת שלא כהלכתה ביאה ריקנית היא וחייב מיתה:"],[15,"רשב\"ג","לפרושי אתא:"],[15,"ששפין","מושחין:"],[15,"שתהא נאה","ששחורה היא:"],[15,"שתהא עזה","שיהא ריחה חזק:"],[15,"למקדש","שבעזרה היו מפטמין:"],[16,"מסייע ליה כו'","מדלא מפרש ליה (לברא בשעת שריית) סמנים ויתנו בה מי רגלים מסייע ליה דקאמר כל מעשיה בקדש בעזרה:"],[17,"המקדיש נכסיו","קיי\"ל סתם הקדשות לבדק הבית:"],[17,"והיו בהן דברים הראויין לקרבן ציבור","דקיי\"ל המקדיש נכסיו ויש בהן דבר הראוי למזבח אינו יוצא מידי מזבח לעולם הראוי ליחיד מוכרין אותו ליחיד הצריך קרבן והראוי לציבור א\"א להקריבו דבעי לקנותו מתרומת הקופות הילכך נותנין אותה לאומנין בשכרן ובגמרא מפרש באומני בית אבטינס שהיו נוטלין קטרת במס' שקלים בפרק התרומה מה היו עושין (פ\"ד ה\"ד):"],[18,"הא תנא להו","התם במסכת שקלים והני ראויין ליחיד כמו לצבור:"],[18,"בהמה וחיה","לאו דוקא:"],[18,"אלא לאו קטרת","דאינו ראוי אלא לציבור אלמא עושין קטרת מן החולין ובחוץ וקשיא לר' יוסי בר' חנינא:"],[19,"באותה הניתנת כו'","לעולם בקודש נעשית ולא הספיקו ללוקחה הימנו עד שהקדישה:"],[19,"מותר קטרת","שבכל שנה היה נשאר מאותן ג' מנים יתירין שכהן גדול מכניס ולא היה מקטיר אלא מלא חפניו ונשאר המותר ואותו מותר לא היה ראוי לשנה הבאה מניסן ואילך דניסן ראש השנה דתרומת שקלים דאמרה תורה חדש והבא קרבן מתרומה חדשה במסכת ראש השנה (דף ז.). ומה היו עושין בו:"],[19,"מפרישין","מהקדש בדק הבית את שכר האומנין המחזקים את בדק הבית:"],[19,"ומחללין","את מותר זה על (מותר) מעות דכל זמן שהיא בקדושתה אינן רשאין לתתה לאומנין דכל דבר שראוי למזבח אינו יוצא מידי מזבח לעולם:"],[20,"ל\"ג  תני רב יהודה  אלא ה\"ג בכולהו מותרין תני חוזרין כו' והכא לא תני","והא מדתני בכולהו מותרין הניתנין לאומנין חוזרין ולוקחין אותן כו' והכא לא תני הכי מכלל דלאו בקטרת גמורה קמיירי אלא בשנעשית חולין וקרי לה ראויין לקרבנות צבור ותיובתא דר' יוסי בר' חנינא:"],[21,"אלא אמר רב יוסף","מאי ראויין דקתני אחד מסממני הקטרת ולא קטרת פטומה:"],[22,"שס\"ח מנין","דהכי סליק חושבנא דסממנין דלעיל. בורית ויין ומעלה עשן לאו סממנין נינהו:"]],[]],[["תנו רבנן מותר הקטרת אחת לששים או לשבעים שנה היו מפטמין אותה לחצאין לפיכך יחיד שפיטם לחצאין חייב דברי רבן שמעון בן גמליאל שאמר משום הסגן","אבל שליש ורביע לא שמעתי וחכמים אומרים בכל יום מתקן במתכונתה והיה מכניס","מסייע ליה לרבא דאמר רבא שמן המשחה שפטמו לחצאין חייב דכתיב (שמות ל, לז) והקטרת אשר תעשה כל שתעשה והא אפשר דעבדה פרס בשחרית ופרס בין הערבים","ת\"ר היו מחזירין אותה למכתשת פעמים בשנה בימות החמה פזורה שלא תתעפש בימות הגשמים צבורה כדי שלא תפוג ריחה וכשהוא שוחק אומר הדק היטב היטב הדק דברי אבא יוסי בן יוחנן","ושלש מנין יתירין שמהן כ\"ג מכניס מלא חפניו ביוה\"כ נותן אותה למכתשת בערב יוה\"כ ושוחקן יפה יפה כדי שתהא דקה מן הדקה כדתניא (ויקרא טז, יב) דקה מה ת\"ל והלא כבר נאמר (שמות ל, לו) ושחקת ממנו הדק מה ת\"ל דקה כדי שתהא דקה מן הדקה","אמר מר כשהוא שוחק אומר היטב הדק הדק היטב מסייע ליה לר' יוחנן דאמר ר\"י כשם שהדיבור רע ליין כן הדיבור יפה לבשמים","א\"ר יוחנן י\"א סממנין נאמרו לו למשה בסיני אמר רב הונא מאי קראה (שמות ל, לד) קח לך סמים תרי נטף ושחלת וחלבנה הא חמשה וסמים אחריני חמשה הא עשרה ולבונה זכה חד הא חד סרי","ואימא סמים כלל נטף ושחלת וחלבנה פרט סמים חזר וכלל כלל ופרט וכלל אי אתה דן אלא כעין הפרט מה הפרט מפורש דבר שקיטר ועולה וריחו נודף אף כל דבר שקיטר ועולה וריחו נודף","וכ\"ת א\"כ לכתוב קרא חד פרטא לאיי מיצרך צריכי דאי כתב נטף ה\"א מין אילן אין אבל גידולי קרקע לא מש\"ה כתב ושחלת ואי כתב ושחלת ה\"א גידולי קרקע אין אבל מין אילן אימא לא משום הכי כתב נטף","וחלבנה לגופיה אתא מפני שריחה רע א\"כ מקח לך נפקא ליה","ואימא סמים בתראי תרין נינהו כסמים קדמאי א\"כ נכתוב סמים סמים בהדי הדדי וסוף נכתוב נטף ושחלת וחלבנה","דבי רבי ישמעאל תני סמים כלל נטף שחלת וחלבנה פרט סמים חזר וכלל כלל ופרט וכלל אי אתה דן אלא כעין הפרט מה הפרט מפורש דבר שקיטר ועולה וריחו נודף אף כל דבר שקיטר ועולה וריחו נודף","או אינו אלא כלל בכלל ראשון ופרט בפרט ראשון אמרת לאו הא אין לך עליך לדון בלשון אחרון אלא בלשון ראשון","אמר מר או אינו אלא כלל בכלל ראשון ופרט בפרט ראשון אמרת לאו הא אין עליך לדון מאי קושיא הכי קא קשיא ליה סמים בתראי תרי כי סמים קדמאי תרין הדר ושני כדשנין דא\"כ נכתוב קרא סמים סמים נטף ושחלת וחלבנה","ומאי פרט בפרט ראשון הכי קא קשיא ליה מיני אילנות ילפי מן נטף וגידולי קרקע ילפי משחלת ולילפי נמי מלבונה זכה דאייתי בחד צד דניתי דבר שריחו נודף ואע\"פ שאין קוטר ועולה","הדר אמר א\"כ נכתוב קרא ללבונה זכה במיצעי ותילף מינה","אי כתביה לבונה זכה במיצעי הויין תרי עשר אם כן נכתוב קרא לבונה זכה במיצעי וחלבנה לבסוף ריש לקיש אמר מגופה מה לשון קטרת דבר שקוטר ועולה","א\"ר חנא בר בזנא א\"ר שמעון חסידא כל תענית שאין בה מפושעי ישראל אינה תענית שהרי חלבנה ריחה רע ומנאה הכתוב עם סממני קטרת אביי אמר מהכא (עמוס ט, ו) ואגודתו על ארץ יסדה:","והסך בשמן המשחה: ת\"ר הסך בשמן המשחה לבהמה וכלים פטור לעובדי כוכבים ולמתים פטור בשלמא בהמה וכלים דכתיב (שמות ל, לב) על בשר אדם לא ייסך ובהמה וכלים לאו אדם הוא מתים נמי פטור דכיון דמית ליה מת מיקרי ולאו אדם אלא עובדי כוכבים אמאי פטור הא אדם נינהו","לאיי דכתיב (יחזקאל לד, לא) ואתן צאני צאן מרעיתי אדם אתם אתם קרויין אדם ואין העובדי כוכבים קרויין אדם","והכתיב (במדבר לא, מו) ונפש אדם ששה עשר אלף א\"ל ההוא לאפוקי בהמה","והכתיב (יונה ד, יא) ואני לא אחוס על נינוה וגו' ההוא לאפוקי בהמה","ואיבעית אימא כדקתני תנא קמיה דר\"א כל שישנו בסך ישנו בבל ייסך וכל שאינו בסך אינו בבל ייסך","תניא אידך הסך בשמן המשחה לבהמה וכלים לעובדי כוכבים ומתים פטור למלכים ולכהנים ר\"מ מחייב ור' יהודה פוטר וכמה יסוך ויהא חייב ר' מאיר אומר כל שהוא רבי יהודה אומר כזית והאמר ר\"י פטור כי פטר ר' יהודה גבי מלכים וכהנים גבי הדיוט מחייב","ר\"מ ור' יהודה במאי פליגי א\"ר יוסף בהא פליגי ר\"מ סבר על בשר אדם לא ייסך כתיב וכתיב (שמות ל, לג) ואשר יתן ממנו על זר מה סיכה כל שהוא אף נתינה כל שהוא","ורבי יהודה סבר ילפינן נתינה דעל זר מנתינה דעלמא מה נתינה דעלמא כזית אף נתינה דעל זר כזית אבל סיכה למימשח מלכים וכהנים דברי הכל כל שהוא","וא\"ר יוסף במאי פליגי רבי מאיר ורבי יהודה גבי מלכים וכהנים ר\"מ סבר ואשר יתן ממנו על זר כתיב ומלך וכהן השתא זרים נינהו ורבי יהודה סבר בעינן עד דאיכא זר מתחלתו ועד סופו ומלך וכהן מעיקרא לאו זרים הוו","א\"ר איקא בריה דרב אמי ואזדו לטעמייהו דתניא"],[[0,"אחת לששים או לשבעים שנה גרסינן היו מפטמין אותה לחצאין","שלא היה צריך לפטם אלא חצי שיעור משום דמותר דששים או שבעים שנה סלקי לחצי שיעור הקטרת פעמים לששים פעמים לשבעים או סמוך להם לפי שאין כל החפניים שוות:"],[1,"לשליש ולרביע לא שמעתי","שהיו משהין המותר שמונים שנים או צ' או ק' שלא הוצרכו לפטם אלא שליש או רביע ויחיד נמי שפיטם שליש או רביע פטור:"],[1,"במתכונתה","לישנא דקרא. אם היה רוצה לפטם הקטרת דבר יום ביומו עושה הילכך יחיד שלא פיטם אלא מנה חייב:"],[2,"","חצאין דרבא לאו דוקא אלא כל דראוי להקטיר:"],[3,"בזורה","מפזרה:"],[5,"היטב הדק הדק היטב","הממונה אומר כן לשוחק:"],[5,"דיבור רע ליין","במסכת מנחות בפרק כל הקרבנות (דף פז.) זרק הגיד של שמרים הגזבר הקיש שהגזבר מקיש בקנה למוציא היין ורומז לו ובלא דבור שרע הוא לנסכים ולא היה מדבר בפיו שהדבור רע ליין:"],[6,"י\"א סמנים","ולעיל חשבנו י\"א צרי צפורן חלבנה ולבונה מר קציעה שבולת נרד כרכום הרי ח' קושט קנמון קילופה הרי י\"א סממנים נאמרו לו למשה ולא ניקבו אלא ד' וכל י\"א דבעי ניתיב ובלבד שיהא קוטר ועולה כדדרשינן לקמן בכלל ופרט כדברי ר' ישמעאל:"],[7,"ואימא סמים כלל","כלומר ממאי דקרא לחושבנא אתא דילמא למידרש כלל ופרט [וכלל] לחוד הוא דאתא ולא למנין י\"א:"],[7,"קוטר","שמתמר ועולה כמקל ולא יפציל לכאן ולכאן:"],[8,"מין אילן","דהוא צרי:"],[9,"לגופה אתא","לאשמועינן דאע\"ג דריחיה רע משוינן ליה לקטרת:"],[9,"אם כן","דבכלל ופרט וכלל לחוד בעי למידרשיה לא נכתוב קרא סמים אלא קח לך הוה משמע כלל אלא הכי נקט ברישא סמים וכתיב נמי קח לך למידרש כלל ופרט וכלל לקוטר ועולה כדלקמן ולמנין י\"א:"],[11,"דבי רבי ישמעאל","נמי בעיא י\"א מדקתני או אינו כו' וליכא למידרשיה אלא כדדריש ליה ובעי קוטר ועולה:"],[12,"כלל בכלל ראשון","כולה מפרש לקמיה:"],[14,"ונילף נמי מלבונה כו'","והיינו דפריך או אינו אלא פרט אחרון דהיינו לבונה. בפרט ראשון מייתי נמי דדמי ליה ולמעוטי דבר [שאין] ריחו נודף ולא קוטר ועולה נאמרה לי כשאר פרטי קמאי דמייתי מאי דדמי ליה:"],[15,"אם כן","דכשאר פרטי מייתי ליה נכתביה במיצעי בהדי שאר פרטי קמאי והיינו דקאמר לאו:"],[16,"","וקפריך ליה הש\"ס הא לאו תירוצא הוא דאי כתבה ללבונה בהדי שאר פרטי בין שני הכללות הויין תרי סרי כגון סמים ב' ונטף ושחלת וחלבנה ולבונה הרי ו' וסמים כנגדן הרי י\"ב ולהכי לא כתבה בהדי פרט דלא תימא י\"ב בעינן ולעולם גמר מיניה:"],[16,"אם כן נכתביה במקום חלבנה","דנשמע מיניה די\"א הן ונשמע מיניה דאפילו אינו קוטר ועולה ונכתב חלבנה לבסוף דהא השתא מיהא לאו מידי גמרינן מיניה:"],[17,"ואגודתו","משמע שכולן ביחד אז על ארץ יסדה:"],[20,"לאפוקי בהמה","משום דכתיב בהמה בההוא עניינא דלא סגי דלא קרי להו אדם:"],[22,"כל שישנו בסך","כל שהוא עובר כשהוא סך את עצמו או אחרים שמצווה שלא יסוך משמן המשחה לזר:"],[22,"ישנו בבל ייסך","מצווים אחרים עליו שלא לסוכו:"],[23,"למלכים וכהנים גדולים","לאחר שנמשחו:"],[24,"מה סיכה כל שהוא","דלא אשכחן שיעור בסיכה אף נתינה כל שהוא אף על גב דנתינה בעלמא כזית כדמפרש לקמן:"],[25,"נתינה בעלמא כזית","דגמרינן מנתינה דונתן לכהן את הקדש דכתיב ביה אכילה (ויקרא כ״ב:י״ד) ואיש כי יאכל קדש וכל אכילה כזית:"],[26,"מעיקרא לאו זרים הם","דהא נמשחו מתחלה:"]],[]],[["בת כהן שנישאת לישראל ואכלה בתרומה משלמת הקרן ואינה משלמת את החומש ומיתתה בשריפה","ניסת לאחד מן הפסולין משלמת קרן וחומש ומיתתה בחנק דברי ר\"מ","וחכמים אומרים אחת זו ואחת זו משלמת הקרן ואינה משלמת החומש ומיתתה בשריפה","אמר רב יוסף מחלוקת בנתינת שמן המשחה ובשינויי דשנינן אבל נתינה דעלמא דברי הכל כזית","גופא תני תנא קמיה דר' אלעזר כל שישנו בסך ישנו בבל ייסך וכל שאינו בסך אינו בבל ייסך א\"ל שפיר קאמרת לא ייסך כתיב וקרי ביה לא יסיך","תני רב חנניה קמיה דרבא מנין לכהן גדול שנטל משמן המשחה שעל ראשו ונתן על בני מעיו מנין שהוא חייב שנאמר (שמות ל, לב) על בשר אדם לא ייסך א\"ל רב אחא בריה דרבא לרב אשי מ\"ש מהא דתניא כהן שסך בשמן של תרומה בן בתו ישראל מתעגל בו ואינו חושש","א\"ל התם (ויקרא כב, ט) ומתו בו כי יחללוהו כתיב כיון דחלליה הא איתחיל אבל גבי שמן המשחה כתיב (במדבר ו, ז) כי נזר גו' אלהיו עליו שמן משחה קרייה רחמנא דאע\"ג דאיתא עליו לא איתחיל:","על אלו חייבין על זדונו כו': קתני חוץ ממטמא מקדש וקדשיו ממאי מפיק ליה הכי קתני חוץ ממטמא מקדש וקדשיו שאין מביא אשם תלוי","וניתני נמי חוץ ממי שעבר עליו יום הכיפורים שאין מביא אשם תלוי אמר ר\"ל כי קתני היכא דאיתיה לחטאת ורחמנא פטריה עבר עליו יום הכיפורים ליתיה לחטאת דקא כפר ליה","ר' יוחנן אמר במבעט דקאמר אין יום הכפורים מכפר דאי הדר ביה בתר יום הכיפורים בעי לאיתויי אשם תלוי ור\"ל סבר מבעט נמי מכפר עליה יום הכיפורים","ובפלוגתא האומר לא יתכפר לי חטאתי אביי אמר אינה מכפרת רבא אמר מכפרת היכא דאמר לא תיקרב דכולי עלמא לא פליגי דלא מכפרת דכתיב יקריב אותו לרצונו כי פליגי דאמר תיקרב ולא תכפר אביי אמר אין מכפרת דהא אמר לא תכפר רבא אמר מכפרת כיון דאמר תיקרב כפרה ממילא אתי","והדר ביה רבא כדתניא יכול יהא יום הכיפורים מכפר על שבין ועל שאין שבין ודין הוא ומה חטאת ואשם מכפרין ויוה\"כ מכפר מה חטאת ואשם אין מכפרין אלא על השבין אף יוה\"כ אין מכפר אלא על השבין","לא אם אמרת בחטאת ואשם שאין מכפרין על המזיד כשוגג תאמר ביוה\"כ שמכפר על המזיד כשוגג והואיל ומכפר על המזיד כשוגג מכפר על שבין ועל שאין שבין ת\"ל (ויקרא כג, כז) אך חלק","מאי שבין ושאין שבין אלימא שבין שוגג לא שבין מזיד הא קתני לא אם אמרת בחטאת ואשם כו'","אלא כי הא דעולא א\"ר יוחנן אכל חלב והפריש קרבן והמיר דתו וחזר בו הואיל ונדחה ידחה","נהי דאידחי קרבן גברא בר כפרה הוא אלא שבין דאמר יכפר עלי חטאתי שאין שבין דאמר לא תכפר עלי חטאתי ש\"מ","ורמינהי יכול לא יהא יום הכפורים מכפר אלא על שנתענה בו ולא עשה בו מלאכה וקראו מקרא קודש לא נתענה בו ועשה בו מלאכה ולא קראו מקרא קודש יכול לא יהא יום כיפורים מכפר ת\"ל (ויקרא כג, כז) יוה\"כ הוא מ\"מ ותרוייהו סתם סיפרא הוא קשיין אהדדי","אמר אביי לא קשיא הא רבי אליבא דרבי יהודה הא רבי אליבא דידיה דתניא רבי אומר כל עבירות שבתורה בין עשה תשובה ובין לא עשה תשובה יוה\"כ מכפר","חוץ מפורק עול ומגלה פנים בתורה ומפר ברית בשר שאם עשה תשובה יוה\"כ מכפר ואם לאו אין יוה\"כ מכפר","רבא אמר הא והא רבי אליבא דנפשיה ומודה רבי בעבירות דיוה\"כ גופיה דלא מכפר דאי לא תימא הכי כרת דיוה\"כ לרבי כיון דבכל שעתא ושעתא מכפר היכי משכחת לה","ומאי קושיא דילמא דעבד עבידתא כולי ליליא ובהדי עמוד השחר מית דלא הוה יממא דלכפר ליה תינח כרת דליליא כרת דיממא היכי משכחת לה","ומאי קושיא דילמא בהדי דקאכל נהמא חנקתיה אומצא ומית דלא הוה ליה שהות ביממא דלכפר ליה אי נמי דעבד עבידתיה סמוך לשקיעת החמה אי נמי בהדי דעביד עבידתיה פסקיה מרא לשקיה ומית דלא הוה ליה שהות ביממא דלכפר ליה:","וחכמים אומרים אף המגדף כו': מאי אף המגדף שאין בו מעשה","רבנן שמעו לר' עקיבא דתני בעל אוב ולא תני ידעוני אמרו ליה מאי שנא דלא מייתי קרבן משום דלית ביה מעשה מגדף נמי לית ביה מעשה","ת\"ר מגדף מביא קרבן הואיל ונאמר בו כרת דברי ר\"ע ואומר (ויקרא כד, טו) ונשא חטאו וכללא הוא כל היכא דכתיב ביה כרת מייתי קרבן והא פסח ומילה דכתיב בהו כרת ולא מייתי קרבן"],[[0,"שנשאת לישראל. ואינה משלמת חומש","דלא זרה שהרי לא נתחללה שאם ימות בעלה ותנשא לכהן אוכלת או אם זרע אין לה הדרא לתרומה:"],[0,"משלמת כו'","אשם ל\"ג:"],[1,"ומיתתה בחנק","ורבי מאיר לטעמיה דאע\"ג דמעיקרא לאו זרה היא השתא מיהא זרה הויא:"],[2,"וחכמים","היינו רבי יהודה בר פלוגתיה:"],[2,"אחת זו כו'","דבעינן זר מתחלתו:"],[3,"ובשנויי דשנינן","דטעמיה דר\"מ משום דאיתקש לסיכה:"],[3,"אבל נתינה דעלמא","כגון לא יתן עליה לבונה דמנחת חוטא בכזית דילפינן מונתן לכהן את הקדש (ויקרא כ״ב:י״ד) והכי מפרשא בפרק כל המנחות באות מצה (מנחות נט:):"],[4,"לא ייסך כתיב","בשני יודין שדי חדא לתוך התיבה וקרי לא יסיך דמשמע מי שמצווה שלא יסיך לא לעצמו ולא לאחרים מצווה אחר עליו שלא לסוכו ועובד כוכבים לאו בר מצוה הוא:"],[5,"כהן שסך בן בתו ישראל מתעגל בו כו'","ופי' כהן שסך את עצמו שמן יכול בן בתו ישראל לבא להתעגל בו ואפילו גדול ושף עצמו באבי אמו ואינו חושש אלמא כיון דבטלה בהתירא בטלה והכי תניא בהדיא בתוספתא דמסכת תרומות (פ\"י ה\"י) סך כהן את עצמו שמן של תרומה ומביא בן בתו ישראל ומעגלו על גביו. ובן בתו ישראל דנקט משום דרגיל אצלו והוא הדין לאחריני:"],[7,"שאינו מביא אשם תלוי","שאין אשם תלוי בא אלא על ספק חטאת קבועה כדמפרש בפ' בתרא (לקמן כריתות כה.):"],[9,"מתני' במבעט","ביוה\"כ דאמר לא תכפר עליו משום הכי לא תני ליה:"],[11,"ודין הוא","שלא יכפר:"],[11,"אלא על השבין","דלרצונו בעינן:"],[12,"","אשם לאו דוקא נקט דהא אשכחן אשם אמזיד בפרק שני (לקמן כריתות ח:) ד' מביאין על הזדון:"],[12,"אך","בעשור לחדש יוה\"כ הוא:"],[12,"חלק","יום כפור לשבין ולא לשאינן שבין:"],[13,"מאי שבין","דקתני אין מכפרין אלא על השבין:"],[13,"הא קתני לא אם אמרת כו'","וא\"כ מאי קאמר היינו הך:"],[14,"אלא כי הא כו'","והיינו דקאמר חטאת אינו מכפר אלא על השבין ששבין משעת הפרשה עד שעת הקרבה ולא שהמיר דתו בינתיים והתם בעי למילף יוה\"כ דאם המיר דת קודם יוה\"כ וחזר בו אחר יוה\"כ תו לא מכפר עליה יום הכפורים אחר על עבירותיו שמקמי המרתו:"],[15,"אמאי נהי","דבקרבן אמרינן הואיל ונדחה לאחר הפרשה ידחה מעל המזבח אבל גברא לגבי יוה\"כ בר כפרה הוא כישראל מעליא:"],[16,"ורמינהו","אהא דתני לעיל יוה\"כ אינו מכפר אלא על השבין:"],[16,"מקרא קדש","בתקון סדר התפלה:"],[17,"","ה\"ג לא קשיא הא ר' יהודה הא רבי:"],[18,"פורק עול","של כל המצות:"],[18,"מגלה פנים","דורש באגדות של דופי כגון מנשה שהיה אומר מה היה לו למשה לומר ותמנע היתה פילגש:"],[19,"","ברייתא דקתני יוה\"כ מ\"מ רבי היא:"],[19,"מודה רבי בעבירות דיוה\"כ","דהא דקתני לא התענה בו מכפר אעבירות דכל השנה אבל ההיא עבירה דעינוי לא מכפר ואך חלק נמי דקתני לעיל בעבירות דיומיה קאמר:"],[19,"","יום הכפורים אינו מכפר אלא היום כדכתיב (ויקרא ט״ז:ל׳) כי ביום הזה:"],[19,"כרת","הולך ערירי בלא בנים ואם יש לו מתים:"],[21,"אי נמי דעביד עבידתא סמוך לשקיעת החמה","דלא הוה שהות לכפורי:"],[21,"א\"נ בהדי דעביד עבידתא פסקיה מרא דרפיק בה לשקיה ומית","מיד דלא הוה שהות לכפורי:"],[22,"","ה\"ג מאי אף המגדף:"],[23,"שמעו לר' עקיבא","דמתני' ר\"ע היא כדמפרש לקמן מגדף מביא קרבן דברי ר' עקיבא ואמרי אף מגדף נמי כידעוני. תימה לי ולר' יוחנן דאמר לעיל (כריתות דף ג:) הואיל ושניהם בלאו אחד נאמרו מאי אף דקתני במתניתין:"],[24,"ואומר חטאו ישא","מפרש לקמן דכרת דמגדף איירי בקרבן עבודת כוכבים:"]],[]],[["הכי קאמר מגדף מביא קרבן הואיל ובא בו כרת במקום קרבן דברי ר\"ע קסבר מיגו דבעי מכתב כרת בעלמא וכתיב כרת במקום קרבן שמע מינה מייתי קרבן","ואומר (במדבר ט, יג) חטאו ישא אתא לרבנן והכי קאמר ר\"ע לרבנן אמריתו מגדף לית ביה מעשה מהו מגדף מברך את השם אלא כרת דכתיב למאי אתא","אמרי ליה ליתן כרת למקלל דכתיב במקלל ((במדבר ט, יג) חטאו ישא האיש ההוא) וכתיב בפסח שני (במדבר ט, יג) חטאו ישא מה להלן כרת אף כאן כרת","ת\"ר (במדבר טו, ל) את ה' מגדף איסי בן יהודה אומר כאדם האומר לחבירו גירפתה הקערה וחיסרתה קסבר מגדף מברך את השם הוא","ר' אלעזר בן עזריה אומר כאדם האומר לחבירו גירפתה הקערה ולא חיסרתה קסבר מגדף היינו עובד ע\"ז","תניא אידך את ה' רבי אלעזר בן עזריה אומר בעובד ע\"ז הכתוב מדבר וחכמים אומרים לא בא הכתוב אלא ליתן כרת למברך השם:","\u0001מתני׳\u0002 יש מביאות קרבן ונאכל ויש מביאות קרבן ואינו נאכל ויש שאינם מביאות","מביאות קרבן ונאכל המפלת כמין בהמה חיה ועוף דר\"מ וחכ\"א עד שיהא בו מצורת אדם","המפלת סנדל או שיליא או שפיר מרוקם והיוצא מחותך וכן שפחה שהפילה מביאה קרבן ונאכל","ואלו מביאות ואינן נאכלות המפלת ואין יודע מה הפילה ושתי נשים שהפילו אחת ממין פטור ואחת ממין חובה א\"ר יוסי אימתי בזמן שהלכו זה למזרח וזה למערב אבל אם היו שתיהן עומדות שתיהן מביאות קרבן ונאכל","אלו שאין מביאות המפלת שפיר מלא מים מלא דם מלא גנינים המפלת כמין דגים וחגבים ושקצים ורמשים המפלת יום ארבעים ויוצא דופן ר' שמעון מחייב ביוצא דופן:","\u0001גמ׳\u0002 שפחה מנלן דת\"ר (ויקרא יב, ב) בני ישראל אין לי אלא בני ישראל גיורת ושפחה מנין ת\"ל (ויקרא יב, ב) אשה","מאי וכן שפחה ס\"ד אמינא כי אמרינן כל מצות שהאשה חייבת בה עבד חייב בה ה\"מ בדבר ששוה בין איש ובין אשה אבל יולדת דבנשים איתא באנשים ליתא אימא לא תחייב שפחה אהכי תנא שפחה:","אלו מביאין קרבן כו': מאי עבדין מייתין תרוייהו חד קרבן ודאי וחטאת עוף ספק ומתני","ומי אית ליה לר' יוסי תנאה והתנן רבי שמעון אומר מביאות שניהן חטאת אחת רבי יוסי אומר אין שניהן מביאות חטאת אחת אלמא לר' יוסי לית ליה תנאה","אמר רבא מודה ר' יוסי במחוסר כפרה וכן כי אתא רבין אמר ר' יוחנן מודה רבי יוסי במחוסר כפרה","מ\"ט התם בעי גברא ידיעה דכתיב (ויקרא ד, כג) או הודע אליו חטאתו הילכך לא מתיין ומתני אבל הכא כי מתיין נשים קרבן לאישתרויי באכילת קדשים","כדתני סיפא דההיא רבי יוסי אומר כל חטאת שהיא באה על חטא אין שתים מביאות אותה:","אלו שאין מביאות כו' ר' שמעון מחייב ביוצא דופן: מ\"ט דר\"ש אמר ר\"ל אמר קרא (ויקרא יב, ה) ואם נקבה תלד לרבות לידה אחרת מאי היא יוצא דופן","ורבנן מ\"ט א\"ר מני בר פטיש (ויקרא יב, ב) אשה כי תזריע וילדה עד שתלד ממקום שמזרעת:","\u0001מתני׳\u0002 המפלת לאור שמונים ואחד ב\"ש פוטרין מן הקרבן וב\"ה מחייבין","אמרו ב\"ה לב\"ש מ\"ש אור שמונים ואחד מיום שמונים ואחד אם שיוה לו לטומאה לא ישוה לו לקרבן","אמרו להם ב\"ש לא אם אמרתם במפלת יום שמונים ואחד שכן יצאה לשעה שהיא ראויה להביא בה קרבן תאמר במפלת לאור שמונים ואחד שלא יצאה לשעה שהיא ראויה להביא בה קרבן","אמרו להן ב\"ה והלא המפלת יום שמונים ואחד שחל להיות בשבת תוכיח שלא יצאה לשעה שהיא ראויה להביא בהו קרבן וחייבת קרבן","אמרו להן ב\"ש לא אם אמרתם יום שמונים ואחד שחל להיות בשבת שאף על פי שאינן ראוי לקרבן יחיד ראוי לקרבן ציבור תאמר במפלת לאור שמונים (יום) ואחד שאין הלילה ראוי לא לקרבן יחיד ולא לקרבן ציבור","והדמים אינן מוכיחים שהמפלת בתוך מלאת דמיה טמאים ופטורה מן הקרבן:"],[[0,"אתיא לרבנן","(רבנן קאמרי ליה הגירסא הכתובה בספרים אינה כפי שיטת הש\"ס וכך היא בעיני) והכי קאמרי ליה רבנן לר\"ע אמרת מגדף מביא קרבן הואיל ונאמר בו כרת במקום קרבן מי סברת מגדף דקרא היינו מברך את השם מגדף היינו עובד ע\"ז והאי דקתני במתני' וחכ\"א אף המגדף כו' הכי קאמרי אף המגדף דידך אף מברך את השם שאתה קורא אותו מגדף:"],[1,"אלא כרת במברך את השם מנא להו","במברך את השם כתיב איש כי יקלל אלהיו ונשא חטאו (ויקרא כ״ד:ט״ו) ונאמר בפסח (במדבר ט׳:י״ג) חטאו ישא האיש ההוא מה להלן כרת אף כאן כרת והכי נמי איכא דדריש ליה בפסחים בפרק מי שהיה טמא (פסחים דף צג:) ודרשי הכי וחדל לעשות הפסח ראשון דהא קרבן ה' לא הקריב במועדו חטאו ישא ולא נאמר כרת דמגדף במקום קרבן ולא גמרינן ליה אלא מכרת דפסח שאינה בת חטאת דמצות עשה היא. ור\"ע אית ליה כרת בשני ומוקי לחטאו ישא בפסח שני וגמר לה ממגדף וסבר מגדף היינו מברך את השם ובפסחים (שם) נמי איכא דדריש ליה הכי:"],[3,"גירפת","ר' מתחלפת בד'. הנחת את הקערה מן התבשיל וחסרת גם את העץ. קסבר מגדף היינו מברך את השם ומילתא רבה עבד דפשט ידו בעיקר:"],[4,"ולא חסרת קסבר היינו עובד עבודת כוכבים","כגון משורר ומזמר לעבודת כוכבים דלאו מילתא רבה היא כולי האי:"],[7,"מתני' כמין בהמה חיה ועוף","מפרש טעמא במסכת נדה בפרק המפלת (נדה כב:) הואיל ונאמרה בו יצירה כאדם:"],[8,"סנדל","ולד הוא אלא שנפחתה צורתו:"],[8,"שיליא","נמי אמרינן במסכת נדה בהמפלת (נדה דף כו.) אין שיליא בלא ולד. ושפיר היינו עור הולד מרוקם שיש בתוך השפיר צורת איברים קטנים ובמס' נדה מפרש לה בהמפלת:"],[8,"וכן שפחה","כנענית ובגמ' פריך למה לי למתניי':"],[9,"ואין ידוע מה הפילה","אם צורת אדם וחייבת או דגים וחגבים ופטורה:"],[9,"מביאה קרבן","שתי תורים [א' לעולה וא' לחטאת ועל של] עולה מתנה עלה אם מין חובה ילדה תהא לחובתה ואם לאו תהא עולת נדבה אבל חטאת לא מצי לאתנויי דאין חטאת נדבה ומחייב בספק ואינו נאכל דשמא לאו בת קרבן היא ומליקתה כנבילה בעלמא ומשום חולין על המזבח לא איכפת לן דכיון דאין למזבח אלא דמה לא חשיבא אכילה ובמסכת נזיר (דף כט.) ילפינן דחטאת העוף באה על הספק:"],[9,"וכן שתי נשים שהפילו","במחבואה:"],[9,"אחת מין פטור","דגים וחגבים:"],[9,"ואחת מין חובה","סנדל או שיליא ואין ידוע אי זו הפילה פטור ואי זו הפילה חובה מביאות כל אחת שתי תורים כמו שפירשתי ואינו נאכל:"],[9,"אימתי","אינו נאכל בזמן שהלכה כו' שאינן יכולות להתנות שהביאו קיניהן לכהן והלכו לדרכן:"],[9,"אבל אם שתיהן עומדות כו'","בגמ' מפרש מאי עבדן:"],[10,"גנינין","גוונים:"],[10,"","(כמין דגים וחגבים):"],[10,"המפלת יום ארבעים","במסכת נדה בפ' המפלת (נדה דף ל.) עד שיעברו מ' יום להריון הוי מיא בעלמא:"],[11,"","גמ' ושפחה מנלן דת\"ר דבר אל בני ישראל אשה כי תזריע:"],[12,"מאי וכן שפחה","הא פשיטא לן דכל מצוה שהאשה חייבת בה עבד חייב בה דגמרי לה לה כתיב באשה (דברים כ״ד:א׳) וכתב לה ספר כריתות וכתיב בשפחה או חפשה לא נתן לה:"],[13,"מאי עבדן","לרבי יוסי מתיין תרוייהו חד קרבן בין שתיהן יקנו חטאת העוף חדא ודאי עולת העוף תביא כל אחת ודאי ובתנאי שאם אינה חייבת תהא נדבה אבל חטאת העוף לא מצי למימר תהא נדבה דאין חטאת נדבה ולהכי מייתו חטאת העוף ויקנוהו בין שתיהן ומתנין אם אני חייבת יהא חלקך מחול לי ואם את חייבת יהא חלקי מחול לך וממ\"נ הויא מליקתה כשרה:"],[14,"ר\"ש אומר כו'","בפרק דם שחיטה לקמן (כריתות דף כג.):"],[15,"מודה רבי יוסי","דמתני' בארבעה מחוסרי כפרה דלא מייתי קרבן לשום חטאת אלא לאשתרויי בקדשים:"],[16,"התם","גבי חטאת חלב בפרק דם שחיטה גברא בעי ידיעה שידע שחטא ואי לא מייתי כל חד אשם תלוי ולא חטאת בשותפות:"],[17,"דקתני סיפא דההיא","בפ' דם שחיטה (שם) כל חטאת שהיא באה על חטא אלמא באה על חטא דוקא נקט:"],[18,"ואם נקבה תלד","הוה ליה למכתב ואם נקבה היא:"],[20,"מתני' לאור פ\"א","שילדה נקבה לאור פ\"א שהיתה ראויה למחר להביא כפרתה הפילה:"],[20,"ב\"ש פוטרין מן הקרבן","מלידה ב' אע\"ג דלאחר מלאת הוא הואיל ולילה הוא ולא יצאה שעה ראויה לקרבן דלילה מחוסר זמן קרבן הוא דכתיב (ויקרא ז׳:ל״ח) ביום צותו הילכך לענין קרבן כתוך מלאת דמי:"],[21,"מ\"ש אור פ\"א מיום פ\"א","דודאי חייבת כדמפרש לקמן בפ' ארבעה מחוסרי כפרה (כריתות דף ט.):"],[21,"אם שיוה לו לטומאה","שהרי אתם מודים שמשקיעת החמה של יום פ' כלו ימי טוהר שלה ואם ראתה בליל פ\"א טמאה:"],[25,"והדמים","שאתה אומר אם שוה לו לטומאה כו' אינן מוכיחין לקרבן שהרי המפלת תוך מלאת דמיה טמאין מפני הלידה ואינה חייבת קרבן שני:"]],[]],[["\u0001גמ׳\u0002 תניא אמרו להן ב\"ה לב\"ש הרי הוא אומר (ויקרא יב, ו) לבת לרבות אור שמונים ואחד","ר' הושעיא הוה שכיח קמיה דבר קפרא שבקיה ואתא קמיה דרבי חייא יומא חד פגע ביה בעא מיניה זב שראה ג' ראיות בליל ח' מה ב\"ה אומרים בדבר זה","טעמייהו דב\"ה במפלת בלילה משום דכתיב לבת אבל זב שראה ג' ראיות בליל ח' פטרי דלא מייתרי קראי או דלמא לא שנא","א\"ל בר קפרא מה בבלי אומר בדבר זה אישתיק רבי הושעיא לא אמר כלום א\"ל בר קפרא צריכין לדברי עייא נחזור על הראשונות הרי הוא אומר לבת לרבות אור שמונים ואחד","נימא כתנאי זב שראה ג' ראיות בליל ח' תני חדא מביא ותניא אידך אינו מביא מאי לאו תנאי היא דהא דתניא מביא קסבר לילה אין מחוסר זמן והדתני אין מביא קסבר לילה מחוסר זמן","אמר רב הונא בר אחא א\"ר אלעזר הני תנאי סברי לילה מחוסר זמן והא דתניא מביא בזב בעל ב' ראיות והדתניא אין מביא בזב בעל ג' ראיות","זב בעל ב' ראיות מאי למימרא הא קמ\"ל דוקא ראה בליל ח' אבל ביממא דז' לא קסבר כל ראייה שסותרת אין מביאה לידי קרבן","אמר רבא אמאי אוקימתא להא דתניא אין מביא בזב בעל ג' ראיות ליתנייה גבי חמשה מביאין קרבן אחד על עבירות הרבה לא פסיקא דא\"ר יוחנן ראה אחת בלילה וב' ביום מביא ב' בלילה ואחת ביום אין מביא","אמר רב יוסף תדע דאחת בלילה וב' ביום מביא דהא ראייה ראשונה שכבת זרע בעלמא ואילו חזי תרתין אחרנייתא מצטרפי להו","אמר רב ששת בריה דרב אידי מידי איריא ראייה ראשונה של זב חזייה בזמן חיובא אחת בלילה כיון דלאו בזמן חיובא חזייה אי לאו דאשמעינן רבי יוחנן דמצטרף ה\"א לא תצטרף","ומי א\"ר יוחנן לילה מחוסר זמן","והאמר חזקיה נטמא ביום מביא בלילה אין מביא ור' יוחנן אמר אפי' בלילה מביא","כי קא\"ר יוחנן ב' בלילה ואחת ביום אין מביא לדברי האומר מחוסר זמן","לדברי האומר פשיטא ראה אחת בלילה וב' ביום איצטריכא ליה מהו דתימא כיון דלאו בזמן חיובא קחזי ליה לא תצטרף קמ\"ל:","\u0001מתני׳\u0002 האשה שיש עליה ספק ה' לידות וספק ה' זיבות מביאה קרבן אחד ואוכלת בזבחים ואין השאר עליה חובה ה' זיבות ודאות וה' לידות ודאות מביאה קרבן אחד ואוכלת בזבחים והשאר עליה חובה","מעשה שעמדו קינין בירושלים בדינר זהב אמר רבן שמעון בן גמליאל המעון הזה לא אלין הלילה עד שיהיה בדינרין בסוף נכנס לב\"ד ולמד האשה שיש עליה ה' לידות ודאות ה' זיבות ודאות מביאה קרבן אחד ואוכלת בזבחים ואין השאר עליה חובה ועמדו קינין ביום ההוא ברבעתים:","\u0001גמ׳\u0002 ת\"ר ה' לידות ודאי ה' זיבות ספק או ה' לידות ודאי וה' לידות ספק מביאה ב' קינין אחת על הודאי ואחת על הספק של ודאי נאכלת והשאר עליה חובה של ספק אין נאכלת ואין השאר עליה חובה","ר' יוחנן בן נורי אומר על ודאי תאמר על האחרונה ותפטר של ספק אם יש ודאי ביניהן תאמר על הודאי ותפטר ואם לאו תאמר על אחד מהן ותפטר ר\"ע אומר בין על הודאי בין על הספק תאמר על אחת מהן ותפטר","א\"ל רב נחמן בר יצחק לרב פפא אימא לך משמיה דרבא הני תנאי במאי פליגי דר' יוחנן בן נורי מדמי להון לחטאת דמאן דחייב ה' חטאות עד דמייתי כולהון וסוף מכפר ליה ה\"נ ל\"ש","ור\"ע מדמי להון לטבילין דמאן דמחייב ה' טבילות כיון דטביל חדא זימנא איטהר ה\"נ ל\"ש","א\"ל רב פפא אי ס\"ד ר' יוחנן בן נורי לחטאת מדמי להן אמאי של ספק תאמר על אחת מהן ותפטר אילו מאן דמחייב"],[[1,"גמ' שבקיה","ר' אושעיא לבר קפרא:"],[1,"בעא מיניה","רבי אושעיא לבר קפרא:"],[1,"בליל ח'","לזיבה ראשונה ולמחר היה ראוי לקרבן:"],[1,"מה ב\"ה כו'","מי מייתי ב' קרבנות אי לא:"],[3,"בבלי","רבי חייא עלה מבבל כדאמרי' התם (סוכה דף כ.) בתחלה נשתכחה תורה מישראל עלה הלל הבבלי ויסדה וחזרה ונשתכחה עלו בני הגולה ויסדוה ומאן נינהו יהודה וחזקיה בני רבי חייא:"],[3,"עייא","ר' חייא ובלשון גנאי קאמר ליה:"],[3,"","(הדר בעא מיניה ר' אושעיא מבר קפרא):"],[3,"נחזור על הראשונות","כמו אמר מר. לעיל הרי הוא אומר כו' ומיבעיא לר' אושעיא טעמייהו דב\"ה משום או לבת או משום דסברי לילה אינו מחוסר זמן:"],[4,"והא דתניא אינו מביא קרבן [קסבר] לילה מחוסר זמן","וטעמייהו דב\"ה משום או לבת:"],[5,"זב בעל שתי ראיות","שזיבה ראשונה בת שתי ראיות היתה:"],[5,"בת ג'","הלכך כיון דלא יצאת שעה הראויה לקרבן כולה חדא זיבה אריכתא היא:"],[7,"ליתנייה","בפ' שני (לקמן כריתות דף ט.) גבי ה' מביאין קרבן אחד כו' כי היכי דקתני נזיר שנטמא טומאות הרבה:"],[7,"לא פסיקא ליה","כיון דזמנין דאראיות דלילה נמי מיחייב כגון ראה אחת בליל ח' ושתים ביום המחרת:"],[8,"שכבת זרע בעלמא הוא","דאין לה אלא טומאת ערב בעלמא כדתניא זאת תורת הזב ואשר תצא ממנו שכבת זרע זב בראיה ראשונה הקישו לבעל קרי במס' נדה (דף לה.) ואמרו נמי במגילה (דף ח.) שתים לטומאה וג' אף לקרבן אבל חדא ראייה אין לה אלא טומאת ערב:"],[10,"ומי א\"ר יוחנן כו'","דקאמר ב' בלילה ואחת ביום כו':"],[11,"נטמא","נזיר ביום ח' שראוי לקרבן מביא ב' קרבנות:"],[11,"בליל","ח' אינו מביא דלענין קרבן טומאה אריכתא היא דלילה מחוסר זמן:"],[14,"","\u0003מתני'\u0004 ספק זיבה כגון [טועה] שראתה ג' ימים ואינה יודעת אם בימי נדותה אם בימי זיבה מביאה קרבן ואינו נאכל:"],[14,"","ספק לידה כגון שהפילה ואין ידוע מה:"],[14,"האשה שיש עליה ה' ספקות של לידה או ה' של ספק זיבה מביאה קרבן אחד","חטאת העוף הבאה על הספק:"],[14,"ואוכלת בזבחים","שהרי הקרבן הזה לטהרה בא והרי הוא כטבילה אם נטמאת האשה כמה טומאות טבילה אחת עולה לכולן אף קרבן זה כן:"],[14,"ואין השאר עליה חובה","לא הצריכוה חכמים להביאן שאף האחת בקושי התירו להקריבה ספק מליקת חולין למזבח שאם לא כן אין לה תקנה ליטהר בקדשים:"],[14,"ה' לידות ודאות או ה' זיבות ודאות מביאה קרבן אחד ואוכלת בזבחים","כמו שפירשתי:"],[14,"והשאר עליה חובה","כדאמרינן לקמן בפ' שני (כריתות ד' ט:) יכול תביא על הלידה שלפני מלאת ועל הלידה שלאחר מלאת קרבן אחד לשניהם ת\"ל זאת:"],[15,"קינין","שני קינין ד' תורין:"],[15,"בדינרי זהב","בשני זהובין קן לדינר זהב:"],[15,"המעון הזה","שבועה:"],[15,"נכנס לב\"ד ללמוד כו'","אע\"פ שהיקל על דברי תורה עת לעשות לה' הוא שאלמלי לא ימצאו יחדלו מלהביא אפילו אחד ויאכלו בקדשים בטומאת הגוף:"],[15,"קינין ברבעתים","ב' קינין בשני רביעי דינר כסף. ל\"א רבעתים לשון חצי הוא:"],[16,"גמ' ה\"ג בתוספתא ה' לידות ודאי וה' לידות ספק כו' ר' יוחנן בן נורי אומר על הודאי","חיישינן לפשיעה דאי אמרת תביא על אחת מהן שמא יש אשה שתלד לידה אחת ודאית ואינה רוצה להביא קרבן שתאמר והלא אשתקד היו עלי ה' לידות ודאות ולא הבאתי קרבן על ד' מהן ועכשיו אני מביאה ור\"ע סבר כיון דלא אכלה אשתקד בלא שום קרבן לא פשעה:"],[16,"תאמר על האחרונה","אני מביאה ותפטר על השאר. ר\"ע אומר תאמר על אחת מהן ואינה צריכה לומר על האחרונה ותפטר על השאר:"],[17,"ועל הודאי תאמר על האחרונה ותפטר","עכשיו מחיוב שאר קרבנות ואוכלת בזבחים היום ולמחר תקריב שאר קרבנות:"],[17,"אם יש ודאי ביניהן","ממין הספק דאמר על הודאי כדי שתיעשה ודאי ותהא נאכלת ותפטר לגמרי כדפרישית במתני' דבקושי התירו להקריב ספק:"],[17,"על אחת מהן","ואפילו על הראשונה:"],[17,"בין ודאי כו'","אינה צריכה לומר על האחרונה אני מביאה: בדר\"ע ל\"ג ותפטר:"],[18,"ועד דמייתי כולהון","לא מכפרת אם הביא חטאת ראשונה עדיין חטאים האחרים עומדין אף כאן אם הביאה על הראשונות עדיין טומאה האחרונה במקומה ולא טהרה לאכול בקדשים לפיכך תאמר על האחרונה וטהרה והראשונות תביא לאחר זמן:"],[19,"מאן דמחייב ה' טבילות","אפי' אמר על הראשונה אני טובל טהר מכל טומאה:"]],[]],[["חמש אשמות תלויין כי מייתי חד מי מיפטר והתניא זה הכלל כל שחלוקין בחטאות חלוקין באשמות","אלא דכולי עלמא לטבילות מדמי להון ובחוששין לפשיעה קמיפלגי רבי יוחנן בן נורי סבר חיישינן לפשיעה ורבי עקיבא סבר לא חיישינן לפשיעה:","\u0001הדרן עלך שלשים ושש\u0002","מתני׳ \u0001ארבעה\u0002 מחוסרי כפרה וארבעה מביאין על הזדון כשוגג","ואלו הן מחוסרי כפרה הזב והזבה והיולדת והמצורע","רבי אליעזר בן יעקב אומר גר מחוסר כפרה עד שיזרוק עליו הדם נזיר ליינו ותגלחתו וטומאתו:","\u0001גמ׳\u0002 מאי שנא זב וזבה דמני להון בתרין משום דחלוקה טומאתו דזב לא מטמא באונס וזבה לא מטמאה בראיות כבימים","דתניא (ויקרא טו, ב) מבשרו ולא מחמת אונסו (ומי טמא) בראיות כבימים דתניא תלה הכתוב את הזכר בראיות ואת הנקבה בימים וזבה מטמאה באונס ולא מטמאה בראיות כבימים","מצורע ומצורעת נמי חלוקה טומאתן דמצורע טעון פריעה ופרימה דכתיב (ויקרא יג, מה) בגדיו יהיו פרומים וראשו יהיה פרוע ואסור בתשמיש המטה","ומצורעת אינה טעונה פריעה ופרימה דתניא אין לי אלא איש אשה מנין כשהוא אומר (ויקרא יג, מה) והצרוע הרי כאן שנים","אם כן מה ת\"ל איש נתקו הכתוב מענין של מעלה לענין של מטה לומר איש פורע ופורם ואין האשה פורעת ופורמת ומותרת בתשמיש המטה שנאמר (ויקרא יד, ח) וישב מחוץ לאהלו שבעת ימים ולא מחוץ לאהלה","הלכך נמנינהו בתרין זב וזבה עיקר טומאתן חלוקה מצורע ומצורעת אין עיקר טומאתן חלוקה האי והאי כגריס הוא:","ר\"א בן יעקב אומר גר מחוסר כו': ות\"ק מאי טעמא לא תני גר כי קתני מדעם דמישרי למיכל בקדשים גר כי קא מייתי קרבן לאכשורי נפשיה למיעל בקהל","ונזיר מאי טעמא לא תני סוף סוף נזיר נמי כי מייתי קרבן לאישתרויי למישתי יין דחולין הוא","ור\"א דקתני נזיר למישרי נפשיה ניתני נמי נזיר טמא כי קא מייתי קרבן למיחל עליה נזירות בטהרה הוא","תנו רבנן גר מעוכב לאכול בקדשים עד שיביא קינו הביא פרידה אחת שחרית אוכל בקדשים לערב כל הקינין שבתורה אחד חטאת ואחד עולה כאן שתיהן עולות","הביא חובתו מן הבהמה יצא עולה ושלמים יצא מנחה ושלמים לא יצא לא אמרו קן אלא להקל","מאי שנא מנחה ושלמים דלא יצא דכתיב (במדבר טו, יד) כאשר תעשו כן יעשה מה אתם עולה ושלמים אף גר עולה ושלמים","א\"כ חובתו אחת מן הבהמה לא תיסגי עליה בגוויה דהכתיב כאשר תעשו כן יעשה אר\"פ יש לומר לעוף איתרבי לעולת בהמה לא כל שכן","אי הכי אפילו מנחה נמי מיעט קרא כן","ועוף היכא איתרבי דת\"ר כאשר תעשו כן יעשה מה אתם עולה ושלמים אף הוא עולה ושלמים שנא' (במדבר טו, טו) ככם כגר מנין לרבות את העוף ת\"ל (במדבר טו, י) אשה ריח ניחוח לה' איזה דבר שכולו לה' הוי אומר עולת העוף"],[[1,"ה' אשמות תלויין [כו'] חוששין לפשיעה","אם לא הצריכוה לומר על האחרונה אני מביאה תהא סוברת שנפטרה בקרבן זה ולא יהו השאר עליה חובה ותפשע ולא תביאם וכי מצרכת לה לומר על האחרונה אני מביאה ידעה דהשאר עליה חובה אבל על הספק שאין השאר עליה חובה לא מזקקינן לה לומר על האחרונה אני מביאה:"],[1,"ורבי עקיבא לא חייש לפשיעה","ואני שמעתי חוששין לפשיעה שמא תפשע ולא תביא אפילו קרבן אחד ותאכל זבחים בטומאת הגוף וקשיא לי בגוה טובא חדא אפשר היא מתיא קרבנה ומשום דלא מצרכת לה לומר על האחרונה ליחוש שמא תחזור בה ועוד אי חיישת להכי כל שכן דעל הספק היא מקילה ואמאי לא מצרכת לה לומר על האחרונה ליחוש שמא תחזור בה ולא תביאנו ואכלה בקדשים בספק טומאת הגוף:"],[3,"מתני' ארבעה מחוסרי כפרה","מביאין חטאת ולא על חטא אלא לאכול בקדשים:"],[5,"עד שיזרוק עליו הדם","דבעי איתויי קרבן כדמפרש לקמיה:"],[5,"ונזיר ליינו ולתגלחתו ולטומאתו","ונזיר מחוסר כפרה שכל זמן שלא כיפר אסור ביין ובתגלחת ולטמא למתים:"],[6,"גמ' דמני להו בתרין","דחשיב זב וזבה בתרין מהנך מחוסרי כפרה:"],[7,"מבשרו","מכח אברו ומתוקף יצרו:"],[7,"","זבה מטמאה באונס כדאמרינן בפרק בנות כותים (נדה דף לו:) וכי יזוב זוב דמה (ויקרא ט״ו:כ״ה) הרי אונס אמור:"],[7,"ומטמא בראיות","אם ראה ג' ביום אחד:"],[7,"כבימים","אם ראה ג' ימים רצופין כדמפרש בב\"ק בפרק ב' (דף כד.) זבה לא מטמאה אלא בימים:"],[9,"הרי כאן שנים","דצרוע משמע בין זכר בין נקבה מטמאין בנגעים:"],[10,"ה\"ג א\"כ מה ת\"ל איש לענין של מטה","דלטהרת טומאת נגעים א\"א שהרי נאמר והצרוע:"],[10,"איש","דכתיב במקרא העליון לענין מקרא התחתון שפריעה ופרימה כתובה באחרונה לומר לך איש פורע ופורם:"],[11,"עיקר טומאתן חלוקה","זה בראיות ובימים וזו בימים ולא בראיות:"],[11,"כגריס","דזהו שיעור נגע כחצי פול:"],[13,"סוף סוף נזיר","מ\"ט לא תני הא לאישתרויי הוא: ומשני ההוא לאו לאשתרויי בקדשים אלא ביין דחולין הוא וכי קחשיב כפרה דמעכבא שום אכילה דקדשים:"],[15,"גר מעוכב לאכול בקדשים","דאפילו לרבנן סבירא להו כר\"א בן יעקב דאמר לאישתרויי הוא דמייתי והא דלא תני ליה משום דלא מיקרי מחוסר כפרה:"],[15,"הביא פרידה אחת","גוזל אחד שחרית:"],[15,"אוכל בקדשים לערב","ובלבד שיביא השניה כדאמרינן לקמן להביא פרידה אחת א\"א:"],[15,"כאן שתיהן עולות","כדאמרן לקמן בגמ' (כריתות ט.) מדור המדבר:"],[16,"הביא חובתו מן הבהמה","עולה אחת יצא:"],[16,"עולה ושלמים","לאו דוקא אלא משום דבעי למיתני מנחה ושלמים לא יצא:"],[17,"מה אתם עולה ושלמים","דכתיב (שמות כ״ד:ה׳) וישלח את נערי בני ישראל וגומר:"],[18,"לא תיסגי בגוה","עד דמייתי שלמים:"],[20,"שכולו לה'","שאין כהן נהנה ממנו דבעולת בהמה איכא עורה לכהנים אבל עולת העוף ליכא מידי:"]],[]],[["יכול שאני מרבה אפילו מנחה ת\"ל כן","תניא אידך (במדבר טו, יד) יעשה אשה ריח ניחוח לה' שומע אני כל שעולה לאשים אפילו מנחה ת\"ל (במדבר טו, יד) כאשר תעשו כן יעשה מה אתם מיני דמים אף הם מיני דמים","אי מה אתם עולה ושלמים אף הם עולה ושלמים ת\"ל (במדבר טו, טו) ככם כגר יהיה לכם הקשתיו ולא (לדבר אחר) לקרבנותיכם","רבי אומר ככם כאבותיכם מה אבותיכם לא נכנסו לברית אלא במילה וטבילה והרצאת דם אף הם לא יכנסו לברית אלא במילה וטבילה והרצאת דמים","להביא פרידה אחת א\"א שלא מצינו בכל התורה כולה: לא אמרו קן אלא להקל עליו:","ולא והתניא (ויקרא א, ה) והקריבו מה ת\"ל לפי שנאמר בתורים (ויקרא א, ה) והקריב שומע אני האומר הרי עלי עולת העוף לא יפחות משני פרידין ת\"ל והקריבו אפי' פרידה אחת חובה מיהא לא אשכחן","והאיכא יולדת דמתיא בן יונה או תור לחטאת משום דאיכא כבש בהדה","אמר מר מה אבותיכם לא נכנסו לברית אלא כו' בשלמא מילה דכתיב (יהושע ה, ה) כי מולים היו כל העם היוצאים אי נמי מהכא (יחזקאל טז, ו) ואעבור עליך ואראך מתבוססת בדמיך ואומר לך בדמיך חיי וגו'","הרצאת דמים דכתיב (שמות כד, ה) וישלח את נערי בני ישראל אלא טבילה מנלן דכתיב (שמות כד, ו) ויקח משה חצי הדם ויזרק על העם ואין הזאה בלא טבילה","אלא מעתה האידנא דליכא קרבן לא נקבל גרים אמר רב אחא בר יעקב (במדבר טו, יד) וכי יגור אתכם גר אשר בתוככם וגו'","ת\"ר גר בזמן הזה צריך שיפריש רובע לקינו אר\"ש כבר נמנה עליו רבן יוחנן בן זכאי ובטלה מפני התקלה אמר רב אידי בר גרשום אמר רב אדא בר אהבה הלכה כר\"ש","ואיכא דמתני לה על הדא דת\"ר גר תושב מותר לעשות מלאכה בשבת לעצמו כישראל בחולו של מועד","ר\"ע אומר כישראל בי\"ט ר' יוסי אומר גר תושב עושה בשבת לעצמו כישראל בחול רש\"א ואחד גר תושב ואחד [עובד כוכבים] עבד ואמה התושבים עושין מלאכה בשבת לעצמן כישראל בחול:","\u0001מתני׳\u0002 אלו מביאין על הזדון כשוגג הבא על שפחה ונזיר שנטמא ושבועת העדות ושבועת הפקדון","חמשה מביאין קרבן אחד על עבירות הרבה וחמשה מביאין קרבן עולה ויורד אלו מביאין קרבן אחד על עבירות הרבה הבא על שפחה ביאות הרבה ונזיר שנטמא טומאות הרבה:","\u0001גמ'\u0002 הבא על השפחה מנלן","דת\"ר (ויקרא יט, כב) וכפר עליו הכהן באיל האשם על חטאתו אשר חטא מלמד שמביא קרבן אחד על עבירות הרבה (באיל האשם) (ויקרא יט, כב) ונסלח לו מחטאתו אשר חטא לעשות (שוגג כמזיד):","נזיר שנטמא: מנלן","דכתיב (במדבר ו, ט) וכי ימות מת עליו בפתע פתאום פתע זה שוגג וכן הוא אומר (במדבר לה, כב) אם בפתע בלא איבה הדפו פתאום זה אונס וכן הוא אומר (במדבר יב, ד) ויאמר ה' פתאום אל משה","תניא אידך פתאום זה מזיד וכן הוא אומר (משלי כב, ג) ערום ראה רעה ונסתר ופתאים עברו ונענשו","נכתוב קרא פתאום דמשמע שוגג ומשמע מזיד ומשמע אונס מזיד ואונס כדאמר ומשמע נמי שוגג דכתיב (משלי יד, טו) פתי יאמין לכל דבר ולא נכתוב קרא פתע","אי כתב קרא פתאום דמשמע שוגג ומשמע מזיד ומשמע אונס ה\"א כי מייתי קרבן בשוגג מידי דהוי אתורה כולה אבל אונס ומזיד אימא לא","כתב רחמנא פתע דשוגג הוא לגלויי עליה דפתאום דאונס ומזיד הוא דאפי' הכי חייב רחמנא:","שבועת העדות: מנלן דת\"ר בכולן נאמר ונעלם כאן לא נאמר ונעלם לחייב על (השוגג כמזיד):","שבועת הפקדון: מנלן יליף תחטא תחטא משבועת העדות:","חמשה מביאין קרבן אחד על עבירות הרבה: קתני הבא על השפחה ביאות הרבה מנלן","דת\"ר וכפר עליו הכהן באיל האשם על חטאתו אשר חטא מלמד שמביא קרבן אחד על עבירות הרבה (באיל האשם) ונסלח לו מחטאתו אשר חטא לעשות מזיד כשוגג","והא קרא כי כתיב במזיד כתיב אלא אימא לעשות שוגג כמזיד","בעא מיניה רבי חנינא טירנאה מר' יוחנן הבא על חמש שפחות חרופות בהעלם אחת מהו חייב על כל אחת ואחת או אינו חייב אלא אחת אמר ליה חייב על כל אחת ואחת","מאי שנא מחמש העלמות בשפחה אחת א\"ל אין שפחה אחת גופין מוחלקין ה' שפחות גופין מוחלקין","ומנלן דגבי שפחה גופין מוחלקין אמר ליה לאו אמרת גבי עריות ואשה לחלק על כל אשה ואשה גבי שפחה נמי כתיב (ויקרא יט, כ) אשר ישכב את אשה שכבת זרע"],[[2,"לכם הקשתיו","במקצת ולא כל קרבנותיכם ומיהו עולה מסתבר דמכשרא דכולה כליל:"],[3,"מילה וטבילה והרצאת דמים","מפרש לקמן:"],[5,"והקריבו","גבי עולת העוף דנדבה בויקרא:"],[5,"והקריב","משמע קרבן שלם:"],[7,"כל העם היוצאים","בשעת יציאתן מלו:"],[7,"בדמיך","דם פסח ודם מילה:"],[8,"הרצאת דמים","זריקת דמים על המזבח:"],[9,"וכי יגור אתכם גר וגו' לדורותיכם","אע\"ג דליכא מקדש:"],[10,"צריך שיפריש רובע דינר לקינו","דלכשיבנה בית המקדש יביא קן דאמרי' לעיל דצריך קרבן וקרבן בפחות מרובע לא אפשר להפריש דאין מצוי קן בפחות מרובע כדאמרינן במתני' ועמדו קינין ברבעתים אבל פחות לא אפשר:"],[10,"מפני התקלה","שלא יהנה ממנו:"],[11,"גר תושב","שקבל עליו שלא לעבוד עבודת כוכבים כגון נעמן:"],[11,"עושה מלאכה בשבת לעצמו","בדבר האבד כישראל בחולו של מועד:"],[12,"כישראל בי\"ט","אוכל נפש:"],[13,"מתני' שבועת העדות","קרבן עולה ויורד:"],[13,"שבועת הפקדון","אשם:"],[16,"","\u0003גמ' \u0004מדמצי למיכתב על חטאתו ולישתוק וכתיב על חטאתו אשר חטא לאתויי חטאים הרבה:"],[16,"ונסלח לו מחטאתו אשר חטא","להכי הדר כתיב תו ב' זימני חטא בר מב' זימני קמאי לעשות מזיד כשוגג:"],[18,"ויאמר ה' פתאום","בע\"כ יצאו שלשתן ע\"פ הדיבור:"],[19,"ופתאים עברו ונענשו","היינו מזיד דאין עונש אלא על המזיד:"],[21,"ה\"א","אע\"ג דפתאום דעלמא משמע אונס ושוגג ומזיד פתאום דנזיר ודאי מדמייתי קרבן עלה ש\"מ דשוגג הוא מידי דהוה אכל התורה דרוב קרבנות על השגגה הן באין להכי כתיב פתע דהוי שוגג לגלות עליה דפתאום:"],[23,"בכולן","בכל המביאין עולה ויורד שבאותה פרשה כגון מטמא מקדש ושבועת בטוי דכתיבי בהו שבועת העדות:"],[27,"לעשות מזיד כשוגג והא עיקר קרא במזיד כתיב","דכתיב (ויקרא י״ט:כ׳) בקורת תהיה והיינו מלקות ואין מלקות אלא במזיד ועליה קאמר והביא את אשמו ותו למה לי ונסלח לו מחטאתו לרבות מזיד:"],[27,"אלא אימא לעשות שוגג כמזיד","דמהו דתימא דוקא אמזיד מביא ולא אשוגג קא משמע לן ונסלח לו מחטאתו אשר חטא דלהכי כתיב חטא ארבע זימני תרי למילף קרבן אחד על עבירות הרבה ותרי לעשות שוגג כמזיד:"],[28,"בהעלם אחת","כלומר קודם שילקה ויביא קרבן על זו חזר ובעל זו:"],[30,"לאו אמרת גבי עריות","בפ\"ק (לעיל כריתות ב:) ואל אשה לחלק על כל אשה ואשה כו':"]],[[0,"יכול שאני מרבה אפי' מנחה","פירוש מנחת נסכים שהיא כולה לאישים:"],[2,"ת\"ל ככם כגר","מצי למימר כדלעיל השתא לעוף איתרבאי:"],[7,"דכתיב כי מולים היו כל העם","פירוש שמלו עצמם ביציאתם ממצרים ואע\"פ שאותן שהיו נימולים בימי אברהם לא מלו אותם ביציאת מצרים מ\"מ מעיקרא כשמלו עצמן מלו ליכנס בברית המקום וליבדל משאר אומות וגם כי עתה טבלו:"],[8,"וישלח את נערי בני ישראל ויעלו עולות","ואע\"ג דפליגי התם בפרק פרת חטאת (זבחים קטו) איכא דאמרי עולת ראייה הואי ואיכא דאמרי עולת תמיד [הואי] י\"ל שהקריבו הרבה עולות:"],[12,"(לעיל. גבי) גר תושב עושה מלאכה לעצמו","מכאן קשה לפ\"ה דפרק החולץ (יבמות מח:) דקאמר וינפש בן אמתך והגר זה גר תושב פי' בקונט' שקיבל עליו שלא לעבוד עבודת כוכבים ומחלל שבת כעובד כוכבים והכא קאמר גר תושב עושה מלאכה לכן י\"ל דההיא מיירי לענין שלא לעשות מלאכה עבור רבו אבל לעצמו שרי (פסק) מכאן פסק ר\"י שמותר להניח לעובד כוכבים לעשות מלאכתו בשבת בבית ישראל עבור עצמו:"]]],[["והיא שפחה לחלק על כל שפחה ושפחה:","נזיר שנטמא טומאות הרבה: מאן תנא","אמר רב חסדא רבי יוסי בר' יהודה היא דאמר נזירות דטהרה משביעי הוא דחיילא עליה ומשכחת לה כגון שנטמא בשביעי וחזר ונטמא בשביעי וכיון דלא יצא שעה הראויה להקריב בה קרבן אינו חייב אלא קרבן אחד","דאי רבי כיון דאמר רבי נזירות דטהרה עד שמיני לא חיילא עליה אי דנטמא בשביעי וחזר ונטמא בשביעי כולה טומאה אריכתא היא","אי דנטמא בשמיני וחזר ונטמא בשמיני כיון דיצאת שעה שראוייה להקריב קרבן מחייב על כל אחת ואחת אלא ש\"מ ר' יוסי ברבי יהודה","ומאי דרבי יוסי בר' יהודה דתניא (במדבר ו, יא) וקדש את ראשו ביום ההוא ביום הבאת קרבנותיו דברי רבי","ר\"י בר' יהודה אומר ביום תגלחתו:","\u0001מתני'\u0002 המקנא לאשתו ע\"י אנשים הרבה ומצורע שנתנגע נגעים הרבה","הביא ציפרין ונתנגע לא עלו לו עד שיביא חטאתו רבי יהודה אומר עד שיביא אשמו:","\u0001גמ׳\u0002 מנלן דכתיב (במדבר ה, כט) זאת תורת הקנאות תורה אחת לקנויין הרבה:","מצורע שנתנגע נגעים הרבה כו': מנלן דכתיב (ויקרא יד, לב) זאת תורת המצורע תורה אחת למצורעים הרבה:","הביא ציפרין ונתנגע לא עלו לו עד שיביא חטאתו רבי יהודה אומר עד שיביא אשמו:","והאמרת אין מביא אלא קרבן אחד חסורי מחסרא והכי קתני הביא ציפרין ונתנגע אין מביא אלא קרבן אחד ולאקבועי בעניות ובעשירות לא מיקבע עד שיביא חטאת רבי יהודה אומר עד שיביא אשמו","תנן התם מצורע שהביא אשמו והעשיר הכל הולך אחר חטאת דברי ר\"ש רבי יהודה אומר הכל הולך אחר אשם תניא ר\"א בן יעקב אומר הכל הולך אחר ציפרין","אמר רב יהודה אמר רב שלשתן מקרא אחד דרשו (ויקרא יד, לב) אשר לא תשיג ידו בטהרתו ר\"ש סבר דבר המכפרו ר' יהודה סבר דבר המכשירו ר' אליעזר בן יעקב אומר דבר הגורם לו טהרה ומאי נינהו ציפרין:","\u0001מתני'\u0002 האשה שילדה ולדות הרבה והפילה בתוך שמונים נקבה חזרה והפילה בתוך שמונים נקבה","והמפלת תאומים","ר' יהודה אומר מביאה על הראשון ואינה מביאה על השניה מביאה על השלישי ואינה מביאה על הרביעי:","\u0001גמ׳\u0002 מנלן דתני תנא קמיה דרב ששת (ויקרא יב, ז) זאת תורת היולדת לזכר ולנקבה מלמד שמביאה קרבן אחד על ולדות הרבה יכול אף על הלידה ועל הזיבה ת\"ל זאת","קתני יכול על הלידה ועל הזיבה אינה מביאה אלא קרבן אחד אלא מעתה אכלה דם וילדה ה\"נ דאין מביאה אלא קרבן אחד","אימא הכי יכול על הלידה שלפני מלאת ועל הלידה שלאחר מלאת ת\"ל זאת:","הפילה בתוך שמונים כו': כשתמצי לומר לדברי ר' יהודה ולד ראשון גורם ומולד ראשון מונה לדברי חכמים ולד שני גורם ומולד שני מונה","כשתמצי לומר פשיטא הכי איתא מפלת תאומים איצטריך ליה ס\"ד אמינא במפלת תאומים מודה רבי יהודה לרבנן קמ\"ל","איבעיא להו"],[[2,"נזירות טהרה משביעי חיילא","הלכך כי נטמא תרי זימני בשביעי הוו להו טומאות הרבה דהא אתחלא נזירות דטהרה ולענין קרבן לא מחייב אלא אחד דלא יצא אדם זה לשעה ראויה לקרבן:"],[5,"וקידש את ראשו","שנזירות טהרה חלה עליו. יום תגלחתו כו':"],[7,"מתני' המקנא לאשתו כו'","מביא מנחת שעורים אחת על כולן כשהוא משקה:"],[7,"שנתנגע נגעים הרבה","כגון שספר שבעה ולא הספיק להביא קרבנותיו עד שנתנגע וכן שניה וכן שלישית:"],[8,"הביא צפרין","אותן שתי צפרין חיות אחת לשחיטה ואחת לשילוח ולאו קרבן נינהו:"],[8,"לא עלו לו","קס\"ד דהאי לא עלו לו משמע שצריך לחזור ולהביא לבסוף שתי צפרין לכל נגע ונגע עד שיביא חטאת אבל הביא צפרין וחטאתו ונתנגע אין צריך להביא לכשיטהר על נגע ראשון:"],[12,"גמ' והאמרת אינו מביא אלא קרבן אחד","על נגעים הרבה אלמא חד צרעת אריכתא היא ואמאי מחייבת ליה לאתויי צפרים אכל נגע:"],[12,"ולאקבועיה בעניות כו'","וה\"ק ולא עלו הצפרין ליקבע בעניות ובעשירות דאם היה עני בשעת הבאת צפרין והעשיר צריך להביא קרבן עשיר ואם היה עשיר והעני מביא עני בדלות עד שיביא חטאתו דבתר חטאת אזלינן בין בעניות בין בעשירות:"],[14,"אשר לא תשיג ידו","בשעת טהרתו יביא בעניות אע\"פ שהעשיר:"],[14,"ר\"ש סבר","האי טהרתו היינו דבר המכפר חטאו דעל ז' דברים נגעים באין במסכת ערכין (דף טז.):"],[14,"דבר המכשירו","אשם שמדמו נותנין על בהונותיו מכשירו בקדשים:"],[14,"צפרין","גורמין לו תחלת טהרתו שמדם הצפור מזין עליו:"],[15,"מתני' האשה שילדה ולדות","וקא מפרש כיצד כגון שהפילה לתוך פ' של נקבה וכו' כגון שטבלה לאחר שבועיים דטומאה ושמשה ונתעברה והפילה נקבה לאחר מ' של יצירת הולד דהיינו נ\"ד ללידה ראשונה וחזרה והפילה לסוף נ\"ד של זו. ולהכי נקט נקבה דבזכרים ליכא למימר הכי דאי הפילה בתוך מ' דזכר מיא בעלמא הוא האי שני דאין הולד נוצר עד יום מ':"],[16,"והמפלת תאומים","אפילו זכרים כגון שנתעברה ג' והפילה אחד לאחר מ' והשני נשתהה ויצא בתוך ימי טוהר הראשון ושלישי בתוך ימי טוהר דשני מביאה קרבן אחד על האחרון ופטורה:"],[17,"ר' יהודה","פליג בין אולדות בין אתאומין ואמר מביאה קרבן אחד על הראשון על הולד הראשון ולא על השני מפני שנולד בתוך מלאת של ראשון ומביאה על השלישי משום דהוא לא נולד תוך מלאת דלא חשבינן מלאת לשני דכמאן דליתיה דמי הואיל ונולד תוך מלאת של ראשון ושלישי הוי תחילת לידה ואינה מביאה קרבן על הרביעי הואיל ונולד תוך (מ') מלאת של שלישי אבל שלישי לא נולד תוך מלאת דראשון דהא עברו ימי טומאה דראשון (ויצירת שני וטומאתו ויצירת שלישי) דהוי טפי מפ' לראשון וגבי תאומים נמי דקפליג ר' יהודה כגון שנולד שלישי לאחר מלאת דראשון ועל מלאת דשני לא איכפת לו דכמאן דליתיה דמי:"],[18,"גמ'","כל היכא דכתיב תורת משמע רבים:"],[18,"יכול על הלידה ועל הזיבה","קרבן אחד כגון שראתה ג' ימים בימי זיבה והפסיקה רביעי וילדה בחמישי הרי זו יולדת בזוב כדאמרי' בנדה (דף לו:) דבעי שתפסוק מן הזוב סמוך ללידה ואם לא פסקה ודאי דם מחמת הולד ואינה יולדת בזוב:"],[19,"אלא מעתה","מהיכא תיסק דעתיה דעל הלידה ועל הזיבה קרבן אחד דאיצטריך קרא למעוטי הא ודאי אכלה חלב וילדה מי סלקא אדעתין דמביאה קרבן אחד על הלידה ועל החלב וגבי זיבה נמי מה ענינה אצל לידה:"],[20,"זאת","משמע על לידה אחת מביאה [קרבן אחד על ולדות הרבה] הא אחר מלאת חייב על כל אחת ואחת:"],[21,"לדברי ר' יהודה","מדלא חשיב מלאת לשני ש\"מ ולד ראשון גורם לקרבן ומולד ראשון מונה פ' יום הילכך שלישי שנולד אחר מלאת דראשון ולד מעליא הוא לקרבן:"],[21,"לדברי חכמים","דלא מחייבי אלא חד אבתרא מחייבי ליה דסבירא להו ולד שני כלומר אחרון גורם לקרבן וראשון דלא מלו ימי טוהר דיליה לית ליה קרבן ומשני מנינן מלאת עד שלישי ומשלישי עד רביעי ולא מטמא מלאת אלא עד בתרא:"],[22,"פשיטא דהכי איתא","דאי לאו הכי מאי טעמייהו:"],[22,"מפלת תאומים איצטריכא ליה","משום מפלת תאומים איצטריך ליה תנא לאשמועינן דבמפלת תאומים נמי פליג רבי יהודה דמהו דתימא בתאומים מודה דחדא לידה אריכתא היא הואיל ועיבורן כאחת ואית ליה נמי מלאת לשני ושלישי לאו בר קרבן הוא:"]],[[0,"והיא שפחה לחלק על כל שפחה ושפחה","תימה דהכא בעינא לחלק אע\"ג דגופין מוחלקין והתם פרק אותו ואת בנו (חולין פב:) לא תשחטו ביום אחד משמע דפשיטא דחייב גבי שחטה ואח\"כ שחט בניה משום דגופין מוחלקין אע\"ג דליכא קרא וכן לקמן בפרק אמרו לו (כריתות דף יז.) דאמרי שבתות כי גופין דמיין:"],[10,"תורה אחת למצורעים הרבה","ובתורת כהנים מפיק ליה מדכתיב וכבשה אחת מלמד שמביא אחת על נגעים הרבה ומוזאת תהיה תורת דריש תורה אחת לכל מצורעין לפי שמצינו שחלק הכתוב בטומאותיהם ובשבועותיהם:"],[22,"מפלת תאומים איצטריכא ליה","סד\"א במפלת תאומים מודה רבי יהודה לרבנן וקשה דא\"כ מפלת תאומי' למאן קתני לה אי רבנן פשיטא ואי לר' יהודה הא מודה לרבנן צ\"ע:"]]],[["בטומאה מה לי א\"ר יהודה מי אמרינן עד כאן לא קא\"ל ר' יהודה ולד שני כמאן דליתיה דמי אלא לענין קרבן כיון דלא יצאה שעה שראויה להקריב בה קרבן הואיל וכן ולד שני כמאן דליתיה דמי אבל לענין טומאה וטהרה אימא סבירא ליה כמאן דאיתיה דמי ומפסקא טומאה דשני וממלא יומי טהרה דראשון והדר מונה יומי טהרה לשני","או דלמא לרבי יהודה חומרא הוא דאית ליה אבל הכא קולא הוא וקולא לית ליה","אמר רב הונא מסורא ת\"ש יולדת שוחטין וזורקין עליה ביום מ' לזכר וביום שמונים לנקבה","עד כאן טמאה היא ואמר רב חסדא הא מני ר' יהודה הוא דאמר ולד שני כמאן דליתיה דמי","ואי אמרת בטומאה ס\"ל לר' יהודה ולד שני כמאן דאיתיה דמי היכי שחטינן עלה ביום מ' לאורתא נמי לא מציא אכלה אלא לאו ש\"מ לטהרה ולטומאה ס\"ל לרבי יהודה ולד שני כמאן דליתיה דמי","לעולם אימא לך לטומאה ולטהרה סבירא ליה לרבי יהודה דולד שני כמאן דאיתיה דמי וכי תניא ההיא בפסח הבא בטומאה","ומי אכלה והתנן פסח הבא בטומאה לא יאכלו ממנו זבים וזבות נדות ויולדות","ההיא לא אכלי כי לא טבילן כי תניא ההיא דשוחטין וזורקין עליה דהא טבלה א\"ה משמיני דיליה הוא דחזיא","משמיני לא חזיא קסבר טבול יום דזב כזב דמי","אי הכי ביום מ' נמי לא חזיא לאיי ביום מ' חזיא קסבר מחוסר כפורים דזב לאו כזב דמי","ולרבא דאמר מחוסר כפורים דזב כזב דמי הא מתנייתא היכי מתרץ לה אמר רב אשי רבא מתרץ לה ביום מ' ליצירת זכר וביום שמונים ליצירת נקבה ור' ישמעאל היא דאמר לזכר מ' ואחד לנקבה שמונים ואחד","סוף סוף תיפוק לי דטמאה היא משום נדה בלידה יבישתא אי הכי מאי למימרא מהו דתימא אי אפשר לפתיחת הקבר בלא דם קמ\"ל דאפשר לפתיחת הקבר בלא דם","א\"ר שמעיה ת\"ש (ויקרא יב, ה) ששים יכול בין רצופין בין מפוזרין ת\"ל יום מה יום רצוף אף ששים כולן רצופין מני אלימא רבנן מי אית לרבנן מפוזרין","אלא לאו רבי יהודה היא ומדקא יהיב לה ששים רצופים בהדי הדדי ש\"מ חומרא אית ליה לר' יהודה קולא לית ליה","לא לעולם רבנן היא והכא במאי עסקינן ליולדת זכר מתוך שמונים של נקבה","סוף סוף שלמין יומי דקדמאה ועד כאן דבתראה לא שלמין דהא רבנן לולד שני מנו אלא משכחת לה לרבנן ביולדת תאומים נקבה קדמייתא וזכר בתראה וכגון דילידתיה לזכר בתראה בעשרים ליומי טהרה דבעיא מינקט ליה שבעה יומי טומאה דלידה תאומים נקבה","וה\"ק יכול היכא דילדה תאומים נקבה מעיקרא וזכר לבסוף תפסיק טומאה דלידה במיצעי ונימני לה ששה וששים מפוזרין ת\"ל יום מה יום כולו רצוף אף ששים כולם רצופין","אמר אביי ת\"ש (ויקרא יב, ד) שלשים יכול בין רצופין בין מפוזרין ת\"ל יום מה יום כולו רצוף אף שלשים רצופין מני הא אלימא רבנן ומי אית להו לרבנן"],[[0,"בטומאה מה לי א\"ר יהודה","מי אית ליה מלאת לשני לענין ימי טוהר:"],[0,"לא קאמר ר\"י אלא לענין קרבן","הוא דלית ליה מלאת לשני הואיל ובתוך זמן קרבן ראשון נולד:"],[0,"אבל לענין טומאה וטהרה","מונה לעצמו לבד אותן של ראשון ונקראין ימי הטומאה על שמו ומסולקין ממלאת של ראשון:"],[0,"ומיפסקא טומאה דשני","את ימי טוהר של ראשון וממלא ימי טוהר דראשון דהא מלאת דראשון א\"א דלא מלינן ליה לר' יהודה דהוא עיקר והדר מני שמונים ימים ימי טוהר לשני:"],[1,"או דלמא חומרא אית ליה","לאפושי לקרבנות ויהיב ימי טומאה וימי טהרה לשני משעת לידתה ואילך ומעוכבת לאכול בקדשים עד מלאת ימי טומאה וטהרה אבל קולא לית ליה להיות ימי הטומאה נקראין על שמו דשני להיות גומרין השלמה לראשון תחתיהן דלהאי מילתא נמי כמאן דליתיה דמי וימי טוהר דראשון לא ממלינן ותימלי לשני ימי טוהר אחריני תחתיהן דהא מילתא קולא היא להאריך טוהר דמיה וקולא לית ליה והא ליכא למימר דליהוי שני בטל לגמרי מתורת מלאת דהא נמי קולא היא דהא אם כן מכשרת לאכול טבולת יום בקדשים ועל כרחיך בעית למיתב ימי טוהר לשני הלכך אי יהבת לראשון השלמת ימי טוהר קולא היא:"],[2,"שוחטין","את הפסח וזורקים עליה ביום ארבעים לזכר. קס\"ד ביום מ' דימי טוהר דזכר:"],[3,"והוינן בה עד כאן טמאה היא","דמחוסרת כפרה:"],[3,"אמר רב חסדא הא מני ר' יהודה היא דאמר ולד שני כמאן דליתיה דמי","ומוקים הא מתניתא ביולדת תאומים היום אחד ושני למחר דמ' דשני הוי מ\"א לראשון והיום ראויה להביא קרבנה על הראשון ואשמועינן דשוחטין עליה ואפי' מחוסרת כפרה ולאחר שחיטת פסחה תביא כפרתה ותאכל לערב פסחה אלמא ולד שני כמאן דליתיה להיות מעכב עליה שתהא מונה לו וימשכו ימי טוהר שלה עד למחר:"],[4,"ואי אמרת בטומאה סבירא ליה לר' יהודה כמאן דאיתיה דמי","לגרום ימי טומאה שלו השלמה לימי טוהר של ראשון היכי שחטינן לאורתא נמי לא מציא אכלה שהולד השני גרם להאריך ימי טוהר של ראשון יום אחד שהרי שמיני לראשון הוא שביעי לשני ומימי טומאתו הוא והפסיק מניינו של ראשון וצריכה להשלימו ועד יום מ' ושנים לראשון אינה ראויה להביא כפרתה אלא לאו ש\"מ כמאן דליתא דמי ועולין ימי טומאה וטהרה שלו למנין ימי טוהר של ראשון:"],[5,"לעולם אימא לך כו'","וההיא ברייתא לאו בולד שני מיתוקמא אלא בכל ולדות דעלמא ודקשיא לך הא לאורתא נמי מחוסרת כפורים היא בפסח הבא בטומאה עסקינן דנטמא רוב הקהל ואישתראי טומאה לגביה:"],[6,"לא יאכלו ממנו כו'","דכי אישתראי טומאה בצבור לגבי טומאת מת אישתראי דכתיב (במדבר ט׳:י׳) איש כי יהיה טמא לנפש וגו' ועלה דרשינן (פסחים דף סו:) איש נדחה לפסח שני ואין צבור נדחין אלא עושין בטומאה:"],[7,"לא יאכלו בדלא טבלו","דלא פסקו מזיבה או פסקו ולא ספרו ז' ולא טבלו אבל יולדת ביום ארבעים היא טבלה בשמיני ללידתה:"],[7,"א\"ה","אמאי נקט יום מ' לזכר או שמונים לנקבה משמיני ללידתה נמי חזיא:"],[9,"ביום מ' נמי לא חזיא","אפי' לאורתא דהא מיחסרא כפרה וקס\"ד מחוסר כפורים דזב כזב דמי ואינו אוכל בפסח הבא בטומאה:"],[10,"","הא דרבא בשחיטת קדשים בתחילת פ\"ב (דף יז:):"],[10,"אמר רב אשי רבא","לא מתרץ לה ביום מ' דימי טוהר כלל אלא הכי מוקים לה ביולדת ביום מ' להריונה וילדה זכר שוחטין עליה בו ביום ור' ישמעאל היא דאמר בפרק המפלת חתיכה (נדה ל.) בריית נקבה לפ\"א:"],[11,"יבשתא","בלא דם:"],[11,"הקבר","רחם:"],[12,"יכול בין רצופין","כגון שלא הפילה בינתיים:"],[12,"בין מפוזרין","כגון אם הפילה לסוף נ\"ד יכול יפסיקו לה טומאת הנפל וישלימו לה ששים יום של טהרה ללידה הראשונה לבד מימי טומאת הנפל המפסיקין בינתיים:"],[12,"תלמוד לומר יום מה יום כולו רצוף","אם טמא טמא ואם טהור טהור אף ששים יום כולם רצופים לטהרה:"],[12,"מי אית להו מפוזרין","הא מוולד שני מניא ולא משלמו ימי טוהר דראשון אלא אחר אחרון הולכין הלכך לא משכחת להו מפוזרין לעולם:"],[13,"אלא לאו ר' יהודה היא","דאית ליה ימי טוהר דראשון דלדידיה ראשון עיקר לענין קרבן ואשמועי' הכא דלענין טומאה וטהרה לית ליה ימי טוהר לראשון דא\"כ לא משכחת לה טהורין רצופין אלא משני מניא וש\"מ חומרא בעלמא אית ליה במתני' לאפושי קרבנות ולענין קרבן לחודיה הוא דמני לראשון אבל לגבי טומאה להשלים ימי טוהר לראשון למנותן מפוזרין לית ליה דקולא היא דהדר בעיא למיתב ימי טוהר לשני:"],[14,"לעולם רבנן היא","וה\"ד מפוזרין ביולדת זכר בתוך שמונים של נקבה שימי טוהר של זכר כלין קודם לשמונים דנקבה ראשונה ובכה\"ג דימי טוהר של שני כלין קודם לימי טוהר דראשון לית להו לרבנן דמוולד שני לימנו ובעיא לאשלומי ימי טוהר דראשון ואתא קרא לאשמועינן דלא משלימין לבתר פ' דלידה ראשונה שבעה כנגד ז' ימי טומאה דזכר שהפסיקו בינתיים אלא משני מונה:"],[15,"סוף סוף","לא משכחת הכי דשלמין שמונים דנקבה קמייתא ועד כאן מ' דזכר לא שלמין דלא משכחת לידת זכר עד נ\"ד דנקבה י\"ד דטומאה דנקבה ומ' דיצירת הזכר וכיון (דרבינן לוולד שני משום דלא) משכחת מפוזרין:"],[15,"ביולדת תאומין","שנתעברו:"],[15,"לעשרים לימי טהרה","עשרים לאו דוקא דהוא הדין לבציר מהכי או טפי מהכי:"],[16,"מפוזרין","כלומר שפסקו לה שבעה ימי טומאה דזכר לימי טוהר דנקבה וליתיב לה שבעה אחריני לאחר שמונים ללידה הראשונה ת\"ל יום:"],[17,"ל' דזכר מפוזרין","כגון יולדת תאומים וילדה שני בתוך ל' דזכר ראשון יכול יתנו לה שבעה לבד מ' ללידה הראשונה כגון ז' ימי טומאה דשני דהשתא הוו ל' מפוזרין שהרי הפסיקו ימי טומאה בינתיים שלא עלו למנין:"]],[[10,"ביום מ' ליצירת זכר","אף שאין יכולין לידע יום ארבעים ליצירה דהלא שכבת זרע שוהה לקלוט פעמים עד שלשה ימים ומיהו שמואל היה בקי כדאמרינן פרק המפלת (נדה כה:) שאני שמואל דרב גובריה:"],[11,"קא משמע לן","פירוש אפשר לפתיחת הקבר בלא דם והכי פסיק בשאלתות דרב אחאי מהאי דהכא מדשוחטין וזורקין:"]]],[["מפוזרין הא אמרי רבנן לולד שני מניא אלא לאו ר' יהודה היא וש\"מ חומרא אית ליה קולא לית ליה","ועוד אמר רב אשי ת\"ש (ויקרא יב, ה) וששת ימים יכול בין רצופין ובין מפוזרין ת\"ל ששים מה ששים כולן רצופין אף ששה כולן רצופין מני אלימא רבנן מי אית להו לרבנן מפוזרין האמרי רבנן לולד שני מניא","אלא לאו רבי יהודה היא וש\"מ חומרא אית ליה קולא לית ליה ש\"מ:","\u0001מתני׳\u0002 אלו מביאין קרבן עולה ויורד על שמיעת קול ועל בטוי שפתים ועל טומאת מקדש וקדשיו והיולדת והמצורע:","\u0001גמ׳\u0002 תנו רבנן יש מביא בדלות ועשירות ויש מביא בדלות ויש מביא בדלי דלות","יולדת מביאה בדלות ועשירות מצורע מביא בדלות שמיעת הקול ובטוי שפתים וטומאת מקדש וקדשיו מביאין בדלות ודלי דלות","תניא אידך יש מביא אחד תחת אחד יש מביא שנים תחת שנים יש מביא שנים תחת אחד יש מביא אחד תחת שנים מכאן אתה למד לעשירית האיפה בפרוטה:","יולדת מביאה אחת תחת אחת פרידה אחת ועוף תחת כבש מצורע שתי פרידין תחת שני כבשים שמיעת הקול ובטוי שפתים וטומאת מקדש וקדשיו מביאין ב' פרידין תחת כבשה אחת ומביאין בדלי דלות עשירית האיפה תחת שתי פרידין","קתני מכאן אתה למד לעשירית האיפה שהיא בפרוטה מנלן דת\"ר האומר הרי עלי בסלע למזבח מביא כבש שאין דבר קרב בסלע אלא כבש","ממאי מדאמר רחמנא (ויקרא ה, טו) איל אשם בכסף שקלים מכלל דכבש בן שנה בסלע מדכתיב (במדבר ו, יב) כבש בן שנתו ותנן עמדו קינין בו ביום ברבעתים","ומדחס רחמנא עליה דדלות למיהוי חד משית עשר בעשירות חס רחמנא עליה דדלי דלות למיהוי חד משית עשר בדלות","א\"כ דלות כמה הויא ריבעא וכמה פריטי בריבעא ארבעים ותמניא פריטי חד משית עשר כמה הוי דדלות תלתא פריטי","דקתני מכאן אתה למד לעשירית האיפה בפרוטה אמאי פרוטה האמרת עשירית האיפה דלי דלות הוא ואמרת חד משית סרי דדלות הוא דחשבינן דג' פריטי הויין","תנא מיולדת יליף דמתיא פרידה אחת תחת כבש דהוי חד מתלתין ותרין דכבש ועד כאן דלי דלות כמה הוי חד משית עשר בדלות דמהיכא יליף מכבש ואיל עד כאן פרוטה ופלגא הוי","אמר רבא כולה מילתא מיולדת יליף וה\"ק מדחס רחמנא עליה דדלות למיהוי חד מתלתין ותרין בעשירות ומאי היא יולדת הכי חס רחמנא עליה דדלי דלות למיהוי חד מן תלתין ותרין בדלות","א\"ה (נכי) ריבעא דפרוטה הוי ה\"נ אלא דלאו אורח ארעא לאיתויי פחות מפרוטה למקום:","\u0001מתני׳\u0002 מה בין שפחה לבין כל העריות שלא שוותה להן לא בעונש ולא בקרבן שכל העריות בחטאת ושפחה באשם כל העריות בנקבה ושפחה בזכר","כל העריות אחד האיש ואחד האשה שוין במכות ובקרבן ובשפחה לא השוה לא האיש לאשה במכות ולא השוה אשה לאיש בקרבן","כל העריות עשה בהן את המערה כגומר וחייב על כל ביאה וביאה","זו חומר החמיר בשפחה"],[[0,"מי אית להו מפוזרין הא לולד שני מנו","וכיון דבראשון זכר ליכא לאוקומי כדאוקמא ליה דימי טוהר דראשון משכין לבתר ימי טוהר דשני:"],[0,"אלא לאו ר' יהודה היא","דמונה לראשון וקאמר דרצופין יהבינן לה אלמא משני הוא דמני:"],[0,"וש\"מ חומרא אית ליה קולא לית ליה","להאריך ימי טוהר דראשון שהשלימו לז' אחרים כנגד ז' ימי טומאה והדר מותיב ימי טוהר לשני דקולא יתירא היא:"],[1,"ששת ימים כו'","כגון הפילה לאחר ס\"ג דטוהר דנקבה שהן ע\"ז ללידתה והיה לה למנות עוד ג' ימים והפילה ונטמאו יכול יתנו לה ג' אחרים כנגד ג' אלה דנטמאו דנהוו ו' מפוזרים דהכא לא כתיב יום אלא ימים דמשמע אפילו מפוזרין:"],[1,"מי אית להו מפוזרין הא לולד שני מנו","וימי ולד שני זה מושכין ימים רבים אחר פ' של נקבה ראשונה ומפוזרין לא משכחת לה אלא לאו ר' יהודה היא כו':"],[3,"מתני' שמיעת הקול","ושמעה קול אלה:"],[3,"וטומאת מקדש","בשוגג ובטוי שפתים כולהו כתיבי בהדדי בפרשת ויקרא גבי קרבן עולה ויורד דהא קרא דאו נפש כי תגע בכל דבר טמא וגו' בטומאת מקדש וקדשיו משתעי כדמפרש בפרק קמא דשבועות (דף ז.):"],[4,"","\u0003גמ'\u0004 עשירות כשבה או שעירה. דלות תורים ובני יונה. דלי דלות עשירית האיפה:"],[5,"שמיעת הקול ובטוי שפתים וטומאת מקדש וקדשיו","מפרש בויקרא שמביאים בדלות ובדלי דלות:"],[6,"יש מהם מביאין כו'","מפרש לקמן:"],[7,"יולדת","בעשירות כבש לעולה ובן יונה או תור לחטאת: ובדלות שתי תורים דהיינו פרידה דעוף תחת כבש:"],[7,"עשירית האיפה תחת שני פרידין","דהיינו אחת תחת שתים:"],[8,"הרי עלי בסלע","בקרבן הנקח בסלע:"],[9,"","(מדבכל התורה כולה קרי לכבש בן שנה מכלל דאיל בן שתי שנים):"],[9,"מדכתב רחמנא","גבי אשם מעילות בויקרא איל בכסף שקלים דהיינו שתי סלעים:"],[9,"ברבעתים","קן ברובע דינר דהיינו כדמייתי שתי פרידים בדלות ברובע דינר תחת כבש הנקח בסלע היינו חד מט\"ז בסלע שהוא ד' דינרים ורובע דינר היינו י\"ו רבעים: ברובע דינר יש מ\"ח פרוטות כדאמרינן בפ\"ק דקדושין (דף יב.) שש מעה כסף דינר ומעה שתי פונדיון ופונדיון ב' איסרין ואיסר ב' מסמסות מסמס ב' קונטרק וקונטרק ב' פרוטות דהיינו ל\"ב פרוטות למעה ולמעה וחצי שהוא רובע דינר הוו מ\"ח פרוטות וכיון דאמרת דלי דלות דהיינו עשירית האיפה בעי מהוי חד מי\"ו בדלות אשתכח דעשירית האיפה הוי ג' פרוטות דהיינו חד מי\"ו של מ\"ח:"],[13,"תנא מיולדת יליף","דלות יליף מיולדת דמתיא פרידה הנקחת בשמינית של דינר תחת כבש הנקח בסלע דהיינו חד מל\"ב בכבש והוא כ\"ד פרוטות:"],[13,"ועד כאן דלי דלות כמה הוי חד מט\"ז בדלות","דנהי דילפת דדלות חד מל\"ב מיולדת אבל דלי דלות דלא משכחת ביולדת בע\"כ מכבש ואיל ילפת לה כדדרשינן לה לעיל דלא משכחת דלי דלות אלא בשמיעת הקול ובבטוי שפתים ובמטמא מקדש וקדשיו וע\"כ דלי דלות מדלות דידהו מילף וכי היכי דדלות דידהו שתי פרידין תחת הכבש דהיינו חד מי\"ו בדלות ונהי דאשכחת בדלות בעלמא כגון ביולדת שהיא פרידה אחת שמינית של דינר דהיינו כ\"ד פרוטות וכי מייתי דלי דלות חד מי\"ו הוי פרוטה ופלגא:"],[14,"כולה מיולדת יליף","ואע\"ג דאין בה דלי דלות יליף מהתם דכי היכי דאשכחן בה דלות אחד מל\"ב דעשירות דלי דלות נמי הוה חד מל\"ב דדלות ודלות דיולדת הכי הוו כ\"ד פרוטות ודלי דלות פרוטה נכי רבעא דהיינו חד מל\"ב:"],[16,"","\u0003מתני'\u0004 כל חטאת יחיד נקבה היא דהיינו כשבה או שעירה:"],[17,"שוין במכות ובקרבן","אם מזידין שניהן לוקין כדקיי\"ל איש או אשה כי יעשו מכל חטאת האדם וגו' השוה הכתוב אשה לאיש לכל העונשין ואם שוגגין שניהם מביאין קרבן דבתרווייהו כתיב כרת במזיד דכתיב ונכרתו הנפשות העושות וכל שזדונו כרת שגגתו חטאת:"],[17,"ובשפחה כו'","שהאשה לוקה והאיש באשם כדמפרש בגמ':"],[18,"כל העריות כולן עשה בהן מערה כגומר","במסכת יבמות בפרק הבא על יבמתו (יבמות דף נג:):"],[18,"","ובשפחה אינו חייב אלא על גמר ביאה דשכבת זרע כתיב בה שראויה להזריע:"],[18,"וכל העריות חייב על כל ביאה וביאה","ובשפחה אמרו לעיל בפירקין (כריתות דף ט:) שמביא קרבן אחד על ביאות הרבה:"]],[[9,"מכלל דכבש בן שנה בסלע","וקשה שהרי אומר בחטאת בת דנקא בפרק איזהו מקומן (זבחים דף מח.) וגם אמרינן לקמן (כריתות דף כז.) מפני מה לא נתנה תורה שיעור קצבה למחוסרי כפרה שמא יוזלו טלאים ואין להם כפרה וי\"ל הא דקאמר כבש בסלע רגילות הוא שקונהו בסלע למצוה מן המובחר אבל בפחות סגי אבל אשם צריך כסף שקלים דמדאורייתא הוא אבל חטאת דאורייתא אין לה שיעור רק מדרבנן לכך מצוה לכתחלה בסלע ובפחות סגי עד דנקא אבל פחות מדנקא מיקרי עבריינא ומכל מקום אם הוזלו והם שמנים בפחות מדנקא מתכפר בהם ובאשמות אפילו הם שמנים וטובים בפחות מכסף שקלים שהוזלו אינו מתכפר משום דכתיב כסף שקלים:"]]],[["שעשה בה את המזיד כשוגג","איזו שפחה כל שחציה שפחה וחציה בת חורין שנאמר (ויקרא יט, כ) והפדה לא נפדתה דברי ר' יהודה ר' ישמעאל אומר זו היא שפחה ודאית ר' אליעזר בן יעקב אומר כל עריות מפורשות ושיור אין לנו אלא חציה שפחה וחציה בת חורין:","\u0001גמ׳\u0002 מנלן דהיא לקי והוא לא לקי דתנו רבנן (ויקרא יט, כ) בקורת תהיה מלמד שהיא לוקה יכול שניהן לוקין תלמוד לומר תהיה היא לוקה והוא אינו לוקה","ומנין דהדין בקורת לישנא דמלקות הוא א\"ר יצחק תהא בקראי כדתניא גדול הדיינין מקרא שני מונה שלישי אומר הכהו רב אשי אומר בביקור תהיה כדתנן אין אומדין אותו אלא מכות הראוין להשתלש","ת\"ר בזמן שהאשה לוקה האיש מביא קרבן אין האשה לוקה אין האיש מביא קרבן מנלן אמר רבא דכתיב (ויקרא יט, כ) ואיש כי ישכב את אשה שכבת זרע והיא שפחה נחרפת לאיש והפדה לא נפדתה או חופשה לא נתן לה","מכדי עד הכא באיש קא משתעי קרא נכתוב והביא את אשמו לה' ולבסוף לכתוב בקורת תהיה אמאי כתב רחמנא ברישא בקורת תהיה ולבסוף כתב והביא את אשמו לה' ה\"ק אם בקורת תהיה היא והביא את אשמו לה' ואם לא תהיה בקורת לא יביא הוא את אשמו","אימא הוא מעטיה קרא אבל היא תילקי ותיתי קרבן והביא את אשמו לה' כתיב","א\"ר יצחק לעולם אינו חייב אלא על שפחה בעולה בלבד שנאמר והיא שפחה נחרפת לאיש ומאי משמע דהאי נחרפת לישנא דשנויי הוא דכתיב (שמואל ב יז, יט) ותשטח עליו הריפות ואב\"א (משלי כז, כב) אם תכתוש האויל במכתש בתוך הריפות בעלי","(עזרא י, יט) ויתנו ידם להוציא נשיהם ואשמים איל צאן על אשמתם אמר רב חסדא מלמד שכולן שפחות חרופות בעלו:","איזוהי שפחה כו': ת\"ר והפדה יכול כולה ת\"ל לא נפדתה יכול לא נפדתה ת\"ל והפדה","הא כיצד פדויה ואינה פדויה חציה שפחה וחצייה בת חורין ומאורסת לעבד עברי דברי ר\"ע רבי ישמעאל אומר בשפחה כנענית הכתוב מדבר ומאורסת לעבד עברי א\"כ מה ת\"ל והפדה לא נפדתה דברה תורה כלשון בני אדם","ר' אלעזר בן עזריה אומר כל עריות מפורשות לנו משוייר לנו חציה שפחה וחציה בת חורין ומאורסת לעבד עברי אחרים אומרים (ויקרא יט, כ) לא יומתו כי לא חופשה בשפחה כנענית הכתוב מדבר ומאורסת לעבד כנעני","לר' ישמעאל בשלמא והפדה לא נפדתה כדקתני דברה תורה כלשון בני אדם אלא דקתני מאורסת לעבד עברי מנלן דכתיב כי לא חופשה מכלל דהוא חופש","ר' אלעזר בן עזריה היינו ר\"ע לר' ישמעאל קאמר לדידי בעלמא כוותיך סבירא ליה דדברה תורה כלשון בני אדם והכא שאני מכדי כתיב ליה קרא כי לא חופשה והפדה לא נפדתה ל\"ל ש\"מ להכי אתא לחציה שפחה וחציה בת חורין","לאחרים בשלמא והפדה לא נפדתה קסבר דברה תורה כלשון בני אדם אלא הא דעבד כנעני מנלן אמר קרא כי לא חופשה אם אינו ענין לדידה תנהו ענין לדידיה:","\u0001מתני׳\u0002 כל עריות אחד גדול ואחד קטן קטן פטור אחד ער ואחד ישן ישן פטור אחד שוגג ואחד מזיד שוגג בחטאת ומזיד בהכרת:","\u0001גמ׳\u0002 והכא חייב קטן א\"ר יהודה הכי קתני כל עריות אחד גדול ואחד קטן קטן פטור וגדול חייב והכא גדול נמי פטור מ\"ט דהא מקשיין אהדדי","כל עריות אחד ניעור ואחד ישן ישן פטור וכאן ישן נמי חייב א\"ר יהודה אמר רב הכי קתני כל עריות אחד ניעור ואחד ישן ישן פטור וניעור חייב וכאן אפילו ניעור פטור מ\"ט דמקשיין אהדדי","תני תנא קמיה דרב ששת עשו גומר כמערה מתכוין כשאין מתכוין כדרכה כשלא כדרכה ניעור כישן","א\"ל מאי קאמרת אי בשפחה חרופה קתני אמאי עשו גומר כמערה גומר בשפחה חרופה מיחייב מערה לא מיחייב ותו מתכוין כשאינו מתכוין אי מכוונה מיחייבא אי לא לא מיחייבא","וכדרכה כשלא כדרכה נמי כדרכה בשפחה חרופה מיחייב ושלא כדרכה לא מיחייב מאי טעמא (ויקרא יט, כ) שכבת זרע כתיב ומאי ניעור כישן","ואי בשאר עריות קא תני עשו גומר כמערה"],[[1,"ר' ישמעאל אומר שפחה","גמורה:"],[1,"כל העריות מפורשות","שהן בנות חורין ושיור אין לנו וזו ודאי משונה היא חציה שפחה וחציה בת חורין:"],[3,"גמ' תהא בקריאה","שהן קורין עליה והפלא ה' את מכותך שכן קורין על הלוקין במס' מכות (דף כב:):"],[3,"בבקורת תהיה","שאם אינה יכולה לקבל ארבעים אומדין אותה בבקור ובמחשבה:"],[3,"מכות הראויות להשתלש","כגון י\"ח או כ\"א או כ\"ד שהיו מכין אותו שתי ידות (מלפניו ואחת מאחריו) ומקרא ילפינן לה במס' מכות (דף כג.):"],[4,"בזמן שהאשה לוקה","שגדולה היא ובת עונשין היא:"],[6,"אימא הוא מיעטיה קרא","מהדר אמתני' דקתני לא השוה אשה לאיש לקרבן אימא הוא מיעטיה קרא ממלקות דכתיב תהיה אבל היא אימא תילקי ותייתי קרבן:"],[7,"לישנא דשינוי הוא","שנשתנית מברייתה:"],[7,"הריפות","דבר שנשתנה ע\"י כתישה וכאן נמי ע\"י אבר שמש דש:"],[8,"ויתנו ידם להוציא","פסוק הוא בספר עזרא:"],[10,"פדויה [ואינה פדויה]","והפדה לא נפדתה משמע פדויה ואינה פדויה:"],[12,"לרבי ישמעאל מאורסת לעבד עברי מנא ליה","בשלמא לר\"ע דמוקי לה בחציה בת חורין לא בעיא קרא דאיכא למימר מדחייב עלה רחמנא ודאי מאורסת היא מישראל דהא תפסו לה קדושין הילכך איכא למימר לעבד עברי נתקדשה שהרי רבו מוסרה לו בעל כרחו כדמפרש בקדושין (דף יד:) ולא לעבד כנעני שהרי אסורה לו אלא לרבי ישמעאל דאמר שפחה גמורה מאורסת לעבד עברי מנא ליה (דאמר לעבד עברי שהרי אסורה לו) דילמא לעבד כנעני דהא לדידיה שריא לגמרי טפי מעברי:"],[14,"אם אינו ענין לדידה","דהא כתיב (ויקרא יט) והפדה לא נפדתה:"],[15,"מתני' כל העריות","אם האחד גדול או האיש או האשה האחד חייב והאחד פטור ובשפחה אינו כן ובגמרא מפרש לה:"],[15,"שוגג בחטאת ומזיד בהכרת","ובשפחה נהי דאם הוא מזיד והיא שוגגת דפטורין הואיל ואינה לוקה כדאמרינן לעיל בקורת תהיה והביא את אשמו ואי לא פטורין מיהו אם הוא שוגג והיא מזידה היא במלקות והוא באשם כדאמרי' בהאי פירקא דשוגג ומזיד שוין בבא על השפחה:"],[16,"גמ' והכא חייב","בתמיה וכי קטן חייב בשפחה:"],[16,"דהא איתקוש להדדי","כדאמרן לעיל אם אין האשה לוקה אין האיש מביא אשם:"],[17,"וכי ישן חייב","בתמיה:"],[19,"מערה לא מיחייב","דשכבת זרע כתיב בה:"],[19,"וכי מכוין מיחייב ואי לא לא מיחייב","דשכבת זרע בעינן ושאינו מתכוין כגון נפל מן הגג ונתקע אין ראוי להזריע:"],[21,"ואי בשאר עריות קתני איפכא מיבעי ליה","עשו מערה בעריות חייב כגומר שלא כדרכה חייב כבכדרכה דמשכבי אשה כתיב (ויקרא יט):"]],[[4,"אין האשה לוקה","כגון שהיא שוגגת וקטנה אין האיש מביא קרבן והא דאמרינן לרבות שוגג כמזיד היינו שוגג דאיש כמזיד אבל האשה צריך שתהא מזידה:"],[16,"דהא מקשו להדדי","הלשון אינו מכוון דהאיש הוקשה לאשה ולא אשה לאיש דהא כי האיש כמו האשה חייבת כדאיתא בת\"כ ואיש פרט לקטן יכול שאני מוציא בן תשע שנים ויום אחד ת\"ל ואיש א\"כ אשה לא איתקשה לאיש:"],[18,"באין מתכוין (דכדרכה) פטור","פירש הקונט' משום דש\"ז כתיב ובאין מתכוין אינו ראוי להזריע כגון נפל מן הגג ונתקע וקשה מאן לימא לן דאינו ראוי להזריע אלא האי טעמא משום שאנוס הוא:"]]],[["איפכא איבעי ליה למיתני","א\"ל איסמייה א\"ל לא הכי קתני עשו גומר שלא כדרכה בשפחה חרופה דלא מיחייבי כמערה כדרכה (ויקרא יט, כ) דשכבת זרע כתיב","מתכוין שלא כדרכה בשפחה דפטורין כאינו מתכוין דשכבת זרע כתיב ניעור שלא כדרכה בשפחה דפטורין כישן מ\"ט דשכבת זרע כתיב","נמצא מתכוין והמערה בשפחה כשאין מתכוין בכל עריות ישן כדרכה כישן דעריות נמצא ניעור שלא כדרכה בשפחה כישן דכל עריות:","\u0001הדרן עלך ארבעה מחוסרי כפרה\u0002","מתני׳ \u0001אמרו\u0002 לו אכלת חלב מביא חטאת עד אומר אכל ועד אומר לא אכל אשה אומרת אכל ואשה אומרת לא אכל מביא אשם תלוי עד אומר אכל והוא אומר לא אכלתי פטור","שנים אומרים אכל והוא אומר לא אכלתי רבי מאיר מחייב א\"ר מאיר אם הביאוהו שנים לידי מיתה חמורה לא יביאוהו לידי קרבן הקל אמרו לו מה אם ירצה לומר מזיד הייתי פטור","אכל חלב וחלב בהעלם אחת אינו חייב אלא אחת אכל חלב ודם ופיגול ונותר בהעלם אחת חייב על כל אחת ואחת זה חומר במינין הרבה ממין אחד","וחומר במין אחד ממינין הרבה שאם אכל כחצי זית וחזר ואכל כחצי זית אחר בהעלם אחת ממין אחד חייב משני מינין פטור:","\u0001גמ׳\u0002 קתני אמרו לו אכלת חלב מביא חטאת אמרו כמה הויין תרין והוא מה אמר להון אלימא דשתיק ולא קמכחיש להו אלא שתיקה דתרין הוא דמביא חטאת על שתיקה דחד לא","אימא מציעתא עד אומר אכל והוא אומר לא אכלתי טעמא דמכחיש ליה אבל שתיק מיחייב וכ\"ש תרי","אלא דקמכחיש להו מני ר\"מ היא דאמר הכחשה דבי תרי לאו הכחשה היא אבל לרבנן פטור","ומאי קמשמע לן מסיפא שמעת מינה הא קמשמע לן דבר זה מחלוקת ר\"מ ורבנן והוא דקמכחיש להו","איכא דאמרי אמרו לו נמי חד קרי ליה דתנן האשה שהלך בעלה למדינת הים ובאו ואמרו לה מת בעליך ונישאת ואח\"כ בא בעלה תצא מזה ומזה דקי\"ל דאפילו בחד","ממאי מדקתני סיפא נישאת שלא ברשות מותרת לחזור לו מאי שלא ברשות שלא ברשות בית דין ועד אחד","מכלל דרישא ברשות ב\"ד ובעד אחד אלמא גבי עד אחד קתני אמרו והכא נמי דקתני אמרו לו משמע אפילו עד אחד","והוא מאי קאמר אלימא דקא מכחיש ליה מי מייתי והא קתני מציעתא עד אחד אומר אכל והוא אומר לא אכלתי פטור","אלא דשתיק ממציעתא שמע מינה עד אחד אומר כו' טעמא דקא מכחיש ליה אבל שתק מישתק חייב","לעולם דלא מכחיש ליה והכי קתני אמרו לו אכלת חלב מביא חטאת במה דברים אמורים דשתיק אבל מכחיש ליה פטור","ומדאורייתא מנלן דלא מכחיש ליה חייב דת\"ר (ויקרא ד, כג) או הודע אליו חטאתו ולא שיודיעוהו אחרים יכול אפילו אין מכחישן תלמוד לומר או הודע אליו מכל מקום","במאי עסקינן אלימא בתרין תרין ואין מכחישן קרא בעי"],[[3,"נמצא מתכוין ומערה בשפחה","שהערה בה בכוונה פטור דהעראה בשפחה פטור כשאינו מתכוין דעריות. העראה פלוגתא היא (בסנהדרין בארבע מיתות) (סנהדרין דף נה:) איכא למ\"ד העראה זו נשיקה ואיכא למאן דאמר זו הכנסת עטרה:"],[5,"מתני' אמרו לו","מפרש בגמרא:"],[6,"אם הביאוהו כו'","כגון אם העידו בו שהרג את הנפש:"],[6,"אם ירצה לומר מזיד הייתי","אם היה רוצה לפטור עצמו בשקר היה יכול לומר מזיד היה ומזיד פטור:"],[11,"גמ' ר\"מ היא","דאמר אם הביאוהו שנים כו':"],[12,"מאי קמשמע לן הא מסיפא שמעינן לה","דקתני שנים אומרים אכל כו':"],[12,"הכי קאמר סיפא דבר זה","ששנינו למעלה אמרו לו אכלת כו' מביא חטאת לאו דברי הכל היא אלא מחלוקת ר\"מ וחכמים שרבי מאיר אומר אם הביאוהו שנים כו' וחכמים אומרים כו' וסיפא מפרש לרישא:"],[13,"איכא דאמרי","הכי פריך הש\"ס אמרו משמע חד כו':"],[14,"מותרת לחזור לו","לראשון ועל פי עדים שאמרו לה שנים מת בעליך ולפיכך מותרת לראשון שהרי אנוסה היא ששנים אמרו לה דאונס בישראל שרי:"],[15,"מכלל דרישא","דקתני תצא מזה ומזה שנשאת ברשות ב\"ד ועד אחד דהוה לה למידק יפה אם מת דהאי דשריוה רבנן לאנסובי על פי עד אחד משום דדייקא ומנסבא דמתוך חומר שהחמרת עליה בסופה דתצא מזה ומזה הקלת עליה בתחלתה כדאמר במסכת יבמות (דף פח.) ואמטו להכי נשאת על פי עד אחד והיא גופה לא דייקא ואישתכח דלא מת תצא מזה ומזה כדאמרינן במסכת סוטה (דף כז:) ונטמאה ונטמאה שני פעמים אחד לבעל ואחד לבועל:"],[18,"לעולם דלא מכחיש ליה","ומתניתין הכי קתני אמרו לו [כו'] בד\"א בשותק אבל מכחישו כגון עד אמר אכל והוא אמר לא אכלתי פטור:"],[19,"הודע אליו","משמע מעצמו ולא שיודיעוהו אחרים:"]],[[1,"הכי קתני עשו כו'","והכי פירוש דברייתא עשו גומר כמערה ומתכוון כשאינו מתכוון והאי דינא הוי בכדרכה ושלא כדרכה כדמפרש הש\"ס ומכל מקום קצת קשה אמאי לא תנא ניעור כישן בהדייהו ותנא ליה בתריה דכדרכה ושלא כדרכה:"],[3,"נמצא מתכוין כו'","קשה אמאי האריך הש\"ס בלישניה דהאי לאו פירוש דברייתא הוא דכבר אסיקנא ליה שפיר:"],[3,"כשאין מתכוין דעריות","פירש הקונטרס כגון שאשתו ואחותו במטה וכסבור לבא על אשתו ונמצא אחותו דפטור ממלקות וחייב חטאת הואיל ונהנה דמתעסק הוא וקשה שהרי בשפחה נמי חייב חטאת בכי האי גוונא שהרי מביאין על הזדון כשוגג וא\"כ מאי קאמר נמצא מתכוין בשפחה כשאין מתכוין לעריות בכה\"ג שוו תרווייהו לכך יש לומר כשאין מתכוין דעריות כגון נפל מן הגג ונתקע דפטור לגמרי דאנוס הוא:"],[5,"מתני' אמרו לו עד אומר לו אכל כו'","צ\"ל דמיירי שהעידוהו שנים בבת אחת דאי בזה אחר זה הא כ\"מ שהאמינה תורה עד אחד הרי כאן שנים וכיון שנתקבל עדותו תו לא קפדינן בעדות השני שאומר לא אכל וצ\"ל דמיירי שהאיש שמעידין בו שותק דאי אמר איני יודע פטור כדנפקא בגמרא או הודע אליו כו' ומסיק דמיירי בעד אחד שאינו יכול לחייבו קרבן וע\"כ מיירי שאותו שהעיד עליו אומר איני יודע דאי אמר לא אכלתי פשיטא דעד אחד לא מהימן כדכתיב (דברים יט) לא יקום עד אחד באיש דנראה שאין עד אחד קם רק לשבועה:"],[5,"ואשה אומרת לא אכל","מכאן משמע דאשה מהימנא טפי מגזלן שהרי גבי גזלן משמע דלא אמרי' שתיקה כהודאה כדאמרינן (קדושין דף סו.) אי מהימנא לך דלא גזלנא הוא זיל אפקה ואע\"ג דשתקה אלמא לא אמרינן שתיקה כהודאה דמיא ועובדא הוה ההוא סמיא דהוה מסדר מתנייתא קמי דרב ששת כו' אתא חד גברא ואמר שאשתו זינתה וקא אמר אי מהימנא לך דלאו גזלנא הוא זיל אפקה והכא אי שתיק מהימנא האשה:"],[5,"עד אומר אכל והוא אומר לא אכלתי פטור","והוא הדין אם אמר איני יודע כמו שפירשתי:"],[8,"שאם אכל כחצי זית וחזר ואכל כחצי זית ממין אחד חייב משני מינין פטור","וא\"ת והא אמרינן בפ' קדשי מזבח (מעילה יז:) הפיגול והנותר אין מצטרפין וקא אמר בגמרא לא שנו אלא לטומאת ידים אבל לאכילה מצטרפין וי\"ל דהתם לענין מלקות אי נמי לענין שאם יפלו לקדירה אחת מצטרפין לתת טעם דהא שם אחד הוא דליכא אלא חד לאו אתרווייהו אבל הכא מיירי לדין חיוב קרבן:"],[10,"אימא מציעתא עד אומר אכל והוא אומר לא אכלתי כו'","והוא הדין דמצי מייתי מרישא עד אומר אכל ועד אומר לא אכל ומביא אשם תלוי טעמא דאמר עד אחד לא אכל הא לאו הכי חייב חטאת דשתיקה כהודאה דמיא דע\"כ מיירי דשתק דאי מכחיש ליה פטור לגמרי ואפילו אומר איני יודע כמו שפירשתי:"],[11,"אלא דקא מכחיש להו ומני ר\"מ היא","דליכא למימר דמיירי כשאמר איני יודע דפשיטא דחייב דאיני יודע גבי תרי עדים הויא כשתיקה:"]]],[["אלא לאו בחד וקתני כי אין מכחישן מהימן שמע מינה:","א\"ר מאיר קל וחומר כו':","איבעיא להו מ\"ט דרבנן משום דאדם נאמן על עצמו יותר ממאה איש או דלמא משום דאמרינן מיגו דאי בעי אמר מזיד הייתי פטור כי אמר נמי לא אכלתי מהימן ופטור","ומאי נפקא מינה למיפשט מינה לטומאה דאי אמרת טעמייהו דרבנן משום דאדם נאמן על עצמו יותר ממאה איש ל\"ש טומאה חדשה ול\"ש טומאה ישנה","ואי אמרת טעמיהון דרבנן משום דאמר מיגו היא פטרי ליה רבנן מטומאה ישנה אבל מטומאה חדשה מחייב מ\"ט טומאה ישנה מיגו דאי בעי אמר טבלתי פטור כי אמר נמי לא נטמאתי פטור דאיכא למימר מאי לא נטמאתי דקאמר לא עמדתי בטומאתי אלא טבלתי","אבל טומאה חדשה מחייב מ\"ט דכי אמר נמי טבלתי מחייב דאמרו ליה עדים השתא נטמאת","מאי ת\"ש אמר לו עד אחד נטמאת והוא אומר לא נטמאתי פטור יכול אפילו שנים א\"ר מאיר ק\"ו אם הביאוהו שנים למיתה חמורה לא יביאוהו לידי קרבן הקל וחכ\"א אדם נאמן על עצמו יותר ממאה איש ש\"מ טעמייהו דרבנן משום דאמרי אדם נאמן על עצמו יותר ממאה איש","א\"ר אמי לעולם טעמא דרבנן משום דאמרינן מיגו והכי קתני מתוך שאם רצה לומר לא עמדתי בטומאתי פטור הילכך אדם נאמן על עצמו יותר ממאה איש אי הכי היינו חלב","מהו דתימא אכלתי חלב קמתריץ דבוריה לא אכלתי שוגג אלא מזיד אבל נטמאת והוא אומר לא נטמאתי אימא לא קמתריץ דבוריה קמ\"ל הכא נמי לא עמדתי בטומאתי אבל טבלתי","ת\"ש (ויקרא ה, ה) והתודה מודה בדברים חייב אין מודה בדברים פטור א\"ל עד אחד נטמאת והוא אומר לא נטמאתי פטור","יכול אפילו שנים מכחישין א\"ר מאיר אם הביאוהו שנים לידי מיתה חמורה לא יביאוהו לידי קרבן הקל ר' יהודה אומר נאמן אדם על עצמו יותר ממאה איש","ומודים חכמים לר\"י בחלבין ובביאת מקדש אבל בטומאה לא מודו לי'","במאי עסקינן אילימא"],[[2,"אדם נאמן על עצמו","בדברים שיש בהם כפרה לא מימנע לאיתויי חטאת להתכפר נגד קונו:"],[2,"מיגו דאי בעי כו'","אם היה רוצה לשקר יכול לומר מזיד הייתי ומה שאמרתי לא אכלתי לא אכלתי שוגג אלא מזיד:"],[3,"לטומאה","כגון אמרו לו נטמאת ומיד באת למקדש:"],[4,"טומאה ישנה","אתמול נטמאת והיום נכנסת:"],[4,"טומאה חדשה","ליכא משום מיגו דטבלתי ליכא למימר דהאמרו לו בשעת טומאה נכנסת ואי נמי טבלת לא העריב שמשך וטבול יום הנכנס למקדש בשוגג חייב חטאת כדאמר במנחות בהקומץ רבה (מנחות דף כז:) מחוסר כיפורים שנכנס למקדש חייב חטאת ואין צריך לומר טבול יום וליכא למימר נמי מזיד דבעי' דליתרץ דיבוריה ואי הוה אמר להו לא נכנסתי הוה מתרץ דיבוריה לא נכנסתי שוגג אלא מזיד אבל כיון דאמר להו לא נטמאתי כי אמר נמי לא נטמאתי שוגג אלא מזיד לא מיפטר מקרבן דטומאה לא איכפת לן אי שוגג אי מזיד הוה דביאת מקדש הואי שוגג:"],[6,"נטמאת","ובאת למקדש:"],[6,"פטור","כדאמר לקמן והתודה מודה בדבר חייב שאינו מודה בדבר פטור:"],[7,"לעולם טעמייהו דרבנן משום מיגו","ובטומאה ישנה הוא דפליגי. והכי קתני גרסינן:"],[7,"א\"ה","גבי טומאה בהא פליגי דר' מאיר לית ליה מיגו ורבנן אית להו מיגו היינו חלב דמתני' ותרתי למה לי:"],[8,"אכלת חלב","אית להו לרבנן מיגו משום דמתריץ דיבוריה כו' אבל טומאה דליכא למימר לא נטמאתי שוגג אלא מזיד אימא לא מיתריץ דיבוריה קמ\"ל דמיתריץ בגוונא אחריתי לא עמדתי בטומאתי:"],[9,"והתודה","אשר חטא עליה גבי טומאת מקדש כתיב בויקרא:"],[11,"מודים חכמים לר' יהודה","ופליגי אדר\"מ בחלבין כגון אכלת חלב והוא אומר לא אכלתי ובביאת מקדש אמרו לו נכנסת למקדש טמא והוא אומר לא נכנסתי:"],[11,"אבל בטומאה","כגון היכא דאמר לא נטמאתי לא מודו ליה ולא סבירא להו דפטור. אלמא טעמייהו דרבנן משום מיגו דמיתריץ דיבוריה כגון לא עשיתי שוגג אלא מזיד אבל גבי לא נטמאתי דליכא למימר לא נטמאתי לא מודו לר' יהודה ואיפשיט בעיין דטעמא משום מיגו ותו לא מידי:"]],[[0,"אלא לאו בחד וקתני כי אין מכחיש מהימן ש\"מ","אבל אי מכחיש לא מהימן ור\"ל ע\"כ שאמר איני יודע דאי אמר בהדיא לא אכלתי פשיטא דפטור דעד אחד אינו קם רק לשבועה כדפרישית במתניתין:"],[2,"או דלמא טעמייהו דרבנן משום מיגו דאי בעי אמר מזיד הייתי וכו'","משמע לפום ריהטא שהוא נאמן מטעם מיגו שיכול לומר מזיד (אני) הייתי וקשה שהרי מיגו במקום עדים הוא דיש עדים שאכל והוא אמר לא אכלתי וא\"כ מהימנא ליה במקום עדים מכח מיגו ואמרינן בב\"מ (דף פא:) מיגו במקום עדים לא אמרינן גבי ההיא דלא תיזיל באורחא דנהר פקוד זיל באורחא דנרש ותו אין זה מיגו דלא משוי איניש נפשיה רשיעא כדאמרינן (קדושין דף נ.) גבי ההיא הבא מן החלון והביא לו מן הדלוסקמא (והביא לו) אע\"פ שאומר בעל הבית לא היה בלבי מזה אלא מזה בעל הבית כו' דדברים שבלב אינן דברים והתם מוכח ליה ופריך ודלמא למיפטר נפשיה מקרבן קאמר ומשני דא\"כ הוה אמר מזיד הייתי ופריך והא לא משוי איניש נפשיה רשיעא לכך יש לומר דהא דנאמן הכא דמיתריץ דיבוריה דאיכא למימר הא דאמר לא אכלתי רוצה לומר לא אכלתי שוגג אלא מזיד והכי פירושא מיגו דאי בעי אמר מזיד הייתי פטור השתא נמי מה שאמר לא אכלתי כך רצה לומר והכי מתרצינן מילתיה דבהכי היה דעתו ואף על גב דלא משוי איניש נפשיה רשיעא כדאמר (סנהדרין דף ט:) גבי פלוני רבעני דאינו נאמן משום דאין אדם משים עצמו רשע היינו ליפסל נפשיה לא מהימן אבל אי אמר מזיד אכלתי חלב מהימן דאומר מתכוין לטובה שאינו רוצה להביא חולין בעזרה וא\"ת ונישייליה אם היה דעתו לכך ויש לומר דאפי' הדר אמר הכי לא אכלתי שוגג אלא מזיד כיון שלא אמר כך באותה שעה מחייב ר\"מ והכי איתא בתורת כהנים אומר ר' מאיר אם בתחלה אומר מזיד הייתי שומעין לו אבל אם היה דן עמהם כל היום שאומר לא אכלתי ולא אמר יותר ואפילו אומר אח\"כ לא אכלתי שוגג אלא מזיד חייב וא\"ת היאך מחייב ר' מאיר והאמר לא אכלתי ובע\"כ לא יביא חטאת כדאמר ב\"ק (דף מ.) חייבי חטאות אין ממשכנין אותן וי\"ל דהתם מיירי כשאמר דלא ניחא ליה בכפרה אבל האי ניחא ליה בכפרה אלא שהוא סבור להיות פטור ממשכנין אותו:"],[3,"נפקא מינה לטומאה","וה\"נ מצי למימר נפקא מינה היכא שאמר לא אכלתי לא שוגג ולא מזיד:"],[11,"ומודים חכמים לר' יהודה בחלבין ובביאת מקדש אבל בטומאה לא מודו דפטור","רש\"י פירש שתי לשונות ור\"י פירש שיטה אחרת ומודים חכמים לר' יהודה כו' אבל בטומאה לא מודו ליה כמו נטמאת והוא אמר לא נטמאתי ומפרש הש\"ס במאי אילימא בטומאה ישנה מ\"ש הכא ומ\"ש הכא אלא שמע מינה בטומאה חדשה ומשום הכי לא מודו דלא שייך מיגו וטעמייהו דרבנן משום מיגו ודווקא בחלבים ובעריות מודו משום דשייך מיגו אבל בטומאה לא מודו דלא שייך מיגו אבל לר' יהודה דטעמא משום אדם נאמן על כו' פטר הכא והכא ומיפשט בעיא דטעמייהו דרבנן דפליגי עליה דר\"מ הוי מטעם מתרץ דיבוריה כדמשמע הכא ואי רבנן דר\"מ היינו רבי יהודה טעמיה משום דאדם נאמן על עצמו ודחי רבינא לעולם אימא לך בטומאה ישנה כלומר מהכא לא מוכח מידי דמצינו למימר דאפילו ר' יהודה לא מהימנא רק מטעם מיגו והא דפליגי הכא בטומאה ישנה וקאמרי רבנן דחייב כגון דקאמרי עדים אכלת קדשים בטומאת הגוף והוא אמר לא נטמאתי דלא חשבי רבנן דמיתריץ דיבוריה בהא דאמר דר\"ל לא עמדתי בטומאתי אלא טבלתי דאי הוה אמר לא אכלתי מצינן למיתריץ דיבוריה שר\"ל לא עמדתי בטומאתי אלא טבלתי תחלה אבל כשאומר לא נטמאתי כבר איתכחיש ליה מיגו קמא בטומאת מגע שאמר לא נטמאתי דמשמע לא שוגג ולא מזיד כיון שלא השיב להם על האכילה כמו שאמרו לו והך סוגיא דהכא קשה להא דפר\"ק דבבא מציעא (דף ג:) דקאמר לא תהא הודאת פיו גדולה מהעדאת עדים מק\"ו וקאמר ק\"ו ומה פיו כו' ופריך מה לפיו שכן מחייבו קרבן תאמר בעדים שאין מחייבין אותו קרבן ומאי פריך הא דפיו מחייבו קרבן היינו כשאין עדים מכחישין דאם אמר אכלתי חלב בשוגג והעדים מעידים שבאותו היום שאומר שאכל ובאותה שעה התרו בו או שמעידין שהיה שומן לא מחייב קרבן (מטותיה) [מפומיה] ובעדים שאין פיו מכחישן חייב דאפילו בעד אחד חייב כדמשמע הכא ועוד אדרבה עדים חמירי טפי מפיו שהרי עדים מחייבין אותו אפילו פיו מכחישן דעד כאן לא פטרי רבנן רק מטעם מיגו אבל אי מכחיש להו בהדיא חייב קרבן ותו מאי משני ר' חייא כר\"מ ס\"ל אפילו כרבנן נמי שהרי מחייבין היכא דלא מתרץ דיבוריה:"]]],[["בטומאה ישנה מאי שנא חלבין וביאת מקדש דמודו ליה דאם רצה יאמר מזיד הייתי טומאה ישנה נמי מתרץ דיבוריה דאם רצה יאמר לא עמדתי בטומאתי אלא טבלתי","אמר רבינא לעולם בטומאה ישנה וכגון דאמרי ליה עדים אכלת קדשים בטומאת הגוף והוא אמר להון לא נטמאתי דהכא לא מתריץ דיבוריה דליכא למימר לא עמדתי בטומאה אבל טבלתי","מאי אמר להון טבלתי ואכלתי כי אמר להון הכי איתכחש ליה דבוריה קמא מיהא בטומאת מגעו","אמר רב נחמן הלכה כר' יהודה אמר רב יוסף לא אמרה אלא בינו לבין עצמו ולעצמו","אמר ר\"ל מודה ר\"מ לחכמים שאם אמרו לו שנים בעלת שפחה חרופה והוא אומר לא בעלתי מהימן דאי בעי אמר להון לא גמרתי ביאתי","אמר רב ששת מודה ר\"מ לחכמים בנזיר טמא שאמרו לו שנים נטמאת והוא אומר לא נטמאתי פטור דאי בעי אמר נשאלתי על נזירי","אמר אביי מודה רבי מאיר לחכמים שאם אמרו לו שנים יודע אתה בעדות פלוני והוא אומר לא ידעתי פטור דאי בעי אמר לא נתכוונתי לעדות:","אכל חלב וחלב בהעלם אחת [כו']: מתקיף לה ר' זירא אמאי אינו חייב אלא חטאת אחת והא ב' זיתי חלב אכל","א\"ל אביי העלמות מחולקות והכא העלם אחד הוא דאיכא","איכא דמקשי ליה הכי טעמא דהעלם אחת הא בשתי העלמות חייב שתים אמאי שם חלב אחד הוא אמר ליה אביי העלמות מחולקין:","אכל חלב ודם פיגול ונותר חייב כו':","ממין אחד חייב פשיטא אמר ריש לקיש משום בר תוטיני כגון שאכלו בשני תמחויין ואליבא דרבי יהושע דאמר תמחויין מחולקין","מהו דתימא כי אמר ר' יהושע לא שנא לקולא ולא שנא לחומרא קמ\"ל דחייב אלמא לחומרא אמר לקולא לא אמר","איכא דאמר על סיפא משני מינין פטור פשיטא אמר ריש לקיש משום בר תוטיני כגון שאכלו בשני תמחויין ואליבא דר' יהושע דאמר תמחויין מחולקין","דמהו דתימא כי אמר ר' יהושע לחומרא אמר לקולא לא אמר קמ\"ל מב' מינין פטור","מאי מב' מינין ממין אחד הוא ואמאי קרי ליה ב' מינים משום דאכלו בב' תמחויין וקתני פטור אלמא ל\"ש לקולא ול\"ש לחומרא קאמר רבי יהושע","מדסיפא מין אחד ושני תמחויין רישא מין אחד ותמחוי אחד פשיטא","אמר רבינא כגון שהיתה לו ידיעה בינתיים ואליבא דרבן גמליאל דאמר אין ידיעה לחצי שיעור","דתנן הכותב שתי אותיות בשתי העלמות אחת שחרית ואחת ערבית ר\"ג מחייב וחכמים פוטרין","רבן גמליאל סבר אין ידיעה לחצי שיעור ורבנן סברי יש ידיעה לחצי שיעור:","\u0001מתני׳\u0002 כמה ישהא באוכלין כאילו אוכל קליות דברי ר\"מ וחכמים אומרים עד שישהא מתחלה ועד סוף כדי אכילת פרס חייב","אכל אוכלין טמאין ושתה משקין טמאין שתה רביעית יין ונכנס למקדש ושהה כדי אכילת פרס חייב רבי אליעזר אומר אם פסק בה או אם נתן בו מים כל שהוא פטור:","\u0001גמ׳\u0002 איבעיא להו ר\"מ לחומרא קאמר או לקולא קאמר לחומרא קאמר והכי קתני כאילו אוכל קליות דאפילו כוליה יומא ואף על גב דמתחלה ועד סוף יותר מכדי אכילת פרס כיון דמשכיה אכילתיה מחייב ואמרו ליה רבנן דעד שישהא בכדי אכילת פרס הוא דחייב יותר מכדי אכילת פרס פטור","או דלמא לקולא קאמר דהכי קתני כאילו אוכל קליות והוא דלא איפסיק ביני וביני אבל דאיפסיק ביני וביני אע\"ג דמתחלה ועד סוף בכדי אכילת פרס פטור ואמרו ליה רבנן כיון דמתחלה ועד סוף בכדי אכילת פרס הוא חייב","ת\"ש וחכמים אומרים עד שישהא בכדי אכילת פרס מתחלה ועד סוף"],[[1,"אמר רבינא לעולם","טעמא משום מיגו בחלבין ובביאת מקדש איכא מיגו דלא נכנסתי שוגג אלא מזיד וגבי טומאה דלא מודו ליה משום דליכא מיגו ואע\"ג דשייך ביה קרבן ואיכא טומאה ישנה דלית בה מיגו כגון אמרו לו אכלת קדשים כו':"],[1,"ל\"א מודים חכמים לר\"י בחלבין ובביאת מקדש","דשייך בהו קרבן אבל בטומאה גרידתא בלא ביאת מקדש דליכא קרבן לא מודו ליה:"],[1,"בטומאה","ונגע בטהרות:"],[1,"ובמאי עסקינן אי בטומאה ישנה כו'","אלא מדפסיק ותני דלא מודו ליה בשום טומאה שמע מינה טעמא לאו משום מיגו דהא בטומאה ישנה איכא מיגו אלא טעמא משום דאדם נאמן על עצמו הילכך היכא דאיכא קרבן הכי אבל בטומאה גרידתא לא:"],[1,"וקפריך הש\"ס במאי","טומאה עסקינן דליכא מיגו אי בטומאה ישנה האיכא מיגו ואמאי לא מודו ליה בישנה:"],[1,"אמר רבינא לעולם","איכא ישנה דלית בה מיגו וכגון דאמרו לו נטמאת אתמול ואכלת היום קדשים דהיינו טומאת הגוף ומתחייבת חטאת והוא אומר לא נטמאתי ואכחשינהו בין באכילה בין בנגיעה דלא אכל ולא נגע קדשים בטומאה ואי הדר ואמר השתא לא נטמאתי דקא אמינא לא עמדתי בטומאה לא קמכוין אלא למיפטר מקרבן (לא) ומאכילה דאית בה קרבן מכחיש להו מנגיעה לא מכחיש להו ואיתכחש דיבוריה קמא בטומאת מגע:"],[3,"לא אמר","ר' יהודה שהוא נאמן וטהור אלא לאכול טהרות בינו ובין עצמו אבל לפני אחרים לא יאכל דלמא אתי לזלזולי בטהרות:"],[3,"לעצמו","נאמן לאכול טהרות שהוא נוגע דאדם נאמן על עצמו אבל לאחרים לא יאכילם:"],[4,"מודה ר\"מ כו'","אבל מיגו דמתניתין לא אמר דנוח לו לשקר לומר לא אכלתי מעשות רשע ולומר מזיד היה:"],[5,"נשאלתי","לחכם על נדרי ובהיתר נטמאתי והכי קאמינא לא נטמאתי בעודי בנדרי:"],[6,"יודע אתה בעדות","והוא השביעו ולא הודה וחייב אתה קרבן שבועת העדות מיגו דמצי למיפטר נפשיה בהיתרא ולומר מאי לא ידעתי דקאמינא לא נתכוונתי להיות עד:"],[7,"חלב וחלב","שני זיתי חלב:"],[8,"","ה\"ג העלמות מחלקין:"],[11,"ממין אחד חייב","אסיפא דמתניתין קאי דקתני שני חצאי זיתים ממין אחד חייב פשיטא:"],[12,"מהו דתימא כי אמר ר' יהושע","לקמן בהאי פירקא (שני חצאי זיתים ממין אחד חייב) תמחויין מחלקין:"],[12,"בין לקולא","כגון אכל שני חצאי זיתים בשני תמחויין לא מצטרפין:"],[12,"בין לחומרא","דאם אכל שני זיתים בשני תמחויין בהעלם אחד חייב שתים קמ\"ל ממין אחד חייב אפילו בשני תמחויין ולא פליג ר' יהושע:"],[12,"קמ\"ל","דלחומרא קאמר:"],[13,"ה\"ג משני מינין פטור פשיטא","ומדסיפא דאין מצטרפין מיירי במין אחד ושני תמחויין מכלל דרישא דקתני ממין אחד חייב דמצטרפין מין אחד ותמחוי אחד קאמר פשיטא:"],[17,"אין ידיעה לחצי שיעור","אכל חצי שיעור ונודע לא הויא ידיעה לחלק דאם חזר ואכל חצי שיעור מצטרפין:"],[18,"הכותב שתי אותיות","הויא מלאכה בשבת:"],[20,"מתני' כמה ישהא האוכלן","לשני חצאי זיתים דאמר מצטרפין:"],[20,"כאילו אוכל קליות","משערין אותן כאילו נתפררו לפירורין דקין כקליות ואוכלן אחת אחת וכשיעור אותה שהייה מצטרפים:"],[20,"פרס","מפרש בעירובין (דף פב:) ככר שהוא משלש לקב חציה לבית המנוגע. חצי ככר הוא פרס לשון פרוסה והוא ד' ביצים:"],[21,"אכל אוכלין טמאין","נפסל גופו מן התרומה אם אכל חצי פרס כדאמרינן בעירובין בפרק כיצד משתתפין (שם) וחצי חציה לפסול את הגויה:"],[21,"נכנס למקדש","ארביעית יין קמהדר דמשום אוכלין טמאין לא מחייב אביאת מקדש:"],[21,"אם הפסיק בה","שלא שתה בבת אחת רביעית יין:"],[22,"גמ' לחומרא","כאילו אוכל קליות אחת אחת בסמוך זו לזו בההוא משערים שאם אכל כחצי זית והפסיק ולאחר אותה שעה אכל חצי זית אחר אף אם שהה מתחלה ועד סוף יותר מכדי אכילת פרס בסמוך זו לזו מצטרפין ואפילו הוי האי שיעורא כולי יומא:"],[22,"א\"ד לקולא קאמר","דבהא ס\"ל כרבנן דבטפי מאכילת פרס לא מצטרף ולהכי מדמי לקליות דאם לא הפסיק בינתים אלא כאכילת קליות שדרכן לאוכלן זו סמוך לזו מצטרף ואם הפסיק לא מצטרף אפילו בכדי אכילת פרס:"]],[[16,"מדסיפא מין אחד ושני תמחויין כו'","אבל לעיל דאוקי רישא במין אחד ושני תמחויין לא דייק מכלל דסיפא משני מינין שני מינין ממש כגון חלב ודם דאיכא למימר תנא סיפא אגב רישא אבל רישא אגב סיפא לא תנא:"],[17,"דאמר אין ידיעה לחצי שיעור","והא דקרי ליה העלם אחד לר\"ג הוא דלא מחשב ידיעה לחצי שיעור ומכל מקום תני ליה לאשמועינן דאפילו בהעלם אחד משני מינין פטור:"],[20,"מתחלה ועד סוף כדי אכילת פרס","מהכא משמע דלתרי גווני מיירי שיעור פרס חדא לענין הפסקה שאם הפסיק בין אכילה לאכילה כשיעור פרס אין מצטרף וחדא כדאמרי' בעלמא (פסחים דף מד.) שאם נתן כזית תרומה בשיעור פרס דחולין ואכלן שהוא חייב עליה:"],[21,"אוכלין טמאין כו'","אית ספרים דגרסי שקצים ובטמאים מיירי וא\"ת תיפוק ליה מכי נגע בהו טמא ויש לומר דתחב לו חבירו בבית הבליעה:"]]],[["אי אמרת בשלמא רבי מאיר לחומרא היינו דקתני עד שישהא עד דשהי דיליה כדי אכילת פרס","אלא אי אמרת ר' מאיר לקולא וחכ\"א אם שהה מיבעי ליה אלא לאו ש\"מ ר' מאיר לחומרא ש\"מ","אמר רבנאי אמר שמואל בחלבים ובנבילה עד שישהא מתחלה ועד סוף בכדי אכילת פרס אוכלים טמאים שקצים ורמשים ומשקין אפילו כל היום כולו בכדי אכילת פרס","מאי קאמר אמר רב פפא הכי קאמר אפילו כל היום כולו והוא שאכל כזית בכדי אכילת פרס","מיתיבי כל האוכלין מצטרפין לפסול הגוייה בכחצי פרס מאי לאו דאכליה לחצי פרס בכדי אכילת פרס לא דאכל כזית כזית בכדי אכילת פרס","מיתיבי כל האוכלין מצטרפין לפסול את הגוייה בכחצי פרס בכדי אכילת פרס כיצד אכל וחזר ואכל אם יש מתחלת אכילה ראשונה ועד סוף אכילה אחרונה כדי אכילת פרס מצטרפין יותר מכאן אין מצטרפין","לא התירו לאכול פחות מכשיעור לירד ולטבול ירד וטבל ועלה והשלימו מצטרף התירו לה לעוברה לאכול פחות מכשיעור מפני הסכנה","כל המשקין מצטרפין לפסול את הגוייה ברביעית בכדי אכילת פרס כיצד שתה וחזר ושתה אם יש מתחלת שתיה ראשונה ועד סוף שתיה אחרונה כדי אכילת פרס מצטרפין יותר מכאן אין מצטרפין","הותרו לה למגע טמא מת להניק בנה ובנה טהור","קתני מיהת אם יש מתחלת אכילה ראשונה ועד סוף אכילה בכדי אכילת פרס מצטרף תיובתא דרבנאי תיובתא","אמר מר לא התירו לו לאכול פחות מכשיעור לירד ולטבול מאי קאמר","אמר רב יהודה הכי קאמר אכל פחות מכשיעור לא התירו לו לירד ולטבול שאם ירד וטבל ועלה והשלימו מצטרף ואתי למימר אהני לי טבילה קמייתא ואין יודע שאין טבילה אלא באחרונה","קתני התירו לה לעוברה לאכול פחות מכשיעור מפני הסכנה מפני הסכנה אפילו טובא נמי תיכול אמר רב פפא הכי קתני הותרו לה לעוברה פחות מכשיעור אפילו טובא מפני הסכנה","קתני התירו למגע טמא מת להניק את בנה ובנה טהור אמאי טהור כיון דיינק חלב איטמי ליה מחלב","וכי תימא לא איתכשר נתכשר בטיפה מלוכלכת על פי הדד אמר רב נחמן אמר רבה בר אבוה שינק בתקיפה אחת לא הניח טיפה מלוכלכת על פי הדד","אמר רבא שתי תשובות בדבר חדא דקחזינא לפומיה דינוקא דמלא חלב ועוד מקום חלב מעיין הוא","דקתני חלב אשה מטמא בין לרצון ובין שלא לרצון בהמה אינה מטמא אלא לרצון","מאי לאו שלא לרצון דלא ניחא ליה וקתני מטמא","אלא אמר רבא היינו טעמא דבנה טהור דספק ינק כשיעור וספק לא ינק ואם תמצא לומר ינק ספק ינקו באכילת פרס ספק ינקו ביותר מכדי אכילת פרס","ולרבא מקום חלב מעיין הוא ולא צריך הכשר","והתנן האשה שנטף חלב מדדיה ונפל לאויר תנור תנור טמא וקשיא לן במאי איתכשר ואמר רבי יוחנן בטיפה מלוכלכת ע\"פ הדד","וכי תימא רבא לא סבר לה כר' יוחנן והתניא נמצאת אתה אומר תשעה משקין בזוב הזיעה וליחה סרוחה וריעי טהורין מכולם דמעת עינו ודם מגפתו"],[[0,"א\"א בשלמא ר' מאיר לחומרא","דאפילו ביותר מכדי אכילת פרס מחייב היינו דקאמרי ליה רבנן לעולם אינו חייב ביותר מכדי אכילת פרס אלא עד שתהא שהיית אכילתן כשיעור פרס:"],[1,"אלא אי אמרת ר' מאיר לקולא","קאמר דאפילו בכדי אכילת פרס לא מצטרף אם הפסיק בינתיים ורבנן בעו לאחמורי מאי עד שישהא הכי מיבעי להו למימר אם שהה כדי אכילת פרס חייב ומשמע אע\"ג דהפסיק:"],[2,"בחלבים ובנבילה","אכל שני חצאי זיתי חלב או נבלה:"],[2,"אוכלין טמאין","שיעורן לפסול את הגוף בחצי פרס:"],[2,"ומשקין טמאין","פוסלין את הגוף ברביעית:"],[2,"אפילו כל היום כולו","שהה באכילת חצי פרס ובלבד שיאכל כל זית וזית שבו בכדי שהיית אכילת פרס:"],[6,"לא התירו לאוכל פחות מכשיעור לירד ולטבול","הואיל ואינו צריך לטבילה ולקמן מפרש מאי איכפת ליה:"],[6,"התירו לה כו'","מפרש לקמן:"],[8,"למגע טמא מת","לאשה שנגעה בטמא מת:"],[9,"תיובתא דרבנאי","דאמר כל זית וזית כו':"],[13,"איטמי מחלב","דבשלמא ממגע שנגע בה לא מיטמא בנה שהיא שנגעה בטמא מת הויא ראשונה ואין אדם וכלים מטמאין אלא מאב הטומאה אלא מחלב איטמי דהאוכל כחצי פרס אוכלין טמאין נפסל גופו:"],[14,"וכי תימא לא איתכשר","האי חלב ולאו טמא הוא דחלב אין בו תורת משקה דמשקה הבא לאוכל כאוכל דמי במסכת שבת בפרק חבית שנשברה (דף קמד:) הלכך בעי הכשר:"],[14,"הא איתכשר בטיפה המלוכלכת על פי הדד","כלומר בטפה שפי הדד מלוכלך בו דההיא ודאי מכשר לשאר החלב היוצא דרך שם דהא לא קיימא לאכילת תינוק:"],[14,"שינק בתקיפה אחת","בכח:"],[15,"לפומיה דינוקא דמלא חלב","הלכך אי אפשר שלא תהא טיפה מלוכלכת על הדד:"],[15,"ועוד","חלב לאו תורת אוכל [או משקה] אית ליה דאחד ממעייני האשה הוא כרוקה וכמימי רגליה דאמרינן לקמן דמטמאין טומאה חמורה בכל שהוא שהוא כאחד מאבריה:"],[16,"בין לרצון","של תינוק בין שלא לרצון שאינו רוצה להניק וקתני מטמא ואי הוה ליה תורת אוכל אמאי מטמא שלא לרצון הא לא איתכשר הכשר מעליא דדומיא דכי יתן בעינן דניחא ליה:"],[17,"גליון אמר רבא שתי תשובות בדבר כו'","כלומר רואין אנו שפעמים אין תינוק יונק בכח ומניח טיפה מלוכלכת על פי הדד:"],[17,"ועוד מקום חלב מעיין הוא","והרי הוא כאחד מאבריה ויטמא בלא הכשר כרוקה:"],[17,"שלא לרצון","מאי היא דלא ניחא ליה לתינוק הרי לא יתכשר החלב בטיפה המלוכלכת ע\"פ הדד דשלא לרצון התינוק יצאת דדומיא דכי יתן בעינן וקתני מיטמא אף על גב דלא הוכשר אלמא מעיין הוא ואמאי בנה טהור:"],[18,"אלא אמר רבא כו'","אלא מקום חלב לאו מקום מעיין הוא וצריך הכשר אבל לא ניחא ליה טהור דהא לא איתכשר ומהשתא יכול לתרוצי לה בשלא לרצון. ע\"כ הגליון:"],[18,"כשיעור","רביעית ואם אוכל הוא חצי פרס ספק לא ינק כשיעור וטהור דהאי חלב אע\"ג דמעיין הוא לא מטמא בכל שהוא דהא היא גופה לא מטמיא במגע דראשונה היא הלכך אין לחלבה אלא טומאת שאר משקין:"],[20,"האשה שנטף חלבה כו'","כשהיא נדה. ואי מעיין הוא הא מיטמא בכל שהוא כאחד מאבריה והכשר למה ליה:"],[21,"וכי תימא כו' והתניא","בהדיא דלאו מעיין הוא:"],[21,"ליחה סרוחה","קייטור\"א בלע\"ז:"]],[[6,"התירו לעוברה לאכול פחות מכשיעור מפני הסכנה","ואם תאמר אפילו בלא סכנה נמי כדאמרינן (טהרות פ\"ב מ\"ג) והשלישי יאכל בנזיד הדמע וכן פרק קמא דחולין (דף ב:) קאמר טמא בחולין מאי למימרא ואף על גב שחולין טמאין וי\"ל הכא מיירי לענין לאכול תרומה אחר כך אבל בלא לאכול תרומה אפילו כשיעור נמי ואם תאמר מאי פריך מפני הסכנה אפילו טובא נמי ויש לומר דזימנין שאין לה כי אם תרומה:"],[13,"כיון דינק לה מחלב איטמי ליה מחלב כו'","הא איתכשרת בטיפה מלוכלכת על פי הדד שאותה טיפה אין סופה שיניקנה התינוק והוא משקה ואם תאמר והא אמר פרק כל שעה (פסחים דף לג:) מכי סחט לה בצר שיעוריה ופירש הר\"י לענין הכשר דפחות מכשיעור לא מקבל הכשר והכא בפה התינוק אין חלב כביצה ויש לומר דמדרבנן לא בעי כביצה והתם היינו דאורייתא:"],[13,"בנה אמאי טהור","כיון דינק מחלב איטמי ליה מחלב ונפסל גופו מטומאת גוייה:"],[15,"אמר רבא שתי תשובות בדבר כו' ועוד מקום חלב מעיין הוא","וכיון שמעיין הוא ומטמא כרוקה אין הדד שמשום שמיוחד לתינוק ליהוי אוכל וניטל שם משקה מיניה דאתי למימר דאינו מעיין ואינו מטמא בזבה כרוקה ואם כן למה צריך הכשר והשתא טעי רבא וסבר דכיון שהוא מעוגל ויוצא כרוק חשיב מעיין אף על גב דאינו חוזר ונבלע ומנלן לרבא דמעיין הוא דתנא חלב האשה מטמא לרצון ושלא לרצון א\"כ משקה הוא מן התורה ומעיין הוי כזבה דאי לאו מעיין הוא לא הוה מטמא כ\"א לרצון כמו חלב הבהמה ואע\"ג דחמור מחלב הבהמה לענין דם מגפתה כדאיתא בסיפא דההיא משנה מ\"מ אי לאו מעיין הוא לא הוה מטמא שלא לרצון שיטת הר\"י אבל רש\"י פירש מקום חלב מעיין הוא ולאו תורת אוכל אית ליה דאחד ממעייני אשה הוא כרוקה ומימי רגליה דאמר לקמן דמטמאין טומאה חמורה בכל שהוא כמו א' מאבריה וקשה שהרי הכא מיירי בטמא מת ואין לו מעיינות ותו מאי קאמר כאחד מאבריה והלא נדה עצמה אינה מטמאה לאבריה ותו דרוקה ומימי רגליה צריכי קרא ולא אתו מהאי סברא לכן נראה כמו שפירשתי:"]]],[["וחלב אשה מטמאין טומאת משקין ברביעית רוקו זובו ומימי רגליו מטמאין טומאה חמורה בכל שהוא","ואי אמרת מקום חלב מעיין חלב נמי נטמא טומאה חמורה בכל שהוא כזובו ורוקו אלא שמע מינה מקום חלב אשה לאו מעיין הוא","אי הכי קשיא הא מתניתא ואמר רבא מטמא בין לרצון ובין שלא לרצון","מי סברת שלא לרצון דאמר דלא ניחא ליה לא מאי שלא לרצון דאמר דדעתיה דתינוק קריבא לגבי חלב אבל אמר לא ניחא ליה טהור:","אכל אוכלין טמאין וכו': למה לי שהייה דקתני ושהה אמר רב יהודה הכי קתני אכל אוכלין טמאין ושתה משקין טמאין ושתה רביעית יין ושהה באכילתן ובשתייתן כדי אכילת פרס ונכנס למקדש חייב:","ר\"א אומר כו': ת\"ר (ויקרא י, ט) יין ושכר אל תשת יכול אפילו כל שהוא אפילו מגתו","ת\"ל ושכר אין אסור אלא כדי לשכר וכמה כדי לשכר רביעית יין בן מ' יום","אם כן מה ת\"ל יין לומר לך שמוזהרין עליו כל שהוא ומוזהרין עליו מגתו","ר' יהודה אומר יין אין לי אלא יין שאר משכרין מנין ת\"ל ושכר אם כן מה ת\"ל יין על היין במיתה ועל שאר משקין באזהרה","ר' אליעזר אומר יין אל תשת ושכר אל תשתהו כדרך שכרותו הא אם הפסיק בו או נתן לתוכו מים כל שהוא פטור","במאי פליגי תנא קמא סבר גמרינן (במדבר ו, ג) שכר שכר מנזיר","ור' יהודה לא יליף שכר שכר מנזיר ור' אליעזר סבר מאי שכר מידי דהוא משכר","כמאן אזלא הא דתניא אכל דבילה קעילית ושתה דבש או חלב ונכנס למקדש ושימש לוקה כמאן כר' יהודה אמר רב יהודה בר אחותאי הלכה כרבי אליעזר וקרי רב עליה דרבי אלעזר טובינא דחכימי","רב אחא דהוצל הוה נידרא עלה דביתהו אתא לקמיה דרב אשי א\"ל זיל האידנא ותא למחר דרב לא מוקי אמורא עליה מיומא טבא לחבריה משום שכרות","אמר ליה והאמר רב הלכה כר' אלעזר ומר הוא דקא רמי ביה מיא אמר ליה הא לא קשיא הא ברביעית הא ביותר מכדי רביעית","ת\"ר (ויקרא י, י) ולהבדיל בין הקודש ובין החול אלו דמין וערכין חרמין והקדשות","בין הטמא ובין הטהור אלו טמאות וטהרות ולהורות זו הוראה את כל החוקים אלו מדרשות אשר דבר ה' זו הלכה ביד משה זה תלמוד","יכול אף המשנה ת\"ל ולהורות ר' יוסי בר' יהודה אומר יכול אף תלמוד ת\"ל ולהורות","כמאן אזלא הא דתניא יצא שרץ טמא וצפרדע טהור ששתויי יין מורין בהן הוראה נימא רבי יוסי בר' יהודה היא ולא רבנן אפי' תימא רבנן ושאני הכא דזיל קרי בי רב הוא","אמר רב הלכה כרבי יוסי ברבי יהודה והא רב לא מוקים אמורא מיומא טבא לחבריה משום שכרות שאני רב דאורי מורי וניקם דלא לורי כל היכא דיתיב רב לא סגי ליה בלא הוראה:","\u0001מתני׳\u0002 יש אוכל אכילה אחת וחייבין עליה ארבעה חטאות ואשם אחד טמא שאכל חלב והיה נותר מן המוקדשין ביוה\"כ","רבי מאיר אומר אם היה שבת והוציאו חייב אמרו לו אינו מן השם:"],[[0,"רוקו בכל שהוא","דכתיב (ויקרא ט״ו:ח׳) וכי ירוק הזב בטהור וגו' וזובו ומי רגליו ילפינן מרוקו במסכת נדה בפרק דם הנדה (נדה דף נה.):"],[4,"ושהה כדי אכילת פרס","(יב:) משמע במקדש שהה והיינו דקפריך בגמרא מה לי לישהויי דקתני ושהה:"],[6,"עד מ' יום","מתוק הוא ולא משכר:"],[7,"מוזהרין עליו בכל שהוא ומגתו","אבל אינו במיתה עד שישתה רביעית בן מ' יום:"],[10,"במאי פליגי","תנא קמא ור' יהודה:"],[10,"","שכר שכר מנזיר:"],[12,"דבילה קעילית","מקום:"],[13,"נדרא עלה דביתהו","שלא ליהנות הימנה:"],[13,"אתא לקמיה דרב אשי","לאחר אכילה ושתיה:"],[13,"לא מוקים אמורא עליה","למידרש בפירקא:"],[13,"מיומא טבא לחבריה","מאחר שעשה שמחת יום טוב שאכל ושתה עד למחר משום שכרות:"],[14,"ביותר מרביעית","אף על גב דרמא ביה מיא משכר ואנא יותר מרביעית שתאי:"],[15,"ולהבדיל","יין ושכר אל תשת בבואכם אל אהל מועד וגו' ולהבדיל וגו' ובבואכם להבדיל בין הקדש והחול נמי אל תשת יין ושכר:"],[15,"הדמין והערכין והקדשות","שאסורים שתויי יין לשום אותן לבעלים לפדותן דדילמא לא שיימי להו שפיר:"],[16,"ההוראה","של איסור והיתר שתויי יין אסורין בה:"],[16,"מדרשות","שדורשין בפירקא אסור לשתויי יין שיש בהן הוראה:"],[16,"הלכה","למשה מסיני:"],[17,"תלמוד לומר ולהורות","לאפוקי משנה שאין מורין הלכה מתוך משנה הלכך מותר לשתויי יין לשנות:"],[17,"ר' יוסי אומר יכול אפילו התלמוד","יהא אסור ללמוד תלמוד לומר ולהורות לא אסרתי אלא הוראת הלכה למעשה:"],[18,"שתויי יין מורים","ששרץ טמא וצפרדע טהור ואין חוששין שהרי לכל גלוי:"],[18,"נימא רבי יוסי בר יהודה היא","דאמר שתויי יין מותר בגמרא ואי אפשר שלא יבין ויורנו משם ולא רבנן דאסרו אפילו לשנות בגמרא וכל שכן שום הוראה:"],[19,"והא רב לא מוקים כו'","ואמאי לא דריש בפירקא כיון דגמרא שרי כל שכן מדרשות:"],[19,"לא סגי בלא הוראה","דכ\"ע בעו מיניה:"],[20,"מתני' ד' חטאות","חד משום דאכל קדש בטומאה וחד משום חלב וחד משום נותר וחד משום יוה\"כ:"],[20,"ואשם","מעילה:"],[21,"אינו מן השם","דאין חיוב זה משום אכילה:"]],[[0,"וחלב האשה מטמא טומאת משקין ברביעית","ואם תאמר כיון דמשקה הוי מן התורה כדמשמע בפרק דם הנדה (נדה נה:) דקאמר דמעות עינו דכתיב ותשקמו בדמעות שליש (תהילים פ׳:ו׳) וחלב דכתיב ותפתח את נאד החלב ותשקהו (שופטים ד׳:י״ט) א\"כ ליטמא בכל שהוא כמו שאר משקין כדמשמע פר' קמא דפסחים (דף יד.) דקאמר (אי) דאיכא משקה בהדי בשר ואין רגילות שיהא רביעית מים נדבק בבשר וגם פרק קמא דהתם (דף יז:) קאמר משקה דמטבחייא דכן לא אמרן אלא ברביעית דחזי להטביל מחטין וצינורות אבל בציר מרביעית לא וגם בפ' אלו דברים (ברכות נב.) קאמר נוטלין לידים ואח\"כ מוזגין הכוס שמא יטמאו המשקין שאחורי הכוס מחמת הידים ויחזרו ויטמאו הכוס ואין רגילות שיהא נדבק רביעית בדופני הכוס לכך נראה לומר שאין אלו רק מדרבנן ולכך בעי רביעית וקרא דקמייתי אסמכתא בעלמא:"],[4,"ונכנס למקדש","פירוש ועבד עבודה אבל בכניסה בלא עבודה לא מחייב והכי פירשו בתורת כהנים:"],[12,"אמר רב הלכה כרבי אליעזר","ואם תאמר והא אמר רב (כתובות דף י:) אכל תמרים אל יורה ויש לומר דהתם מדרבנן אבל מן התורה יין דוקא:"],[20,"ארבע חטאות ואשם אחד","ואם תאמר אמאי לא חשיב ה' כגון נשבע שלא יאכלנו ואכלה ויש לומר מידי דאיתיה בשאלה לא קתני ומוקדשין דתני אף על גב דהוו בשאלה מכל מקום השתא שנשחטו ונזרקו דמן כהילכתא ליתא בשאלה אבל ליכא למימר דאיירי בבכור שהרי קאמר בגמרא אקדשיה מיגו דאיתוסף בה איסור וכו' ואי הוי מיירי בבכור לא הוה אומר אקדשיה שהרי קדוש בפטר רחם:"]]],[["\u0001גמ׳\u0002 נימא אית ליה לר\"מ איסור חל על איסור נהי דאיסור חל על איסור לית ליה איסור כולל ואיסור מוסיף אית ליה","טהור מעיקרא לא אסור אלא בחלב הוה ליה טמא מיגו דאסור בחתיכות טהורות איתוסף ביה נמי איסורא עילוי חלב","וחלב מעיקרא לא אסור אלא באכילה אקדשיה מיגו דאיתוסף ביה איסורא דהנאה איתוסף ביה לגבי חלב","ואכתי להדיוט הוא אסור אבל לגבוה שרי הוה ליה נותר מיגו דאיתוסף איסורא לגבי גבוה איתוסף ביה לגבי הדיוט חל עליה יוה\"כ מיגו דאיתוסף ביה איסור לגבי חולין איתוסף ביה לגבי גבוה","ונתני ה' חטאות ונוקמה כגון דאכל כזית פיגול בחדא בהמה קמיירי בשתי בהמות לא קמיירי ונותר ופיגול בחדא בהמה לא משכחת לה","אלמה לא משכחת לה כגון שהעלה אבר פיגול לגבי מזבח דפקע פיגוליה מיניה והוה ליה נותר","וכדאמר עולא קומץ פיגול שהעלה לגבי מזבח פקע פיגולו ממנו והוה ליה נותר באבר אחד קא מיירי בשני אברים לא קמיירי ונותר ופיגול בחד אבר לא משכחת לה","אלמה לא משכחת לה כגון שהעלה אבר פיגול לגבי מזבח דפלגיה אנחיה ע\"ג מזבח ופלגיה מאבראי דמזבח דההוא דמזבח פקע פיגול והוה ליה נותר וכדאמר עולא קומץ פיגול שהעלה על המזבח פקע פיגולו ממנו והוי ליה נותר","א\"ל לא אי רובא דמזבח שדייה למזבח רובא דבראי שדייה לבראי","תפשוט דבעי רמי בר חמא הלכו באברים אחר הרוב או לא אלא בכזית אחד קמיירי בשני זיתים לא קא מיירי","ולא והקתני י\"ה ובי\"ה כותבת דמחייב וכותבת אית ביה שני זיתים","א\"ר זירא כגון שאכל כוליא בחלבה רב פפא אמר כגון דמלייה בתמרי","רב אדא בר אחא מתני ה' חטאות ומתריץ לה כגון דאכל כזית פיגול ולא משני כהני שינויי דקא משנינן","ונתני שש חטאות ונוקמה כגון דאכל כזית דם בחדא אכילה קא מיירי בשתי אכילות לא קא מיירי ושיערו חכמים דאין בית הבליעה מחזיק יותר משני זיתים:","ר\"מ אומר וכו': ונתני אם הוציאו חייב מ\"ט קתני אם היתה שבת אמר רפרם זאת אומרת עירוב והוצאה לשבת ואין עירוב והוצאה לי\"ה","ממאי דלמא יש עירוב והוצאה לי\"ה והכי קתני אם היתה שבת והוציאו חייב אף משום שבת וי\"ה","אלא אי איתמר דרפרם על הדא איתמר דתניא (ויקרא טז, כא) ושלח ביד איש עתי איש להכשיר את הזר עתי אפילו בטומאה ואפי' בשבת עתי במזומן","קתני עתי אפילו בשבת אמר רפרם זאת אומרת עירוב והוצאה לשבת ואין עירוב והוצאה ליה\"כ","ממאי שאני שעיר המשתלח דהכשירו ביה\"כ בכך אלא דרפרם ברותא היא:","\u0001מתני׳\u0002 יש בא ביאה אחת וחייב עליה ו' חטאות כיצד הבא על בתו חייב עליה משום בתו ואחותו אשת אחיו ואשת אחי אביו ואשת איש ונדה: \u0001גמ׳\u0002"],[[0,"גמ' נהי דאיסור","גרידא חל על איסור לית ליה כגון האוכל נבלת בהמה טמאה אינו חייב משום נבלה דהיינו איסור גרידא דליכא לא כולל ולא מוסיף:"],[1,"מגו דנאסר בחתיכות (טהורות)","איתסר נמי בחלב משום טומאה והיינו כולל דלא איתוסף איסורא אחפצא אלא אגברא איתוסף איסורא לגבי אחריני כייל נמי להאי באיסורא:"],[2,"איסור הנייה","היינו מוסיף דאיתוסף איסורא אחפצא:"],[3,"נותר","נמי איסור מוסיף:"],[3,"יה\"כ","איסור כולל דאיתוסף איסורא אגברא אמידי דמשתרי ליה עד השתא:"],[4,"בשתי בהמות לא מיירי ונותר ופיגול בחדא בהמה ליכא","דפיגול אינו אלא בד' עבודות של דם הילכך מדפגלה לא חזיא לא לאכילת אדם ולא לאכילת מזבח הלכך לא חייל עליה נותר:"],[5,"דפקע ממנו פיגולו","דקדשהו מזבח בעבודה. טעמיה דעולא מפרש בזבחים (דף מג.):"],[8,"אי רובא אמזבח שדייה","לכולו אבר אמזבח והוי כוליה נותר כו':"],[9,"הלכו באברים כו'","האי בעיא בפרק בהמה המקשה (חולין ע.):"],[9,"כזית אחד","חלב דאיסור קמיירי בשני זיתי חלב לא קמיירי:"],[10,"כותבת אית בה ב' זיתים","דכך בית הבליעה מחזיק:"],[11,"כגון שאכל כוליא בחלבה","דאאכילת חלב מחייב שלש חטאות ואשם וגורם נמי להשלמת אכילת כותבת וזית של כוליא משלים לכותבת הילכך לא תנא פגול דבשני זיתי חלב לא קמיירי. ואי תימא לוקים כגון שהעלה זית של כוליא אמזבח דהוה חלב פיגול ולכוליא נותר א\"כ לא מהני נותר אזית דחלב ואנן בעינן דליהוי חד אכולהו דאכילה קתני דהיינו כזית:"],[11,"","(גליו\"ן) אלא בכזית אחד מיירי ואי אנחיה לפלגיה דזית אמזבח אין הקטרה בפחות מכזית:"],[11,"כגון שאכל כוליא בחלבה","ואם נפשך לומר ליחייב אכוליא משום פיגול ואחלבה משום נותר לא מצי למימר הכי דטמא שאכל קתני דבחלב עצמו בעי לאוקומי לכולהו איסורי. פירוש מורי:"],[11,"רב פפא אמר","להכי לא תנא פיגול דלא מיירי בשני זיתי חלב ודקא קשיא לך כותבת כגון דמלייה לחלב בתמרי והשלימו לככותבת:"],[12,"ומתרץ לה כגון דאכל כזית פיגול","מבהמה אחרת בהדה:"],[14,"וניתני אם הוציאו חייב","דהא יה\"כ הוא:"],[16,"במזומן לו","שיזמנוהו מאתמול להוליך השעיר:"],[17,"זאת אומרת","מדקתני אפילו בשבת אין עירוב והוצאה ליה\"כ דאם יש איסור הוצאה ליה\"כ אמאי איצטריך לרבויי שבת הא דחי יה\"כ והוא הדין לשבת:"],[18,"דילמא","מיה\"כ לא שמעינן לשבת דיה\"כ שאני דהכשר מצותו בכך דומיא דתמידין שקריבין בשבת:"],[19,"מתני' בתו ואחותו","שבא על אמו והולידה:"],[19,"ואשת אחיו","שנשאת לו קודם לכן ולאחר מיתתו נשאה אחי אביו ובא זה אביה עליה בנדתה:"]],[[6,"אמר עולא קומץ פיגול כו'","ואם תאמר אמאי לא פריך מאבר גופיה דאמר פרק המזבח מקדש (זבחים פד. ופה:) דחשיב שחטו חוץ לזמנו כו' אם עלו לא ירדו כך אם ירדו לא יעלו וקאמר עולא ל\"ש אלא שלא משלה בו האור אבל משלה בו האור אפילו ירדו יעלו וא\"כ ש\"מ דעושה לחמו של מזבח ופקע פיגולו ממנו וי\"ל דמכל מקום לא תנא ליה בהדיא כל כך דפקע פיגולו ממנו כמו בהדיא דקומץ:"],[6,"פקע פיגולו ממנו","במנחות הקשה רש\"י פרק הקומץ (דף יד.) אמאי איצטריך קרא למעט קומץ מפיגול תיפוק לי דלא קרב המתיר כמצותו ותירץ דמיירי במשלה בו האור ברובו שהותרו השירים כדאמרינן קומץ מאימתי מתיר השיריים באכילה משהוצת האור ברובו וקשה דא\"כ (לוקים) דפקע פיגולו ממנו כדמוכח הכא ויש לומר דמיירי שחציו העלה ע\"ג המזבח וחציו לא העלה דלא פקע פיגולו מן החצי שנשאר ואם תאמר ואפי' לכתחלה נמי מעלין ליה כדאמרינן פרק בית שמאי (זבחים מג:) האי קומץ דפלגיה אנחיה אארעא אסיקנא ליה לכתחלה וי\"ל שאני התם שהיה כולו מתחלה ע\"ג המזבח ואח\"כ הוריד חציו למטה אבל הכא לא היה על המזבח וא\"ת מנחת נסכים ומנחת כהן משיח שהם כולן כליל אמאי צריך קרא למעט אותם מפיגול והלא אינה מתרת שום דבר ויש לומר כיון שקדשו בכלי הוי כמו קרבו מתירין וקבעה בפיגול ולכך צריך קרא למעט:"],[9,"תפשוט דבעי רמי בר חמא הלכו באיברים אחר הרוב","פירש בקונטרס היינו בעיא דפרק בהמה המקשה (חולין ע.) ואינו נראה לר\"ת דמאי שייכא ההיא בעיא להך דהכא דהתם מיירי אם יצא חציו ברוב אבר אי הוי כילוד או לא לכך נראה לפרש דהיינו בעיא דפרק מזבח מקדש (זבחים פז.) דאיבעיא להו אויר מזבח כמזבח או לא כו' רובו לכבש ככבש דמי רובו למזבח כמזבח דמי תפשוט דבעי רמי בר חמא יש חיבור בעולין או לא:"],[14,"עירוב והוצאה לשבת","פירוש נתערבה הוצאה עם שאר מלאכות לשבת ולא נתערבה הוצאה עם שאר מלאכות בי\"ה. לשון מורי ז\"ל:"],[15,"אם היה שבת והוציאו","וא\"ת מה שייך זה לענין אכילה ויש לומר דהכי פירושו והוציאו בפיו דכיון שהניחו בפיו ברה\"י והוציאה ברשות הרבים מחייב משום הוצאה דבליעתו היא הנחתו דהא מוציא שתי אותיות וכתבן כשהוא מהלך חייב דכתיבתן זו היא הנחתן:"],[18,"אלא דרפרם ברותא היא","ובפרק שני שעירים (יומא סו:) איתא נמי הא דהכא ולא דחי דילמא שאני שעיר המשתלח כו' כדדחי הכא אלא רגילות הוא דברי תורה עניים במקומם ועשירים במקום אחר:"]]],[["והא לית ליה לרבי מאיר איסור חל על איסור נהי דאיסור חל על איסור לית ליה איסור מוסיף ואיסור כולל אית ליה","כגון שבא על אמו והוליד בת דאיסור בתו ואחותו בהדי הדדי אתי נשאת לאחיו מיגו דאיתוסף איסור לגבי אחין איתוסף איסורא לגבי דידיה","נשאת לאחי אביו מיגו דאיתוסף איסורא לגבי שאר אחי אביו איתוסף לגבי דידיה ה\"ל אשת איש מיגו דאיתוסף איסור לגבי עלמא איתוסף נמי לגבי דידיה ה\"ל נדה מיגו דאיתוסף איסור לגבי בעלה איתוסף נמי לגבי דידיה:","\u0001מתני׳\u0002 הבא על בת בתו חייב עליה משום בת בתו וכלתו ואשת אחיו ואשת אחי אביו ואחות אשתו ואשת איש ונדה ר' יוסי אומר אם עבר זקן ונשאה חייב עליה משום אשת אב","וכן הבא על בת אשתו ועל בת בתה:","\u0001גמ׳\u0002 קתני חייב עליה משום אשת אב מי שריא ליה א\"ר יוחנן כגון שנפלה לו ליבום","א\"ה מאי עבר א\"ר יעקב שעבר משום כלת בנו שניה","כדתני' כלתו ערוה כלת בנו שניה וכן אתה מוצא בבת בנו ובבת בן בנו עד סוף כל הדורות","ומי אית ליה לר' יוסי איסור חל על איסור והא תנן עבר עבירה שיש בה שתי מיתות נידון בחמורה רבי יוסי אומר נידון בזיקה ראשונה שבאה עליו","ותניא כיצד א\"ר יוסי נידון בזיקה ראשונה חמותו ונעשת אשת איש נידון משום חמותו","אשת איש ונעשת חמותו נידון משום אשת איש","א\"ר אבהו מודה רבי יוסי באיסור מוסיף וכן כי אתא רבין א\"ר יוחנן מודה ר' יוסי באיסור מוסיף","מאי איסור מוסיף איכא הכא דאיכא ברא לסבא מיגו דאיתוסף איסורא לגבי בריה איתוסף איסורא לגבי דידיה:","\u0001מתני׳\u0002 הבא על חמותו חייב עליה משום חמותו וכלתו ואשת אחיו ואשת אחי אביו ואחות אשתו ואשת איש ונדה וכן הבא על אם חמיו ועל אם חמותו","רבי יוחנן בן נורי אומר הבא על חמותו חייב עליה משום חמותו ואם חמותו ואם חמיו אמרו לו שלשתן שם אחד הן:","\u0001גמ׳\u0002 א\"ר אלעזר א\"ר הושעיא ר' יוחנן בן נורי וסומכוס אמרו דבר אחד ר' יוחנן בן נורי הא דאמרן סומכוס מאי היא דתנן"],[[0,"והא לית ליה לר' מאיר כו'","דהא לא בעי' לאוקומי לעיל אלא באיסור כולל ומוסיף:"],[1,"מיגו דאיתוסף איסורא בה לגבי שאר אחין","משום אשת אח איתוסף נמי איסורא גבי דידיה:"],[2,"נשאת לאחי אביו מיגו דאיתוסף איסורא לגבי אחיו איתוסף לגבי דידיה","ולגבי אחיו משום אשת אחי האב:"],[2,"","ל\"א ה\"ג \u0003מיגו דאיתוסף איסורא לגבי בני אחי אביו משום אשת אב\u0004:"],[3,"מתני' בת בתו וכלתו","שנשאה בנו:"],[3,"ואחות אשתו","שהיה נשוי את בת חתנו שהיא אחות בת בתו מן האב כגון שהיתה לו בת מאשה אחרת ונשאה זה האב חמיו של בעל בתו וכשבא זה על בתו של חתנו שהיא לו בת בתו היתה אחות אשתו:"],[3,"ואשת אחיו","שמת בנו ונשאה אחיו של זה:"],[3,"ואשת אחי אביו","שמת אחיו ונשאה אחי אביו:"],[3,"אם עבר הזקן","אביו של זה ונשאה ואחר כך בא עליה זה חייב אף על אשת האב:"],[4,"וכן בת אשתו","חייב עליה משום בת אשתו וכלתו ואשת אחיו כו' וכן בת אשתו חייב עליה משום כל אלה:"],[5,"גמ' ומי שריא ליה","לאביו של זה והא אשת אחיו היא דהא מחייבינן ליה לבנו משום אשת אחי אביו אלמא אסירא ליה לאביו משום אשת אח ואין לו אישות בה ואמאי קאמר רבי יוסי חייב עליה משום אשת אב:"],[5,"שנפלה לו ליבום","מאחיו שמת בלא בנים ובא הוא ליבמה:"],[6,"אם כן מאי עבר","זקן הא שפיר עבד דאינה אסורה עליו משום איסור ערוה. ואם תאמר כלתו היא דהא מחייבינן לבריה משום אשת אח לאו פירכא היא דאיכא לאוקומה דאשת אחיו של בנו מאמו היא ולאו כלתו של אב היא אלא אשת חורגו ומותרת לו:"],[6,"דעבר משום כלת בנו שהיא שניה","מדברי סופרים דהא חייבנו לבריה משום כלתו. והוא הדין נמי דמצי לתרוצי דעבר משום בת בת בנו שהיא שניה אלא חדא מינייהו נקט:"],[8,"שתי מיתות","חמותו ואשת איש איכא שריפה וחנק ושריפה חמורה מחנק:"],[8,"בזיקה ראשונה","ולא באחרונה דאין איסור חל על איסור:"],[11,"מודה ר' יוסי","במתני' דאיכא איסור מוסיף ה\"ה לכולל ובת אחת כדמפרש לקמן הלכך חמותו ונעשית אשת איש אף על גב דאיכא איסור מוסיף דאיתוסף איסורא דאשת איש אכולי עלמא אפ\"ה נידון בחמותו משום דחמורה היא אבל אשת איש ונעשית חמותו ליכא לא כולל ולא מוסיף:"],[12,"","והכא בבת בתו ועבר אביו ונשאה \u0003מאי איסור מוסיף איכא \u0004- דליתוסף איסור אשת אב אהאי:"],[12,"כגון דאית ליה ברא לסבא","ואחיו של זה הוא דמגו דאיתוסף איסורא אההוא ברא משום אשת אב איתוסף נמי אהאי:"],[14,"מתני' ר' יוחנן בן נורי אומר כו' משום חמותו ואם חמותו","שהיה נשוי בתה ובת בתה ואם חמיו שנשא את בת בנה:"],[14,"שלשתן שם אחד","בחד קרא כתיבי ובחד לאו הלכך אין חילוק חטאות ביניהם:"]],[[1,"נשאת לאחיו מיגו דאיתוסף כו'","פירוש משום אשת אח וא\"ת והא ממזרת היא ואם כן היאך אסורה לאחיו משום אשת אח איך חל איסור אשת אח על איסור ממזרת ויש לומר דמיירי דאחיו נמי ממזר ואם כן ליכא איסור ממזרת דהוא עצמו כמו כן ממזר ועי\"ל דאיסור חמור חל שפיר על איסור קל כדפרישית לעיל:"],[3,"הבא על בת בתו","הקשה רבינו ברוך אמאי לא חשיב בהדייהו בת בנה כגון שניסת בתו לבן אשתו וילדה לו בת דהויא בת בתו ובת בנה בבת אחת וגם בסיפא קשה אמאי לא תני בת בנה ובת בתה דמשכחת לה ביעקב שנשא רחל ולאה שאינם אחיות ויש לה בן לרחל מאדם אחר ונשא בת לאה שהיתה לה מיעקב וילדה בת לאה בת ובא יעקב עליה הרי היא בת בן אשתו ובת בתו ולפי מה שפי' לקמן דמתני' לא מיירי רק באיסור מוסיף ניחא שפיר והקשה הקדוש ה\"ר יום טוב אמאי לא תני חמותו כגון שנשא בת בת בתו דבת בתו היא חמותו וי\"ל דת\"ק לא מיירי בעבד איסורא ומהאי טעמא לא תני אם חמותו ואם חמיו ושניות הן ואפילו לרבי יוסי נמי דמיירי בעבר זקן ונשאה יש לומר להכי לא תני להו דהוי איסור כולל ואפילו לר' חייא דאמר פרק ד' אחין (יבמות לב: ולג.) לר' יוסי מחייב תרתי משום איסור כולל היינו באיסור כולל בשם אחד אבל בשני שמות לא ומש\"ה ניחא לדידיה גבי אשת איש ונעשת חמותו דלא אמרי' נידון בחמותו משום דשני שמות הן:"],[3,"ואחות אשתו","ואומר הר\"י דלא גרס ליה דאם כן שבע הוו ואדתני לעיל שש ליתני שבע ואם תאמר וליתני שבע וליחשוב אחות אשתו וכגון שדינה בת יעקב ניסת לאדם מעלמא וילדה לו בת ואותו אדם היה לו בת אחרת מאשה אחרת ונשאה יעקב ואם כן הרי בת דינה ליעקב בת בתו ואחות אשתו וחיילא איסור אחות אשתו באיסור כולל מיגו דמיתסר בשאר אחיות משום אחות אשה איתסר נמי בבת דינה משום אחות אשה ויש לומר דלא תני רק איסורי דמודי בהו ר' יוסי ומיירי בסיפא דהיינו איסור מוסיף ואפילו לר' חייא דאמר דאית ליה לר' יוסי איסור כולל י\"ל לא נחת למיתני במתני' רק איסור מוסיף וא\"ת מכל מקום אמאי לא תנא אחות אשתו ובבת אחת וכגון שיעקב נשא אחותו נכרית של בת דינה בת יעקב וילדה לו בת השתא הויא אותו בת של דינה בת בתו של יעקב ואחות אשתו ויש לומר דבאיסורא שחל ע\"י קדושין לא תני אלא אותה שחל האיסור מיד בשעת קדושין והשתא מיד שנשא יעקב בת האיש לא היה שום איסור עד שנולדה דינה מאותו האיש אז חל איסור אחות אשתו עם איסור בת בתו וא\"ת ובגמרא נמי דקאמר מודי ליה באיסור מוסיף מנליה דילמא כולה מתני' באיסור בת אחת מיירי וכגון שנתקדשה הלה פחות מבת ג' שנים דכי נשלם שנה שלישית אז חלו כל האיסורין וחשיב במתני' בבת אחת וי\"ל דלא חשיב איסורא שע\"י קדושין אלא כשחלין בשעת קדושין ואי בבת אחת הויין עלה הרי לא חלו שום איסור עד גמר שלש שנים ויום אחד ועוד י\"ל דמתני' לא אתיא לאורויי רק באיסור מוסיף כמו שפירשתי:"],[13,"אשת אחיו","היינו אשת אחיו מאמו דאי מאביו היאך נשאה זקן ולא תפסי בה קידושין דהויא כלתו ומכאן משמע דאשת אחיו מאמו בכרת ומחייב עליה חטאת והא דממעט בתורת כהנים היינו מעריריות אבל כרת איכא:"]]],[["שחטה ואת בת בתה ואח\"כ שחט את בתה סופג את הארבעים סומכוס אומר משום רבי מאיר סופג שמונים","אמר רבא דלמא לא היא עד כאן לא קאמר ר' יוחנן בן נורי הכא אלא משום שמות מוחלקין דמיקריא חמותו ומיקריא אם חמותו ומיקריא אם חמיו","אבל גבי אותו ואת בנו דכולהו אותו ואת בנו מיקריין דאין שמות מוחלקין לא","אמר רב נחמן בר יצחק דלמא עד כאן לא קאמר סומכוס אלא גבי אותו ואת בנו דגופין מוחלקין","אבל הכא דאין גופין מוחלקין אימא כר' אבהו א\"ר יוחנן ס\"ל דא\"ר אבהו א\"ר יוחנן (ויקרא יח, יז) שארה הנה זמה היא הכתוב עשאן לכולן זמה אחת:","\u0001מתני׳\u0002 אמר רבי עקיבא שאלתי את רבן גמליאל ואת ר' יהושע באיטליס של עימאום שהלכו ליקח בהמה למשתה בנו של רבן גמליאל הבא על אחותו ועל אחות אביו ועל אחות אמו מהו חייב אחת על כולן או חייב על כל אחת ואחת","אמרו לו לא שמענו אבל שמענו הבא על ה' נשיו נדות בהעלם אחת שהוא חייב על כל אחת ואחת (ורואה אני) שהדברים ק\"ו:","\u0001גמ׳\u0002 היכי דמי אילימא כדקתני מאי תיבעי ליה הרי שמות מוחלקין הרי גופין מוחלקין","אלא הכי קתני הבא על אחות אביו שהיא אחות אמו חייב אחת על כולן או חייב על כל אחת ואחת מהו מי אמרינן הרי שמות מוחלקין או דלמא הרי אין גופין מוחלקין","אמרו לו לא שמענו אבל שמענו הבא על ה' נשיו נדות בבת אחת שהוא שם אחד שחייב על כל אחת ואחת משום נדה","וראינו שהדברים ק\"ו ומה הבא על ה' נשיו נדות בבת אחת שהיא שם אחת חייב על כל אחת ואחת אחותו שהיא אחות אביו שהיא אחות אמו שהן ג' שמות אינו דין שיהא חייב על כל אחת ואחת","איכא למיפרך מה לה' נדות שכן גופין מוחלקין","אלא אמר קרא (ויקרא כ, יז) ערות אחותו גלה לחייב על אחותו שהיא אחות אביו שהיא אחות אמו","אמר רב אדא בר אהבה משכחת לה ברשיעא בר רשיעא שבא על אמו והוליד ב' בנות וחזר ובא על אחת מהן והוליד בן ובא בנו על אחות אמו שהיא אחותו שהיא אחות אביו דהוה ליה רשיעא בר רשיעא","ת\"ר בא עליה וחזר ובא עליה וחזר ובא עליה חייב על כל אחת ואחת דברי ר' אליעזר וחכמים אומרים אינו חייב אלא אחת","ומודים חכמים לר' אליעזר בבא על ה' נשיו נדות בבת אחת שהוא חייב על כל אחת ואחת הואיל והוא גרם להן","אמר רבא לרב נחמן מי אמרינן הואיל והוא גרם להן והתניא הוא בהעלם אחת והיא בה' העלמות הוא אינו חייב אלא אחת והיא חייבת על כל אחת ואחת","אלא אימא הואיל וגופין מוחלקין","איבעיא להו קצר וקצר מה לי אמר רבי אליעזר","טעמא דר' אליעזר התם משום דהוא דעבד תרתין ואמטול להכי אמר חייב על כל אחת ואחת וה\"נ דעבד תרתין","או דלמא טעמיה דרבי אליעזר התם משום דאי אפשר לו לערבן לביאות זו בזו אמטול להכי א\"ר אליעזר חייב על כל אחת ואחת אבל קצר כגרוגרת וחזר וקצר כגרוגרת בהעלם אחת כיון דאפשר לו לערב שתי גרוגרות בבת אחת אינו חייב אלא אחת מאי","אמר רבה טעמא דר\"א התם משום דעבד תרתי ה\"נ הא עבד תרתי ורב יוסף אמר טעמא דר' אליעזר התם דאי אפשר לו לערבן אבל אפשר לו לערבן אינו חייב אלא אחת","איתיביה אביי לרבה ר' אליעזר מחייב על ולדי מלאכות במקום אבות מלאכות","הא אב ואב בבת אחת פטור ואי אמרת טעמא דרבי אליעזר משום דקעבד תרתי אמאי פטור","אמר מר בריה דרבנן אנא ורב נחומי בר זכריה תרגימנא הכא במאי עסקינן","בדלית המודלית על גבי תאינה וקצצן בבת אחת משום הכי מחייב רבי אליעזר הואיל ושמות מוחלקין וגופין מוחלקין","דכוותה קצר וקצר היכי משכחת לה דמיפטר כגון שקצר שתי גרוגרות בבת אחת אבל קצר כגרוגרת וחזר וקצר כגרוגרת חייב:","\u0001מתני׳\u0002 ועוד שאל רבי עקיבא אבר המדולדלת בבהמה מהו אמרו לו לא שמענו אבל שמענו אבר המדולדלת באדם שהוא טהור וכך היו"],[[0,"שחטה ואת בת בתה","לא עבד איסורא:"],[0,"ואחר כך שחט את בתה","של ראשונה עכשיו נמצא ששחט ב' איסורים ראשונה אותו ואת בנו שלישית ושניה בנו ואותו דבנו שניה ואותו שלישית והילכך סופג פ' לסומכוס אף על גב דשם אחד הן:"],[3,"דגופין מוחלקין","שמחמת ראשונה ושניה באו אלו שני איסורים על השלישית אבל הכא אין גופין מוחלקין:"],[4,"דלמא כדר' אבהו","אבל הכא אע\"ג דעל ידי בתה ובת בתה ובת בנה נאסרה הזקנה עליו ג' איסורים ואין גופין מוחלקין בה:"],[4,"זמה אחת","דאינו חייב על אשה ובתה ובת בתה ובת בנה בביאה אחת כמתני' אלא אחת והיינו חמותו ואם חמותו ואם חמיו:"],[5,"מתני' באיטליז","שוק:"],[5,"עמאום","שם העיר:"],[5,"הבא על אחותו כו'","מפרש בגמ':"],[7,"גמ' הרי שמות מוחלקין","שג' לאוין מוחלקין בהו:"],[7,"שמות","לאוין:"],[10,"שם א'","לנדה לא תקרב:"],[10,"שהיא אחות אביו","כדמפרש לקמי' ברשיעא בר רשיעא:"],[12,"ערות אחותו גלה","מפרש בפ\"ק (לעיל כריתות ב:) דאייתר ליה להא דרשא:"],[14,"בא עליה","על אחת מכל העריות וחזר ובא עליה בהעלם אחת:"],[15,"בבא על ה' נשים נדות","בהעלם אחת:"],[15,"הואיל והוא גרם להן","להביא כל אחת חטאת דהיינו ה' חטאות הלכך הוא נמי מייתי ה' חטאות אבל ה' ביאות בערוה אחת בהעלם א' היא נמי לא מתיא אלא חד וכן הוא:"],[16,"הוא בהעלם אחת","בין [בא] ה' ביאות בה' עריות בין ה' ביאות על כל אחת:"],[16,"והן ה' העלמות","שנודע לכל אחת בין כל ביאה וביאה מביאותיו הוא אינו חייב אלא אחת על כל אחת והיא על כל אחת ואחת חייבת ה' דהיינו על כל ביאה וביאה. אלמא אף על גב דהוא גרם לכל אחת להביא ה' חטאות לא בעי הוא למייתי על כל חדא אלא אחת: ואית ספרים דכתיב בהו \u0003הוא בהעלם אחת והיא בה' העלמות \u0004- ובערוה אחת מיירי לשון נקייה הוא ויש\"ר כח\"ו:"],[18,"קצר","כגרוגרת בשבת וזה השיעור חזר וקצר בהעלם א' מה לי אמר רבי אליעזר:"],[20,"שתי ביאות א\"א לערב","הילכך חשיבי [אבל] קצירת שתי גרוגרות אפשר לערב ולקצור בבת אחת:"],[22,"ר' אליעזר מחייב על ולדי מלאכות במקום אבות מלאכות","שאם עשה אב ותולדה בהעלם אחת חייב שתים הא אב ואב כגון קצר וקצר דזו וזו אב מלאכה פטור מן אחת:"],[24,"הכא במאי עסקינן","הא דקתני רבי אליעזר כו' דדייקינן מינה הא אב ואב פטור:"],[25,"בדלית","טרייל\"א של גפן היא:"],[25,"המודלית על גבי תאנה","ותאנים בתאנה ואין ענבים בגפן והיה צריך לבצור הגפן להסקה וקצץ בבת אחת פרי התאנה וזמורת הגפן דחייב שתים חדא אפרי דתאנה דהיינו קוצר וחדא אזמורה דתולדה דקוצר דקיימא לן (שבת דף עג:) זומר וצריך לעצים תולדה דקוצר היא משום הכי חייב שתים אף על גב דבבת אחת הואיל ושמות מוחלקין זה אב וזו תולדה וגופין מוחלקין דשני אילנות הן:"],[26,"דכוותה גבי קצר וקצר","דדייקינן הא אב ואב פטור כגון שקצר שתי גרוגרות בבת אחת דהשתא לאו תרתין הוא דעבד ובבת אחת עשאן גופין ושמות מוחלקין נמי ליכא אבל קצר וחזר וקצר דתרתין מלאכות עבד בהעלם אחת מחייב ר' אליעזר:"],[27,"מתני' אבר המדולדלת בבהמה","תלוש רובה ומעורה במקצת:"],[27,"מהו","שיטמא משום אבר מן החי כאילו נתלש לגמרי דקיימא לן בהעור והרוטב (חולין קכח:) דאבר מן החי מטמא כנבלה:"],[27,"אבר","הנתלש מן האדם לגמרי מטמא כמת בפרק העור והרוטב (חולין קכט:) והמדולדלת שדבוק קצת טהור:"]],[[7,"הרי שמות מוחלקים","ואף על גב דלעיל גבי עריות צריך קרא אשה לחייב על כל אשה ואשה אף על גב דגופין מוחלקין מ\"מ הוה פשיטא ליה לרבי עקיבא דגופין מוחלקין חייב על כל אחת ואחת:"],[12,"ערות אחותו גלה","הקשה רבינו ברוך אמאי לא מייתי כרת דכתיב באחותו דמצרכי רבנן להכי ומייתי לדרבי יצחק ויש לומר דמייתי הא דפשוט יותר וכהאי גוונא אשכחנא בסנהדרין (דף לד:) ובמגילה (דף כ.):"]]],[["מוכי שחין עושין בירושלים הולך לו ערב פסח אצל הרופא וחותכו עד שמניח בו כשערה ותוחבו בסירא ונמשך ממנו","והלה עושה פסחו והרופא עושה פסחו ורואה אני שהדברים ק\"ו:","\u0001גמ׳\u0002 תנן התם המוחק את הכרישה והסוחט בשערו ובכסותו משקה שבתוכו אינם בכי יותן והיוצאין ממנו הרי הן בכי יותן","אמר שמואל וכרישה עצמה הוכשרה מאי טעמא בשעת פרישה ממנו הוכשרה","והתנן ערב פסח הולך לו אצל כו' ואי אמרת בשעת פרישתן הוכשר הא איכא נמי ההוא אבר המדולדל בשעת פרישתו מאדם נטמייה לאדם","כדקאמר רב יוסף בניתזין בכל כחן הכא נמי בניתזין בכל כחן","והיכא איתמר דרב יוסף אהא זב וטמא מת שהיו מהלכים וירדו עליהם גשמים אע\"פ שסוחטין זה את זה משקין היורדין מצד העליון לצד התחתון טהורים שאין מחשבין אלא שיצאו מכולן","יצאו מכולן הרי מכשירין שאין נחשבין אלא לאחר שיצאו מגופו אמר רב יוסף בניתזין בכל כחן:","\u0001מתני׳\u0002 ועוד שאלו ר' עקיבא השוחט ה' זבחים בחוץ בהעלם אחת מהו חייב על כל אחת ואחת או אחת על כולן אמרו לו לא שמענו","אמר רבי יהושע שמעתי באוכל מזבח אחד מה' תמחויין בהעלם אחת שהוא חייב על כל אחת ואחת משום מעילה ורואה אני שהדברים ק\"ו","אמר ר\"ש לא כך שאלו ר' עקיבא אלא באוכל נותר מחמשה זבחים בהעלם אחת מהו חייב אחת על כולן או חייב על כל אחת ואחת אמרו לו לא שמענו","א\"ר יהושע שמעתי באוכל מזבח אחד בה' תמחויין בהעלם אחת שהוא חייב על כל אחת ואחת משום מעילה ורואה אני שהדברים ק\"ו","אמר לו ר' עקיבא אם הלכה נקבל אם לדין יש תשובה אמר לו השב","אמר ולא אם אמרת במעילה שעשה בה את המאכיל כאוכל ואת המהנה כנהנה","צירף את המעילה לזמן מרובה תאמר בנותר שאין בו אחת מאלו:","\u0001גמ׳\u0002 מאי קשיא ליה לר\"ש הכי קא קשיא ליה מה ראיה לשוחט מאוכל מה לאוכל שכן נהנה","אלא כך שאלו האוכל נותר מחמשה זבחים בהעלם אחת מהו חייב בכל אחת ואחת או אחת על כולן אמרו לו לא שמענו","אמר ר' יהושע שמעתי באוכל מזבח אחד מחמשה תמחויין בהעלם אחת שחייב על כל אחת ואחת משום מעילה ורואה אני שהדברים ק\"ו מה מזבח אחד שאין גופין מוחלקין חייב על כל אחת ואחת משום תמחויין מוחלקין חמשה זבחים דגופין מוחלקין לא כל שכן","אמר ר' שמעון לא כך שאלו אלא באוכל מזבח אחד נותר מחמשה זבחים בהעלם אחת מהו חייב אחת על כולן או חייב על כל אחת ואחת אמרו לו לא שמענו","רבי יהושע אומר שמעתי באוכל מזבח אחד בחמשה תמחויין שהוא חייב על כל אחת ואחת משום מעילה ורואה אני שהדברים ק\"ו: אמר לו ר' עקיבא אם הלכה נקבל כו':","קיבלה רבי יהושע להא תשובה מר' עקיבא או לא ת\"ש דתניא אכל ה' חתיכות נותר מזבח אחד בהעלם אחת בחמשה תמחויין אינו מביא אלא חטאת אחת ועל לא הודע שלהן אינו מביא אלא אשם תלוי אחת","מחמשה תמחויין בחמש העלמות מביא חטאת על כל אחת ואחת ועל לא הודע שלהן מביא אשם תלוי על כל אחת ואחת מה' זבחים בהעלם אחת חייב","ר' יוסי בר' יהודה אומר אפילו אכל ה' חתיכות מה' זבחים בהעלם אחת אינו מביא אלא חטאת אחת ועל ספיקן אין מביא אלא אשם תלוי אחת כללו של דבר כל שחלוקין בחטאות חלוקין באשמות","אכל ה' חתיכות בה' תמחויין מזבח אחד לפני זריקת דמים אפי' בהעלם אחת חייב על כל אחת ואחת משום מעילה"],[[0,"מוכי שחין","אבריהן נופלין:"],[0,"וחותכו","לא משום טהרה שקודם לכן נמי טהור אלא שלא יהא מאוס ברגל באבר המדולדל:"],[0,"שמניח כשערה","ולא חותכו לגמרי שלא יטמא אותו החותכו שנוגע בו בשעת פרישה:"],[0,"ותוחבו","לאבר בסירא בקוץ המחובר לקרקע או לכותל והוא החולה נמשך ונתלש האבר מאליו:"],[1,"ק\"ו","מפרש בגמ' אדם שמטמא מחיים שמקבל טומאה מחיים [ואפילו הכי לא מטמא אבר המדולדל ק\"ו בהמה שאינה מקבלת טומאה מחיים]:"],[2,"גמ' המוחק את הכרישה","כותש את הקפלוט שקורין פור\"ש:"],[2,"הסוחט מים שבשערו","כגון יוצא מבית המרחץ ומסתפג באלונטית:"],[2,"משקין שבתוכו","שבתוך הכרישה אינן בכי יותן דלא חשיבי מידי הואיל ובלועין הן:"],[2,"והיוצאין הימנו הרי הן בכי יותן","אם נפלו על הזרעים:"],[3,"וכרישה עצמה","לאחר שיצאו ממנו המשקין הוכשרה אף על פי שלא נגעה בהן אחר יציאתן:"],[4,"(מ\"ט כו') ניטמייה לאדם","למוכי שחין:"],[5,"בניתזין בכל כוחן","שמשך עצמו בכח ונתלש בכח וליכא נגיעה בשעת פרישה אבל מי כרישה יוצאין בנחת ולאחר שיצאו ממנה חשובין הן מיד וקודם שיפלו לארץ נוגעין בה בשעת פרישה:"],[6,"זב או טמא מת שהיו מהלכין בדרך וירדו גשמים","על בגדיהן אף על פי שסחטן הזב בעצמו החליק כסותו כלפי מטה שיפלו המים אותן המשקין היורדין בבגד מלמעלה למטה טהורים ואין מטמאין אדם הנוגע בהן לפי שאינן חשובין הואיל ועומדין ליבלע בשפה התחתונה של בגד:"],[7,"יצאו מכולן הרי אלו מכשירין","אם נפלו על הזרעים וטהורין שאינן מטמאין את הזרעים אלא אם כן הזב נוגע בהן לאחר שיצאו מכולו. והא דכתיב בסיפא אלא לאחר שיצאו מגופו ל\"ג לה:"],[9,"מתני' חייב","משום מעילה על כל תמחוי אם אכלן קודם זריקת דמים:"],[9,"ק\"ו","מפרש בגמרא:"],[12,"אם הלכה","שקבלת מרבך שחייב על כל אחד מן הזבחים נקבלנה ממך:"],[12,"ואם לדין","שאתה למד אותה מק\"ו ממעילה יש תשובה:"],[13,"המאכיל כאוכל","שאם נתן אוכל הקדש לחבירו חייב כאילו אכלה הוא עצמו דקיי\"ל המוציא הקדש לחולין הוא מעל ולא מי שניתן לו:"],[13,"והמהנה כנהנה","במידי דלאו בר אכילה:"],[14,"צירף את המעילה לזמן מרובה","שאם נהנה היום בחצי פרוטה ומכאן עד ג' שנים חצי פרוטה מצטרפות לקרבן ולקמן בפרק ספק אכל חלב (כריתות דף יח:) מפיק לה מתמעול מעל ריבה:"],[15,"גמ' מאי קשיא ליה לר' שמעון","מה ראייה לשוחט בחוץ מאוכל זבח לפני זריקה:"],[20,"לא הודע","שהיו ה' חתיכות נותר וה' חתיכות כשרות לפניו ואין ידוע איזו אכל אם הה' של נותר אם הה' כשרות:"],[21,"בה' העלמות","ומזבח אחד אכל נותר חייב ה' משום נותר דהעלמות מחלקין:"],[21,"מה' זבחים","אכל נותר בהעלם א' חייב ה' הואיל וגופים מוחלקין. ר' יוסי ור' אליעזר סבירא להו כר' עקיבא דמתני' דר' שמעון:"],[22,"אבל אכל ה' חתיכות כו'","אתאן לת\"ק דאיירי רישא בה' חתיכות נותר מזבח אחד והכי קאמר לגבי מעילה מודינא דתמחויין מחלקין:"],[23,"לפני זריקת דמים","שייכא מעילה אבל נזרק הדם דהיתה לה שעת היתר לכהנים שוב אין בו מעילה וכן מפורש במנחות בפרק התכלת (מנחות דף מז:):"]],[[2,"המוחק את הכרישה","פי' בקונטרס כותש הקפלוט וקשה דא\"כ פירות נינהו ומי פירות אינן מכשירין ועוד קשה דקאמר הסוחט בשערו אינו בכי יותן והיוצאין ממנו הרי הוא בכי יותן ופי' הקונטרס סחט בשערו אחר שיצא מבית המרחץ וא\"כ שבשערו אמאי אינו בכי יותן והלא תחלתו לרצון היה ואמרינן (מכשירין פ\"א מ\"א) כל משקה שתחלתו לרצון אף על פי שאין סופו לרצון לכך פר\"י דמיירי שירדו הגשמים עליהם ולא היה לרצון עד שיצאו מהם:"],[2,"והיוצאין ממנו לאחר שיצאו הרי זה בכי יותן","אף על גב דשלא ילקה הכותל אינו בכי יותן התם משום דלא ניחא ליה דאתו והכא נמי אף על גב דלא ניחא ליה מעיקרא מכל מקום כיון שהוא עצמו דוחקן להוציא מהם המים אחשבינהו:"],[6,"מצד העליון לצד התחתון טהורין","פירש בקונטרס משום שסופה ליבלע בבגד וקשה שהרי במסכת נדה פרק האשה (דף סב: ושם) קאמר חרסין שבלעו משקים טמאים ונפלו לאויר התנור כי הוסק התנור טמא מפני שהמשקין יוצאין ואע\"פ שלאחר היסק יחזרו ויבלעו החרסין אלא יש לפרש משום דהוי שלא לרצון כ\"ז שהם על בגדיו כמו במשקין שבכרישה:"],[13,"ואת המהנה כנהנה","והוא הדין דמצי למימר הנהנה כאוכל מה שאין כן בנותר אלא אגב דנקט מאכיל כאוכל קאמר מהנה כנהנה:"]]],[["ואילו על ספיקו מביא אשם תלוי לא קתני מני הא אילימא ר\"ע ליתני נמי סיפא ועל ספיקן מביא אשם תלוי דהתנן ר\"ע מחייב על ספק מעילה אשם תלוי","אלא לאו רבי יהושע היא וקתני בה' העלמות מביא ה' חטאות וש\"מ קיבלה מיניה","אלא אדרבה מסיפא דקתני מה' זבחים אפילו בהעלם אחת חייב על כל אחת ואחת ש\"מ לא קיבלה מיניה","ואלא מאי אית למימר תנאי היא דאיכא תנא דקיבלה ואיכא תנא דלא קיבלה","אפי' תימא ר\"ע היא והאי תנא סבר לה כותיה בחדא ופליג עליה בחדא סבר לה כותיה בהעלמה ופליג עליה במעילות","ה\"ד ה' מעילות אמר שמואל כאותה ששנינו חמשה דברים בעולה מצטרפין הבשר והחלב והיין והסלת והשמן","חזקיה אמר כגון שאכל מה' אברים ר\"ל אמר אפילו תימא באבר אחד משכחת לה בכתף רבי יצחק נפחא אמר כגון שאכל בה' מיני קדירה רבי יוחנן אמר כגון שאכל בה' טעמים:","\u0001מתני׳\u0002 אמר ר' עקיבא שאלתי את רבי אליעזר בעושה מלאכות הרבה בשבתות הרבה מעין מלאכה אחת בהעלם אחת מהו חייב אחת על כולן או חייב על כל אחת ואחת","אמר לו חייב על כל אחת ואחת מק\"ו ומה נדה שאין בה תוצאות הרבה וחטאות הרבה חייב על כל אחת ואחת שבת שיש בה תוצאות הרבה ומיתות הרבה אינו דין שיהא חייב על כל אחת ואחת","אמרתי לו אם אמרת בנדה שיש בה שתי אזהרות שהוא מוזהר על הנדה והנדה מוזהרת עליו תאמר בשבת שאין בה אלא אזהרה אחת","אמר לי הבא על הקטנות יוכיח שאין בה אלא אזהרה אחת וחייב על כל אחת ואחת","אמרתי לו אם אמרת בקטנות שאף על פי שאין בהן עכשיו יש בהן לאחר זמן תאמר בשבת שאין בה עכשיו ולא לאחר זמן","אמר לי הבא על הבהמה יוכיח אמרתי לו הבהמה כשבת:","\u0001גמ׳\u0002 מאי קבעי מיניה אי שבתות כגופין דמיין ואי לא בעי מיניה ניבעי העושה מלאכה אחת בשבתות הרבה","אלא ולדי מלאכות אי כאבות דמיין ואי לא בעי מיניה ניבעי מיניה העושה מלאכות הרבה מעין מלאכה אחת בשבת","אמר רבא אמרי בי רב תרתי בעא מיניה שבתות כגופין דמיין ואי לא בעא מיניה ולדי מלאכות כמלאכות דמיין אי לא","ושבתות היכי מיבעי ליה שגגת שבת וזדון מלאכות פשיטא ליה דימים שבינתיים הויין ידיעה לחלק","וזדון שבת ושגגת מלאכות הוא דבעי מיניה אי כגופין דמיין אי לא","או דלמא זדון שבת ושגגת מלאכות פשיטא ליה דכגופין דמיין ושגגת שבת וזדון מלאכות הוא דבעי מיניה דימים שבינתים אי הויין ידיעה לחלק אי לא","אמר רבה"],[[0,"ואילו על הספקות כו' לא קתני","בסיפא גבי מעילה:"],[0,"מני","כלומר ת\"ק מני:"],[0,"ר\"ע מחייב על ספק מעילה כו'","בפרק דם שחיטה (לקמן כריתות כב.):"],[1,"וקתני בה' העלמות כו'","העלמות הוא דמחלקין אבל זבחים לא וש\"מ הדר ביה ר' יהושע:"],[3,"אלא מאי אית לך למימר","מיהא ברייתא תנאי היא בתמיה. כלומר מאי בעית למשמע מהך ברייתא תנאי היא ת\"ק דקתני העלמות דמשמע דהעלמות מחלקין ולא זבחים אית ליה דקיבלה ר' יהושע והדר ביה והאי דקתני ה' זבחים בהעלם אחד חייב על כל אחד ואחד תנא אחרינא הוא ואית ליה דלא קיבלה אפילו הא לא פשטת מינה דתנאי היא דאפילו תימא ר' עקיבא היא ות\"ק אליבא דר\"ע קאי מדקתני העלמות דמשמע העלמות ולא זבחים. ודקא קשיא לך דלא תניא אשם תלוי אספק מעילות:"],[4,"האי תנא סבר לה כו'","והאי דקתני מה' זבחים בהעלם אחד חייב על כל אחד תנא אחרינא הוא ור' יהושע היא:"],[5,"ה' דברים בעולה מצטרפין","לענין כזית להעלותן בחוץ שאם העלן חייב כרת ולהכי נקט עולה דבשאר זבחים לא מצטרף בשר לפי שאינן כליל. כאותה ששנינו כו' ה\"נ שאכל מה' דברים הללו:"],[6,"בכתף","יש ה' אברים הפרסה והעצם התחתון עד הארכובה ושני עצמות לבד מן הכתף:"],[6,"ה' מיני קדירה","כגון כרישין ובצלים וכרוב ודלעת ולפת ואכלן כזה עצמו וכזה עצמו:"],[6,"ה' מיני טעמים","צלי ומבושל כבוש שלוק וצלי קדר:"],[7,"מתני' מלאכות הרבה מעין מלאכה אחת","תולדות הרבה של אב אחד בשבתות הרבה אותן שעשה בשבת זו עשה בשבתות אחריני וכולן בהעלם אחת. ובגמרא פריך מאי קמבעיא ליה דנקט תרי מילי שבתות הרבה ותולדות הרבה ואמאי נקט תולדות ולא אבות:"],[8,"תוצאות הרבה","עניינים הרבה כגון שבת דאיכא אבות מלאכות ותולדותיהן:"],[8,"נדה אין בה תוצאות הרבה","דאין חיובה אלא ביאה וחייב על כל ביאה וביאה בהעלם אחת כדאמר ר\"א לעיל בגמרא בא עליה וחזר ובא עליה כו':"],[9,"והנדה מוזהרת עליו","דכתיב (ויקרא כ׳:י״ח) ונכרתו שניהם מקרב עמם:"],[10,"על הקטנות","כמו על הקטנה ומאי קטנות דעלמא. כלומר הבא על אחת מן הקטנות ביאות הרבה בנדתה יוכיח שאינה מוזהרת עליו וחייב על כל ביאה וביאה:"],[12,"הבא על הבהמה יוכיח","שחייב על כל ביאה כדאמרן לעיל טעמא שא\"א לערב הביאות:"],[12,"בהמה כשבת","פלוגתא היא בגמרא איכא למאן דאמר קבל ר\"ע מר\"א והכי קאמר ליה בהמה כשבת מה בהמה חייב על כל אחת ואחת אף שבת חייב על כל אחת דאינו יודע להשיב כלום ולמאן דאמר לא קיבלה מיניה ה\"ק ליה אף בהמה מיבעי לי כשבת:"],[13,"גמ' מאי קבעי מיניה","דנקט שבתות הרבה ועושה בזו אותה מלאכה שעשה בזו ונקט תולדות ולא אבות:"],[13,"אי קבעי מיניה שבתות כגופין דמיין אי לא","אי האי דעבד בכמה שבתות אותן מלאכות שעשה בזו עשה בזו ובהעלם אחד דלא הודע לו בינתיים מי אמרינן כיון דבתרי שבתות עשאן הויין הני תרתי שבתות כשני גופי עבירות כאילו קצר וזרע בהעלם אחת וחייב על כל אחת או לא דאמרינן דהוי כעושה מלאכה אחת כמה פעמים בהעלם אחת דחייב חדא אי הא קמיבעיא ליה אמאי נקט תולדות ליבעי הכי אעשה אב מלאכה אחת בשבתות הרבה מהו:"],[14,"אי בולדי מלאכות קבעי מיניה","אם עושה תולדות הרבה מאב אחד אי חייב אחת או על כל אחת ואחת ולהכי נקט תולדות אם כן אמאי נקט שבתות הרבה ליבעי הכי העושה מלאכות הרבה מעין מלאכה אחת בשבת אחת:"],[15,"תרתי בעא מיניה","ופשיט תרוייהו לחומרא מדקתני חייב על כל אחת ואחת ואע\"ג דמנדה לא מצי למיפשט ליה אלא חדא דהא בנדה ליכא תולדות:"],[16,"ושבתות היכא","איזו מהן כלומר ה\"ד דקעביד לה להא (אב) מלאכה בכמה שבתות בשגגת שבתות וזדון מלאכות פשיטא ליה לר\"ע דחייב על כל אחת דלא אמרינן חדא שגגה אלא אמרינן ימים שבינתיים הויין ידיעה דדמי כמי שנודע לו בינתיים דשבת הוי והוי כעושה מלאכה אחת בכמה העלמות:"],[17,"וזדון שבת","יודע שהוא שבת ושגגת מלאכות דסבור שמלאכה זו מותרת היא דבעי מיניה דהא ליכא למימר ימים שבינתיים הויין ידיעה לחלק דלהכי הויין ידיעה לידע ששבת היתה אבל לענין שגגת מלאכות ליכא ידיעה עד שילמוד והכי קמיבעיא ליה האי דעבד חדא מלאכה בב' שבתות מי אמרינן כיון דבב' ימים הם אף על גב דהעלם אחד הוא לגבי מלאכות הויין הנך שבתות כגופין של מלאכה שאינן דומין זה לזה כגון זרע וקצר בהעלם אחד בזדון שבת ושגגת מלאכות דחייב על כל אחת כדאמרינן שבת (דף ע.) אחת שהיא הנה זדון שבת ושגגת מלאכות:"],[17,"או לאו","כגופין דמיין והרי עשה בהעלם אחד מלאכה אחת י' פעמים שאינו חייב אלא אחת:"],[18,"או דלמא זדון שבת ושגגת מלאכות פשיטא ליה דשבתות","כגופי מלאכות שאין דומות זו לזו שהעושן בשגגת מלאכות וזדון שבת חייב שתים דהיינו אחת שהיא הנה ובשגגת שבת וזדון מלאכות קמבעיא ליה דאפילו אמרי' כגופין דמיין לא מחייב אלא חדא דהיינו הנה שהיא אחד שהעושה ב' אבות בשגגת שבת וזדון מלאכות בהעלם אחד אינו חייב אלא אחת אלא אי איכא ידיעה בינתיים דשבת היא מהניא לחלק דהעלמות מחלקין והכי קמיבעיא ליה מי אמרינן ימים שבנתיים הויין ידיעה כמו שנודע לו ששבת היא אי לא:"]],[[1,"אלא לאו רבי יהושע היא וקתני בה' העלמות חייב ה' חטאות","משום דוקא העלמות מחלקין ופר\"י דה\"ה דמצי לאתויי מרישא ה' חתיכות מה' תמחויין מזבח אחד אינו חייב אלא אחת דהא במתני' נמי מדמי תמחויין אלא משום דתמחויין לא הוה הבעיא לא נקט ליה:"],[4,"אפילו תימא ר\"ע היא","וה' זבחים בהעלם אחת חייב על כל אחת ואחת לאו ר\"ע אלא ר' יהושע:"],[6,"בכתף של עולה","יש בה ז' עצמות:"],[6,"בה' מיני קדירה","פר\"י כגון צלי ומבושל וטיגון וצלי קדר וכבוש וה' מיני טעמים כגון פילפלין וזנגבילא וקנה וקנמון וקדה ורש\"י לא פירש כן:"]]],[["מסתברא שגגת שבת וזדון מלאכות פשיטא ליה דימים שבינתיים הויין ידיעה לחלק וזדון שבת ושגגת מלאכות הוא דבעי מיניה כגופין דמיין או לאו","ופשיט ליה דזדון שבת ושגגת מלאכות כגופין דמיין ולא קביל מיניה ופשט ליה דולדי מלאכות כמלאכות דמיין ולא קביל מיניה","אמר רבה מנא אמינא לה דתנן כלל גדול אמרו בשבת כל השוכח עיקר שבת ועשה מלאכות הרבה בשבתות הרבה אינו חייב אלא אחת","היודע עיקר שבת ועשה מלאכות הרבה בשבתות הרבה חייב על כל שבת ושבת היודע שהוא שבת ועשה מלאכות הרבה בשבתות הרבה חייב על כל אב מלאכה ומלאכה","ואילו חייב על כל אב מלאכה של כל שבת ושבת לא קתני","מני הא אילימא ר\"א אימא סיפא העושה מלאכות הרבה מעין מלאכה אחת אין חייב אלא אחת ואי ר\"א חייב על כל ולדי מלאכות כמלאכות","אלא פשיטא ר\"ע היא וש\"מ שגגת שבת וזדון מלאכות פשיטא ליה דימים שבינתיים הויין ידיעה לחלק","זדון שבת ושגגת מלאכות הוא דבעי אי כגופין דמיין ופשט ליה דכגופין דמיין ולדי מלאכות כמלאכות דמיין ותרוייהו לא קביל מיניה","אמר ליה אביי לעולם אימא לך זדון שבת ושגגת מלאכות פשיטא ליה לר\"ע דשבתות לאו כגופין דמיין ושגגת שבת וזדון מלאכות הוא דבעי מיניה דימים שבינתיים מי הויין ידיעה לחלק או לא","ופשיט ליה דימים שבינתיים לחלק וקביל מיניה ופשט ליה ולדי מלאכות כמלאכות דמיין ולא קביל מיניה","רב חסדא אמר זדון שבת ושגגת מלאכות אפילו ר\"ע ס\"ל דכגופין דמיין וכי בעי מיניה שגגת שבת וזדון מלאכות הוא דבעי מיניה דימים שבינתיים אי הויין ידיעה לחלק","ופשיט ליה ימים שבינתיים הויין ידיעה לחלק וקביל מיניה","ופשט ליה דולדי מלאכות כמלאכות דמיין ולא קביל מיניה","אמר רב חסדא מנא אמינא לה דתניא הכותב שתי אותיות בהעלם אחת חייב בב' העלמות רבן גמליאל מחייב וחכמים פוטרין ומודה רבן גמליאל שאם כתב אות אחת בשבת זו ואות אחת בשבת אחרת פטור","ותניא אחריתי הכותב שתי אותיות בשתי שבתות אחד בשבת זו ואחד בשבת זו ר\"ג מחייב וחכמים פוטרין קא סלקא דעתך דר\"ג כר\"ע סבירא ליה","בשלמא לדידי דאמינא זדון שבת ושגגת מלאכות אפילו ר\"ע אומר דשבתות כגופין דמיין הא דתניא פטור בזדון שבת ושגגת מלאכות דשבתות כגופין דמיין"],[[0,"מסתברא","מהא מתני' דאמרינן לקמן:"],[2,"השוכח עיקר שבת","דסבור לא נכתבה שבת בתורה דהיינו העלם זה וזה בידו שגגת שבת ושגגת מלאכות:"],[2,"חטאת אחת","על כולן [דחדא] שגגה היא והתם ליכא למימר ימים שבינתיים הויין ידיעה דהא לא ידע לעולם עיקר שבת עד שילמוד:"],[3,"היודע עיקר שבת","שידע שארבעים אבות מלאכות אסורות בשבת אבל אינו יודע שהיום שבת דהיינו שגגת שבת וזדון מלאכות ועשה מלאכות הרבה בשבתות הרבה ולא נודע לו בינתיים שחטא:"],[3,"חייב על כל שבת ושבת","חטאת אחת משום דימים שבינתיים הויין ידיעה לענין שגגת שבת ואינו חייב על כל מלאכה ומלאכה של כל שבת ושבת דהא שגגת שבת וזדון מלאכות דהיינו הנה שהיא אחת אבל כגופין דמיין ליכא למימר (פשטו מינה) דנימא דמש\"ה חייב על כל שבת דעל כרחיך מסיפא קדייק ואזיל דלית ליה להאי תנא שבתות כגופין דמיין וטעמא דרישא משום דימים שבינתיים הויין ידיעה לחלק:"],[3,"היודע שהוא שבת ועשה מלאכות [הרבה] בשבתות הרבה","ואותן שעשה בזו עשה בזו דשגג במלאכות הרבה כסבור מלאכה זו מותרת חייב על כל מלאכה ומלאכה על שבת ראשון דהיינו אחת שהיא הנה זדון שבת ושגגת מלאכות:"],[4,"ואילו חייב על כל מלאכה ומלאכה על כל שבת ושבת לא קתני","בהך סיפא גבי זדון שבת ושגגת מלאכות דכיון דאותן עצמן שעשה בזו עשה בזו ובהעלם אחד אלמא שבתות לאו כגופין דמיין וה\"ל עושה מלאכה אחת כמה פעמים בהעלם אחד ואינו חייב אלא אחת:"],[5,"מעין מלאכה אחת אינו חייב אלא אחת","דכיון דאב אחד לכולן:"],[6,"וש\"מ","ממציעתא שגגת שבת וזדון מלאכות פשיטא ליה לר\"ע דימים שבינתיים הויין ידיעה מדקתני חייב על כל שבת ושבת:"],[7,"ותרוייהו לא קביל מיניה","מדלא קתני חייב על כל אב מלאכה של כל שבת וולדי מלאכות נמי לא קביל מיניה כדקתני סיפא מלאכה אחת כו':"],[8,"א\"ל אביי [כו'] לאו כגופין דמיין","מדלא קתני על כל מלאכה של כל שבת:"],[9,"וקביל מיניה","מדתניא מציעתא חייב על כל שבת ושבת וה\"ק סיפא דמתני' בהמה כשבת הדין עמך דודאי כזה כן זה:"],[9,"ולא קביל מיניה","מדתניא סיפא מעין מלאכה אחת כו'. בין אביי ורבה איכא פלוגתא אליבא דר\"א בזדון שבת ושגגת מלאכות דלרבה מחייב ליה ר\"א תרתי ולאביי אפילו ר\"א לא מחייב אלא חדא ועוד דמאי דקאמר רבה דמיבעיא ליה לר\"ע קאמר אביי דפשיטא ליה אבל תרוייהו מודו דלר\"ע שבתות לאו כגופין דמיין וגבי שגגת שבת אית ליה ימים שבינתיים הויין ידיעה לחלק:"],[10,"רב חסדא אמר זדון שבת ושגגת מלאכות אפי' ר\"ע ס\"ל כגופין דמיין","והאי דקתני בכלל גדול גבי שגגת מלאכות היודע שהוא שבת כו' חייב על כל מלאכה ומלאכה של כל שבת ושבת קאמר אע\"ג דאותה שעשה בזה עשה בזה ובהעלם אחת אפ\"ה חייב דשבתות כגופין דמיין משום הכי קתני בשבתות הרבה:"],[11,"וקביל מיניה","כדקתני (טעמא כו') מציעתא היודע עיקר שבת כו':"],[12,"ולא קביל מיניה","כדקתני סיפא מעין מלאכה אחת כו':"],[13,"מנ\"ל","דאית ליה לר\"ע שבתות כגופין דמיין:"],[13,"ר\"ג מחייב","דאין ידיעה לחצי שיעור ולא מהני ידיעה שבינתיים לחלק שלא יצטרפו:"],[14,"קס\"ד ר\"ג כר\"ע ס\"ל","כדמפרש לקמן דליכא למימר דכר\"א ס\"ל מדקתני ומודה:"],[15,"והא דתני פטור בזדון שבת ושגגת מלאכות","דכיון דשבתות כגופין דמיין גבי זדון שבת ושגגת מלאכות הוה ליה כעושה שני חצאי מלאכות שאינן דומות זו לזו בהעלם אחת שפטור מכולם:"]],[[2,"אמר רבה מסתברא כו'","ופשט ליה דשבתות כי גופין דמיין כו'. ואם תאמר קשיא מיניה אדרבה שהרי רבה קאמר לעיל לר\"א דקצר וקצר מחייב תרתי אפי' בשבת אחת וא\"כ למה צריך שבתות כגופין דמיין וכן בנדה מאי נפקא ליה מיניה מגופין מוחלקין הא ר\"א מחייב על כל ביאה וביאה וי\"ל דר\"א השיב לר\"ע לפי דברי רבי עקיבא:"],[2,"דתנן כלל גדול כו' אלא פשיטא ר\"ע היא וש\"מ ימים שבינתים כו'","וא\"ת מאי פשיטא ליה להביא ראיה מדבריו וי\"ל דסבר רבה כיון דמיבעיא ליה בולדי מלאכות דהיינו העושה מלאכות הרבה מעין מלאכה אחת מיבעיא ליה הסמוכה לה דהיינו יודע שהוא שבת ועשה מלאכות הרבה כו' דהיינו זדון שבת ושגגת מלאכות אי שבתות כגופין דמיין או לא:"],[10,"רב חסדא אמר כו' ופשט ליה ימים שבינתיים הויין ידיעה לחלק כו'","כי קמייתי ראיה מיניה אבל לא מק\"ו דהא אותיב ר\"ע על הק\"ו אלא מקבלה חייב על כל אחת ואחת:"],[13,"אמר רב חסדא מנא אמינא לה דתניא הכותב כו' ומודה ר\"ג שאם כתב כו' פטור","מהך לבד לא היינו מייתינן בשבתות כגופין מדחזינן דפטור דאיכא למימר דמיירי בשגגת שבת וזדון מלאכות ולכך פטור דימים שבנתיים הויא ידיעה לחלק דאף על גב דר' גמליאל קאמר אין ידיעה לחצי שיעור דלמא ידיעה כי ההיא מחלקת דאיכא לחלק בין ידיעה לימים שבינתיים ובימים שבינתיים מודה דאינה מצטרפת לכך צריך להביא טעם אחר שזדון שבת יש חשיבות לשבתות להיות כגופין משגגת שבת:"],[14,"ותניא אחריתי כו'","הא דתניא פטור בזדון שבת ושגגת מלאכות דכיון דשבתות כגופין דמיין גבי זדון שבת ושגגת מלאכות (דכיון דשבתות כגופין דמיין) ה\"ל כעושה ב' חצאי מלאכות שאינן דומות זו לזו בהעלם אחת שפטור מכולם:"]]],[["והא דתניא חייב בשגגת שבת וזדון מלאכות (דשבתות כגופין דמיין) דקסבר אין ידיעה לחצי שיעור","אלא לרבא דאמר ס\"ל לר\"ע דשבתות כגוף אחד הן","בשלמא הא דתניא חייב משכחת לה בין בזדון שבת ושגגת מלאכות דשבתות כגוף אחד הן ובין בשגגת שבת וזדון מלאכות דקסבר אין ידיעה לחצי שיעור","ואלא הדתניא פטור במאי מוקמת לה לא בחדא ולא בחדא","אמר לך רבא רבן גמליאל ס\"ל כר' אליעזר דאמר שבתות כגופין דמיין","והא מדקתני ומודה רבן גמליאל מכלל דפליגי אאחרנייתא אי אמרת בשלמא כר' עקיבא ס\"ל היינו דפליגי בשגגת שבת וזדון מלאכות דרבן גמליאל סבר אין ידיעה לחצי שיעור","ומודה רבן גמליאל בזדון שבת ושגגת מלאכות שהוא פטור אלמא שבתות כגופין דמיין אלא אי אמרת רבן גמליאל כר' אליעזר ס\"ל מכלל דפליגי במאי","אי בשגגת שבת וזדון מלאכות אפילו רבי אליעזר כרבן גמליאל ס\"ל דאין ידיעה לחצי שיעור דתניא הכותב שתי אותיות בשתי שבתות אות אחת בשבת זו ואות אחת בשבת זו ר' אליעזר מחייב","ואלא באחת על האריג חיובי מחייב דתנן ר\"א אומר האורג שלשה חוטין בתחלה ואחד על האריג חייב","אמר רבא מכלל דפליג בחדא דתניא הוציא חצי גרוגרת וחזר והוציא חצי גרוגרת בהעלם אחת חייב בשתי העלמות פטור רבי יוסי אומר בהעלם אחד ברשות אחד חייב בשתי רשויות פטור","דר' גמליאל כת\"ק ור' אליעזר כרבי יוסי","ת\"ש אמר לו חייב על כל אחת ואחת מק\"ו ומה נדה שאין בה תוצאות הרבה","בשלמא לרב חסדא דאמר שגגת שבת וזדון מלאכות בעי מיניה דימים שבינתים מי הויין ידיעה לחלק או לא היינו דקאמר ליה ומה נדה","אלא לרבא דאמר זדון שבת ושגגת מלאכות הוא דבעי מיניה דשבתות אי כגופין דמיין ואי לא ליתני נדות","אמר לך רבא תני נדות שמואל תני נדה רב אדא בר אהבה תני נדה רב נתן בר אושעיא אמר תני נדות","ולרב חסדא דאמר שגגת שבת וזדון מלאכות הוא דבעי מיניה דימים שבינתים מי הויין ידיעה לחלק ואי לא נדה מאי ימים שבינתים הויין ידיעה לחלק אית בה","אמר רבא כגון שבא עליה וטבלה וראתה וחזר ובא עליה וטבלה וחזר ובא עליה דטבילות הויין כימים שבינתים","ת\"ש הבא על הקטנות יוכיח בשלמא לרבא היינו דקתני קטנות","אלא לרב חסדא מאי קטנות קטנות דעלמא","מתניתין דלא כהדין תנא דתניא א\"ר שמעון בן אלעזר לא כך שאלו ר' עקיבא לרבי אלעזר אלא כך שאלו הבא על אשתו נדה וחזר ובא על אשתו נדה בהעלם אחת מהו חייב אחת על כולן או חייב על כל אחת ואחת","אמר ליה חייב על כל אחת ואחת מקל וחומר ומה שבת שאין בה אלא אזהרה אחת שהוא מוזהר על השבת והשבת אינה מוזהרת עליו חייב על כל אחת ואחת נדה שיש בה שתי אזהרות שהוא מוזהר על הנדה ונדה מוזהרת עליו אינו דין שהוא חייב על כל אחת ואחת","אמרו לו לא אם אמרת בשבת שיש בה תוצאות הרבה לחטאות הרבה תאמר בנדה שאין בה תוצאות הרבה לחטאות הרבה","אמרו לו הבא על הקטנות יוכיח שאין בה תוצאות הרבה לחטאות הרבה וחייב על כל אחת ואחת","אמרו לו לא אם אמרת בקטנות שכן גופין מוחלקין אמרו לו הבא על הבהמה יוכיח שאין גופין מוחלקין וחייב על כל אחת ואחת אמרו לו הבהמה כנדה:","\u0001הדרן עלך אמרו לו\u0002","מתני׳ \u0001ספק\u0002 אכל חלב ספק לא אכל ואפילו אכל ספק יש בו כשיעור וספק"],[[0,"והא דתניא חייב בשגגת שבת וזדון מלאכות","דאי נמי סבירא לן ימים שבינתים ידיעה הן הכא ליכא למימר דמהני חילוק שבתות לחלק שלא יצטרפו דקסבר אין ידיעה לחצי שיעור:"],[3,"לא בחדא ולא בחדא","בשגגת מלאכות לא מוקמת לה דהא אמר לעיל לר' עקיבא לאו כגופין דמיין ומצטרפין ובשגגת שבת נמי לא דאי נמי אמרינן ימים שבינתיים הויין ידיעה לחלק הא שמעינן ליה לר\"ג לעיל דאין ידיעה לחצי שיעור דקתני בשתי העלמות ר\"ג מחייב:"],[5,"א\"א בשלמא כר\"ע ס\"ל","דאית ליה לר\"ע נמי שבתות כגופין דמיין והא דקתני מודה לר\"ע הוא דמודה היינו דפליגי בהכותב אות אחת בשבת זו ואות אחת בשבת זו בשגגת שבת וזדון מלאכות דר' גמליאל מחייב כאידך ברייתא דאין ידיעת ימים שבינתים מועלת לחצי שיעור ור' עקיבא היינו חכמים דפטרי סבר יש ידיעה:"],[6,"אלא אי אמרת כר\"א ס\"ל","בשגגת מלאכות וזדון שבת דהאי דקתני ומודה לר\"א קאמר על כרחיך מכלל דפליגי במקצת:"],[7,"ר\"א מחייב","ודאי בשגגת שבת קאמר ומש\"ה קתני דאין ידיעה לחצי שיעור דאי בשגגת שבת וזדון מלאכות הא כולי עלמא מודו דלר\"א שבתות כגופין דמיין ופטור:"],[8,"אלא באחת על האריג","פליגי ר' גמליאל ור\"א והכי קאמר מודה ר\"ג לר\"א בכותב אות אחת כו' זדון שבת ושגגת מלאכה שהוא פטור דשבתות כגופין דמיין ואף על גב דפליג עליה באחת על האריג דהתם מחייב ר' גמליאל אע\"ג דדמי להאי דכותב חצי שיעור בשבת שני ומשלים לשיעור הראשון ואורג נמי חצי שיעור על האריג אפילו הכי מחייב ר\"ג דהכא היינו טעמא דשבתות כגופין דמיין ולא מצטרפין דדמי כחורש חצי שיעור וזורע חצי שיעור אבל באורג דמעיקרא הוי בהאי בגד אריג שיעור הרבה חשיב האי חוט שארג זה אגב כל הבגד ואף על גב דת\"ק דר' גמליאל דפליג עליה באין ידיעה לחצי שיעור לאו ר\"א הוא אפילו הכי האי ומודה דקתני אדר\"א קאי ואפלוגתא דאחת על האריג והא דקתני ליה הכא גבי העלמות איידי דאיירי בכותב לחצאים הא ר\"א נמי חיובי מחייב:"],[9,"אמר רבא","לעולם ומודה דקתני לר\"א מודה ואהך פלוגתא קאי דפליגי בהדא:"],[9,"בשתי העלמות פטור","ויש ידיעה לחצי שיעור:"],[9,"לשתי רשויות","ושתיהן רה\"ר פטור דרשויות מחלקות. ברייתא דלעיל מודה ר' גמליאל לר\"א דשבתות כגופין דמיין דמחלקין לכתיבת שתי אותיות מלצרף אבל בהא פליג עליה דרשויות לא מחלקות:"],[12,"היינו דקא\"ל ומה נדה","דנדה אית בה ידיעת ימים שבינתים כדמפרש לקמן:"],[13,"אלא לרבא דאמר","דגופין בעא מיניה מאי פשיט ליה מנדה בנדה מאי חילוק גופין איכא:"],[14,"תני נדות","מה נדות שאין בהן תוצאות הרבה הבא על חמש נשים נדות חייב על כל אחת ואחת כו' דגופין נינהו שבתות לא כ\"ש שהן גופין:"],[14,"שמואל תני נדה","דס\"ל כרב חסדא:"],[18,"קטנות דעלמא","אנשים הרבה הבאין על קטנות הרבה בנדות:"],[19,"לא כי האי תנא","דהאי תנא סבר נדה מיבעיא ליה ושבת פשיטא ליה:"],[20,"חייב על כל אחת ואחת","אם עשה חמש אבות מלאכות בהעלם אחד:"],[23,"על הבהמה","ביאות הרבה על אחת:"],[23,"בהמה","מיבעיא ליה כנדה:"],[25,"מתני' ספק אכל חלב","מפרש בגמרא מר אמר חתיכה אחת ומר אמר שתי חתיכות:"],[25,"ואפילו אכל","כגון שסבור שומן הוא ואח\"כ נודע לו שהוא אכל חלב אבל ספק יש בו כזית ספק אין בו:"]],[[10,"ר\"ג כתנא קמא","וקשה דמאי קאמר כת\"ק דלר\"ג העלמות אינן מחלקות שהרי כפשטה לא מצינו למימר דהא ת\"ק קאמר בשתי העלמות פטור:"],[23,"אמר לו הבא על בהמה יוכיח שאין גופין מוחלקין","וה\"ה דמצי למימר נדה יוכיח שהרי ר\"א מחייב על כל אחת ואחת אלא שלא שמע מרבותיו נדה רק בהמה לכך נקט ליה:"],[25,"מתני' ספק אכל כו'","ומיירי בשעה שאכל היה סבור שהוא שומן דאי יודע שהוא ספק חלב היכי מייתי קרבן הא לא שב מידיעתו:"]]],[["אין בו","שומן וחלב לפניו ואכל אחד מהן ואינו יודע איזה מהן אכל אשתו ואחותו עמו בבית שגג באחת מהן ואינו יודע באיזו מהן שגג שבת ויום חול ועשה מלאכה באחד מהן ואינו יודע באיזו מהן עשה מביא אשם תלוי","כשם שאם אכל חלב וחלב בהעלם אחת אינו חייב אלא חטאת אחת כן על לא הודע שלהן אינו מביא אלא אשם תלוי אחד","אם היתה ידיעה בינתים כשם שהוא מביא חטאת על כל אחת ואחת כך מביא אשם תלוי על כל אחת ואחת","כשם שאכל חלב ודם ופיגול ונותר בהעלם אחת חייב על כל אחת ואחת כך על לא הודע שלהן מביא אשם תלוי על כל אחת ואחת:","\u0001גמ׳\u0002 איתמר רב אסי אמר חתיכה אחת שנינו ספק של חלב ספק של שומן חייא בר רב אמר חתיכה משתי חתיכות שנינו","במאי קא מיפלגי רב אסי סבר יש אם למסורת (ויקרא ה, יז) מצות כתיב","וחייא בר רב אמר יש אם למקרא מצוות קרינן","איתיביה רב הונא לרב אסי ואמרי לה חייא בר רב לרב אסי חלב ושומן לפניו ואכל אחת מהן מאי לאו מדסיפא שתי חתיכות רישא נמי שתי חתיכות","אמר להו רב לא תיזלא בתר איפכא דיכול לשנויי לכו סיפא בשתי חתיכות רישא בחתיכה אחת אי הכי יש לומר חתיכה אחת מחייב שתי חתיכות צריכא למימר זו ואין צריך למימר זו","ולחייא בר רב דאמר מדסיפא בשתי חתיכות רישא נמי בשתי חתיכות מיתנא תרתי למה לי פרושי קא מפרש ספק אכל ספק לא אכל חלב מביא אשם תלוי כיצד כגון שהיה חלב ושומן לפניו","אמר רב יהודה אמר רב היו לפניו שתי חתיכות אחת של שומן ואחת של חלב אכל אחת מהן ואינו יודע איזו מהן אכל חייב חתיכה אחת ספק של חלב ספק של שומן ואכלה פטור","אמר רבא מאי טעמא דרב דאמר קרא (ויקרא ד, כב) ועשה אחת מכל מצות ה' בשגגה עד שישגוג בשתים מצות כתיב מצוות קרינן","איתיביה אביי רבי אליעזר אומר כוי חייבין עליו אשם תלוי","אמר לו ר' אליעזר סבר יש אם למסורת מצות כתיב","איתיביה ספק בן תשעה לראשון או בן שבעה לאחרון יוציא והולד כשר","וחייב באשם תלוי הא מני רבי אליעזר היא","איתיביה נמצא על שלו טמאין וחייבין בקרבן","על שלה אתיום טמאין וחייבין בקרבן נמצא על שלה לאחר זמן טמאין מספק ופטורין מן הקרבן ותני עלה חייב משום אשם תלוי הא מני רבי אליעזר היא","א\"ר חייא אמר רב היו לפניו שתי חתיכות אחת של חלב ואחת של שומן ואכל אחת מהן ואינו יודע איזה מהן אכל חייב חתיכה ספק של שומן ספק של חלב ואכלה פטור","א\"ר זירא מ\"ט דרב קסבר שתי חתיכות אפשר לברר איסורו חתיכה אחת אי אפשר לברר איסורו","מאי איכא בין טעמא דרבא לטעמא דרבי זירא איכא בינייהו כזית ומחצה","לרבא ליכא מצוות ופטור לרבי זירא אפשר לברר איסורו","איתיביה רבי ירמיה לרבי זירא רבי אליעזר אומר כוי חייבין על חלבו אשם תלוי אמר ליה רבי אליעזר סבר לא בעינן לברר איסורו"],[[1,"אכל אחד מהן","וכסבור שומן הוא ואחר כך נודע שהאחד היה חלב וזה לא ידע איזו אכל מביא אשם תלוי אבל אם בשעת אכילה היתה לו ספק והזיד ואכלה מספק מזיד הוא ופטור:"],[1,"שגג באחת מהן","כסבור זו היא אשתו ואחר כך נסתפק איזו היתה מביא אשם תלוי ואם נודע לו שאחותו היתה מביא חטאת:"],[2,"כך על לא הודע שלהן","כגון אכל שתי חתיכות כסבור שומן הן ואחר כך נודע שהן ספק אינו מביא אלא אשם תלוי אחד הואיל ולא נודע בין אכילה לאכילה שספק חלב אכל:"],[3,"ואם היתה ידיעה בינתים","ידיעת ספק:"],[3,"כשם שהוא מביא חטאת על כל אחת","אם היתה ידיעה ודאי בינתים:"],[3,"כך","בידיעת ספק מביא שני אשמות תלויין:"],[5,"גמ' חתיכה אחת שנינו","אכל חתיכה אחת כסבור שומן הוא ואחר כך נודע לו שספק הוא היינו הא דקתני מתני' ספק אכל חלב וכו':"],[5,"חתיכה משתי חתיכות","כדמפרש בסיפא חלב ושומן לפניו כו' אבל חתיכה אחת פטור:"],[6,"מצות כתיב","בויקרא גבי אשם תלוי ועשתה אחת מכל מצות ה' אשר לא תעשינה ולא ידע ואשם ונשא עונו והביא את אשמו וגו':"],[7,"מצוות קרינן","דמשמע אחת מתוך שתים:"],[9,"ב' חתיכות מיבעיא","דבשלמא חתיכה אחת איכא לפלוגי משום טעמא דלקמן דאי אפשר לברר איסורו או דלא איקבע איסורו אבל שתי חתיכות ליכא למימר הכי:"],[13,"כוי","ספק בהמה ספק חיה:"],[13,"אשם תלוי","אף על גב דליכא חתיכה אחת משתי חתיכות אם אכל חלבו בשוגג כסבור חיה הוא:"],[15,"ספק בן תשעה כו'","היבמה שנתייבמה בתוך שלשה חדשים:"],[16,"וחייבים באשם תלוי","שמא בן הראשון הוא ונמצא שבא על אשת אח שיש לה בנים שהוא בכרת והא אשה דומיא דחתיכה אחת היא:"],[17,"נמצא על שלו","במסכת נדה בפרק כל היד (נדה דף יד.) דרך בנות ישראל משמשות בשני עדים שני סדינים לקנח אחד לו ואחד לה נמצא על שלו ודאי בשעת תשמיש היה ובועל נדה בשוגג הוה וחייבים שתי חטאות:"],[18,"אתיום","לשון יווני הוא. כלומר לאחר תשמיש:"],[18,"לאחר זמן","התם מפרש שיעורא:"],[18,"וחייבין באשם תלוי","ואמאי הא ליכא שתי מצוות:"],[20,"אפשר לברר איסורו","דאשם תלוי אינו בא אלא להגין מן הייסורין עד שיוודע לו ויביא חטאת כדמפרש בפרק בתרא (לקמן כריתות כה.) הילכך שתי חתיכות [ואכל אחת] ונשארה האחת אפשר שיבוא לאחר זמן בקי שיכיר אם זו הנותרת שומן ודאי חלב אכל ויביא חטאת אבל חתיכה אחת ואכלה אי אפשר לבררה:"],[21,"מאי איכא בין רבא","דאמר לעיל טעמיה דרב משום יש אם למקרא:"],[21,"לר' זירא","דמפרש טעמיה דרב לברר איסורו:"],[21,"ה\"ג איכא בינייהו כזית ומחצה","כגון ב' חתיכות בזו כזית ובזו כחצי זית ואכל את של כזית ואין ידוע אם הוא חלב או שומן:"],[22,"לרבא ליכא מצוות","ליכא ב' זיתים ופחות מכזית כמאן דליתיה:"],[22,"לר' זירא אפשר לברר האיסור","בחצי זית זה הנשאר:"],[23,"כוי חייבים כו'","והא אי אפשר לברר איסורו:"]],[[8,"מדסיפא בשתי חתיכות רישא נמי בשתי חתיכות","וההיא נמי אפי' אכל ספק יש בו כשיעור כו' כמו כן צריך לומר דמיירי שיש שתי חתיכות לפניו ובשתיהן כשיעור וכך צ\"ל על כרחין שהרי אמרינן לקמן איכא בינייהו כזית ומחצה דלמאן דאמר איקבע איסורא ליכא אם כן שמע מינה דיש שתי חתיכות ומכל מקום האי זית אכל ואפילו אכל מן האיסור מסופק הוא אם אכל כזית ואשמעינן דאפילו בספק ספיקא מייתי אשם תלוי וגבי שבת ויום חול נמי מצינו למשכח שתי חתיכות כגון שעשה מלאכה בין השמשות דספק יום או לילה וגם איקבע איסורא שעשה מלאכה בבין השמשות קרוב למוצאי שבת דאיקבע איסורא כל היום וגם אפשר לברר איסורא שיוכל לראות לפי ענין המלאכה שפעל בשבת לפי מה שיש כמה עבר מן הלילה ולא עבר ממנה רק מעט ופעל מלאכה רבה א\"כ פעל קצת מן היום:"],[11,"אמר רב יהודה אמר רב כו' חתיכה אחת פטור כו'","ואם תאמר דהא אמרינן פרק שני דכתובות (דף כב:) גבי שנים אומרים מת ושנים אומרים לא מת כו' ופריך עלה הבא עליה באשם תלוי קאי ומאי פריך הא בעינן מצוות יש לומר דהתם פריך למאן דאמר הכא דלא בעינן חתיכה משתי חתיכות אבל קשה דרב אדרב שהרי קאמר הכא רב יהודה אמר רב ובפרק האשה רבה (יבמות פח.) קאמר אמר רבה אמר רב לא שנו אלא שנשאת בעד אחד כו' ופריך הש\"ס הבא עליה באשם תלוי קאי ומאי פריך ותירץ דהכי פריך הבא עליה באיסור אשם תלוי קאי ועוד יש לומר דפריך התם לרב נחמן דמתרץ הכא טעמא דרב משום איקבע איסורא והיכא דאכל עובד כוכבים הראשונה משום השניה חייב משום דאיקבע איסורא וניחא התם דפריך שפיר שהרי כבר איקבע איסורא שהיתה אשת איש:"],[13,"איתיביה אביי","כל הנך פירכי מצי למיפרך לעיל לחייא בר רב:"],[18,"ותני עלה וחייבים באשם תלוי","וקשה שהרי הכא משמע דבריית' מפרשא למתני' והתם פרק כל היד (נדה יד:) לא משמע הכי דאמר על מתני' ופטורין מן הקרבן תנא וחייבין באשם תלוי ותנא דידן סבר בעינן חתיכה משתי חתיכות ועוד קצת קשה אמאי לא קאמר מהא (הוריות דף ח:) ומביאין אשם תלוי על עשה ועל לא תעשה שבנדה ואע\"ג דליכא שתי חתיכות:"]]],[["איתיביה ספק בן תשעה לראשון או בן שבעה לאחרון יוציא והולד כשר וחייב באשם תלוי הא מני רבי אליעזר היא","איתיביה נמצא על שלה אתיום טמאין וחייבין בקרבן נמצא על שלה לאחר זמן טמאין מספק ופטורין מן הקרבן ותני עלה וחייבין באשם תלוי הא מני רבי אליעזר היא","אמר רב נחמן אמר רבה בר אבוה אמר רב היו לפניו שתי חתיכות אחת של חלב ואחת של שומן ואכל אחת מהן ואינו יודע איזו מהן אכל חייב חתיכה ספק של חלב ספק של שומן ואכלה פטור","אמר רב נחמן מאי טעמא דרב קסבר שתי חתיכות איקבע איסורא חתיכה אחת לא קבעה איסורא","מאי איכא בין איקבע איסורא לשאי אפשר לברר איסוריה","איכא בינייהו כגון שהיו לפניו שתי חתיכות אחת של חלב ואחת של שומן ובא עובד כוכבים ואכל את הראשונה ובא ישראל ואכל את השניה לרבא ליכא מצוות בעידנא דאכל ישראל לר' זירא אי אפשר לברר איסוריה לרב נחמן איקבע איסורא","איתיביה רבא לרב נחמן רבי אליעזר אומר כוי חייבין על חלבו אשם תלוי ר' אליעזר לא בעי קביעותא לאיסורא","איתיביה ספק בן ט' לראשון או בן ז' לאחרון יוציא והולד כשר וחייבין באשם תלוי הא מני ר' אליעזר היא","איתיביה נמצא על שלו טמאין וחייבין בקרבן נמצא על שלה אתיום טמאין וחייבין בקרבן נמצא על שלה לאחר זמן טמאים מספק ופטורין מן הקרבן ותני עלה וחייבין באשם תלוי","אישתיק לבתר דנפק אמר מאי טעמא לא אמרי ליה דהא מני רבי מאיר היא דלא בעי קביעותא לאיסורא","דתניא השוחט אשם תלוי בחוץ ר' מאיר מחייב וחכמים פוטרין","ואמאי לימא ליה דר' אליעזר היא הא קמ\"ל דר\"מ בשיטת ר' אליעזר קאי","אמר רבה בר אבוה אמר רב חתיכה ספק של חלב ספק של שומן ואכלה באנו למחלוקת ר' אליעזר וחכמים","לר' אליעזר מאי איריא כי אכלה אפילו לא אכלה נמי דהתנן ר' אליעזר אומר מתנדב אדם אשם תלוי בכל יום","אמר רב אשי ר' אליעזר אליבא דבבא בן בוטא דתנן אלא אומרים לו המתן עד שתכנס לבית ספק","ת\"ר היו לפניו שתי חתיכות אחת של שומן ואחת של חלב בא ישראל ואכל את הראשונה בא עובד כוכבים ואכל את השניה חייב וכן כלב וכן עורב בא עובד כוכבים ואכל את הראשונה בא ישראל ואכל את השניה פטור ורבי מחייב","אכל את הראשונה בשוגג והשניה במזיד חייב הראשונה במזיד והשניה בשוגג פטור ורבי מחייב אכל שתיהן במזיד פטור מכלום","שתיהן בשוגג שניהן חייבין השני לא מן הדין אלא שאם אתה אומר פטור קבעת את הראשונה בחטאת","ומנו אי רבי מן הדין ומן הדין הוא אי רבנן משום דלא נקבע ראשון בחטאת נימא ליה לשני אייתי חולין לעזרה אמר רב אשי"],[[5,"לרבי זירא אי אפשר לברר איסוריה","דהא שתיהן נאכלות:"],[5,"לרב נחמן איקבע איסורא","מעיקרא וחייב:"],[10,"ר\"מ מחייב","משום שחוטי חוץ אף על גב דאיכא למימר שמא לא אכל חלב ואשם זה חולין הוא דלא בעי קביעות לאיסור:"],[10,"וחכמים פוטרין","דלא איקבע איסורא דשמא חולין הוא:"],[11,"ואמאי","אצטער דלא אמר לו ר' מאיר היא הוה ליה למימר אשמעתיה דר' אליעזר היא:"],[11,"בשיטת ר' אליעזר אמרה","משום הכי מחייב דלא בעי קביעות איסור והאי דלא הוה אמר ליה ר' אליעזר היא לא איכפת ליה משום דממילא הוה מצי ידע:"],[12,"אמר רבא כו'","אף על גב דאמרי לעיל פטור דבעינן שתי חתיכות לאו דברי הכל אמרי דהא ר' אליעזר מחייב כיון דאמר דמתנדב אדם כו' וליכא למימר חולין לעזרה מייתי הכא ודאי מיחייב הואיל ובא לידי ספק:"],[13,"מתנדב אדם כו'","טעמיה דר' אליעזר בגמרא מפרש בפרק בתרא (לקמן כריתות כה.):"],[14,"אמר רב אשי","האי דבעינן מקצת איסורא לרבי אליעזר אליבא דבבא בן בוטא קאמר דאמר בפרק בתרא (שם) שהיה מביא אשם תלוי בכל יום חוץ ממוצאי יום הכיפורים אמר המעון הזה אילו מניחים אותי הייתי מביא אלא אומרים לי (כו') המתן עד שתיכנס לבית הספק כלומר המתן עד למחר שיש מקצת ספק שמא חטאת היום אבל מוצאי יום הכיפורים אין לחוש בכך דהא כיפר עליו יום הכיפורים על ספקו כדאמרינן בפרק בתרא (שם) חייבי אשמות תלויין שעבר עליהן יום הכיפורים פטורין ואליבא דהאי בעינן מקצת ספק כגון חתיכה אחת אפילו לר' אליעזר אבל רבנן דפליגי אדר' אליעזר בפרק בתרא (שם) דאמרי אין מביאין אשם תלוי אלא על דבר שזדונו כרת ואי מייתי הוי מכניס חולין לעזרה הכא נמי פטרי דדוקא בעינן כדקרינן מצוות:"],[15,"וכן אם אכל כלב","את השנייה או עורב חייב ישראל הואיל ובשעה שאכל הוה חתיכה משתי חתיכות:"],[15,"פטור","דליכא ב' חתיכות:"],[15,"ורבי מחייב","דלא בעי ב' חתיכות:"],[16,"ואת השניה במזיד","שהיה יודע שספק הוא:"],[16,"חייב","אשם תלוי אקמייתא דבשוגג הואי ומשתי חתיכות הואי:"],[16,"פטור","דבשעת שוגג לא הוו שתי חתיכות:"]],[[10,"השוחט אשם תלוי בחוץ ר' מאיר מחייב","ואף על גב דר' מאיר קאמר לקמן פרק המביא (כריתות דף כג:) אם נודע לו ספיקו יצא וירעה בעדר דהוא יוצא לחולין הכא מיירי קודם שנודע לו דעדיין שם אשם עליו:"],[10,"וחכמים פוטרין","לאו היינו חכמים דלקמן דפליגי עליה דרבי מאיר פרק המביא (ג\"ז שם) דאמר ירעה עד שיסתאב וימכר ויפלו דמיו לנדבה דאם כן הקדש גמור הוא וחייבין עליו בחוץ אלא חכמים היינו כר' מאיר ועדיפי מר' מאיר ופטרי אפילו קודם שנודע לו:"],[12,"באנו למחלוקת רבי אליעזר וחכמים כו' מאי איריא כי אכלה אפי' כי לא אכלה נמי דהא תנן ר' אליעזר אומר מתנדב כו'","ואם תאמר מאי פריך אין הכי נמי מתנדב אבל הכא הוא מחייב אשם עבור חטאו וקמ\"ל צריך שיביאנו ולא בעינן חתיכה משתי חתיכות ועוד קשה אמאי לא פריך ליה לעיל על ההיא דר' אליעזר אמר כוי חייבין על חלבו אשם תלוי ויש לומר דהכי פריך מאי איריא כי אכלה כו' פירוש על כרחך האי ר' אליעזר דהכא לאו היינו רבי אליעזר דכוי דאם כן מאי קא משמע לן רב נחמן אלא לעיל גרס רבי אלעזר והכא גרס ר' אליעזר דהוא בר פלוגתיה דרבי יהושע וכן מוכח הסוגיא מטעמים אשר פירשתי ולכך פריך הא דאמר דבחתיכה אחת מחייב רבי אליעזר אשם תלוי מנא לך הא לא משכחת דרבי אליעזר לא מצריך שתי חתיכות אלא מטעמא דאמר מתנדב אדם אשם [תלוי] בכל יום ומשום הכי מייתי אפילו בחתיכה אחת ואם כן חובה לא הוי ואם כן אפילו כי לא אכל נמי ומשני רבי אליעזר [אליבא] דבבא בן בוטא [קאמר] ובמוצאי יום הכיפורים כדפירש הקונטרס ואתא לאשמועינן דרבי אליעזר סבר יש אם למסורת ומצות כתיב (ואף על גב) דאשכחנא דר' אליעזר אית ליה פרק קמא דקדושין (דף יח:) יש אם למסורת גבי בבגדו בה ואם כן ליתני אכלה חובה דמצות כתיב בה לא אכלה נדבה מכל מקום על כרחך לא אייתי הכא מהאי טעמא דסבר דיש אם למסורת דאם כן מצי מייתי כמו כן אחריני טובא דסבר דיש אם למסורת ועוד אפילו סבר בעלמא דיש אם למסורת סבירא ליה הכא יש אם למקרא מטעם שפירשתי לעיל:"]]],[["ר' אליעזר היא דאמר מתנדב אדם אשם תלוי בכל יום הילכך אמרינן ליה אייתי אשם תלוי ואתני אי אכל ראשון שומן הוא אכל חלב ליהוי כפרה ואי לא ליהוי נדבה","ת\"ר אכל ספק חלב ונודע לו ספק חלב ונודע לו רבי אומר אומר אני כשם שמביא חטאת על כל אחת ואחת כך מביא אשם תלוי על כל אחת ואחת","רבי יוסי ברבי יהודה ור' אלעזר ורבי שמעון אומרים אין מביא אלא אשם תלוי אחד שנאמר (ויקרא ה, יח) על שגגתו אשר שגג אפילו על שגגות הרבה אינו חייב אלא אחת","אמר ר' זירא כאן שנה רבי ידיעות ספק מחלקות לחטאות","רבא אמר אין ידיעות ספק מחלקות לחטאות אלא הכי קתני כשם שאם היתה לו ידיעה ודאי מביא חטאת על כל אחת ואחת כך אם היתה לו ידיעת ספק מביא אשם תלוי על כל אחת ואחת","א\"ל אביי ואת לא תסברא דידיעות ספק מחלקות לחטאות דאי סלקא דעתך ידיעות אין מחלקות לחטאות וחטאת אחת מביא אמאי מביא אשם תלוי על כל אחת ואחת","והתניא כללו של דבר כל שחלוקין בחטאות חלוקין באשמות","אמר ליה רבא בר חנן לאביי ולדידך דאמרת ידיעות ספק מחלקות לחטאות אלא מעתה אכל כזית חלב לפני יום הכיפורים וכזית חלב אחר יום הכיפורים ויוה\"כ במקום אשם תלוי קאי הכי נמי דמביא שתי חטאות","הא בהעלם אחת אכלינון א\"ל אביי ומאן לימא לן דיום הכיפורים מכפר על דלא מתידע ליה דילמא והוא דמתידע ליה א\"ל רבא הודע ולא הודע תנן","איכא דאמרי אמר ליה רבא בר חנן לאביי מה אילו אכל כזית חלב שחרית ביום הכיפורים וכזית חלב במנחה ביוה\"כ הכי נמי דמיחייב שתי חטאות","א\"ל אביי ומאן לימא לן דיוה\"כ כל שעתא מכפר דילמא כוליה יומא מאורתא א\"ל רבה בב\"ח תרדא תניא הרי שבא לידו ספק עבירה ביוה\"כ אפילו עם חשיכה פטור שכל היום מכפר","מתיב רב אידי בר אבין אכל ושתה בהעלם אחת אינו חייב אלא חטאת אחת והא בין אכילה לשתייה אי אפשר דלא הוה שהות ביום דמתיידע ליה וכפר ליה דיוה\"כ במקום אשם תלוי קאי וקתני אינו חייב אלא חטאת אחת","ואי סלקא דעתך ידיעות ספק מחלקות לחטאות ליחייב שתי חטאות אמרי כי אמר ר' זירא לרבי הא רבנן היא","והא מדסיפא רבי היא דקתני שתה ציר או מורייס פטור הא חומץ חייב","ומני רבי היא דתניא חומץ אין משיב את הנפש רבי אומר אומר אני חומץ משיב את הנפש ומדסיפא רבי רישא נמי רבי אמרי סיפא רבי רישא רבנן","איתיביה רבא אכל היום אכל למחר נהנה היום נהנה למחר אכל היום נהנה למחר נהנה היום אכל למחר ואפילו מכאן ועד שלש שנים מנין שהן מצטרפין זה עם זה","ת\"ל (ויקרא ה, טו) תמעול מעל ריבה ואמאי הא כיפר עליה יום הכפורים","אמרי כי מכפר יוה\"כ על איסורא על ממונא לא מכפר","ואיבעית אימא כי מכפר יוה\"כ על כוליה שיעורא על פלגא דשיעורא לא מכפר","וכן אמר ריש לקיש כאן שנה רבי ידיעות ספק מחלקות לחטאות רבי יוחנן אמר אין ידיעות ספק מחלקות לחטאות","אלא הכי קתני כשם שאם היתה לו ידיעה ודאי מביא על כל אחת ואחת כך אם היתה לו ידיעת ספק מביא אשם תלוי על כל אחת ואחת","בשלמא לרבי יוחנן היינו דקא תלי לאשם בחטאת אלא לריש לקיש חטאת באשם מיבעיא ליה קשיא","ורמי דר' יוחנן אדר' יוחנן ורמי דריש לקיש אדריש לקיש דתניא שני שבילין אחד טמא ואחד טהור והלך בראשון ולא נכנס בשני ונכנס חייב","הלך בראשון ונכנס פטור בשני ונכנס חייב הלך בראשון ונכנס והזה ושנה וטבל והלך בשני ונכנס חייב"],[[0,"ר' אליעזר היא","הילכך ליכא למימר חולין לעזרה נינהו:"],[0,"ואתני אי ראשון שומן אכל","ודאי השני חלב ואי אכל ודאי חלב מספקא ליהוי ליה כפרה להגין עליו עד שיודע לו ויביא חטאת ואי לא ליהוי נדבה:"],[1,"ונודע לו","שספק הוא:"],[1,"כשם","שאם יודע לו באחרונה שכולן ודאי חלב היו ודאי ליהוי מביא חטאת על כל אחת ואחת דידיעות ספק שבינתים מחלקות לחטאות דלא הוי העלם אחת:"],[1,"כך מביא אשם תלוי על כל אחת","כל זמן שלא נודע לו ידיעה ודאית:"],[3,"כאן שנה רבי","כדפרישית:"],[7,"אלא מעתה אכל כזית חלב קודם יום הכיפורים וכזית חלב לאחר יום הכיפורים","ושניהם בהעלם אחת:"],[7,"במקום אשם תלוי","כדקתני בפ' בתרא (לקמן כריתות כה.) חייבי אשמות תלויים שעבר עליהן יום הכיפורים א' והוה ליה כידיעת ספק:"],[8,"דילמא","הא דאמרינן יום הכיפורים מכפר והוא דמתיידע ליה שספק חלב אכל:"],[8,"הודע ולא הודע תנן","בפ\"ק דשבועות (דף יב:) מפרש בגמרא בין שנודע לו ספקו בין שלא נודע לו ספקו קודם יום הכיפורים יוה\"כ מכפר אלמא אף על גב דלא מתיידע ליה לגמרי מכפר:"],[10,"תרדא","שוטה. לשון אחר עצל:"],[11,"אכל ושתה בהעלם אחת","ביום הכיפורים:"],[11,"אינו חייב אלא אחת","דשתיה בכלל אכילה:"],[11,"דמתיידע ליה","כלומר אי שיעור דהוי אפשר לאודועי וכיון דאיכא שהות דיום הכיפורים בנתיים כדי ידיעה קם ליה ההוא שיעור במקום ספק ידיעה באשם תלוי:"],[12,"רבנן היא","ר' יוסי ור' אליעזר:"],[15,"אכל היום","משל הקדש שוה חצי פרוטה:"],[15,"נהנה","במידי דלאו בר אכילה:"],[15,"ומכאן עד ג' שנים","ובהעלם אחד:"],[16,"הא כפר עליו יוה\"כ","שבינתים על חצי שיעור קמא ואי ידיעות ספק מחלקות הא הוה יוה\"כ כידיעת ספק ואמאי מצטרפין:"],[21,"היינו דתלי לאשם בחטאת","דכשם שאם היתה ידיעה ודאית בנתיים היתה מחלקת לחטאות דכתיב (ויקרא ה) או הודע אליו חטאתו כך ידיעת ספק מחלקת לאשמות ומביא אשם תלוי על כל אחת ואחת אלא לריש לקיש חטאת באשם איבעי ליה למיתלי כשם שידיעת ספק מחלקת לאשמות כך מחלקת לחטאות ולכשיודע לו באחרונה יביא חטאת על כל אחת ואחת דהא עיקר ידיעת ספק באשם כתיבא:"],[22,"אחד טמא ואחד טהור","ואין ידוע איזה טמא ואיזה טהור:"],[22,"ולא נכנס","למקדש:"],[22,"בשני ונכנס","למקדש:"],[22,"חייב","על ביאת מקדש דממה נפשך איכא ידיעה ודאית וטמא הוא שהרי הלך בשתיהן:"],[23,"בשני ונכנס","ובכניסתו בשני נעלמה ממנו טומאה דכניסה ראשונה חייב:"]],[[6,"והתניא כל שחלוקות כו'","ואף על גב דר' יהודה קאמר לה לעיל (כריתות דף טו:) מכל מקום לא משמע דפליג עליה רבי בהא לרבי יוסי ברבי יהודה הכי פירושו כל שחלוקות לחטאות כגון חלב ודם פיגול ונותר חלוקין לאשמות דצריך להביא אשם תלוי על כל אחת ואחת אבל בידיעה לא קמיירי וגם לרבא הכי פירושו כל שחלוקות לחטאות בידיעת ודאי חלוקות לאשמות בידיעת ספק:"],[7,"אלא מעתה אכל כזית חלב לפני יוה\"כ וכזית לאחר יוה\"כ","דהשתא איכא שתי אשמות אכילת חלב דלפני יוה\"כ כיפר יוה\"כ במקום אשם ואכילת חלב דלאחר יוה\"כ הביא עליו אשם והשתא איכא ב' אשמות הכי נמי דאם נודע לו אחר כך על שניהן שיביא שתי חטאות והא אכלם בהעלם אחת אלא לא מייתי ואם כן שמע מינה דהאי כללא כל שחלוקין כו' ליתא שהרי הכא איכא ב' אשמות וליכא כי אם חטאת אחת:"],[8,"אמר ליה דילמא יום הכיפורים אינו מכפר אלא אם כן הודע","ועתה יש שתי חטאות כמו שתי אשמות. אמר ליה רבא בר רב חנן תרדא רבא בר רב חנן היה חבר אביי כדאיתא פרק כיצד מברכין (ברכות דף מו):"],[9,"","\u0003הא דנקט חלב שחרית ביום הכיפורים\u0004 ולא נקט מילתא דהיתר וחייב קרבן עבור יום הכיפורים עצמו דאסורה באכילה דאם כן צריך למינקט ככותבת שהוא שיעור אכילת יום הכיפורים ונקט שיעור זוטא ולכך נקט כזית חלב שהוא פחות:"]]],[["רבי שמעון פוטר בזו ר\"ש בן יהודה פוטר בכולן משום רבי שמעון","ואפילו בקמייתא אמר רבא הכא במאי עסקינן כגון שהלך בראשון ובשעת הילוכו בשני שכח שהלך בראשון ובהא פליגי ת\"ק סבר מקצת ידיעה כידיעה דמיא ור\"ש סבר מקצת ידיעה לאו כידיעה דמיא","אמר מר הלך בראשון ונכנס והיזה וטבל והלך בשני ונכנס חייב אמאי חייב הא לא הוי ליה ידיעה","אמר ריש לקיש הא מני רבי ישמעאל היא דלא בעי ידיעה בתחלה רבי יוחנן אמר אפילו תימא רבנן כאן עשו ספק ידיעה כידיעה","סלקא דעתך כאן עשו והוא הדין לכל התורה כולה קשיא דרבי יוחנן אדרבי יוחנן","קשיא דריש לקיש אדריש לקיש","בשלמא דר' יוחנן אדר\"י לא קשיא כאן עשו אבל בכל התורה כולה לא","מאי טעמא הכא גבי טומאה כתיב (ויקרא ה, ב) ונעלם ממנו והוא טמא ידיעה דאית בה נמי ספק חייב קרא אבל בכל התורה כולה כתיב (ויקרא ד, כג) או הודע אליו חטאתו אי אית ליה ידיעה הוא דמחייב","אלא לר\"ל קשיא אדמוקים לה כר' ישמעאל לוקמה כרבי הא קמ\"ל דר' ישמעאל נמי לא בעי ידיעה בתחלה","הא מתניתין היא דתנן רבי ישמעאל אומר ונעלם ממנו שתי פעמים לחייב על העלם טומאה ועל העלם מקדש","איצטריך סלקא דעתך אמינא מקרא לית ליה מגמרא אית ליה קמ\"ל:","\u0001מתני׳\u0002 חלב ונותר לפניו ואכל אחד מהן ואינו יודע איזה מהן אכל אשתו נדה ואחותו עמו בבית שגג באחת מהן ואינו יודע באיזה מהן שגג שבת ויום הכיפורים ועשה מלאכה בין השמשות ואינו יודע באיזה מהן עשה רבי אליעזר מחייב חטאת ורבי יהושע פוטר","א\"ר יוסי לא נחלקו על העושה מלאכה בין השמשות שהוא פטור שאני אומר מקצת עשה היום ומקצת עשה למחר","על מה נחלקו על העושה מלאכה בתוך היום ואינו יודע אם בשבת עשה אם ביוה\"כ עשה או על העושה ואינו יודע מעין איזו מלאכה עשה שרבי אליעזר מחייב חטאת ורבי יהושע פוטר א\"ר יהודה פוטרו היה רבי יהושע אף מאשם תלוי","ר' שמעון ור' שמעון שזורי אומרים לא נחלקו על דבר שהוא משם אחד שהוא חייב על מה נחלקו על דבר שהוא משום ב' שמות שרבי אליעזר מחייב חטאת ורבי יהושע פוטר","א\"ר יהודה אפילו נתכוון ללקוט תאנים וליקט ענבים ענבים וליקט תאנים שחורות וליקט לבנות לבנות וליקט שחורות ר\"א מחייב חטאת ור' יהושע פוטר תמיהני אם פטר בה ר' יהושע א\"כ למה נאמר (ויקרא ד, כג) אשר חטא בה פרט למתעסק:","\u0001גמ׳\u0002 תניא א\"ר אליעזר מה נפשך אי חלב אכל חייב אי נותר אכל חייב אי אשתו נדה בעל חייב אי אחותו בעל חייב אי בשבת עשה מלאכה חייב אי ביה\"כ עשה מלאכה חייב","אמר לו רבי יהושע הרי הוא אומר אשר חטא בה עד שיודע לו במה חטא ורבי אליעזר האי בה מאי עביד ליה מיבעי ליה פרט למתעסק"],[[0,"רבי שמעון פוטר בזו","דשני טומאות נינהו אכל חדא וחדא כניסה איכא למימר שביל זה הוא הטהור והילכך ליכא ידיעה ודאית בתחלה ובטומאת מקדש בעינן ידיעה בתחלה ובסוף והעלם בנתים ות\"ק דמחייב מפרש טעמיה לקמן:"],[1,"ואפילו בקמייתא","בתרתי קמייתא בתמיה והא איכא ידיעה ודאית בכניסה אחריתי:"],[1,"שכח שהלך בראשון","ואף על גב דטומאה ודאית היא מיהא ליכא אלא מקצת הידיעה דשכח את הראשון ובהא פליגי הני תרי תנאי אליבא דר' שמעון ת\"ק אליבא דר' שמעון לא פטרו אלא בבתרייתא דאילו בקמייתא כיון דממה נפשך איכא טומאה ידיעה ודאית שהלך בשניהם אף על פי ששכח שהלך בראשון אפילו הכי מקצת ידיעה כידיעה והוה ליה ידיעה בתחלה אבל בבתרייתא ליכא ידיעה ודאית:"],[1,"ור' שמעון בן יהודה סבר","אף על גב דטומאת ידיעה ודאית היא כיון דליכא אלא מקצת ידיעה כמאן דליתיה דמיא:"],[3,"ר' ישמעאל כו'","בפרק שני דשבועות (דף יד:):"],[5,"וקשיא דריש לקיש אדריש לקיש","דאמאי לא אוקמה כרבי ולימא ידיעת ספק כודאי:"],[7,"ונעלם והוא טמא","משמע אף על גב דאיכא קצת העלמה בטומאה חייב:"],[9,"ונעלם כו'","מדאפיק הני תרי ונעלם להך דרשא אלמא לית ליה ידיעה בתחלה דידיעת טומאה דבעי בתחלה ובסוף לא מפקא אלא מהנך תרי ונעלם כדאמרן בפ\"ק דשבועות (דף ד.):"],[11,"מתני' חלב ונותר לפניו","וכסבור שניהן שומן דהיתרא:"],[11,"אשתו נדה ואחותו עמו בבית","בא על האחת כסבור זו אשתו וכסבור שטהורה היא ונמצא שאשתו היתה נדה ועוד ספק על איזו מהן בא:"],[11,"ור' יהושע פוטר","מפרש בגמרא אשר חטא בה עד שיודע לו במה חטא:"],[13,"או שעשה","מלאכה בשבת ואינו יודע איזו מלאכה עשה אם חרש אם זרע:"],[13,"אף מאשם תלוי","מפרש בגמ':"],[14,"לא נחלקו","ר' אליעזר דאמר לא בעינן שידע במה חטא [ור' יהושע דאמר בעינן שידע במאי חטא]:"],[14,"על דבר שהוא משם אחד","כגון שתי אילנות של מין אחד לפניו ולא ידע אם מזה לקט אם מזה:"],[14,"שהוא חייב","שהרי ידע במה חטא איזו מלאכה עשה שבלקיטת תאנים חטא:"],[14,"על מה נחלקו על דבר שהוא משום שני שמות","כגון ספק קצר ספק טחן אי נמי ספק תאנים ספק ענבים וכן בנתכוין לזו ועשה את זו דבה דכתיב בקרא בין אידיעה בין אחטאת היא לר' יהושע עד שיתכוון לחטוא בה ולעת הידיעה ידע במה חטא ולרבי אליעזר כיון דנתכוון לדבר שיש בו חטא ולעת ידיעה נודע לו שחטא סגי:"],[15,"ותמיה אני אם פטר בה","כלומר על מה פטר בה רבי יהושע הלא נתכוון על דבר האסור:"],[15,"א\"כ","דמתעסק כי האי גוונא חייב למה נאמר בה:"],[15,"פרט למתעסק","בהיתרא כגון לחתוך את התלוש וחתך את המחובר אבל זה המתעסק באיסור חייב:"],[17,"גמ' מבעי ליה פרט למתעסק","כגון נתכוון לזו ועשה אחרת. ואי קשיא אם כן דר\"א אית ליה דרב נחמן האי בה דדריש ר' אליעזר פרט למתעסק לא צריך דממלאכת מחשבת דמייתי רב נחמן מצי למילף נראה לי דר\"א לית ליה דרב נחמן דדריש מלאכת מחשבת אסרה תורה דלא משמע ליה ההיא דרשא ולא מייתי דרב נחמן אלא משום דאמר בהדיא דמתעסק בשבת פטור אבל לרבי יהושע דדריש אשר חטא בה עד שיוודע לו במה חטא איהו דריש כרב נחמן מלאכת מחשבת אסרה תורה:"]],[[8,"אדמוקמת כרבי ישמעאל לוקמה כרבי","וצ\"ל על כרחך דלאו כרבי ממש דאם כן בלא קשיא דריש לקיש אדר\"ל מצי למפרך לוקמה כרבי ומטעם ידיעת בית רבו ומש\"ה חייב דהוה ליה ידיעת בית רבו ורבי סבר שמה ידיעה אלא הכי פריך אדמוקמת ליה כרבי ישמעאל ומוקמת ליה בלא ידיעה כלל לוקמה כרבי ובידיעת מקצת כמו ידיעת ספק דסבר רבי שמה ידיעה:"],[9,"הא מתניתין היא דתנן כו'","והקשה הרב ר' שמואל מווארדו\"ן והיכי מוכח מהאי מתניתין דמייתי דרבי ישמעאל לא בעי ידיעה בתחלה לעולם אימא לך דבעי אי משום דמפיק ונעלם ונעלם לדרשא אחריתי הא חזינן רבי דסבר ידיעת בית רבו שמה ידיעה ובעי ידיעת בית רבו אע\"ג דמפיק ונעלם ונעלם להעלם טומאה ולהעלם מקדש כמו הכא ומכל מקום בעי ידיעת בית רבו ממשמעות ונעלם מכלל שידע כבר ויש לומר בשלמא רבי אשכחנא בעלמא דבעי ידיעת בית רבו א\"כ גבי מקדש וטומאה נמי בעי לה אבל רבי ישמעאל לא אשכחנא בשום דוכתא דבעי ידיעת בית רבו ועוד יש לומר א\"כ הוה ליה למימר בהדיא ונעלם מכלל שידע כבר:"]]],[["מתעסק דמאי אי דחלבים ועריות חייב דאמר רב נחמן אמר שמואל המתעסק בחלבים ועריות חייב שכן נהנה","ואי מתעסק בשבת פטור מאי טעמא מלאכת מחשבת אסרה תורה","לרבא משכחת לה כגון שנתכוון לחתוך את התלוש וחתך את המחובר לאביי משכחת לה כגון דנתכוון להגביה את התלוש וחתך את המחובר","דאיתמר נתכוון להגביה את התלוש וחתך את המחובר פטור מאי טעמא דהא לא איכוון לשום חתיכה לחתוך את התלוש וחתך את המחובר אביי אמר חייב דהא איכוון לשום חתיכה רבא אמר פטור דהא לא איכוון לחתיכה דאיסורא:","רבי יוסי אומר לא נחלקו כו': תניא אמר להן רבי יוסי דקדקתם אחרי","מאי אמרי ליה דאמר להו דקדקתם אחרי הכי א\"ל הגביה בין השמשות מהו אמר להו דקדקתם אחרי","ונימא להו מקצת הגבהה היתה מהיום ומקצתה למחר הכי נמי קאמר להו דקדקתם אחרי ולא העליתם בידכם כלום","ולרבי יוסי גמר מלאכה לרבי אליעזר פטור הא שמענא ליה דמחייב דתנן רבי אליעזר אומר האורג שלשה חוטין בתחלה ואחד על האריג חייב","אמר רב יוסף רבי יוסי אליבא דר\"א הכי מתני רבי אליעזר אומר האורג שלשה חוטין בתחלה ושנים על האריג חייב:","א\"ר יהודה פוטרו היה רבי יהושע אף מאשם תלוי: תניא א\"ר יהודה פוטרו היה רבי יהושע אף מאשם תלוי שנאמר (ויקרא ה, א) כי תחטא ולא ידע פרט לזה שידע שחטא אמר לו ר\"ש זהו שמביא אשם תלוי שנאמר (ויקרא ה, יז) ועשה ולא ידע וזה לא ידע במה עשה","אבל ספק אכל חלב ספק לא אכל צא ושאל עליו אם מביא אשם תלוי אם לאו מאי הוי עלה","ת\"ש חטא ולא ידע במה חטא או ספק חטא ספק לא חטא מביא אשם תלוי מאן שמענא ליה דאמר חטא ואין ידוע במאי חטא מביא אשם תלוי ר\"ש וקא תני ספק חטא ספק לא חטא מביא אשם תלוי שמע מינה ס\"ל לרבי שמעון ספק חטא ספק לא חטא מביא אשם תלוי:","ר' שמעון שזורי ור\"ש אומר לא נחלקו כו' אם כן מה ת\"ל (ויקרא ד, כג) אשר חטא בה פרט למתעסק:","אמר רב נחמן אמר שמואל מתעסק בחלבים ועריות חייב שכן נהנה מתעסק בשבת פטור מלאכת מחשבת אסרה תורה","א\"ל רבא לרב נחמן והא תינוקות דכי מתעסק דמי ותנן מי שהיו לו שני תינוקות אחד למול בשבת ואחד למול אחר השבת ושכח ומל את של אחר השבת בשבת רבי אליעזר מחייב חטאת ורבי יהושע פוטר","עד כאן לא פטר רבי יהושע אלא משום דקסבר טעה בדבר מצוה ולא עשה מצוה פטור אבל מתעסק בדבר דלאו מצוה אפילו רבי יהושע מחייב","אמר לו הנח לתינוקות הואיל ומקלקל בחבורה חייב מתעסק בחבורה חייב","איתיביה רב יהודה לשמואל ר' יהודה אומר אפי' מתכוין ללקט תאנים וליקט ענבים ענבים וליקט תאנים שחורות וליקט לבנות לבנות וליקט שחורות ר\"א מחייב חטאת ורבי יהושע פוטר","והא הכא מתעסק הוא ורבי יהושע נמי לא קא פטר אלא מן מינא למינא אבל בחד מינא אפילו רבי יהושע מחייב","אמר ליה שיננא שבוק מתני' ותא בתראי הכא במאי עסקינן כגון שאבד מלקט מלבו נתכוון ללקט ענבים ושכח וסבור תאנים בעינא והלכה ידו על הענבים דרבי אליעזר סבר הרי נעשתה כוונתו ורבי יהושע סבר הרי לא נעשתה כוונתו ומחשבתו"],[[0,"מתעסק בחלבים","כגון חלב ושומן לפניו ונודע שזה חלב וזה שומן ונתכוון לאכול שומן והביט למקום אחר והלכה ידו אל החלב ואכלו אי נמי חלב וחלב לפניו וסבור שהוא שומן ונתכוין לאכול חתיכה זו ואכל את זו ולא דמי לשוגג דשוגג היינו שנתכוין לחתיכה זו עצמה אבל סבור שהוא שומן:"],[0,"מתעסק בעריות","כגון נתכוון לבוא על אשתו נדה וסבור טהורה היא אחותו ואשתו לפניו ונשמטה אשתו ולא ידע ובאה אחותו במקומה ולא דמי לשוגג דשוגג כגון שנתכוון לזו עצמה וסבור שהיא אשתו:"],[1,"אלא מתעסק בשבת","להכי אתא קרא למיפטריה. מתעסק בשבת מפרש לקמיה:"],[1,"מלאכת מחשבת","שחשב ונתכוון למלאכה זו עצמה:"],[2,"משכחת לה","מתעסק בשבת כגון שנתכוון כו':"],[2,"להגביה","פטור לדברי הכל דהאי מתעסק הוי דלא נתכוון לשום חתיכה:"],[4,"דקדקתם אחרי","כלומר נצחתוני וקפחתוני:"],[5,"הגביה","חפץ בין השמשות שבין שבת ליום הכיפורים כדי להוציאו דאהגבהה חייב מיד שיש הגבהה שהיא הוצאה כגון שהיא סמוך לרשות הרבים והוא עומד ברשות הרבים מהו היכי מצית למימר התם מקצתה היום ומקצתה למחר:"],[5,"דקדקתם אחרי","וחשבתם לנצחני ולא הועלתם כלום דאיכא למימר נמי מקצת הגבהה היום ומקצת הגבהה למחר:"],[7,"ולר' יוסי","נהי נמי דמקצתה היום ומקצתה למחר (הוא) גמר מלאכה הוא אמאי קאמר לדברי הכל פטור והא שמעינן ליה לרבי אליעזר דמחייב:"],[8,"ושנים על האריג","כל השיעור הוא זה. ובתחלה היינו טעמא דבעי שלשה משום דסתרי דשנים אינן מתקיימין אבל הכא איכא למימר חציו היום וחציו למחר:"],[9,"כי תחטא ולא ידע ואשם","גבי אשם תלוי כתיב:"],[10,"מאי הוי עלה","דספק אכל ספק לא אכל אליבא דר\"ש:"],[11,"חטא ואינו יודע במאי חטא","כגון חלב ונותר לפניו ולא ידע איזו מהן אכל או ספק חטא או ספק לא חטא כגון שומן וחלב לפניו:"],[14,"תינוקות היינו מתעסק","שנתכוון למול את זה ומל את זה ושוגג כגון שהיה מתכוין לזה עצמו אבל סבור שנולד בשבת:"],[15,"בדבר דלאו מצוה","כגון נתכוין לתאנה זו ולקט את זו:"],[16,"מקלקל בחבורה חייב","דהכי אמרינן בבבא קמא בפרק המניח את הכד (דף לד:) כל המקלקלין פטורין חוץ מחובל ומבעיר:"],[18,"אבל בחד מינא אפילו רבי יהושע מחייב","ואת אמרת מתעסק בשבת פטור דמשמע בסתם ואפילו בחד מינא:"],[18,"אפילו ר' יהושע מחייב","דלאו מתעסק הוא שהרי ללקיטת תאנים נתכוין וליקט תאנים אף על גב דאביי ורבא לא פטרי במתעסק אלא במתכוין להיתר כגון לחתוך את התלוש אבל שמואל אפי' במתעסק באיסור פטר מדנקט הש\"ס למילתיה מלאכת מחשבת אסרה תורה משמע שיתכוין בו:"],[19,"ותא בתראי","תריץ כוותי דמתעסק פטור והכא לאו מתעסק הוא דאותה שנתכוין אותה ליקט ומאי טעמא פטר רבי יהושע כגון שאבד מלקט מלבו מחשבה ראשונה של לקיטה אבדה מלבו ושכחה כגון שנתכוין ללקוט ענבים ושכח וכסבור תאנים בעינא והלכה ידו על הענבים וליקטן בלא מתכוון הרי נעשית בקשתו שלענבים היה צריך [אבל לא נעשית מחשבתו] שבשעת לקיטה חשב על התאנים ועכשיו נמצא שלא נעשית מחשבתו ואנן תרוייהו בעינן בקשתו ומחשבתו:"]],[[3,"לשון התוספות דאיתמר נתכוין להגביה התלוש וחתך המחובר","לפי מה שפירשנו צריך לומר ועלה בידו מחובר אותו עצמו שנתכוון לו דאי חתך מחובר אחר אמאי נקט נתכוון לתלוש אפי' נתכוין למחובר פטור כמו ההיא דשתי נרות ונתכוון לכבות את זו וכיבה את זו ורבינו שלמה יצחקי לא פירש כן:"],[3,"דהא לא איכוון לחתיכה דאיסורא","ואם תאמר שוגג נמי דכל התורה כולה לא מתכוון לאיסור ויש לומר בכל התורה כולה כשאמר מותר הוא בשוגג בדבר שהוא ידוע לנו שהוא איסור אבל הכא מתכוון לדבר שהוא היתר לכולי עלמא אם היה כפי מה שהוא סבור ולכך פטור משום דהוי מתעסק:"],[18,"אבל בחד מינא אפילו רבי יהושע מחייב","לכך פריך לשמואל ולא פריך לאביי ורבא דלעיל משום דלשמואל איירי בהכי במתכוין לאיסור ומיפטר מטעם מלאכת מחשבת אבל לאביי ורבא לא פריך משום דאינהו לא מיירו בהכי אלא מיירו שנתכוון להיתר דפטור מטעם בה פרט למתעסק דהכי סוגיא דלעיל:"],[19,"הכא במאי עסקינן שאבד מלקט מלבו כגון שנתכוון כו'","ובהא פליגי ר' אליעזר ורבי יהושע כדמפרש הש\"ס וניחא עתה דלא פריך הא בחד מינא חייב דדכוותיה בחד מינא קמיירי כגון שנתכוון ללקט תאנים הללו ושכח וכסבור תאנים אחרים בעינא שהם מצד אחר והלכה ידו על התאנים הראשונים ומשום הכי חייב כיון דמעיקרא לתאנים הללו נתכוון דהא דפטור מטעם מלאכת מחשבת בנתכוון לחתוך מחובר זה וחתך מחובר אחר מיירי שלא אבד מלקט מלבו שלא נתכוון מעולם [אלא] לאותו מחובר הראשון:"]]],[["מתיב רב אושעיא רבי שמעון שזורי ורבי שמעון אומרים לא נחלקו על דבר שהוא משם אחד שהוא חייב אלא על דבר שהוא משום שני שמות שרבי אליעזר מחייב חטאת ורבי יהושע פוטר","ורבי יהודה מאי קאמר דפליגי בנתכוין ללקט ענבים ולקט תאנים שחורות ולקט לבנות ענבים ותאנים שחורות ולבנות מאי ניהו שני שמות היינו רבי שמעון ור\"ש שזורי רבי יהודה מאי אתא לאשמועינן","אלא לאו מתעסק איכא בינייהו דרבי יהודה סבר מתעסק חייב ור\"ש שזורי סברי מתעסק פטור","לא מתעסק דברי הכל פטור והכא בהא קא מיפלגי דרבי שמעון שזורי סבר שכח מלקט מלבו בשם אחד דברי הכל חייב","כי פליגי בשני שמות ר' יהודה סבר לא שנא בשם אחד ולא שנא בשני שמות פליגי","רבא אמר ליקדם איכא בינייהו","והתניא היו לפניו שתי נרות דולקות ארוכות ונתכוין לכבות את זו וכיבה את זו להדליק את זו והדליק את זו פטור להדליק ולכבות וכיבה והדליק בנשימה אחת חייב","פשיטא מהו דתימא לא איתעבד מחשבתיה דהא להדליק מעיקרא בעי ולבסוף לכבות וכי עבד מעשה כיבה ובסוף הדליק הוא ואימא פטור קא משמע לן נהי דאקדומי נמי לא מקדים אחורי נמי לא מאחר","תנו רבנן החותה גחלים בשבת חייב חטאת רבי שמעון בן אלעזר אומר משום רבי אליעזר ברבי צדוק חייב שתים מפני שהוא מכבה את העליונות ומבעיר את התחתונות במאי עסקינן אי דקא מיכוין לכבות ולהבעיר מאי טעמא דמאן דפטר אלא דלא קא מכוין להבעיר מאי טעמא דמאן דמחייב תרתי","רבי אלעזר ורבי חנינא דאמרי תרווייהו כגון שנתכוין לכבות העליונות כדי להבעיר את התחתונות דתנא קמא קסבר מקלקל בהבערה פטור ורבי אליעזר ברבי צדוק אמר חייב וכן אמר רבי יוחנן בנפח שנו אמר רבי יוחנן עד כאן לא נתגלתה טעמא של הלכה זו","אמי בר אבין ורב חנניא בר אבין דאמרי תרווייהו"],[[1,"מאי ניהו ב' שמות","קא סלקא דעתך השתא שחורות ולבנות נמי כשני מינין דמו ואי ר' שמעון ור' שמעון שזורי נמי כרבי יהודה מוקמי פלוגתייהו בנתכוין ללקט את זה ולקט את זה רבי יהודה מאי אתא לאשמועינן:"],[2,"אלא לאו מתעסק איכא בינייהו","דשמעיה רבי יהודה לרבי שמעון שזורי דאוקי פלוגתא באבד מלקט מלבו אבל במתעסק דברי הכל פטור ואתא איהו למימר אפילו נתכוין ללקט כו' הוי מתעסק הואיל ובאיסור נתעסק פליגי ומחייב רבי אליעזר ואפילו רבי יהושע לא פטר אלא בשני שמות אבל בשם אחד חייב ותמה אני כו' אם כן למה נאמר בה פרט למתעסק בהיתר או במתעסק באב מלאכה ועשה אב מלאכה אחרת:"],[3,"אבד מלקט מלבו בשם אחד","שנתכוין לתאנה זו ושכח כסבור תאנה אחרת הסמוכה לה בעינא והלכה ידו על הראשונה דברי הכל חייב הואיל ולכך נתכוין תחלה ועוד כששכח מחשבתו לא חשב אלא באותו מין עצמו:"],[4,"בשני שמות","שנתכוין לתאנים ושכח וכסבור ענבים בעינא והלכה ידו על התאנים:"],[4,"ורבי יהודה סבר","אפילו בשם אחד פליגי וסבירא ליה דשחורות ולבנות שם אחד הן הואיל והן מין אחד: (תוספות) מה שאמר במתניתין תמיה אני אם פטר בה ר' יהושע במין אחד שהרי נתקיימה מחשבתו. עד כאן תוספות:"],[5,"ליקדם איכא בינייהו","שנתכוין ללקט זו תחלה ואחר כך זו והלכה ידו על האחרונה ר' שמעון ורבי שמעון שזורי סברי אם משם אחד דברי הכל חייב הואיל ושם אחד הן וסוף סוף תרווייהו עבד ולא איכפת לן במקדים המאוחר כי פליגי בשני שמות ר' אליעזר מחייב חטאת הואיל ולשניהן נתכוין ושניהם עשה ולא איכפת לן במקדים המאוחר ורבי יהושע פוטר הואיל ובשעת לקיטת כל אחת ואחת לא לזה הוא מכוין הוה ליה כמתעסק ופטור ורבי יהודה סבר אפילו בשם אחד פליגי אבל תמהני למה פטר הואיל וסוף סוף לשניהן נתכוין אבל במתעסק בעלמא שלא נתכוין אלא לאחת ולא עשאה ועשה את חברתה דכולי עלמא פטור:"],[6,"והא תניא","סייעתא דחיישינן למוקדם ומאוחר:"],[6,"להדליק זו","בשגגת שבת או בשגגת מלאכות:"],[6,"והדליק זו פטור","דהיינו מתעסק לא נתכוין אלא לאחת ולא עשאה ועשה את חברתה:"],[6,"להדליק ולכבות","כשהיה נר דולק ונר כבוי ונתכוין להדליק זה תחלה ואחר כך לכבות זה וכבה זה ואחר כך הדליק זה:"],[6,"אם בנשימה אחת","שנפח ומחמת הנפיחה כבה זה והדליקה חייב דליכא למימר הי מוקדם והי מאוחר:"],[7,"בשתי נשימות פטור","דלא נעשית כסדר:"],[7,"לא אתעביד מחשבתיה","דאיכא למימר כבה ואחר כך הדליק:"],[8,"החותה","הממלא כלים מצבור הגחלים:"],[8,"מכבה העליונות","שעכשיו נעשות תחתונות וכבו מחמת המשא של עליונות ומבעיר התחתונות שהיו כבויות מחמת המשא שהיה עליהן וכשהן עכשיו עליונות נתבערות:"],[8,"מאי טעמא דמאן דמחייב תרתי","הא לא איכוין לחדא ולגביה מתעסק הוא:"],[9,"כדי להבעיר את התחתונות","כלומר להבערת התחתונות לא הוה צריך אלא לכבוי עליונות היתה עיקר כוונתו שהיה נפח וצריך לפחמין נתכוין לכבות עליונות שהיו גסות ואף על פי שידע שיבערו התחתונות נתכוין לכיבוי של אלו על מנת שיתבערו אלו אף על פי שהוא מקלקלם אצלו:"],[9,"מקלקל בהבערה","כגון דנפח הוא כדאמר רבי יוחנן בנפח שנו דלא ניחא ליה לנפח להבעיר גחלים:"],[9,"מקלקל בהבערה חייב","דקיי\"ל אף על גב דשאר מקלקלים פטורין חובל ומבעיר חייבין:"],[10,"אמי בר אבין כו' כגון שנתכוין","לכבויי ולהבערה ואפילו הכי אהבערה פטור תנא קמא סבר לה כר' יוסי דאמר הבערה ללאו יצאת וליכא קרבן:"]],[[1,"היינו ר' שמעון ור' שמעון שזורי","דעל כרחיך צריך לומר דהכי פירושו דמילתיה לא נחלקו על דבר שהוא משם אחד שחייב כגון תאנים ותאנים ובאבד מלקט מלבו או לבנות ולבנות ושחורות ושחורות ואבד מלקט מלבו כדפי' לעיל על מה נחלקו על דבר שהוא משני שמות כגון ענבים או תאנים או שחורות ולבנות ואבד מלקט מלבו כדמפרש לעיל טעמייהו דלא מצינו למימר לר' שמעון ור' שמעון שזורי על מה נחלקו על דבר משום שני שמות כגון שלקט תאנים או ענבים ואינו יודע מה לקט דמאי קמשמע לן:"],[2,"אלא לאו מתעסק איכא בינייהו דרבי יהודה סבר דמתעסק חייב ור' שמעון שזורי ורבי שמעון סברי מתעסק פטור","ורבי שמעון סבר דפלוגתיה דרבי יהושע ורבי אליעזר באבד מלקט מלבו ונתכוין ללקט תאנים ולקט ענבים או שחורות ולקט לבנות דשני מינין הן כדמפרש לעיל טעמייהו אבל במין אחד ובאבד מלקט מלבו לא נחלקו דלכולי עלמא חייב אבל במין אחד דשלא אבד מלקט מלבו כגון שנתכוין ללקט אלו ולקט אחרות פטור משום מתעסק ורבי יהודה אמר אפילו בנתכוין כו' ובשני מינים פלוגתייהו ובשלא אבד מלקט מלבו ומינה דייקינן דוקא בשני מינין אבל בחד מינא לכולי עלמא חייב כדדייק לעיל הש\"ס ואמאי הא מתעסק הוא והדרן קושיין לדוכתיה והא דפשיטא ליה להש\"ס האי שיטה דלרבי שמעון מתעסק פטור ומוקי פלוגתייהו באבד מלקט מלבו ולרבי יהודה מתעסק חייב ומיירי בשלא אבד דהכי משמע לישנא דמתניתין דר' יהודה מחייב טפי דקאמר ר\"ש שזורי ור' שמעון אומרים לא נחלקו על דבר שהוא משום אחד שחייב כלומר דהתם ודאי חייב על מה נחלקו על שני שמות כו' כלומר דהתם איכא מאן דפטר ועל זה השיב ר' יהודה אפילו נתכוין ללקט תאנים כו' פליגי ואיכא מאן דמחייב ועוד מדקאמר תמה אני אם פטר בה רבי יהושע משמע דר' יהודה מחייב טפי:"],[9,"כגון שנתכוון לכבות העליונות כדי להבעיר התחתונות","כדמפרש רבי יוחנן בנפח שנו ולאו נופח אלא רוצה לומר אותו שעושה הפחמין ביער קרבוני\"ר בלע\"ז שנבערו העצים ונעשו פחמין ומסיר הפחמין גבוה מן האש ורוצה שיכבו לעשות מהם מלאכתם לעשות מהם ברזל ומשאין הפחמין דקין כי אינו חפץ בהן להתחמם רק שיעשו אפר וזהו קלקול ואינן ראויות לשום דבר והיה רוצה שיתאכלו לגמרי ויהיו אפר וזהו נתכוין לכבות העליונות כדי להבעיר התחתונות ואותה הבערה של תחתונות אינו חפץ בהם כי אם שיעשו אפר וזהו קלקול לר\"א ברבי (יצחק) [צדוק] מיחייב שתים משום כיבוי ומשום הבערה ואף על גב דמקלקל הוא ואף על גב דהוי מלאכה שאינה צריכה לגופה בהא סבירא ליה כר' יהודה דמחייב אף על גב דסבר כרבי שמעון במקלקל דהבערה ולרבנן אינו חייב משום הבערה דמקלקל בהבערה פטור:"]]],[["כגון שנתכוין לכבות ולהבעיר דתנא קמא סבר לה כר' יוסי דאמר הבערה ללאו יצאת","ור' אליעזר ברבי צדוק סבר לה כרבי נתן דאמר הבערה לחלק יצאת","רבא אמר להקדים איכא בינייהו","רב אשי אמר כגון שנתכוין לכבות והובערו מאיליהן ותנא קמא סבר לה כרבי שמעון דאמר דבר שאין מתכוין פטור ורבי אליעזר ברבי צדוק סבר לה כרבי יהודה דאמר דבר שאין מתכוין חייב","תנו רבנן החותה גחלים בשבת להתחמם בהם והובערו מאיליהן תני חדא חייב ותני אידך פטור הדתניא חייב קסבר מלאכה שאינה צריכה לגופה חייב עליה והא דתנא פטור קסבר מלאכה שאינה צריכה לגופה פטור עליה:","\u0001הדרן עלך ספק אכל חלב\u0002","מתני׳ \u0001אכל\u0002 דם שחיטה בבהמה בחיה ובעוף בין טמאין בין טהורין דם נחירה דם עיקור דם הקזה שהנשמה יוצאה בו חייבין עליו","דם הטחול דם הלב דם ביצים דם חגבים דם התמצית אין חייבין עליו רבי יהודה מחייב בדם התמצית:","\u0001גמ׳\u0002 ת\"ר (ויקרא ז, כו) כל דם לא תאכלו שומע אני אפי' דם מהלכי שתים דם ביצים דם חגבים דם דגים הכל בכלל ת\"ל (ויקרא ז, כו) לעוף ולבהמה","מה עוף ובהמה מיוחדין שיש בהן טומאה קלה וטומאה חמורה ויש בהן איסור והיתר והן מין בשר אף כל שיש בהן טומאה קלה","אוציא דם מהלכי שתים שיש בהן טומאה חמורה ואין בהם טומאה קלה"],[[2,"להקדים איכא בינייהו","שנתכוין להדליק תחלה ואחר כך לכבות והדליק וכבה בחתייה אחת תנא קמא חייש למוקדם ומאוחר הילכך לתרתי ליכא לחיוביה דשמא כבה תחילה ולמפטריה בולא כלום נמי לא דנהי דאקדומי לא אקדמיה אחורי נמי לא אחר הילכך מחייב חדא ורבי אליעזר לא חייש למוקדם ולמאוחר הילכך מחייב תרתי:"],[3,"רב אשי אמר שנתכוין לכבות","ולא להבעיר שלא היה יודע שסוף תחתונות להבעיר:"],[4,"שאינה צריכה לגופה","כגון זה שאינו צריך להבעירן אלא להתחמם בחתייתן ומכל מקום יודע היה שיתבערו ועל מנת כן עשה וה\"ל מתכוון מיהו מלאכה שאינה צריכה לגופה הויא הך הבערה:"],[6,"מתני' אכל דם שחיטה בבהמה","בין בבהמה בין בחיה בין בעופות:"],[6,"בין דם נחירה ובין דם עיקור","שעקר סימניהם:"],[6,"ובין דם ההקזה שהנשמה יוצאה בו חייבין עליו","כרת דדם הנפש הן. ובגמ' מפרש איזהו דם היקז שהנפש יוצאה בו:"],[7,"דם ביצים","ביצי איל ושור. לשון אחר דם ביצים המוזרות שנתאדמו מחמת חמימות שישבה עליהן התרנגולת:"],[7,"אין חייבין עליהן","כרת שאין כרת אלא בדם הנפש דכתיב (ויקרא י״ז:י״ד) כי נפש כל בשר דמו היא כל אוכליו יכרת:"],[9,"גמ' טומאה קלה","טומאת אוכלין בכביצה:"],[9,"טומאה חמורה","כשהיא נבלה מטמאה במשא. ויש בהן איסור קודם שחיטה והיתר לאחר שחיטה:"]],[[3,"סבירא ליה כרבי יהודה דאמר דבר שאינו מתכוין חייב","ואם תאמר לפי מה שפירש הר\"י פרק קמא דכתובות (דף ה) הא דאמר ר' יהודה דבר שאינו מתכוין אסור מדרבנן דוקא ולא מן התורה קשה דהכא משמע דמדאורייתא קאמר דמחייב חטאת ויש לומר דהכא היינו טעמא דמחייב רבי יהודה משום דהוי פסיק רישיה ולא ימות ואם תאמר אם כן אפילו רבי שמעון מודה ומאי קאמר תנא קמא סבירא ליה כרבי שמעון כו' ויש לומר דהכא הוי טעמא דמלאכה שאינו צריך לגופה ורבי יהודה ורבי שמעון לטעמייהו והאי דנקט טעמא דדבר שאינו מתכוין לא נצרכה דהא מלאכה שאינו צריך לגופו הוא ועוד דסבר שאינו מתכוין הוא דאינו חפץ בהבערתן של הגחלים שאינו נהנה מהם אבל בההיא דקתני החותה גחלים להתחמם בהם לא נקט מתכוין ושאינו מתכוין שהרי להתחמם הוא עושה אבל מלאכה שאינו צריך לגופה היא ולכך פטר ר\"ש דאע\"ג דפסיק רישיה היא כיון דמלאכה שאינו צריך לגופה היא ופטור ואם תאמר ההיא דפרק הבונה (שבת קג.) דקאמר אפילו תימא בארעא שאינו אגם דלא מתכוין פי' ופוטר כר\"ש ופריך והא אביי ורבא דאמרי תרווייהו מודה ר\"ש בפסיק רישיה ולא ימות פירוש אי אפשר שלא יפה הקרקע ומאי פריך מכל מקום מלאכה שאין צריך לגופה היא ויש לומר דהתם ס\"ד דהוה פסיק רישיה ולא ימות דניחא ליה ולכך משני דעביד בארעא דחבריה דהוה פסיק רישיה דלא ניחא ליה וכן מביא הערוך דפסיק רישיה דלא ניחא ליה שרי מההיא (סוכה דף לג:) דממעטין בלולב בי\"ט ופריך והא מתקן לא צריכא דאית ליה הושענא אחריתי אי נמי דאין צריך לגופה אף על גב שמתקנה שרי: [ועי' עוד תוס' שבת מא: ד\"ה מיחם ומ\"ש שם על צדו]:"],[6,"מתני' אכל דם שחיטה (נוהג) כו'","והקשה הר\"י דבגמרא דריש מה בהמה חיה ועוף שמטמאין טומאה חמורה וטומאה קלה ועוף טמא אינו מטמא בגדים אבית הבליעה וא\"כ אינו מטמא טומאה חמורה ומנלן דדמו אסור וי\"ל דלמסקנא ניחא דמפיק ליה בכלל ובפרט וה\"ק לעוף ולבהמה מה עוף ובהמה מיוחדין דאיתנהו במינייהו טומאה חמורה וטומאה קלה כגון בטהורין לאפוקי דגים וחגבים דאין במינם שום טומאה חמורה כו' וכן צריך לומר דקאמר מה בהמה ועוף כו' ויש בהן איסור והיתר ומפרש לקמן (כריתות דף כא:) איסור קמי שחיטה והיתר לאחר שחיטה א\"כ עוף טמא ובהמה טמאה שאין להן היתר לאחר שחיטה מנא ליה אלא שמע מינה הכי קאמר במין בהמה ועוף איכא איסור והיתר ואפי' למ\"ד אין שחיטה לעוף מן התורה נחירה מיהא בעי ואיכא איסור והיתר ומכל מקום נוכל לפרש איסור והיתר קודם מיתה איסור מן החי משום בשר מן החי ולאחר מיתה איכא היתר משום חי אבל גבי טומאה חמורה צ\"ל כדפירשנו ובגמרא דקאמר אי מה בהמה שאינה באם על בנים אף עוף שאינו כו' ה\"נ מצי למימר אי מה בהמה שמטמאה טומאה חמורה אף עוף כו' לאפוקי דם עוף טמא שאינו מטמא טומאה חמורה וה\"נ הוה מצי לפרש אף עוף שאינו באם על הבנים כגון מזומן אבל שאינו מזומן לא:"],[6,"דם עיקור","איכא דמפרש דם עיקור שנעקרו סימנין ממקום חיבורן אבל קשה כיון שאינה מתה על ידי כך והלכה למשה מסיני שיהא פסולה אבל טרפה אינה אם כן דמה אינו בכרת שאין הנשמה יוצאה בה לכן צריך לומר דם משחיטה שהיתה לאחר עיקור:"],[6,"דם הקזה שהנשמה יוצאה בו","והוא הדין דבדם שחיטה ונחירה ועיקור בעינן שהנשמה יוצאה בו אלא לא איצטריך למימר רק גבי דם הקזה שאין רגילות שיקיז דם לבהמתו עד שיבא להם דם הנפש:"],[7,"דם ביצים","פירש בקונטרס ביצת תרנגולת לשון אחר ביצי זכר וקשיא דבגמרא קאמר אוציא דם ביצים שאין מין בשר:"],[7,"דם דגים אין חייבין עליו","משמע הא איסורא איכא וקשיא דבגמרא קאמר אמר רב דם דגים שכינסו אסור ומותיב ליה מברייתא ואמאי ליסייעיה ממתניתין ויש לומר אין הכי נמי הוה מצי למימר וליטעמיך תיקשי ליה ממתניתין:"],[9,"שיש בהן טומאה חמורה וטומאה קלה ויש בהן איסור והיתר והן מין בשר","וקשיא לרבינו ברוך למה צריך לכל הני צדדין דבחד מינייהו סגי דאוציא דם מהלכי שתים שאין בהן טומאה קלה וכן בצד של היתר ואיסור סגי:"]]],[["אוציא דם שרצים שאין בהם טומאה חמורה אוציא דם ביצים שאין מין בשר דם דגים דם חגבים שכולו היתר","(ויקרא ז, כו) לעוף ולבהמה אי מה עוף שאין בה כלאים אף בהמה שאין בה כלאים ת\"ל ולבהמה","אי מה בהמה שאינה באם על הבנים אף עוף שאינו באם על הבנים תלמוד לומר לעוף ולבהמה","ואימא כל דם כלל עוף ובהמה פרט כלל ופרט אין בכלל אלא מה שבפרט עוף ובהמה אין מידי אחרינא לא","(ויקרא ז, כז) נפש אשר תאכל כל דם חזר וכלל כלל ופרט וכלל אי אתה דן אלא כעין הפרט","והא לא דמי כללא בתרא לכללא קמא כללא קמא לאו כללא בתרא כרת","האי תנא דבי ר' ישמעאל כללי ופרטי דרשינן מן הדין גוונא ואף על גב דלא דמי כללא בתרא לכללא קמא","אמר מר כלל ופרט וכלל אי אתה דן אלא כעין הפרט מה הפרט מפורש דבר שיש בו טומאה קלה וטומאה חמורה ויש בה איסור והיתר ויש בהן מין בשר אף כל דבר שיש בו טומאה קלה וטומאה חמורה וכו'","אף כל דקתני לאיתויי מאי","אמר רב אדא בר אבין לאתויי דמו של כוי מאי קסבר אי קסבר כוי ספיקא הוא איצטריך קרא למיסר ספיקא אלא קסבר כוי בריה בפני עצמו הוא","אשכחן דמו חלבו מנלן (ויקרא ז, כג) מכל חלב נבלתו מנלן (דברים יד, כא) מכל נבלה","גיד הנשה מנלן (בראשית לב, לג) בכף הירך תליה רחמנא והא אית ליה כף הירך","טומאתו ושחיטה מנלן סברא מדלכל מילי רבייה רחמנא כבהמה טומאתו ושחיטתו נמי כבהמה","אמר מר אוציא דם מהלכי שתים שיש בהן טומאה חמורה ואין בהן טומאה קלה ורמינהי החותך מן האדם צריך מחשבה והכשר","וקשיא לן מחשבה למה לי תעשה חתיכה שלו מחשבה ואר\"ל בחותכו לכלב ומחשבה לכלב לאו מחשבה היא","ולא והתנן כלל אמרו בטומאה כל המיוחד לאכול אדם טמא עד שיפסל מאכילת כלב","ההוא לאסוקי טומאה מיניה דכיון דמעיקרא הוה חזי לאדם לאסוקי מטומאה עד שיפסל מאכילת כלב הכא לאחותי ליה טומאה אי חזי לאדם חזי לכלב אי לא חזי לאדם לא חזי לכלב","מ\"מ קתני מחשבה ומחשבה לטומאה קלה היא ה\"מ מחיים אבל לאחר מיתה טמא הוא טומאה חמורה","דכוותה גבי בהמה לאחר מיתה אי בשר מטמא טומאה חמורה ואם דם מטמא טומאה חמורה","דתנן דם נבילות בית שמאי מטהרין ובית הלל מטמאין","לא נצרכא אלא לכדתנן נבלת בהמה טמאה בכל מקום נבלת עוף הטהור בכפרים צריך מחשבה ואין צריך הכשר","נבלת בהמה טהורה בכל מקום ונבלת עוף טהור וחלב בשוקים אין צריכין לא מחשבה ולא הכשר","וא\"ל רב לרבי חייא מחשבה למה לי לטומאה קלה היא גופה טומאה היא א\"ל כגון דאיכא פחות מכזית נבילה וצרפה לפחות מכביצה אוכלין דהאי והאי הוי כביצה","אי הכי ליבעי נמי הכשר דהא תנא דבי ר' ישמעאל (ויקרא יא, לז) על כל זרע אשר יזרע מה זרעים מיוחדין שאין סופן לטמא טומאה חמורה וצריך הכשר אף כל שאין סופן לטמא טומאה חמורה צריך הכשר","א\"ל ה\"מ באוכלין דעלמא דלית בו פחות מכזית נבלה אבל הכא דאיכא בגויה פחות מכזית נבילה כיון דאילו מצרף ליה כזית לא בעי הכשר"],[[0,"אוציא דם שרצים שאין בהן טומאה חמורה","שאין שרצים מטמאין אדם לטמא בגדים:"],[0,"שכולו היתר","מפרש לקמן (ע\"ב):"],[1,"לעוף ולבהמה","למה נאמרו שניהם שהרי מאחד מהן הייתי דן כעין הפרט:"],[1,"אי מה עוף כו'","כלומר אם לא נאמר אלא עוף הייתי אומר מה עוף שאין בו כלאים. מפרש לקמן כלאי הצמר דנוצת העוף אין בהן משום כלאים:"],[1,"אף בהמה שאין","בצמרה כלאים כגון שור ועז חייבין על דמן אבל לא על דם צאן שהרי בצמרן כלאים:"],[2,"אף עוף שאינו באם על הבנים","כגון עוף טמא שאינו טעון שילוח חייבין על דמו אבל עופות טהורין לא:"],[6,"דבי ר' ישמעאל דדייני כללי ופרטי כי האי גוונא","בשלהי אלו טרפות (חולין סו.) ואף על גב דלא דמי כללא קמא לכללא בתרא:"],[9,"לאתויי כוי","וחיה לא איצטריך לרבות דחיה בכלל בהמה בפרק בהמה המקשה (חולין עא.) כדמפרש רבי יוחנן לקמיה:"],[9,"איצטריך קרא למיסר ספיקא","בתמיה. דלמאי מדמינן ליה אי לחיה דמה אסור אי לבהמה דמה אסור:"],[10,"נבלתו מנלן","איסור אכילת נבלתו מנלן:"],[11,"בכף הירך תלייה רחמנא","דכל דאית ליה כף שקורין פולפ\"א נוהג בו גיד הנשה והאי דאינו נוהג בעוף בפרק גיד הנשה (חולין דף צב:) מפרש דלא עגיל כף דידיה:"],[12,"טומאתו","שתטמא נבלתו:"],[13,"","\u0003צריכין מחשבה והכשר\u0004 גרסינן במסכת עוקצין:"],[14,"תעשה חתיכה שלו מחשבה","דכיון דחתכיה אחשביה דאי נגעה ביה טומאה מקבל טומאה:"],[20,"נבלת בהמה בכל מקום","ואפילו בשווקים שיש שם רוב עם צריכה מחשבה לאכילה לקבל טומאת אוכלין הואיל דאין דרך לאוכלה:"],[20,"וכן נבלת עוף טהור בכפרים","שהעם מועטים צריכין מחשבה לטומאת אוכלין:"],[20,"ואין צריכין הכשר","משום דמטמאין טומאה חמורה דנבלת בהמה מטמאה במשא ונבלת עוף טהור מטמא בגדים אבית הבליעה ואמרינן לקמן דכל שסופו לטמא טומאה חמורה אינו צריך הכשר:"],[20,"","הכא לא גרסינן \u0003והחלב -\u0004 ואף על גב דתנינא לה גבי שווקים דמשמע הא בכפרים צריך מחשבה לא תנן ליה ברישא דלא מיתני ליה אינו צריך הכשר דאי בחלב נבלה צריך הכשר דאינה מטמאה טומאה חמורה ואי בחלב דשחוטה כיון דבכפרים קאי לא מיתכשר בדם שחיטה דהכשר דקודם מחשבה לאו הכשר הוא כדאמרינן בהעור והרוטב (חולין קכח.) עולשין שליקטן לבהמה ונמלך עליהן לאדם צריכים הכשר שני משנה זו בשילהי מסכת עוקצין:"],[21,"נבלת בהמה טהורה בכל מקום","ואפילו בכפרים שהעם מועט אינן צריכין מחשבה דסתמא למאכל עובדי כוכבים עומדת וכן נבלת עוף טהור וחלב בהמה וחיה בשווקים שהעם מרובין:"],[21,"אינן צריכין מחשבה ולא הכשר","דנבלת בהמה ועוף מטמאין טומאה חמורה וחלב בחלב שחוטה קמיירי שהרי הוכשר בדם שחיטה:"],[22,"והא היא גופה טמאה היא","טומאת נבילות:"],[22,"","בפחות מכזית ליכא טומאת נבילות וכי חשיב עליה לאכילה מצטרף לבהדי אוכלין פחות מכביצה לטומאת אוכלין:"],[23,"אי הכי","דפחות מכזית הוא ולא אתי לעולם לידי טומאת נבילות ניבעי נמי הכשר דהא תנא דבי רבי ישמעאל כו':"]],[[0,"אוציא דם שרצים שאין בהן טומאה חמורה","ואף על גב דמטמא במגע במשא מיהא לא מטמא ולא בגדים:"],[0,"אוציא דם ביצים של עוף שאינו מין בשר","תימה לרבינו ברוך דלא מיירי הכל בחד צד ויש בהן איסור והיתר ודם ביצים וחגבים הוה מצי למעט שאין בהן טומאה חמורה אלא האי פשוט יותר להם להיתר שאומר הש\"ס:"],[9,"כוי בריה בפני עצמה","בפרק אותו ואת בנו (חולין פ.) דקתני כוי בריה בפני עצמה היא ולא הכריעו חכמים אי מין חיה או מין בהמה היא וההיא בריה לא הוי כמו בריה דהכא שהרי בריה דהתם הוי או מין בהמה או מין חיה מדקאמר ולא הכריעו בו חכמים כו' אבל הכא רוצה לומר בריה בפני עצמה שאינה לא חיה ולא בהמה דאי הוי או בהמה או חיה לא איצטריך לרבויי דמו וכן ההיא (יומא דף עד.) כל חלב לרבות כוי וחצי שיעור וקאמר כוי בריה בפני עצמה אינו אומר שיהא ספק או חיה או בהמה דאם כן לא צריך קרא לאסור חלבו:"],[14,"בחותכו לכלב","הוא הדין דהוה מצי לשנויי בחותכו לרפואה אלא הא קא משמע לן דאפילו בחותכו לכלב בעי מחשבה:"],[22,"כגון דאיכא פחות מכזית נבילה וצירפה","אבל כזית וצירפה ליכא למימר ומהניא מחשבה שיטמא האי כביצה אוכלין אחרים אפילו לא יגעו האוכלין רק בצירוף ולא צריך שיגעו בנבילה דא\"כ לא מיישב מה בהמה שיש לה טומאה קלה דמשמע שיש נבילה שאין עליה רק טומאת אוכלין ואי הוה בה כזית הוה ביה טומאה חמורה ועוד יש לומר דמשמע דנקט במתניתין דמייתי עלה בהמה כו' בכ\"מ ונבלת עוף טהור כו' משמע נבלת בהמה דומיא דנבלת עוף כלומר דצריכה מחשבה כמו על עוף ולכך נקט פחות מכזית:"]]],[["לאפוקי מת אף על גב דממליא ליה לא מטמא טומאת אוכלין משום דבטלה דעתו אצל כל אדם","רב חנניא אמר אפילו תימא דהוי כזית הכא במאי עסקינן כגון שחיפהו בבצק","א\"ה הכשר נמי ניבעי ה\"מ באוכלין אחריני דלא מטמו לא במגע ולא במשא אבל הכא נהי דלא מטמא במגע דקמחפי בבצק במשא מיהת ליטמא דהא טעון ליה","לאפוקי מת דאף על גב דחיפהו בבצק מטמא טומאה חמורה דטומאה בוקעת ועולה בוקעת ויורדת","אמר מר יצאו שרצים שאין בהן טומאה ולא שרץ מטמא במגע במשא לא מטמא","אמר מר יצא דם דגים ודם חגבים שכולן היתר מאי כולו היתר אילימא דחלבו מותר הרי חיה דחלבה מותר ודמה אסור ואלא משום דלית בהו איסור גיד הנשה והרי עוף דלית ביה איסור גיד הנשה ודמו אסור","אלא מאי כולו היתר דלא בעי שחיטה","אמר מר מה עוף שאין בו כלאים אף בהמה תלמוד לומר בהמה","כלאים דמאי אילימא כלאים דהרבעה וכלאים דחרישה והתנן חיה ועוף כיוצא בהן","אלא אמר אביי שצימרו אין חייבין עליו משום כלאים","אמר רב יהודה אמר רב דם שרצים לוקין עליו בכזית מיתיבי דם הטחול דם הלב דם הכליות דם אברים הרי אלו בלא תעשה דם מהלכי שתים דם שרצים ורמשים אסור ואין חייבין עליו","מאי אין חייבין עליו כרת אלאו מחייב","חדא דהיינו רישא ועוד תנא מלאו נמי קא ממעט ליה דקתני יצא דם שרצים שאין בהן טומאה חמורה","אמר רבי זירא התרו בו משום שרץ לוקה משום דם אינו לוקה","אמר רב דם דגים שכינסו אסור מיתיבי דם דגים דם חגבים מותר ואפילו לכתחלה ההיא בשלא כינסו כי קא אמר רב בשכינסו","דכוותה גבי מהלכי שתים בשלא כינסו מי אסור והא תניא דם שעל גבי ככר גוררו ואוכלו של בין השינים מוצצו ובולעו ואינו חושש","אלא כי תניא ההיא מתניתא דאית ביה קשקשים כי קאמר רב אסור דלית ביה קשקשים","אמר רב ששת דם מהלכי שתים אפילו מצות פרוש אין בו מיתיבי דם הטחול דם הלב דם הכליות דם אברים הרי אלו בלא תעשה דם מהלכי שתים דם שרצים ורמשים אסור ואין חייב עליו כי תניא אסור"],[[0,"לאפוקי מת","כלומר להכי אמרינן לעיל יצאו מהלכי שתים שאין בהן טומאה קלה דאף על גב דממלי לפחות מכביצה אוכלין מפחות מכזית מן המת לא מצטרף בהדיה לטומאת אוכלין דבטלה דעתו אצל כל אדם:"],[1,"שחפהו בבצק","פחות מכביצה וזה משלימו לכביצה דאף על גב דהוא גופיה טמא מהני ליה צירוף דהשתא לא מטמא במגע דהא מכוסה הוא וכי אמר דמצטרף בהדי בצק לטומאת אוכלין דאיכא כביצה אוכלין טמאין ומטמאין אוכלין אחרים הנוגעים בהן:"],[2,"אי הכי","דמכוסה הוא ואין סופו לטמא טומאה חמורה הכשר נמי ניבעי:"],[3,"לאפוקי מת","להכי קתני לעיל מהלכי שתים אין בהן טומאה קלה דאם חיפהו בבצק טומאה חמורה בוקעת ועולה דכל אהל שעל המת שאין בו חלל טפח טומאה בוקעת ועולה כדאמרינן בהעור והרוטב (חולין קכה.):"],[4,"אמר מר יצאו שרצים כו'","נראה בעיני דל\"ג להא מילתא דקא משני ליה במשא מיהא לא מטמא דהא עוף נמי לא מטמא במשא ואמר לעיל דמטמא טומאה חמורה:"],[8,"חיה ועוף כיוצא בהן","בב\"ק בפרק שור שנגח את הפרה (בבא קמא דף נד:) אחד השור ואחד כל בהמה לנפילת הבור כו' ולכלאים ולשבת וכן חיה ועוף כיוצא בהן:"],[10,"לוקין עליו","קא סלקא דעתך משום דם:"],[10,"[בלא תעשה","ולא בכרת שאינו דם הנפש]:"],[10,"ואין חייבין עליו","מלקות:"],[12,"חדא דהיינו רישא","דאם כן מה הפרש בין דם (מהלכי שתים) לדם האברים ואמאי פלגינהו לתרתי מילי:"],[12,"ועוד האי תנא דלעיל מלאו נמי ממעט ליה דקתני יצא דם שרצים","מכלל דם דלא תאכלו:"],[13,"התרו בו משום שרץ לוקה","כדאמרינן בפרק קמא (לעיל כריתות דף ד:) וזה לכם הטמא לימד על דם השרץ ובשרו שמצטרפין לכזית לאכילה אלמא דם שרצים כבשרן:"],[14,"שכנסו","בכלי אסור דמיחלף בדם בהמה והרואה אומר מותר לאכול דם:"],[14,"דם דגים וחגבים מותר לכתחלה","היינו סיפא דהך ברייתא דקתני לעיל דם הטחול דם הלב כו':"],[15,"דכוותה גבי מהלכי שתים","דקתני בהך מציעתא אסור ואין חייבין עליו מוקמת נמי בשלא כנסו דהא הכי תרצת לסיפא דברייתא:"],[15,"דם שעל הככר","אף על גב דלאו ככנסו דמי וליכא איסורא מיהו מצות פרוש יש בו אבל של בין השינים דאכתי מחובר הוא אפילו מצות פרוש אין בו ומוצצו ואינו חושש ולא ככנסו דמי:"],[16,"דאית ביה","בדם קשקשים מותר לכתחלה דלא אתי לאיחלופי בדם בהמה חיה ועוף:"],[17,"מהלכי שתים","אדם:"],[17,"מצות פרוש אין בו","דאינו מצוה לפרוש ממנו אפי' משום מצות פרישה בעלמא:"]],[[1,"רב חנניא אמר אפילו תימא כו'","לא ניחא ליה לאוקמי כדאוקמא רבי חייא דדוחק הוא לומר כיון דאילו מצרף ליה לכזית משום הכי לא בעי הכשר דה\"נ מצי למימר עתה כיון דאי לא מחפה בבצק לא בעי הכשר כו' ולא רצה לתרץ כדר' חייא אלא משני השתא נמי מטמא במשא ועוד דדוחק הוא במילתיה דר' חייא דטומאה חמורה וטומאה קלה בתרי דוכתי טומאה חמורה בכזית וטומאה קלה פחות מכזית אבל רב חנניא משכח ליה בחד דוכתא בכזית ובחיפהו בבצק דחמורה במשא וקלה במגעו והא דקאמר אפילו תימא דהוי כזית אין הלשון מכוון דמשמע דמודה שפיר בפחות מכזית וליתא כדפירשנו:"],[15,"דכוותה גבי דם מהלכי שתים בשלא כינסו","פירוש דבההיא ברייתא דדם דגים קתני דם מהלכי שתים אסור ומי אסור בשלא בעין והא תניא כו' דם שבין השינים מוצצו ואינו חושש ופירש הקונטרס אפילו מצות פרוש אין בו ולכך פירש הקונטרס דאם לא כן מאי פריך הכי נמי בדם שבין השינים משום דאינו נראה ולא פירש אבל התם שפירש אסור אפילו לא כינסו כדקאמר דם שעל גבי הככר גוררו לכך פי' הקונטרס דם שעל הככר גוררו כו' אף על גב דליכא איסור מצות פרוש יש בו ומיהא פריך דקאמר רב אסור והכא משמע דליכא רק מצות פרוש אף על גב דנראה ופירש אבל קשה שהרי מצות פרוש איסור מעליא הוא ואם כן לא פריך רק מסיפא ומאי פריך שאני התם בדם שבין השינים משום דם דלא פירש אבל דם מהלכי שתים שפירש אסור אפילו לא כינסו ודכוותה דם שעל הדג דמותר אפילו פירש או שמא הא דקאמר מוצצו ובולעו היינו משום שהוא נודע דמהתם אתו והא דקאמר בדם מהלכי שתים שהוא אסור מיירי בשלא נודע מהיכא אתי אבל אצבעו מטפטף דם שרי משום דמהתם קאתי וליכא לספוקי לא בדם בהמה ולא בדם חיה ותירץ רבינו ברוך דהכי פריך דכוותה גבי דם מהלכי שתים בשלא כינסו מי אסור פירוש אי אמרת בשלמא דדם דגים שרי אף בכינסו ודכוותה מהלכי שתים אסור נינהו וא\"כ חידושא דמהלכי שתים אסור אף בכינסו כלומר דבכינסו נמי איצטריך לאשמועינן איסור דמהלכי שתים ניחא דלא תני היתר ממהלכי שתים כגון לא פירש שהרי עיקר מילתיה הוי מכינסו אלא כיון דאמר דכינסו אסור בדם דגים ואם כן הא דתני דם מהלכי שתים אסור מיירי בלא כינסו דבהא איירי מדקאמר דדם דגים מותר דבכינסו אסור וכיון דהא דתני איסור דם מהלכי שתים בשלא כינסו הוה ליה למיתני צד היתר שבו כמו דתנא דם דגים דנקט ההיתר אם איתא דיש בו היתר בדם מהלכי שתים אלא ש\"מ דאין בו היתר כלל ואפילו לא פירש ולכך פריך והא תניא כו' ושבין השינים מוצצו ואינו חושש וא\"כ ש\"מ דמותר וא\"כ הו\"ל לאיפלוגי גבי דם מהלכי שתים ומשני אלא כי תניא מתניתא דאית ביה קשקשין כו' וניחא דלא תני היתר גבי מהלכי שתים דלא שייך ביה קשקשין ומהכא משמע דבדם דגים ליכא איסורא רק בכינסו ובלא קשקשין:"],[17,"מיתיבי דם הטחול כו' הרי אלו בלא תעשה","ומיהא פריך אבל כרת ליכא:"]]],[["דפירש כי קאמר רב בדלא פירש כדתניא דם שעל גבי ככר גוררו ואוכלו של בין השינים מוצץ ובולע ואינו חושש","איכא דמתני לה להא דרב ששת על הדא דתניא יכול חלב מהלכי שתים יהא אוכלו עובר בלאו ודין הוא מה בהמה טמאה שהקלתה במגעה החמרתה בחלבה מהלכי שתים שהחמרתה במגען אינו דין שתחמיר בחלבן","ת\"ל (ויקרא יא, כט) וזה לכם הטמא זה טמא ואין חלב מהלכי שתים טמא אלא טהור","אוציא את החלב שאין שוה בכל ולא אוציא הדם ששוה בכל ת\"ל וזה לכם הטמא זה טמא ואין דם מהלכי שתים טמא אלא טהור א\"ל רב ששת אפילו מצות פרוש אין בו","תנן התם הלב קורעו ומוציא את דמו לא קרעו אינו עובר עליו א\"ר זירא אמר רב ל\"ש אלא בלב עוף הואיל ואין בו כזית אבל לב בהמה דיש בו כזית אסור וחייבין עליו כרת","מיתיבי דם הטחול דם הלב דם הכליות דם אברים הרי אלו בלא תעשה דם מהלכי שתים דם שקצים ורמשים אסור ואין חייבין עליו","כי קתני אין חייבין עליו על דם דיליה כי קאמר רב דאתי ליה מעלמא","דם דיליה היינו דם אברים וליטעמיך מי לא קתני דם כליות וקתני דם אברים אלא תני והדר תני ה\"נ תני והדר תני","מעלמא מהיכא אתי ליה א\"ר זירא בשעה שהנשמה יוצאה מישרף שריף:","דם שהנשמה יוצאה בו חייבין עליו: איתמר איזהו דם הקזה שהנשמה תלויה בו רבי יוחנן אמר כל זמן שמקלח ר\"ל אמר מטיפה המשחרת ואילך","מיתיבי איזהו דם הקזה שהנשמה יוצאה בו כל זמן שמקלח יצא דם התמצית מפני שהוא שותת מאי לאו אפילו ראשון ואחרון דשותת הוא כדם התמצית דמי תיובתא דר\"ל","לא למעוטי דם המשחיר אבל דם ראשון ואחרון אף על גב דהוא שותת היינו דם הנפש","מיתיבי איזהו דם ראשון כל זמן שמקלח יצא ראשון ואחרון מפני שהוא שותת תיובתיה דר\"ל אמר לך תנאי היא דתניא איזהו דם הנפש כל זמן שמקלח דברי ר\"א ר\"ש אומר מטיפה המשחרת ואילך","תנא דבי רבי ישמעאל (במדבר כג, כד) ודם חללים ישתה פרט לדם קילוח שאינו מכשיר את הזרעים","בעא מיניה ר' ירמיה מרבי זירא הקיז דם לבהמה וקיבל דמה בשני כוסות מהו על הראשון דברי הכל חייב על האחרון מי מיחייב או לא","א\"ל פלוגתא דר' יוחנן ור\"ל דאיתמר הקיז דם לבהמה וקיבל דמה בשני כוסות ר\"ל אמר חייב שתי חטאות ורבי יוחנן אמר אינו חייב אלא אחת:","רבי יהודה מחייב בדם התמצית: א\"ר אלעזר מודה ר' יהודה לענין כפרה שנאמר (ויקרא יז, יא) כי הדם הוא בנפש יכפר דם שהנפש יוצאה בו מכפר ושאין הנפש יוצאה בו אינו מכפר","אמר ר\"נ בר יצחק אף אנן נמי תנינא דתניא דם מה ת\"ל (ויקרא יז, י) כל דם","לפי שנאמר כי הדם הוא בנפש יכפר אין לי אלא דם קדשים שהנפש יוצאה בו שהוא מכפר דם חולין ודם התמצית מנין ת\"ל כל דם סתם סיפרא מני ר' יהודה היא:","\u0001מתני׳\u0002 ר\"ע מחייב על ספק מעילה אשם תלוי וחכמים פוטרים ומודה ר' עקיבא שאינו מביא את מעילתו עד שיתודע לו שיביא עמו אשם ודאי","א\"ר טרפון מה לזה מביא שתי אשמות אלא מביא מעילה וחומשה ויביא אשם בשני סלעים ויאמר אם ודאי מעלתי זו מעילתי וזו אשמי ואם ספק מעלתי המעות נדבה ואשם תלוי שממין שהוא מביא על הודע מביא על לא הודע","אמר רבי עקיבא נראין דבריו במעילה מעוטה הרי שיבוא לידו ספק מעילה במאה מנה לא יפה לו שיביא אשם בשתי סלעים ולא יביא ספק מעילה במאה מנה מודה ר\"ע לר' טרפון במעילה מעוטה:"],[[0,"דפירש","שפירש מן האדם בכלי או על גבי ככר:"],[1,"חלב מהלכי שתים","חלב דאשה:"],[1,"היקלת במגעה","שאין בה זיבות ונדות:"],[3,"שאינו שוה בכל","דבטהורה מותר ובבהמה טמאה אסור:"],[4,"לא שנו","דאינו עובר עליו אלא בלב עוף דאין בדמו כזית:"],[6,"דם דיליה","הנבלע בבשר הלב כשאר דם הנבלע באברים:"],[6,"דאתי ליה מעלמא","אותו הנמצא בחלל הלב:"],[8,"מישרף שריף","מושך הדם מבית השחיטה בנשימתו וכונסו בלבו:"],[8,"שריף","בלע\"ז הומי\"ר:"],[8,"גליון מישרף","והוא דם הנפש ואדם הנפש אמרינן בריש פירקין שחייבין עליו כרת. עכ\"ה:"],[9,"דם הקזה","בתחלה שחור ואחר כך יוצא אדום ושתיהן בשתיתה בלא קילוח ברחוק ואחר כך מקלח וסוף כשהדם מתמעט שותת ויורד בסמוך:"],[9,"כל זמן שמקלח","היינו אמצעי:"],[9,"מטיפה המשחרת ואילך","משכלה משחיר הראשון והתחיל להאדים הוא דם הנפש:"],[10,"ראשון ואחרון","מאדים שלפני הקילוח ושל אחרון מדנקט טעמא מפני שהוא שותת והני נמי שותתין:"],[11,"לא למעוטי דם המשחיר","מפני שהוא נמי כדם התמצית:"],[13,"ודם חללים ישתה","דם היוצא מן החללים כלומר לאחר מיתה קרוי משקה פרט לדם קילוח שאינו לאחר מיתה דזהו דם הנפש ואינו קרוי משקה ואינו מכשיר את הזרעים:"],[14,"על הראשון דברי הכל חייב","דדם קילוח מעורב בו:"],[15,"חטאת אחת","על הראשון שדם הקילוח מעורב בו:"],[17,"דם","הוה מצי למיכתב מה תלמוד לומר כל דם ונכרתה וגו':"],[18,"לפי שנאמר כי הדם הוא בנפש יכפר","דמשמע דאינו חייב אלא על דם הראוי לכפרה לזריקה על המזבח ואין לו כרת אלא בדם קדשים והוא שהנפש יוצאה בו שהוא לכפרה דכתיב בנפש יכפר דמשמע אין כפרה אלא בדם הנפש:"],[18,"ודם התמצית","בקדשים:"],[18,"ר' יהודה היא","אלמא ס\"ל דדם התמצית לא מכפר מדאיצטריך לרבויי מכל:"],[19,"מתני' שאינו מביא את מעילתו","אינו צריך להביא את הממון:"],[20,"מביא מעילה","הממון וחומשו:"],[20,"גיליון","היינו דכתיב ואת אשר חטא מן הקדש שמביא שוה מה שנהנה וחומשו במעות ומוסרו לכהן הגזבר והמעות יפלו לנדבה לקיץ המזבח. תוס':"],[20,"בשני סלעים","הנקח בשני סלעים דכתיב (ויקרא ה) בערכך כסף וגו':"],[20,"שממין שמביא כו'","הילכך יכול להביא ולהתנות:"]],[[4,"לא קרעו אינו עובר עליו","מוקמא ליה בלב עוף דליכא כזית ומכל מקום איכא איסורא למ\"ד (יומא עג:) חצי שיעור אסור מן התורה ומשום הכי אסור אבל אינו לוקה כיון דלית ביה כזית:"],[6,"כי קתני בדם דיליה","ולא גרסינן כי קתני אין חייבין עליו דהא גבי לב לא קתני ליה ואם תאמר אמאי לא פריך ממתניתין ופריך מברייתא שהרי בהדיא קתני מתני' דם הטחול דם הלב אין חייבין עליו ויש לומר דאיכא לאוקומי בלב עוף [אבל ברייתא ליכא לאוקמי בעוף] שהרי קתני הרי אלו בלא תעשה:"],[13,"דם חללים פרט לדם קילוח כו'","פירש רש\"י דם חללים שכבר נתחללה כלומר שכבר מתה מקודם לכן מכשיר פרט לדם קילוח דעתה נתחללה ורש\"י לא פירש כן פרק השוחט (חולין לו.) ופירש פרט לדם קילוח כלומר דם שנעשה בו חלל מכשיר פרט לדם קילוח שהוא לאחר שנעשית חלל וקשה שהרי בשמעתין משמע דדם קילוח הוא דם שהנשמה יוצאה בו ומשמע לפי הסוגיא דשמעתא דגבי אדם ובהמה אין דינן שוה דגבי אדם דם שלאחר יציאת נשמה מכשיר אבל לא אותו שיוצא בשעת יציאת נשמה וגבי בהמה דם שלאחר יציאת נשמה אינו מכשיר כדאמרינן פסחים (דף טז:) הנח לדם התמצית דאפילו בחולין לא מכשיר ולא דם מיתה ולא דם מגפתה רק דם שחיטה דמצינו מתשפכנו כמים:"],[14,"קבל דמו בשני כוסות","בכוס ראשון יש דם קילוח ובכוס שני זה שאחר קילוח חייב שתי חטאות אם אכל בשתי העלמות:"]]],[["\u0001גמ׳\u0002 ת\"ר (ויקרא ה, יז) ואם נפש לחייב על ספק מעילות אשם תלוי דברי ר' עקיבא וחכמים פוטרים","לימא בהא קא מיפלגי דר' עקיבא סבר למדין עליון מתחתון ורבנן סברי אין למדין עליון מתחתון","אמר רב פפא דכולי עלמא למדין עליון מתחתון דאם כן צפון בבן בקר לא משכחת להו","אלא הכא היינו טעמא דרבנן דפטרי דגמירי מצות מצות מחטאת","מה להלן דבר שחייבין על זדונו כרת ועל שגגתו חטאת ועל ספיקו אשם תלוי אף כל שחייבין על זדונו כרת ועל ספקו חטאת ועל שגגתו אשם תלוי","לאפוקי מעילה דאין חייבין על זדונו כרת דתניא הזיד במעילה רבי אומר במיתה וחכמים אומרים באזהרה","ור' עקיבא סבר כי ילפינן מצות מצות מחטאת חלב להכי הוא דילפינן מה להלן בקבועה אף כאן בקבועה","לאפוקי עולה ויורד דלא","ורבנן סברי אין גזירה שוה למחצה מכלל דר' עקיבא סבר יש גזירה שוה למחצה אלא דכולי עלמא אין גזירה שוה למחצה","אלא היינו טעמא דר\"ע דאמר קרא ואם נפש וי\"ו מוסיף על ענין ראשון וילמד עליון מתחתון","ורבנן סברי תחתון הוא דגמר מעליון לאשם בכסף שקלים","ור\"ע סבר אין היקש למחצה מכלל דרבנן סברי יש היקש למחצה והא קיימא לן דאין היקש למחצה","דכולי עלמא אין היקש למחצה והכא ה\"ט דרבנן דגמירי מצות מצות אפקיה מהקישא","ור\"ע אשם בכסף שקלים נפקא ליה (ויקרא ז, א) מזאת תורת האשם תורה אחת לכל האשמות לאשם דבכסף שקלים","ורבנן אע\"ג דכתיב זאת תורת האשם איצטריך למכתב ואם נפש וי\"ו מוסיף על ענין ראשון וילמד תחתון מעליון","ואי מזאת תורת האשם הוה אמינא כי אמינא תורה אחת לכל אשמות הני מילי בשאר אשמות ודאין","אבל אשם תלוי כיון דעל ספק חלב קאתי אימא לא יהא ספיקו חמור מודאו מה ודאו חטאת בת דנקא אף ספיקו אשם בר דנקא אהכי כתב רחמנא ואם נפש וי\"ו מוסיף על ענין ראשון","הא ניחא למאן דדריש זאת תורת האשם אלא למאן דלא דריש זאת תורת האשם מאי איכא למימר יליף בערכך בערכך מאשם מעילה","אשם שפחה חרופה לא כתב בה בערכך ילפינן באיל איל:","מודה ר\"ע כו': ואם ספק","מאי קאמר אמר רבא תני אם בספיקו עומד לעולם יהא אשם תלוי שממין שהביא על הודע מביאו על שלא הודע","סוף סוף כי מתידע ליה בעי לאיתויי אשם ודאי","אמר רבא מדברי שניהם נלמד אשם ודאי לא בעי ידיעה לכתחלה:","\u0001מתני׳\u0002 האשה שהביאה חטאת העוף עד שלא נמלקה נודע לה שילדה ודאי תעשינה ודאי שממין שהיא מביאה על הודע מביאה על לא הודע","חתיכה של חולין וחתיכה של הקדש אכל אחת מהן ואין יודע איזה מהן אכל פטור ר\"ע מחייב אשם תלוי אכל את השניה מביא אשם ודאי","אכל אחד את הראשונה ובא אחר ואכל את השניה זה מביא אשם תלוי וזה מביא אשם תלוי דברי ר\"ע ר\"ש אומר שניהן מביאין אשם אחד ר' יוסי אומר"],[[0,"גמ' ואם נפש אדם","באשם תלוי כתיב ולעיל מיניה באשם מעילות קמיירי בויקרא:"],[0,"לחייב על ספק מעילות אשם תלוי","קס\"ד מדכתבינהו גבי הדדי:"],[1,"עליון","מעילות:"],[1,"מתחתון","אשת תלוי:"],[2,"אם כן","דלרבנן אין למדין לא אשכחן צפון בבן בקר דחטאת ועולה יהו טעונין שחיטה בצפון דצפון כתיב בבן צאן בויקרא ובמסכת זבחים (דף מא.) יליף בן בקר בהאי דינא בעליון מתחתון:"],[3,"","באשם תלוי כתיב מצות ובחטאת כתיב מצות:"],[5,"במיתה","בידי שמים:"],[6,"חטאת חלב","היינו סתם חטאת ולהכי נקט חלב משום דסמוכה לחלב דכתיב בויקרא כל חלב וכל דם לא תאכלו וסמיך ליה נפש כי תחטא וגו':"],[7,"לאפוקי עולה ויורד","כגון שמיעת קול וביטוי שפתים וטומאת מקדש וקדשיו דלא מייתי על ספיקו אשם תלוי:"],[9,"","\u0003גליון \u0004 ה\"ג אלא הכא היינו טעמא דר' עקיבא דכתיב ואם נפש:"],[9,"לימא בהא קא מיפלגי","דמר סבר הקישא עדיף ומר סבר ג\"ש עדיף:"],[9,"לא דכולי עלמא הקישא עדיף","שהרי אין משיבין על ההיקש ואמרי לך רבנן היינו היקש דתחתון למד מעליון לכסף שקלים:"],[9,"ור' עקיבא סבר אשם לכסף שקלים נפקא ליה מזאת תורת","אלא היקש להכי אתא ללמוד עליון מתחתון. והכי פירש רחמנא והוא הוא שבקונטרס אלא ע\"כ מבואר היטב. \u0003עכה\"ג\u0004:"],[9,"וי\"ו מוסיף על ענין ראשון כו'","הילכך אתא היקש ואפקיה מגזירה שוה להא מילתא ועל כרחין גזרה שוה זו למחצה:"],[10,"","בעליון כתיב כסף שקלים והקישא לתחתון מעליון הוא דאתא ולא למילף עליון מתחתון (לשווייה גזרה שוה למחצה):"],[11,"","\u0003ורבי עקיבא אין היקש למחצה \u0004לא גרסינן לה דלאו היינו היקש למחצה ובשחיטת קדשים בפרק איזהו מקומן (זבחים דף מח.) איתא לכולה הא שמעתא ולא גרסינן להא אלא הכי גרסינן \u0003ורבי עקיבא אשם בכסף שקלים מנא ליה כו'\u0004 - הילכך על כרחיך הקישא לאפוקי מגזירה שוה אתא למיהוי גזירה שוה למחצה דאי לאו להכי אתא היקישא למאי תדרוש ליה:"],[17,"הניחא למאן דדריש תורת","בשמעתא קמייתא דמנחות (דף ג:) וזאת תורת המנחה תורה אחת לכל המנחות:"],[17,"הניחא למאן דדריש","מצי ר\"ע למימר הכי לא איצטריך היקישא לאשם בכסף שקלים ומהכא נפקא וכי איצטריך היקישא לספק מעילות לאשם תלוי:"],[17,"בערכך בערכך","אשם תלוי מאשם מעילות:"],[18,"אשם שפחה חרופה יליף מאיל איל","אשם נזיר דכתיב בספרים שבוש הוא דהא באשם נזיר (במדבר ו) כבש בן שנתו כתיב ואמרינן בפרק ד' מחוסרי כפרה (לעיל כריתות י:) מדאיל בן שתי שנים בשני סלעים כבש בן שנתו בסלע:"],[20,"מאי קאמר ואם ספק","הא פשיטא דספק הוא לו:"],[21,"סוף סוף","כי הביא במעילה מועטת מעילתו ואשמו בתנאי אכתי לא נפיק מידי שני אשמות דכי מתידע ליה דודאי מעל בעי איתויי אשם ודאי דקא סלקא דעתין אשם דומיא דחטאת וחטאת שהביא על ספיקה אשם תלוי כי מתידע ליה ודאי בעי איתויי חטאת:"],[22,"מדברי שניהם","דר' עקיבא ור' טרפון דמודו במעילה מועטת:"],[22,"לא בעי ידיעה בתחלה","הילכך כי אתייה מספק על תנאי עולה לו לאשם ודאי כי מתיידע ליה:"],[23,"מתני' חטאת העוף","ספק ילדה מין פטור או מין חיוב מביאה קינה העולה מביאה ומתנה אם מין חיוב הוא זו עולתה ואם לאו תהא נדבה אבל חטאת מביאה מספק ואינה נאכלת:"],[23,"תיעשה ודאי","ויאכל לכהנים:"],[24,"ר' עקיבא מחייב","ר' עקיבא לטעמיה דמחייב אשם תלוי בספק מעילות:"],[25,"שניהן מביאין אשם אחד","בשותפות ויאמר זה לזה אם אכלת חתיכה של קדש יהא חלקי מחול ויהא אשם כולו עליך:"]],[[23,"אם עד שלא נמלקה הודע כו' ועושה ודאי","פירוש ותאכל כשאר חטאת ואם תאמר מאי איריא שנודע לה קודם שנמלקה אפילו לאחר שנמלקה נמי תאכל לכהנים דאי משום דלא הויא ידיעה בשעת מליקה הא אמרינן בפרק קמא דמכילתין (דף ז.) מודה ר' יוסי במחוסר כפרה דכיון דאינו מביא רק לאישתרויי בקדשים דלא בעי ידיעה בתחלה ואי טעמא הוי גזירה שמא יאמרו חטאת העוף הבא על הספק נאכלת הניחא לר' יוחנן דאמר לקמן בפרק המביא (כריתות דף כו:) דאם משנמלקה נודע לו שילדה ודאי אסור גזירה כו' אלא לרב דאמר לקמן דאפילו נודע לו משנמלקה כיון שנודע לו קודם הזאה מותר באכילה אם כן אמאי לא נקט משנמלקה ויש לומר דהוא הדין לאחר מליקה ולא אתא לאפוקי רק אחר הזאה דאז ודאי אתו למימר חטאת העוף הבא על הספק נאכלת:"]]],[["אין שנים מביאין אשם אחד","חתיכת חלב וחתיכת חולין אכל אחת מהן ואינו יודע איזה מהן אכל מביא אשם תלוי אכל את השניה מביא חטאת אכל אחד את הראשונה ובא אחר ואכל את השניה זה מביא אשם תלוי וזה מביא אשם תלוי דברי ר\"ע ר\"ש אומר שניהם מביאין חטאת אחת רבי יוסי אומר אין שנים מביאין חטאת אחת","חתיכת חלב וחתיכת קודש אכל אחת מהן ואינו יודע איזה מהן אכל מביא אשם תלוי אכל את השניה מביא חטאת ואשם ודאי אכל אחד את הראשונה ובא אחר ואכל את השניה זה מביא אשם תלוי וזה מביא אשם תלוי רבי שמעון אומר שניהן מביאין חטאת ואשם ר' יוסי אומר אין שנים מביאין חטאת ואשם אחד","חתיכת חלב וחתיכת חלב קודש אכל אחת מהן ואין יודע איזו מהן אכל מביא חטאת רבי עקיבא אומר אף אשם תלוי אכל את השניה מביא שני חטאות ואשם ודאי","אכל אחד את הראשונה ובא אחר ואכל את השניה זה מביא חטאת וזה מביא חטאת רבי עקיבא אומר זה וזה מביאין אשם תלוי ר' שמעון אומר זה מביא חטאת וזה מביא חטאת ושניהן מביאין אשם אחד רבי יוסי אומר אין שניהן מביאין אשם אחד","חתיכת חלב וחתיכת חלב נותר אכל אחת מהן ואין יודע איזה מהן אכל מביא חטאת ואשם תלוי אכל את השניה מביא ג' חטאות","אכל אחד את הראשונה ובא אחר ואכל את השניה זה מביא חטאת ואשם תלוי וזה מביא חטאת ואשם תלוי ר\"ש אומר זה מביא חטאת וזה מביא חטאת ושניהן מביאין חטאת אחת ר' יוסי אומר כל חטאת שהיא באה על חטא אין שנים מביאין אותה:","\u0001גמ׳\u0002 א\"ל רבא לרב נחמן לרבי יוסי חטאת הוא דלא מייתו שניהן הא אשם תלוי מייתו שניהם היינו ת\"ק","וכ\"ת חתיכה משתי חתיכות איכא בינייהו והתניא רבי יוסי אומר זה מביא אשם תלוי וזה מביא אשם תלוי א\"ל הא קמ\"ל דמאן ת\"ק ר' יוסי:","חתיכת חלב וחתיכת קדש [כו'] חתיכת חלב וחתיכת חלב קודש כו' חתיכת חלב וחתיכת חלב נותר כו': א\"ל רבא לרב נחמן וליתי נמי אשם ודאי דנותר דקדש הוא אמר ליה דלית ביה שוה פרוטה","והא מעיקרא דאית ביה שוה פרוטה עסקינן דקתני אשם ודאי אמר ליה ההיא חתיכה דלא נותר היא שויא פרוטה","והא יש אוכל אכילה אחת דקתני ביה נותר וקתני מביא ארבע חטאות ואשם אחד","אמר ליה ההיא בגסה וההיא בדקה ולא קשיא ההיא בימות הגשמים הכא בימות החמה:","אכל אחד את הראשונה כו': אמר ליה רבא לרב נחמן ומי אמר ר\"ש איסור חל איסור","והא תניא רבי שמעון אומר האוכל נבלה ביום הכיפורים פטור","אמר רב ששת בריה דרב אידי כגון דאכל כוליא בחלבה וכוליא בחלבה נמי הא קאי עלה באיסור עולין היכי אתי איסור נותר חייל עלה","וכי תימא סבירא ליה לר\"ש דנותר איסור חמור הוא וחייל על איסור קל דעולין והא נבלה דאיסור קל הוא ויום הכיפורים דאיסור חמור הוא ולא קאתי איסור יום כיפורים דחמור וחייל על נבלה דקל הוא","אלא בקדשים גלי רחמנא דאתי איסור חל על איסור"],[[0,"אין שנים מביאין אשם אחד","דלית ליה תנאי בקרבנות אלא אם כדברי חכמים פטורין ואם כדברי ר' עקיבא כל אחד מביא אשם תלוי:"],[1,"זה מביא אשם תלוי וזה מביא אשם תלוי","דלא בעי חתיכה מב' חתיכות:"],[1,"חטאת אחת","ובתנאי כדפרישית אבל אשם תלוי מייתי כל אחד ואחד משום חתיכת החלב:"],[2,"חתיכת חלב וחתיכת","שומן דקדש אכל כו':"],[2,"מביא אשם תלוי","משום ספק חלב:"],[2,"זה מביא כו'","משום חלב ובהא לא פליג ר' עקיבא לחיוביה שני אשמות תלויין בהן לפי שאין כאן אלא עבירה אחת ספק חלב ספק קדש:"],[2,"חטאת ואשם","בשותפות ויתנו אם אני אכלתי חלב ואתה הקדש יהא חלקי באשם מחול לך וחלקך בחטאת מחול לי:"],[3,"מביא חטאת","דממה נפשך חלב אכל:"],[3,"ר' עקיבא אומר אשם תלוי","על החטאות משום מעילות:"],[5,"חתיכת חלב וחתיכת חלב נותר כו' מביא","שתים אחת משום חלב ואחת משום נותר:"],[6,"כל חטאת שהיא באה על חטא","לאפוקי חטאת העוף של יולדת ששתים מביאות אותה ובתנאי כדאמרינן בפ\"ק (לעיל כריתות ז:) אמר רבי יוסי אימתי שהלכו זה למזרח וזה למערב כו':"],[7,"גמ' ה\"ג היינו ת\"ק וכי תימא חתיכה אחת משתי חתיכות כו'","דר' יוסי ה\"ק אין שנים מביאין חטאת אחת אלא הראשון מביא אשם תלוי והשני פטור דבעינן חתיכה אחת משתי חתיכות:"],[9,"וניתי אשם ודאי","מעילה בהדי אשם וחטאת:"],[10,"והא מעיקרא בדאית בה שוה פרוטה עסקינן דקתני","רישא חתיכה של קדש וחתיכה של חלב כו' אכל את השניה מביא חטאת ואשם:"],[11,"יש שאוכל אכילה אחת","בפרק אמרו לו (לעיל כריתות דף יג:) דקתני נותר וקתני אשם מעילות אלמא איכא נותר שוה פרוטה:"],[12,"בגסה","אכילה גסה שאכל הרבה ואף על גב דאיסור הנאה הוא כשאר כל הקדשים האסורים בהנאה שמועלין בהן דהאי נמי חזי לגבוה שאם עלו לא ירדו:"],[12,"בימות החמה","מסרחת בשר נותר דהא שני ימים או יום ולילה נשתהא ולא שויא אכילה (דקה) פרוטה:"],[13,"איסור חל על איסור","דמיחייב חטאת אנותר דחייל איסור נותר אאיסור חלב:"],[14,"פטור","איום הכיפורים דלא אתי איסור יום הכיפורים וחייל אאיסור נבלה ואפילו נתנבלה היום הוה איסורא בין השמשות דאתמול משום אבר מן החי ולא אתי איסור יום הכיפורים וחייל:"],[15,"כוליא בחלבה","דליכא איסור חל על איסור דאחלב חייב משום חלב ואנותר משום כוליא:"],[15,"דאיסור עולין","דלגבוה סלקא:"]],[[13,"ומי אית ליה לרבי שמעון וכו'","ואם תאמר מאי פריך דוקא גבי יום הכיפורים לא חל על איסור נבלה אבל איסור נותר חל שפיר על איסור חלב שהרי איסור נבלה ואיסור טרפה חל על איסור חלב כדאיתא פרק השוחט (חולין דף לז.) כל שכן איסור נותר דחמיר טפי מנבלה ונמצא דחל על איסור חלב ויש לומר דסבירא ליה כיון דחזינן גבי יום הכיפורים דאיסור חמור לא חל על איסור קל הוא הדין גבי נותר דאינו חמור לא יחול על איסור חלב אף על גב דהותר מכללו ואם תאמר מאי פריך דלמא שאני גבי יום הכיפורים מש\"ה לא חל על איסור נבלה משום דאינו רק איסור כולל אבל הכא גבי נותר הוי איסור מוסיף ונימא אף על גב דלית ליה לרבי שמעון איסור כולל איסור מוסיף מיהא אית ליה והכי אשכחן לרבי יוסי נמי דלית ליה איסור כולל ואיסור מוסיף אית ליה כדאמרינן לעיל (כריתות דף יד:) וכן פרק י' יוחסין (קדושין עז: ושם) דקאמר כהן גדול הבא על אחותו אלמנה אין איסור אלמנה חל על איסור אחותו וקאמר רב ששת הא מני ר\"ש היא דאמר אין איסור חל על איסור דתניא האוכל נבלה ביום הכיפורים פטור ומאי מייתי דלמא שאני גבי יום הכיפורים דאיסור כולל הוא אבל באיסור מוסיף מודה ר\"ש כמו רבי יוסי דלית ליה איסור כולל כההיא דחמותו ונעשית אשת איש כו' ואומר מודה ר' יוסי באיסור מוסיף ויש לומר דהש\"ס ידע דרבי שמעון לית ליה אף איסור מוסיף דתניא פרק ארבעה אחין (יבמות לב.) הבא על אשת אחיו שהיא אחות אשתו אינו חייב אלא אחת בין נשא מת ואחר כך נשא חי בין נשא חי ואחר כך נשא מת ואם תאמר אם כן הכא ובההיא דקידושין (דף עז:) אמאי לא הביא אותה הש\"ס ויש לומר דהכא (מביא דהתם והכא) איסור חמור על איסור קל הוא ואי משום דהכא איסור מוסיף גבי נותר וגבי יום הכיפורים איסור כולל הכי מייתי כיון דאשכחנא לר' שמעון דלית ליה איסור כולל בין באיסור קל ובין באיסור חמור א\"כ בעלמא נמי אשכחנא דלית ליה איסור מוסיף [א\"כ] אפילו באיסור חמור על איסור קל נמי לית ליה ואם כן אמאי חייל איסור נותר על איסור חלב רק שהותר מכללו וכן נמי פרק עשרה יוחסין (שם) איצטריך ליה לאוכוחי דאין איסור חמור חל על איסור קל דלאיכא דאמרי תני התם ואגב הכי אייתי ליה נמי ללשון ראשון דהתם:"]]],[["דתניא (ויקרא ז, כ) אשר לה' לרבות את האימורין","ואימורין קאי עלייהו באיסור עולין וחלב קאי עלייהו באיסור כרת וקאתי איסור טומאה חייל עליה","תדע שכן הוא דהא רבי סבירא ליה איסור חל על איסור (ואימא) וה\"מ איסור חמור על איסור קל אבל איסור קל חל על איסור והוא איסור חמור לא ובקדשים שמעינן ליה דאמר איסור קל על איסור חמור נמי חייל","דהא איסור מעילה קל הוא מיתה ואיסור קדשים איסור חמור כרת ואתי איסור מיתה חייל על איסור כרת","דתניא רבי אומר (ויקרא ג, טז) כל חלב לה' לרבות אימורי קדשים קלים למעילה","ומעילה איסור מיתה וקא חייל על איסור חלב דאיסור כרת הוא ש\"מ בקדשים גלי קרא","והא תניא ר\"ש אומר אין פיגול בעולין ואין נותר בעולין","אלא תנאי היא ואליבא דר\"ש דאיכא דאמרי בקדשים איסור חל על איסור וא\"ד בקדשים נמי אין איסור חל על איסור","ולמ\"ד בקדשים נמי אין איסור חל על איסור כל חלב לה' מאי עביד ליה","מוקים ליה בולדי קדשים דקסברי ולדי קדשים בהוייתן יהו קדושים דתרוייהו בהדדי אתו:","\u0001הדרן עלך דם שחיטה\u0002","מתני׳ \u0001המביא\u0002 אשם תלוי ונודע לו שלא חטא אם עד שלא נשחט יצא וירעה בעדר דברי ר\"מ","וחכמים אומרים ירעה עד שיסתאב וימכר ויפלו דמיו לנדבה ר\"א אומר יקרב שאם אינו בא על חטא זה הרי הוא בא על חטא אחר","אם משנשחט נודע לו ישפך הדם והבשר יצא לבית השריפה נזרק הדם והבשר קיים יאכל ר' יוסי אומר אפילו הדם בכוס יזרק והבשר יאכל","אשם ודאי אינו כן עד שלא נשחט יצא וירעה בעדר משנשחט הרי זה יקבר נזרק הדם הבשר יצא לבית השריפה","שור הנסקל אינו כן עד שלא נסקל יצא וירעה בעדר משנסקל מותר בהנאה","עגלה ערופה אינו כן עד שלא נערפה תצא ותרעה בעדר משנערפה תקבר במקומה שעל ספק באה מתחלה כיפרה ספקה והלכה לה:","\u0001גמ׳\u0002 במאי פליגי ר\"מ סבר כיון דלא צריך ליה לא מקדיש ליה ורבנן סברי מתוך שלבו נוקפו גומר ומקדיש","תנא בין שנודע לו שחטא ובין נודע לו שלא חטא פליגי ר\"מ ורבנן בנודע לו שחטא להודיעך כחו דר\"מ דאע\"ג דידע דחטא כיון דבעידנא דאפרשיה [לא ידע תצא ותרעה בעדר","ובנודע לו שלא חטא להודיעך כחן דרבנן דאע\"ג דלא חטא כיון דבעידנא דאפרשיה לא ידע] לבו נוקפו הוה הלכך גמר ומקדיש","א\"ר ששת מודה ר\"מ לחכמים"],[[0,"ואכל מבשר זבח השלמים אשר לה' לרבות אימורין","שאם אכלן בטומאת הגוף חייב כרת והא אימורין כגון כליות קאי עלייהו באיסור עולין:"],[1,"וחלב","דאימורין קאי עליה בכרת:"],[2,"תדע שכן","דבקדשים איסור חל על איסור לדברי הכל:"],[2,"דהא רבי סבירא ליה","בעלמא איסור חל על איסור והני מילי איסור חמור על הקל אבל קל על החמור לא ובקדשים שמעינן ליה דאפילו קל על החמור. והא דאיסור חמור על הקל לא איתפרש לי היכא:"],[3,"איסור מיתה","קל הוא דאין חייבין על שגגתה חטאת:"],[4,"לרבות אימורי קדשים קלים למעילה","כדכתיב (ויקרא ג׳:ט״ז) כל חלב לה' (הוא) אלמא דחטאה בשגגה מקדשי ה' [שם ה] קרינא בהו:"],[6,"אין פיגול","חל על העולין שהאוכל אימורי פיגול כגון כליות אינו חייב כרת. אלמא אפילו איסור חמור לא חייל אאיסור קל:"],[7,"","תנא דמתני' אליבא דרבי שמעון סבר איסור חל על איסור בקדשים:"],[7,"","והאי תנא דסבר אין פיגול בעולין סבר בקדשים נמי אין איסור חל על איסור:"],[8,"","ולהאי תנא דאין פיגול בעולין האי כל חלב לה' דמשמע דמעילה חיילא אאימורים אלמא איסור קל חל אאיסור חמור בקדשים מאי עביד ליה דבשלמא מאשר לה' לרבות אימורין לאיסור טומאה לא פרכינן דמצי לתרוצי דלאו רבי שמעון היא אלא רבנן דפליגי עליה דר' שמעון דאית להו בחולין איסור חל על איסור על ידי כולל כגון נבלה ביוה\"כ וטומאת הגוף נמי איסור כולל הוא מגו דמתסר בבשר אתסר נמי בחלב אלא האי קרא דמעילה דאמר דאיסור קל חל על איסור החמור קשיא לן דהא לא אשכחן ליה בחולין אלמא דשני לן בין חולין לקדשים:"],[9,"מוקי ליה","באימורי ולדות קדשים:"],[9,"דקסבר ולדות קדשים בהוייתן הן קדושין","והויה לישנא דקרא דאיתרבי מיניה ולדות קדשים דגרסינן בבכורות בפרק ב' (דף יד:) רק קדשיך אלו התמורות אשר יהיה לך אלו הוולדות וההיא דרשא דגבי טומאת הגוף דלעיל אשר לה' לרבות האימורים לית ליה ומוקי ליה לדרשא אחרינא בת\"כ לרבות את הלן ואת היוצא:"],[11,"מתני' המביא אשם יצא וירעה בעדר","עם שאר צאנו כחולין גמורין:"],[12,"וחכ\"א כו'","מפרש טעמא בגמ':"],[13,"ישפך","לאמה:"],[13,"לבית השריפה","דאף על גב דחולין שנשחטו בעזרה בקבורה בעלמא האי בשריפה דהוי כזבח פסול:"],[13,"נזרק הדם","קודם שנודע לו:"],[13,"יאכל","הבשר שהרי גמר כל הכפרה והוה ליה אשם תלוי כשר שהרי על הספק בא מתחלה וכפר הספק והלך:"],[13,"יזרק","הדם שכל העומד ליזרק כזרוק דמי וה\"ל כנודע לו לאחר זריקת דם:"],[14,"אינו כן","בההוא לא פליגי רבנן דאם נודע לו עד שלא נשחט יצא וירעה בעדר דטעמייהו דרבנן באשם תלוי כיון דלבו נוקפו גמר ומקדישו מספק אבל אשם ודאי דאמרו לו אכלת קדש ונודע שלא חטא דהוזמו העדים אי נמי כסבור קדש אכל ונמצא חולין איגלאי מילתא דהקדש טעות הוא דכי אקדשיה אדעתא דחטאת אקדשיה:"],[14,"הרי זה יקבר","בגמרא מפרש מ\"ש דהאי בשריפה והאי בקבורה:"],[14,"נזרק הדם הבשר יצא לבית השריפה","מפרש בגמרא תברא מי ששנה זו לא שנה זו:"],[15,"שור הנסקל אינו כן","כאשם תלוי דהכא לא פליגי רבנן כי אם נודע דלא הרג יצא וירעה בעדר:"],[16,"עגלה ערופה אינו כן","כאשם תלוי לרבנן דאם עד שלא נערפה נמצא ההורג תצא ותרעה בעדר:"],[16,"כיפרה ספיקה","בשעת עריפה שהרי עדיין ספק היה והלכה לה הלכך אסורה בהנאה ותקבר כדין כל העגלות הערופות:"],[17,"גמ' שלבו נוקפו","שמתירא מספק החטא שחטא ומייתי אבל חטאת כיון דהשתא איגלאי מילתא דבעידנא דאפרשיה לא הוה צריך לחטאת לאיתויי הילכך אמרינן מספיקא לא אקדשיה:"]],[[0,"אשר לה' לרבות האימורין","והקשה רבינו אלחנן הא איצטריך קרא דאשר לה' למדרש הניתר לטהורים חייבין עליו משום טומאה (מנחות דף כה:) ויש לומר דשקולים ויבאו שניהם בחד קרא [וע\"ע בתוס' מנחות כה: ד\"ה ת\"ל]:"],[9,"בוולדות קדשים וקסבר בהווייתן הן קדושים","דאיסור חלב ואיסור מעילה בהדי הדדי קא אתו ואף על גב דבקדשים קלים ליכא מעילה עד לאחר זריקה כדתנן פ\"ק דמעילה (דף ז:) מכ\"מ איסורא מיהא איכא ואם תאמר הא איסור חלב קדים ממעי אמו דהכי אמר ר' יוחנן פרק בהמה המקשה (חולין עה.) תלש חלב מבן ט' חי חלבו כחלב בהמה דחדשים גרמי ולא אוירא ויש לומר דנהי דלא בעי אוירא דולד שיצא לחוץ אלא מכל מקום בעינן אוירא דחלב שיוצא החלב לחוץ וממעי אמו לא חייל:"],[11,"","מתני' המביא אשם:"],[12,"יפלו דמיו לנדבה","פירוש יביא בדמיו עולה והנסכים משל ציבור דמותרות אשם לקיץ המזבח ולכך יביא עולה:"],[13,"אם משנשחט הדם ישפך","לרבי מאיר אתי שפיר דחולין בעזרה נינהו אלא אפילו לרבנן דאמרי דעבדי מיניה עולת נדבה היינו דוקא לדמיו אבל איהו גופיה מודו דזבח פסול הוא א\"נ כיון דבשעת שחיטה לא היה ראוי לעולה שעדיין לא נודע לו לכך לא יקריבהו עולה אחר שחיטה:"]]],[["במפריש שני אשמות לאחריות ונתכפר באחת מהן דשני ירעה עד שיסתאב וימכר ויפלו דמיו לנדבה","מאי טעמא ע\"כ לא פליגי ר\"מ עליהון דרבנן אלא משום דלא גלי דעתיה דלבו נוקפו אבל הכא מכדי חד הוא דאיבעי ליה לאפרושי מ\"ט אפריש תרי דסבר אי מירכס חדא מיכפרנא באידך חבריה וכיון דגלי דעתיה דלבו נוקפו היה הואיל וכך היה גמר והקדישו","אמר רב יהודה אמר רב מודים חכמים לר\"מ באשם תלוי שהוזמו עדיו דיצא וירעה בעדר","מ\"ט עד כאן לא פליגי רבנן עליה אלא היכא דאפרשיה ע\"פ עצמו ואמרינן לבו נוקפו אבל היכא דע\"פ עדים אפרשיה לא הוה סמוך עילוי דעדים דסבר דלמא אתו אחרים ומזמי להו","מתיב רבא שור הנסקל אינו כן אם עד שלא נסקל יצא וירעה בעדר ה\"ד אילימא דאתו בי תרי אמרי הרג ובי תרי אמרי לא הרג מאי חזית דציית לבתראי ציית להו לקמאי","אלא לאו בעדי הזמה ודכוותיה גבי אשם תלוי בעדי הזמה ופליגי","א\"ל אביי ודלמא שור הנסקל ה\"ד כגון שבא הרוג ברגליו","ודכוותיה גבי אשם תלוי כגון דהוכרה חתיכה אבל היכא דאפרשיה לאשם תלוי ע\"פ עדים לא","בפלוגתא אשם תלוי שהוזמו עדיו רבי אלעזר אומר הרי היא כמנחת קנאות דתניא נמצאו עדיה זוממין מנחתה תצא לחולין","רבי יוחנן אמר ירעה עד שיסתאב וימכר ויפלו דמיו לנדבה ורבי יוחנן נדמייה למנחת קנאות לא דמי מנחת קנאות לא לכפרה קאתייא אלא לברר עון אבל אשם תלוי דלכפרה אתי מתוך שלבו נוקפו גומר ומקדישו","אמר רבי כרוספדאי אמר ר' יוחנן שור הנסקל שהוזמו עדיו כל המחזיק בו זכה בו","אמר רבא מסתברא טעמא דרבי יוחנן כגון דאמרי ליה נרבע שורו אבל אמרו רבע שורו הוא בעצמו מידע ידיע דלא רבע ולא מפקר ליה וטרח ומייתי עדים","ומאי שנא מהא דאמר רבה בר איתי אמר ר\"ל עיר הנדחת שהוזמו עדיה כל המחזיק בה זכה בה","עיר הנדחת דרבים נינהו כל חד אמר בדעתיה אנא לא חטאי אחרינא חטא ומפקר ממוניה אבל הכא דבדידיה תליא מילתא הוא בעצמו מידע ידע דלא רבע ולא מפקר ליה וטרח ומייתי עדים","אמר ר\"ל הנותן מתנה לחבירו ואמר הלה אי אפשי בה כל המחזיק בה זכה בה","ומ\"ש מהא דאמר רבה בר אבוה אמר רב ששת ואמרי לה א\"ר אבהו אמר רב ששת מקבל מתנה שאמר לאחר שבאת מתנה לידו מתנה זו תיבטל מבוטלת אי אפשי בה דבריו קיימין בטילה אינה מתנה לא אמר כלום"],[[0,"לאחריות","שאם יאבד האחד יקריב לחבירו:"],[1,"מכדי חד ה\"ל לאפרושי","כלומר דהא ידעינן דגלי דעתיה דלבו נוקפו דלא ה\"ל לאפרושי אלא חד והוא הפריש תרי:"],[2,"באשם תלוי שהוזמו עדיו","שאמרו לו שנים אכלת ספק חלב בשוגג והפריש אשם תלוי על פיהם ובאו עדים אחרים והזימום ואמרו הלא אותו היום עמנו הייתם לא סמך אעדים דהא יודע בעצמו שלא אכל וסבר מייתינא סהדי ומזמי להו ויצא אשמו לחולין:"],[5,"אלא לאו בעדי הזמה","בשור הנסקל דמודים חכמים לר' מאיר דאינו באשם תלוי משום דליכא למימר לבו נוקפו הילכך יצא וירעה בעדר:"],[5,"ודכוותיה","הא דפליג באשם תלוי בעדי הזמה פליגי דאף על גב דהוזמו עדים אמרי רבנן דקדוש הוא דלבו נוקפו:"],[6,"דלמא שור הנסקל","דנודע שלא הרג והיכי דמי כגון שבא הרוג אותו האיש שאמרו עליו ששור זה הרגו בא לפנינו ברגליו בריא ושלם בהא מודו רבנן דיצא השור וירעה בעדר:"],[7,"ודכוותיה פליגי באשם דהוכרה חתיכה","הנותרת ונמצא שהיא חלב ואותה שאכל היתה שומן בההיא פליגי רבנן ואמרי דקדוש הוא דאמרי' מתוך שלבו נוקפו גמר ומקדישו:"],[7,"אבל","גבי עדים דאיכא למימר לא נקפו לבו דסבר מייתינא סהדי ומזמי להו בההיא לא פליגי רבנן:"],[8,"בפלוגתא","כי היכי דפליגי רבא ורב יהודה לעיל דאמר מודין חכמים באשם תלוי שהוזמו עדיו ופליג עליה רבא ואותביה שור הנסקל ה\"נ פליגי רבי יוחנן ור\"ל:"],[8,"מנחת קנאות","מנחת סוטה:"],[8,"נמצאו עדיה זוממין","אותן שאמרו שנסתרה עם האיש:"],[9,"לברר עון","אם אמת אם שקר:"],[10,"והוזמו עדיו","לאחר שנגמר דינו ליסקל:"],[10,"זכה בו","דהפקר הוא משנגמר דינו:"],[11,"נרבע שורו","וגמרו דינו בסקילה על פיהם דודאי מסתמא אפקריה מיניה דסבר עדי אמת הן הילכך הפקר הוא:"],[11,"וטרח ואייתי עדים","להזימם:"],[12,"עיר הנדחת כו'","ואף על גב דכל חד וחד ידע שלא חטא ואיכא למימר ממוניה הוא ולא אפקריה ותיובתא דרבא:"],[13,"אחריני חטאו","ואמרי' בחלק (סנהדרין דף קיא:) צדיקים שבעיר הנדחת יוצאין ממנה ערומין וממונם אבד:"],[14,"ואמר הלה","מקבל:"],[15,"מקבל מתנה","שטר מתנת קרקע שאמר המקבל לאחר שבא שטר המתנה לידו:"],[15,"ה\"ג תבטל מבוטלת אי אפשי בה לא אמר כלום בטלה היא אינה מתנה דבריו קיימין ה\"ג לה בהשולח גט","וטעמא מפרש התם משום דתבטל מבוטלת אי אפשי בה להבא משמע והוא כבר קבלה לפיכך לא אמר כלום ואם יש עליו בעל חוב גובה אותה הימנו. ומהא ליכא לאותוביה לר\"ל דכי אמר ר\"ל במתנת מטלטלין דכיון דאתי לידיה והפקירה הויא הפקר אבל זה לא הפקיר את השדה אלא אינו חפץ שתהא המתנה קיימת. אלא סיפא תמיה לן אדר\"ל דקתני בטילה היא אינה מתנה דבריו קיימין דלשעבר משמע והכי קאמר כשקבלתיה לאו לשם מתנה קיבלתיה והודאת בעל דין כמאה עדים לפיכך דבריו קיימין:"]],[[0,"במפריש שני אשמות לאחריות","אית ספרים דגרסי ונתכפר באחד מהן ואינו צריך דאפילו שניהם עדיין חיים אם נודע לו שלא חטא או חטא ירעו עד שיסתאבו:"],[4,"אם עד שלא נסקל יצא וירעה בעדר כו' מאי חזית וכו'","ואם תאמר מאי פריך הא אמרינן סנהדרין (דף טו.) כמיתת בעלים כך מיתת השור וכיון דאין הבעלים נהרגים בעדות מוכחשת השור לא יהרג ואי לאוסרו בהנאה בלא עדות אחרונים נמי אינו אסור בהנאה לפירוש ר\"ת שמפרש בעלמא קדושין (דף נז:) דשור הנסקל אינו אסור מחיים בהנאה עד לאחר שיגמר דינו שישחט ויש לומר דמייתי ליה משום סיפא דקתני משנסקל מותר בהנאה אמאי ציית לקמאי לאוסרו בהנאה אלא לאו בעדי הזמה כו' אבל לא מצי למיפרך מפשטיה דמתניתין דתני ובשור הנסקל אינו כן דהיינו על פי עדים ודכוותה באשם תלוי על פי עדים וקשה לרב יהודה איכא למימר דמתני' מיירי בעדי הכחשה כלומר שהוכחשו העדים שמביא על פיהם אשם דבההיא לא סמיך אעדים שיבאו אחרי הראשונים להכחישן אבל רב יהודה מיירי שהוזמו העדים ואעדים סמיך בהזמה ולכך צריך להש\"ס למידק כדדייק ה\"ד אילימא דאתו בי תרי ואמרי הרג כו'. מ\"ר:"],[11,"דאמרו לו נרבע שורו","מכאן קשה לפירוש רבינו אפרים שהיה אומר רובע ונרבע אינו אסור בהנאה דלא גמרינן ליה משור הנסקל ומנין ליה שהרי צריך קרא גבי רובע ונרבע בכ\"ג ולא גמרינן ליה משור הנסקל והכא משמע דאסור בהנאה מדקאמר כל המחזיק בו זכה בו ויש ליישב דודאי מותר בהנאה והא דקאמר הכא כל המחזיק בו זכה בו דמשמע דאפקריה משום שהוא אסור בהנאה לאו הכי פירושו אלא זכה בו בדמי השור במה ששוה בחייו יותר מאחר מיתה דלא אפקריה רק שיעשה לו מיתת בית דין אבל לא מדמי הנבלה אבל קשה מההיא דשילהי האיש מקדש (קדושין נז.) קאמר הש\"ס לא מצינו בעלי חיים נאסרים ופריך והרי רובע ונרבע דמחיים ועוד דבתוספתא [דב\"ק פ\"ד] איכא בהדיא נרבע אסור בהנאה:"]]],[["מאי לאו דבריו קיימין דהדרא למרה לא דבריו קיימין והוא נמי לא קני לה וכל המחזיק בה זכה בה","מיתיבי האומר לחבירו דין ודברים אין לי על שדה זו אין לי עסק בה וידי מסולקת הימנה לא אמר כלום והא ידי מסולקת הימנה כאי אפשי דמי וקתני לא אמר כלום","שאני התם דאמר כי סליק נפשיה מדין ודברים מגופה דשדה לא סליק נפשיה","מיתיבי הכותב נכסיו לאחרים והיו בהן עבדים ואמר הלה אי אפשי בהן אם היה רבו שני כהן אוכלין בתרומה רשב\"ג אומר כיון שאמר אי אפשי בהן כבר זכו בהן יורשין","בשלמא לרשב\"ג קסבר כי יהיב איניש מתנה אדעתא דמקבלין לה מיניה כי לא מקבלין לה מיניה הדרא למרה","אלא לת\"ק אי כי אמר אי אפשי בהן כל המחזיק בהן זכה בהן הכא דאמר שני אי אפשי בהן הוו להו זרים וקאכלי זרים תרומה קסבר המפקיר עבדו יצא לחירות וצריך גט שחרור מרבו וקסבר מעוכב לגט שחרור אוכל בתרומה:","ר' אליעזר אומר יקרב כו': לר\"א ל\"ל חטא הא א\"ר אליעזר אשם תלוי בנדבה אתי דתנן ר\"א אומר מתנדב אדם אשם תלוי בכל יום","אמר רב אשי ר\"א דאמרו לו הוא דתנן אלא אומרים לו המתן עד שתכנס לבית הספק:","אם משנשחט נודע כו': קתני הבשר יצא לבית השרפה אלמא חולין שנשחטו בעזרה בשריפה","ורמינהי אשם ודאי אינו כן אם עד שלא נשחט יצא וירעה בעדר משנשחט ה\"ז יקבר א\"ר אלעזר תברא מי ששנה זו לא שנה זו","אמר רבה אשם ודאי על אשם תלוי קרמית אשם ודאי כיון דלא צריך ליה לא מקדיש ליה אשם תלוי מתוך שלבו נוקפו גומר ומקדשו","אלא אי קשיא אשם ודאי על אשם ודאי קשיא דקתני ה\"ז יקבר אימא סיפא והבשר יצא לבית השריפה הא ודאי תברא מי ששנה זו לא שנה זו","רב אשי אמר רישא דקתני באשם תלוי והבשר יצא לבית השריפה לא קשיא משום דמיתחזי כזבח פסול:","נזרק הדם הבשר יאכל: ואמאי הא הויא ליה ידיעה אמר רבא אמר קרא (ויקרא ה, יח) והוא לא ידע ונסלח לו והא לא הויא ליה ידיעה בשעת סליחה:","רבי יוסי אומר אפילו הדם בכוס כו': לר' יוסי אמאי יזרק הא הויא ליה ידיעה בשעת סליחה אמר רבא ר' יוסי סבר לה כר\"ש דאמר כל העומד ליזרק כזרוק דמי","אימר דאמר ר\"ש במידי דעומד ליזרק אבל האי אין עומד ליזרק אמרי במערבא קסבר ר' יוסי כלי שרת מקדשין בו את הפסול בתחלה ליקרב:","אשם ודאי אינו כן כו': איתמר עגלה ערופה אימתי נאסרת רב המנונא אמר מחיים רבא אמר לאחר עריפה","בשלמא לרבא מעידנא דאיתעביד בה מעשה אלא לרב המנונא מאימתי"],[[0,"מאי לאו דבריו קיימין והדרא למרה","אלמא היכא דאהני דבריו הדרא למרה:"],[0,"לא דבריו קיימין ולא קני לה ולמרה נמי לא הדרא כו'","והוא הדין דהוה נמי מצי לתרוצי לא דמי לדר\"ל דהכא דכיון דאמר לא לשם מתנה קיבלתיה הויא למרה דכי יהיב איניש מתנה אדעתיה דמקבלי לה מיניה ואי לא מקבלי לאו מתנה היא אבל דר\"ל לאחר שקבלה בתורת מתנה הפקירה והכי מתרצינן לקמן בשמעתין קשיא אחריתי ומיהו בקשיא קמייתא דחייה כי האי גוונא ולקמן דלא מצי לדחוייה שנייה הכי:"],[1,"האומר לחבירו","שהיה שותף עמו בשדה זו:"],[1,"דין ודברים אין לי על שדה זו לא אמר כלום","ולא אבד זכותו:"],[1,"וקתני לא אמר כלום","דאי אפשי בה לאו לשון הפקר ולא לשון מתנה הוא תיובתא דר\"ל ורב ששת דאמרו דבריו קיימין:"],[2,"מדין ודברים סילק נפשיה","ובהכי עסקינן דאמר כל הלשונות הללו ביחד הילכך אמרינן כולהו מדין ודברים קיימו וה\"ק לא אדין ולא אדבר על שדה זו עם שום אדם כי מוחזקת שלי היא ואין לי עסק בה עם שום אדם בדין ודברים וידי מסולקות הימנה בדין ודברים:"],[3,"הכותב נכסיו","שכיב מרע. בפרק שני דשחיטת חולין (דף לט:) מוקמינן פלוגתא בשזיכה לו שטר מתנה על ידי אחר ושתק ולבסוף צווח רבנן סברי מדאישתיק מינח ניחא ליה וקנאה והשתא הוא דהדר ביה ור\"ש סבר הוכיח סופו על תחלתו שלא נתרצה בתחלה:"],[4,"בשלמא","מדר\"ש לא קשיא לר\"ל דכיון דאית ליה הוכיח סופו על תחלתו לא יצאו מיד הראשון כי יהיב איניש מתנה כו' אבל לר\"ל משקנאה הפקירה:"],[5,"אלא לת\"ק","קשיא לר\"ל כיון דלית ליה הוכיח סופו וקנאו שני אי אמרת אי אפשי לשון הפקר הוא הא כי אמר שני אי אפשי בהן כל המחזיק בהן זכה כדר\"ל וקנו עצמן בני חורין מן ההפקר דהפקר נינהו ואישתכח דאכלי עבדים זרים תרומה אלא לאו מדאכלי בתרומה שמע מינה לא אמר שני כלום דלאו לשון הפקר הוא ותיובתא דר\"ל ודרב ששת דאמרו דבריו קיימים והוי הפקר ויצא לחירות דהא זוכה בעצמו מהפקירא:"],[7,"לבית הספק","דקצת איסורא בעיא אי עשה אי לאו אי כרת:"],[11,"(אלא) אשם ודאי","מסתמא לא אקדשיה אי הוה ידע דלא צריך ליה הילכך הקדש טעות הוא אבל אשם תלוי הא ספק הוא ליה והוה סבור דשמא לא חטא ואפ\"ה אקדשיה הילכך גלי אדעתיה דלבו נוקפו וגמר והקדישו ולא הוי חולין שנשחטו בעזרה אלא כשאר קדשים שאירע בהן פסול ובשרפה כדאמרינן בפסחים בפרק כל שעה (פסחים דף כד.):"],[12,"ה\"ג רב אשי אמר משום דמיחזי כזבח פסול","ואשם ודאי קא מתרץ רב אשי דמיחזי שלאחר זריקה אירע בו פסול ואתי למימר קדשים שנפסלו נקברים:"],[13,"ה\"ל ידיעה","ורחמנא אמר ולא ידע הוא דמביא אשם תלוי הא אי ידע לא:"],[13,"סליחה","זריקה היינו עיקר כפרה דכתיב (ויקרא י״ז:י״א) ואני נתתיו לכם על המזבח וגו':"],[14,"כל העומד ליזרק כזרוק דמי","בב\"ק בפרק מרובה (בבא קמא דף עו:):"],[15,"הא אינו עומד ליזרק","דהא לא חטא וסופו להוודע קודם זריקה ואיגלאי מילתא למפרע דאינו עומד ליזרק:"],[15,"כלי שרת","כגון הכא דנתקבל הדם בכלי שרת:"]],[[8,"אלמא חולין שנשחטו בעזרה בשריפה ורמינהי אשם ודאי אינו כן","פירש ר\"י דלרבנן לא פריך שהרי אשם תלוי אף כי נודע לו קודם שחיטה אינו חולין אלא קדוש לדמיו ואם כן לאחר שחיטה פשיטא דבשריפה הוי ואמאי קרי ליה חולין בעזרה אלא לר' מאיר דוקא פריך דאמר אף אשם תלוי כי נודע לו קודם שחיטה ירעה בעדר עם שאר צאנו דחולין גמורין הוי ואפילו הכי קאמר הבשר יצא לבית השריפה וניחא דקרי ליה חולין בעזרה ולכך פריך שפיר ומשני תברא כו' אמר רבה אידי ואידי לר' מאיר אתי שפיר והא דקאמר גבי ודאי יקבר משום דחולין גמורים הוי שהרי הפרישו על הודאי וכי איגלאי מילתא שטעה חולין הוי אבל אשם תלוי לא הפרישו אלא על הספק ואף על גב דרבי מאיר לית ליה לבו נוקפו וגמר ומקדישו היינו דוקא קודם שחיטה אבל לאחר שחיטה גמר בלבו ומקדישו ולכך בשריפה:"],[12,"רב אשי אמר לא קשיא","רישא משום דמיחזי כזבח פסול דהיכא דנזרק נראה כזבח פסול ולכך ישרף אבל רישא דמשנשחט ולא נזרק עדיין יקבר דכיון דלא נזרק לא נראה כזבח פסול אבל אשם תלוי דבא על הספק גם לפני זריקה ישרף דמיחזי יותר כזבח פסול:"],[15,"קסבר רבי יוסי כלי שרת מקדשין הפסול בתחלה ליקרב","ואם תאמר דבפ' המזבח מקדש (זבחים פז.) בעי ר' שמעון בן לקיש מרבי יוחנן כלי שרת מהו שיקדשו לכתחלה ופשט ליה אין מקדשין ונימא דלא כר' יוסי וי\"ל דבעלמא בשאר פסולין אית ליה אין מקדשין והכא שאני דאין זה פסול כל כך שהיה תחלתו קרבן ובא על נקיפת לב ואינו חולין ועדיין שם אשם עליו ורבנן דאמרי ישפך לא קשיא די\"ל דכי נמי בעלמא מקדשי ה\"מ משום דהוו קדשים אך אירע בהן פסול אבל הכא דנמצא שהיה חולין אין כלי שרת מקדשים קדשים פסולין:"]]],[["א\"ר ינאי גבול שמעתי בה ושכחתי ונסבין חברייא למימר ירידתה לנחל איתן אוסרתה","אמר רב המנונא מנא אמינא לה דתנן השוחט פרת חטאת ושור הנסקל ועגלה ערופה ר\"ש פוטר וחכמים מחייבין","בשלמא לדידי דאמינא מחיים בהא פליגי ר\"ש ורבנן דר\"ש סבר שחיטה שאינה ראויה לא שמה שחיטה","ורבנן אמרי שחיטה שאינה ראויה שמה שחיטה אלא אי אמרת לאחר עריפה אמאי פטר ר\"ש שחיטה ראויה היא","וכי תימא סבר ר\"ש עגלה בשחיטה כשרה והתנן כשר בפרה פסול בעגלה ערופה פסול בפרה כשר בעגלה ערופה פרה בשחיטה כשרה בעריפה פסולה עגלה בעריפה כשרה בשחיטה פסולה","אישתיק לבתר דנפק אמר מאי טעמא לא אמינא ליה דר\"ש סבר עגלה בשחיטה כשירה","ורב המנונא אמר לך לא נשתמיט תנא דנשמעינן עגלה בשחיטה כשרה דתימא ר\"ש היא","אמר רבא מנא אמינא לה מדתנן עגלה ערופה אינה כן עד שלא נערפה תצא ותרעה בעדר ואי אמרת מחיים אמאי תצא ותרעה בעדר הא איתסרא לה מחיים","תני עד שלא נראית לעריפה אימא סיפא משנערפה תקבר במקומה תני משנראית לעריפה","אם כן אימא סיפא שעל הספק באה מתחלה כיפרה ספיקה והלכה לה ואי מחיים עדיין לא כיפרה ספיקתה","תנאי היא דתניא נאמר מכשיר ומכפר בפנים ונאמר מכשיר ומכפר בחוץ","מה מכשיר ומכפר האמור בפנים עשה בו מכשיר כמכפר אף מכשיר [ומכפר] האמור בחוץ עשה מכשיר כמכפר:","\u0001מתני׳\u0002 ר\"א אומר מתנדב אדם אשם תלוי בכל יום ובכל עת שירצה הוא היה נקרא אשם חסידים אמרו עליו על בבא בן בוטא שהיה מתנדב אשם תלוי בכל יום חוץ מאחר יום כיפורים יום אחד","אמר המעון הזה אילו היו מניחין לי הייתי מביא אלא אומרים לי המתין עד שתכנס הספק וחכ\"א אין מביא אשם תלוי אלא על שזדונו כרת ושגגתו חטאת","חייבי חטאות ואשמות ודאין שעבר עליהן יום הכיפורים חייבין להביא לאחר יום הכיפורים וחייבי אשמות תלויין פטורין מי שבא בידו ספק עבירה ביוה\"כ אפילו עם חשיכה פטור שכל היום מכפר","האשה שיש עליה חטאת העוף ספק ועבר עליה יוה\"כ חייבת להביא לאחר יום הכיפורים מפני שהיא מכשרת לאכול בזבחים חטאת העוף הבאה על הספק אם משנמלקה נודע תקבר:","\u0001גמ׳\u0002 מ\"ט דר' אליעזר אי ס\"ד חובה היא מתיידע ליה אמאי מייתי חטאת אלא ש\"מ נדבה היא","ורבנן עולה ושלמים הוא דאתו בנדר ונדבה אבל חטאת ואשם חובה נינהו ואשם תלוי היינו טעמא דמייתי מקמי דמתיידע ליה להגן עליו דהתורה חסה על גופן של ישראל","א\"ל רב אחא בריה דרבא לרב אשי דילמא אשם תלוי כעולה ושלמים מה עולה ושלמים דאתו בחובה ואתו בנדבה אשם תלוי נמי דאתי בחובה אתי נמי בנדבה","א\"ל עולה ושלמים עיקר בנדבה כתיבי אשם תלוי עיקר בחובה כתיב","תני רבי חייא קמיה דרבא"],[[0,"גבול שמעתי","מאימתי נאסרת:"],[1,"ר' שמעון פוטר","מאותו ואת בנו:"],[2,"שחיטה שאינה ראויה","באכילה כגון הא דאסירא באכילה דהא מחיים נאסרו כולן:"],[3,"אמאי פטר ר\"ש שחיטה הראויה","לאכילה היא:"],[4,"וכי תימא קסבר ר\"ש עגלה בשחיטה כשרה","לכפרתה והויא לה שחיטה שאינה ראויה לאכילה ומשמע דשחיטה במקום עריפה קיימא:"],[4,"הכשר בפרה","בפרה אדומה:"],[7,"אינה כן","באשם תלוי דבהא לא פליגי רבנן אם עד שלא נערפה תצא ותרעה בעדר:"],[7,"הא איתסרא מחיים","כשירדה לנחל איתן:"],[8,"עד שלא נראית לעריפה","דלא ירדה לנחל איתן:"],[8,"משנערפה תקבר במקומה","נערפה אין לא נערפה לא:"],[10,"תנאי היא","אי אסורה מחיים אי לא דתנא דבי רבי ישמעאל סבר מחיים אסורה:"],[10,"מכשיר בפנים","אשם מצורע:"],[10,"מכפר","חטאות ואשמות:"],[10,"מכשיר בחוץ","צפרי מצורע:"],[10,"מכפר בחוץ","שעיר המשתלח ועגלה ערופה:"],[11,"מה מכשיר האמור בפנים עשה בו מכשיר","אשם מצורע כמכפר כשאר חטאות ואשמות:"],[11,"אף מכשיר ומכפר האמור בחוץ עשה בו מכשיר","צפרי מצורע דאסורין בהנייה מחיים כמכפר בשעיר המשתלח ועגלה ערופה. אלמא סבירא ליה דעגלה ערופה מחיים אסירא דכי היכי דגמר מכשיר ממכפר יליף מכפר ממכפר עגלה משעיר ושעיר ודאי אסור מחיים כשאר קדשים. והכי מפרש במסכת קדושין בשילהי האיש מקדש (קידושין דף נז.):"],[13,"מתני' עד שתכנס לבית הספק","ושאר ימות השנה הוא דאיכא למיחש בספק שמא חטא או שום עון או לאו אבל השתא ליכא למיחש דהא כיפר יום הכפורים:"],[16,"גליון מאי טעמא דרבי אליעזר אי סלקא דעתך חובה כו'","מאי טעמא דרבי אליעזר דאמר אשם תלוי בא בנדבה היינו טעמא דאי ס\"ד חובה הוא בא אם כן כי מתיידע ליה ודאי אמאי מייתי חטאת והלא כבר יצא ידי חובתו אלא ודאי נדבה הוא כדורון עולה ושלמים. \u0003עכה\"ג\u0004:"],[17,"גמ' להגן עליו","מן היסורין עד שיוודע לו:"],[18,"דלמא אשם תלוי","מדקיל כולי האי דאתי על הספק איכא למימר נמי דדינו כעולה ושלמים דאתו בחובה כגון עולת ראייה ושלמי חגיגה ואתו בנדבה אשם תלוי נמי אתי בחובה ובנדבה:"]],[[3,"אמאי פטר ר\"ש שחיטה ראויה היא","הקשה הר\"ר משה לישני דשחט אמה ואח\"כ ערפה דעריפתה זו היא שחיטתה כדאיתא פרק שני שעירי (יומא דף סד.) דחייתו לצוק זו היא שחיטתו ויש לומר דמכל מקום לא היה לו לתנא לקרות ושחטה דהתם אין בברייתא ושחטה רק בעי לאשכוחי ביה מחוסר זמן במשתלח:"],[7,"הא איתסרא לה מחיים","וא\"ת ומה בכך והרי אשם ודאי דנודע עד שלא נשחט יצא וירעה ויש לומר דיש לנו לדמויי עגלה ערופה לאשם תלוי שבאה לכפר הספק שעל ספק באתה מתחלה כיפר ואם כן דמיתסר מחיים גם אחר שנודע באיסור הראשון עומדת:"],[10,"תנאי היא נאמר מכשיר ומכפר בפנים ונאמר מכשיר ומכפר בחוץ כו' אף מכשיר ומכפר בחוץ עשה מכשיר","פירוש צפורי מצורע כמכפר עגלה ערופה קשה ומנלן דמיתסרא מחיים אימא דיליף מעגלה ערופה וצפורי מצורע נאסרים לאחר שחיטה וכן קשיא פרק האיש מקדש (קדושין דף נז. ושם) דמייתי מינה דצפורי מצורע מיתסרי מחיים ובקונט' פירש כאן אלמא סבירא ליה עגלה ערופה אסירא מחיים דכי היכי דגמר מכשיר ממכפר כל שכן דגמר מכפר ממכפר עגלה משעיר המשתלח ושעיר המשתלח ודאי אסור מחיים כשאר קדשים ודוחק ור\"י מפרש דמכשיר בחוץ היינו משולחת ובמקצת ספרים הוא כתיב וה\"פ אף בחוץ עשה מכשיר משולחת דאסור בהנאה כמו עגלה ערופה והדר נילף עגלה ממכשיר כי היכי דאסורה מחיים הכי נמי עגלה והכי נמי שחוטה אסורה מחיים וניחא השתא הך דקדושין ועוד י\"ל (בהך) התם על כרחך הך בנין אב דמכשיר כמכפר לא אתא אלא ללמד על צפורי מצורע דאסירי מחיים דאי לאחר שחיטה ל\"ל מלא תאכלו לרבות השחוטה שמעינן איסור הנאה וא\"ת ולא תאכלו היכי משתמע איסור הנאה והלא הוא כתוב גבי עופות טמאין דמותרין בהנאה וי\"ל דגלי לן קרא דשחוטה מיתסרא סברא הוא שגם המשולחת שתאסר עד השילוח שסברא הוא ששתיהן שוות עד גמר מצוותן ואיסור שבמשולחת היינו איסור הנאה הילכך שחוטה נמי תיאסר בהנאה וכן צ\"ל בסוגיא דהתם:"]]],[["אשם תלוי בא על הנבלה אמר ליה והאנן תנן וחכמים אומרים אינו מביא אשם תלוי אלא על דבר שזדונו כרת ושגגתו חטאת ואי ר' אליעזר בנדבה נמי אתי","אמר ליה מ\"ט לא מתנית זימנין סגיאין תניתה קמי מר ומנו רבה ואמר לי הא מני רבי אליעזר היא דאמרו לו דתנן אלא אומרים לו המתן עד שתכנס לבית הספק","אמר רבא מאי טעמא דאמרו לו אמר קרא (ויקרא ד, ב) אשר לא תעשינה בשגגה ואשם","אמר רבא מ\"ט דרבנן דאמרי אין מביאין אשם תלוי אלא על דבר שזדונו כרת ושגגתו חטאת ילפי מצות מצות מחטאת חלב","מה להלן שזדונו כרת ושגגתו חטאת אף כאן דבר שזדונו כרת ושגגתו חטאת:","תנו רבנן חמשה אשמות מכפרין אשם תלוי אין מכפר כפרה גמורה מאי קאמר אמר רב יוסף ה\"ק חמשה אשמות מכפרין כפרה גמורה ואשם תלוי אין מכפר כפרה גמורה","ודלא כר' אליעזר דאמר אשם תלוי בא על הנבלה","רבינא אמר הכי קתני חמשה אשמות אין אחר מכפר כפרתן דכי מתיידע ליה מייתי אשם תלוי אחר מכפר כפרתו דלכי מתיידע לא מייתי כדתנן חייבי חטאות ואשמות ודאין שעבר עליהן יה\"כ חייבין להביא אחר יה\"כ חייבי אשמות תלויין פטורין:","חייבי חטאות ואשמות ודאין כו': קתני חייבי חטאות ואשמות ודאין שעבר עליהן יוה\"כ חייבין להביא לאחר יה\"כ חייבי אשמות תלויין פטורין מנהני מילי","כי אתא רב דימי א\"ר אמי א\"ר חנינא אמר קרא (ויקרא טז, טז) וכפר על הקודש מטומאת בני ישראל ומפשעיהם לכל חטאתם חטאים דומיא דפשעים מה פשעים דלאו בני קרבן אף חטאים דלאו בני קרבן מכפר אבל חטאים בני קרבן לא מכפר","א\"ל אביי והא כי כתיב הדין קרא בשעיר הנעשה בפנים הוא דכתיב דלא מכפר על עבירות דמצוה ידועה אבל שעיר המשתלח דמכפר על עבירות דמצוה ידועה אימא לך אפילו על חטאים דבני קרבן נינהו מכפר","אלא אמר אביי מהכא (ויקרא טז, כא) והתודה עליו כל עונות בני ישראל ואת כל פשעיהם לכל חטאתם חטאים דומיא דפשעים מה פשעים דלאו בני קרבן אף חטאים דלאו בני קרבן אבל חטאים דבני קרבן נינהו לא מכפר ומיעטיה קרא בשעיר המשתלח למימרא דעל חטאים דבני קרבן נינהו לא מכפר","א\"ל רב דימי ממאי דהני פשעים לאו בני קרבן נינהו דלמא הני דבני קרבן נינהו כדתנן ארבעה מביאין על הזדון כשגגה","איתמר נמי כי אתא רבין אמר ר' יוסי אמר ריש לקיש והתודה עליו את כל עונות בני ישראל ואת כל פשעיהם לכל חטאתם חטאים דומיא דפשעים מה פשעים דלאו בני קרבן מכפר אף חטאים דלאו בני קרבן מכפר אבל חטאים דבני קרבן לא מכפר","אמר אביי אנא נמי מהדין קרא אמרי ואקשי לי רב דימי ממאי דהני פשעים דלאו בני קרבן נינהו דלמא הנך דבני קרבן נינהו כדתנן ארבעה מביאין על הזדון כשגגה אמר ליה רבין רוב פשעים לאו בני קרבן אמר ליה מידי רוב כתיב","אלא אמר אביי מרישיה דקרא והתודה עליו את כל עונות בני ישראל ותניא עונות אלו זדונות וכן הוא אומר (במדבר טו, לא) עונה בה","ואת כל פשעיהם לכל חטאתם כל למה לי לאקשויי לפשעים מה פשעים דלאו בני קרבן אף חטאים דלאו בני קרבן אבל חטאים דבני קרבן נינהו לא מכפר:","חייבי אשמות תלויין כו': מנהני מילי א\"ר אלעזר אמר קרא (ויקרא טז, ל) מכל חטאתיכם לפני ה' וגו' חטא שאין מכיר בו אלא המקום יום הכפורים מכפר","אמר רב תחליפא אבוה דרב הונא בר תחליפא משמיה דרבא קדמייתא נמי לא תיתי"],[[0,"בא על הנבלה","כלומר על ספק איסור לאו:"],[1,"לא מתנית","אינך שונה משנה וברייתא:"],[1,"גליון לא מתנית","למה לא למדת קמיה דרבה והיית יודע כמוני. \u0003עכ\"ה\u0004:"],[1,"לבית הספק","דקצת איסור כל דהו בעינן:"],[2,"מאי טעמא דאמרו לו","אשם תלוי בא על איסור כל דהו כגון לאו דנבלה:"],[2,"דכתיב","באשם תלוי אשר לא תעשינה בשגגה ואשם דאפילו ליכא שגגה אלא במידי דלאו דהיינו שלא תעשינה חייב:"],[5,"חמש אשמות","אשם גזילות ומעילות שפחה חרופה ונזיר ומצורע:"],[5,"אשם תלוי אינו מכפר כפרה גמורה","דלכי מתיידע ליה מייתי חטאת:"],[6,"ודלא כר\"א","דאי כר\"א דאמר בא על ספק נבלה נמצא אשם תלוי דספק נבלה מתכפר כפרה גמורה דלכי מתיידע ליה לאו בר חטאת הוא:"],[7,"אין אחר מכפר כפרתו","שאם מעל בשוגג ולא ידע ועבר עליו יום הכיפורי' ואחר כך נודע לו מביא אשם מעילות וכן כולן:"],[8,"מנהני מילי","דאשמות ודאין לא מכפר יום הכיפורים עלייהו:"],[9,"מה פשעים דלאו בני קרבן","דפשעים היינו מרדין שמורד ברבו וכן הוא אומר מלך מואב פשע בי (מלכים ב ג׳:ז׳):"],[9,"אף חטאים דלאו בני קרבן","כגון נבלה מכפר עלייהו יום הכפורים אבל חטאים דבני קרבן כגון חטאות ואשמות ודאין לא מכפר. וטעמא דמכפר אתלויין מפרש לקמן:"],[10,"דלא בא לכפר על עבירות מצוה ידועה","כדאמר בפרק קמא דשבועות (דף ב.) על טומאה שיש בה ידיעה בתחלה כשנטמא ידע ואין בה ידיעה בסוף כשנכנס לא ידע שהוא טמא וכשיצא לא נודע לו שנכנס בטומאה שיביא קרבן שעיר הנעשה בפנים ויום הכפורים תולה עד שיודע שנכנס למקדש טמא ויביא בעולה ויורד אבל נודע לו שחטא ונכנס למקדש בטומאה אינו מכפר הילכך לא מכפר החטאים דבני קרבן משום דזוטרא כפרתיה אבל שעיר המשתלח דנפישא כפרה דיליה דמכפר על עבירה שנודע לו שחטא כדאמרינן בפרק קמא דשבועות (שם:) על כל עבירות שבתורה הזדונות והשגגות הודע ולא הודע כו' אימא דעל חטאים דבני קרבן נמי מכפר:"],[11,"והתודה עליו","בשעיר המשתלח:"],[11,"ומעטיה קרא בשעיר המשתלח","לאשמועי' דאף על גב דנפישא כפרתו אפילו הכי אבני קרבן לא מכפר:"],[12,"על הזדון כשגגה","בפרק ארבעה מחוסרי כפרה (לעיל כריתות דף ט.):"],[13,"איתמר נמי","כאביי:"],[15,"מן רישא דקרא","כלומר מדרישיה דקרא לגופיה וסיפיה מייתר להך דרשא:"],[15,"עונה בה","והא מזיד הוא דכתיב ברישיה דקרא כי דבר ה' בזה וגו':"],[16,"לאקשויי חטאת כו'","והשתא ליכא למיפרך דרב דימי דאם כן דלבני קרבן קאתי לא לכתוב קרא פשעיהם דהא כתיב עונות ולכתוב חטאתם דמשמע בני קרבן דסתם חטאת בני קרבן אלא מדכתיב פשעיהם מופנה לדרוש דברוב פשעיהם קמיירי:"],[17,"שאין מכיר בו","שלא נודע לו שחטא:"],[18,"קמייתא נמי","דחייבי חטאות ואשמות ודאין כו' דחייבין להביא אחר יום הכיפורים ליכא למיפשט לא מדרב דימי ולא מדאביי דשינויא דחיקא הוא דאכתי איכא למיפרך כדמעיקרא:"]],[[0,"אשם תלוי בא על הנבלה","פירש בקונטרס על ספק איסור לאו. מ\"ט דאמרו לו אשר לא תעשינה בשגגה ואשם. נראה דלא קאמר שיהא חובה להביאו (לרבנן) [לדאמרו לו] על עבירת לאו דהא כתיב ולא ידע אטו על אכילת ספק נבלה לייתי ולא על ודאי אכילת נבילה אלא נראה דלא ידע ליה דקרא לענין חובה ולענין דבר שאם יוודע לו יביא על שגגתו חטאת ואית להו ג\"ש דמצות מצות אבל אהני ליה לא תעשינה דאף על העבירות לאו יכול להביאו ורבנן דדרשי גזירה שוה דמצות לאפוקי לאו דלא מייתי עליה כלל:"],[0,"","צריך עיון שלא מצאתי תוספות יותר"]]],[["למפשטיה לא מדרב דימי ולא מדאביי","אלא מהא חטא שאין מכיר בו אלא המקום יוה\"כ מכפר ומינה חטא שאין מכיר בו אלא המקום הוא דיוה\"כ מכפר אבל דידע בה לא מכפר","ואמר רב תחליפא אבוה דרב הונא משמיה דרבא חייבי מלקיות שעבר עליהן יה\"כ חייב פשיטא מאי שנא מחייבי חטאות ואשמות ודאין","סלקא דעתך אמינא התם ממונא הוא אבל הכא דגופא הוא אימא לא קמ\"ל","והא אנן תנן הודע ולא הודע עשה ולא תעשה","לא קשיא הא דאתרו ביה הא דלא אתרו ביה","אלא מעתה (סימן יולד\"ת מצור\"ע נזי\"ר סוט\"ה בעגל\"ה)","ספק יולדת שעבר עליה יוה\"כ לא תייתי דהא כפר עליה יוה\"כ דחטא שאין מכיר בו אלא המקום הוא אמר רב הושעיא (ויקרא טז, טז) לכל חטאתם ולא לכל טומאתם","ולר' שמעון בן יוחי דאמר יולדת חוטאת היא מאי איכא למימר יולדת כי קא מייתי קרבן לאישתרויי באכילת קדשים הוא ולא לכפרה מתיא","אמר רב אשי אף אנן נמי תנינא האשה שיש עליה חטאת העוף ספק ועבר עליה יוה\"כ חייבת להביא לאחר יוה\"כ מפני שמכשרתה לאכול בזבחים","אלא מעתה ספק מצורע שעבר יוה\"כ לא מייתי דהא עבר עליה יוה\"כ דחטא שאין מכיר בו אלא המקום הוא אמר ר' אושעיא לכל חטאתם ולא לכל טומאתם","והא אמר ר' שמואל בר נחמני אמר ר' יוחנן על ז' דברים נגעים באים (סימן גג\"ג ששל\"ץ) מצורע כי מייתי לאו לכפרה מייתי אלא לאישתרויי באכילת קדשים הוא","אלא מעתה ספק נזיר שעבר עליו יוה\"כ לא מייתי קרבן דהא כפר יוה\"כ דחטא שאין מכיר בו אלא המקום הוא אמר ר' אושעיא לכל חטאת ולא לכל טומאה","ולרבי אלעזר בן הקפר דאמר נזיר חוטא הוא מאי איכא למימר נזיר כי קא מייתי קרבן לאו לכפרה מייתי לאשתרויי באכילת קדשים הוא","אלא מעתה ספק סוטה שעבר עליה יוה\"כ לא תייתי דהא כפר עלה יוה\"כ דחטא שאינו מכיר בו אלא המקום אמר רבי הושעיא לכל חטאתם ולא לכל טומאתם","אמר אביי בועל מכיר בו רבא אמר סוטה כי מתייא לברר עון קא אתיא","אלא מעתה עגלה ערופה שעבר עליה יוה\"כ וכו' אמר אביי הורג מכיר רבא אמר אמר קרא (במדבר לה, לד) ולארץ לא יכופר לדם אשר שפך בה וגו","רב פפא אמר אמר קרא (דברים כא, ח) כפר לעמך ישראל וגו ראויה כפרה זו שתכפר על יוצאי מצרים","השתא דאמרת חטא שאין מכיר בו אלא המקום יוה\"כ מכפר אימא כי מתיידע ליה בתר יוה\"כ נמי לא מייתי חטאת אמר ר' זעירא לא מצית אמרת דכתיב קרא ידיעה גבי חטאת וגבי נשיא וגבי צבור","צריכי דאי כתב קרא גבי יחיד הוה אמינא כולהון מיחיד לא אתאן דאיכא למיפרך מה ליחיד שכל קרבנו נקבה","נכתוב גבי נשיא ונייתי הנך מנשיא","יחיד מנשיא לא אתי דאיכא למיפרך מה לנשיא שכן אין בשמיעת קול תאמר ביחיד שכן ישנו בשמיעת קול","וצבור מנשיא לא אתי דאיכא למיפרך מה לנשיא שכן בקרבנו נקבה","נכתוב גבי צבור יחיד ונשיא מינה איכא למיפרך מה לצבור שכן אין חייבין אלא על העלם דבר עם שגגת מעשה","מחדא ידיעה לא אתיא תיתי חדא ידיעה מתרתי לא נכתוב ידיעה גבי יחיד ותיתי מנשיא וצבור","איכא למיפרך מה לנשיא וצבור שכן אינן בשמיעת קול תאמר ביחיד שישנו בשמיעת קול","לא נכתוב קרא ידיעה גבי צבור ותיתי מידיעה דיחיד ונשיא איכא למיפרך מה ליחיד ונשיא שכן יש בקרבן נקבה תאמר בצבור שאין בקרבן נקבה","לא נכתוב גבי נשיא ותיתי מידיעה דיחיד וצבור מאי פרכת אי משום דאינן בשמיעת הקול יחיד יוכיח דאינו בשמיעת הקול","ואי משום דיש בכל קרבנו נקבה צבור יוכיח דאין בקרבנן נקבה עד דאית להון ידיעה לא מחייב למה לי דכתיב ידיעה גבי נשיא","אם אינו ענין לגופיה דהא אתיא מיחיד וצבור תנהו ענין להיכא דמתיידע ליה בתר יום הכפורים דמייתי חטאת","אביי אמר אי דלא כתיב ידיעה גבי נשיא מיחיד וצבור לא אתי משום דאיכא למיפרך מה ליחיד וצבור שכן אין עשויין להשתנות תאמר"],[[1,"אבל","אי ידעי ביה כגון אשם ודאי שפיר נודע לו:"],[3,"ממונא","דמיחייב לגבוה וכיון דאפשר לשלם לא פטר ליה יום הכיפורים דבתשלומי ממון לא שייכא כפרה:"],[5,"אתרו ביה","דאיכא מלקות לא פטר ליה יום הכיפורים:"],[6,"אלא מעתה","כיון דבחטא שאין מכיר בו אלא המקום יוה\"כ מכפר:"],[7,"ספק יולדת שעבר עליה יום הכיפורים לא תייתי","חטאת העוף על הספק אלמה תנן במתניתין דמייתא:"],[8,"יולדת חוטאת היא","במסכת נדה בפרק המפלת (נדה דף לא:) בשעה שהיא כורעת לילד נשבעת שלא תזקק לבעלה:"],[8,"ולא לכפרא מייתא","דהא מיכפרה בשעת לידה:"],[9,"נמי תנינא","דהיינו טעמא דמתייא לאחר יוה\"כ משום דלאו לכפרה אתי:"],[10,"ספק מצורע","מפרש במסכת נזיר בפרק שני נזירים (נזיר דף ס.) דמייתי קרבן וכן נזיר שנטמא בספק. ספק מצורע כגון ספק קדם שער לבן לבהרת וטהור ספק בהרת ללבן וטמא:"],[11,"על ז' דברים","בערכין בפרק יש בערכין (ערכין דף טז.):"],[11,"גג\"ג ששל\"ץ","סימן שמותם:"],[11,"לא לכפרה","דמנגעו איכפר ליה מצער הנגע נתכפר חטאו:"],[12,"ספק נזיר","נזיר ספק נטמא ספק לא נטמא דאילו ספק נזיר טהור כגון דאמר הריני נזיר אם תלד אשתי בן ולא נודע לו אם בן אם בת מצי אתויי ואתנויי שאם לא היה נזיר עכשיו יהא נזיר לבסוף ולסוף ל' יביא קרבנו כדתנן בפרק הריני נזיר מן הגרוגרות (נזיר יג.) ר' שמעון אומר אמר אם היה בן קיימא הריני נזיר חובה ואם לאו הריני נזיר נדבה:"],[12,"לא נייתי","חטאת העוף הבא על הספק דאמרינן במסכת נזיר בפרק שני נזירים דמייתי:"],[13,"נזיר חוטא הוא","שציער עצמו מן היין במסכת תענית בפ' קמא (דף יא.):"],[13,"לאו לכפרה מייתי","דהא איכפר ליה שנתנוול בגידול שער:"],[14,"ספק סוטה","היינו סוטה סתם דספק הוא אם נטמאת אם לא נטמאת:"],[14,"לא תייתי","מנחת קנאות:"],[15,"לברר עון","להודיע אם נטמאת:"],[16,"ולארץ לא יכופר","אין לך שום כפרה אלא זו עגלה ערופה על הספק והריגת ההורג על הודאי:"],[17,"על יוצאי מצרים","דכתיב אשר פדית והרי כמה יו\"כ עברו עליהן ועדיין הן צריכין לכפרה זו אם נמצא חלל ביניהם:"],[18,"כדכתיב קרא","או הודע גבי יחיד ונשיא וצבור דלא צריכי כולהו איכא למדרש מחד מהנך או הודע דלא צריך כל אימת דמתיידע ליה ואפילו לאחר יוה\"כ:"],[19,"וקא פריך הש\"ס הני מצריך צריכי דאי כתיב גבי יחיד הוה אמינא","יחיד בעי ידיעה ודאית שכן קל הוא שכל קרבנו נקבה אבל נשיא דמייתי שעיר זכר בשאר עבירות צבור כל קרבנו זכר אימא החמירו ובספק נמי לייתי חטאת:"],[21,"מה לנשיא שכן קל שאינו בשמיעת הקול","דמלך לא מעיד ולא מעידין אותו:"],[22,"נשיא יש בקרבנו נקבה","בעבודה זרה דכתיב בעבודה זרה ואם נפש אחת תחטא בשגגה יחיד ונשיא ומשיח במשמע והקריבה עז בת שנתה לחטאת:"],[23,"","צבור אין חייבין פר העלם דבר אלא על העלם דבר שהורו להם ב\"ד שחלב מותר עם שגגת מעשה שאכלו צבור חלב על פיהן:"],[24,"לא לכתוב ידיעה ביחיד ותיתי מנשיא וצבור","הא ליכא למימר דליכא למימר למידין וחזר הדין כשאר דוכתי דכי אמרינן מה לנשיא שכן אינו בשמיעת הקול ליכא למימר צבור יוכיחו דהא נשיא וצבור אינן בשמיעת הקול:"],[26,"לא לכתוב גבי ציבור וליתי מיחיד ומנשיא","דהכא ודאי נמי אין למידין מצד השוה דכי אמרינן מה לנשיא שכן יש בקרבנו נקבה ליכא למימר יחיד יוכיח דהא שניהן יש בקרבנן נקבה:"],[26,"","הכי גרסינן דמאי פרכת דאי משום דיחיד כל קרבנו נקבה צבור יוכיח דאין בקרבנן נקבה ואי משום דאינו בשגגת מעשה יחיד יוכיח דישנו נמי בשגגת מעשה:"],[30,"מה להנך שכן אין עשויין להשתנות","ואף על גב דהך פירכא לאו קולא וחומרא היא הא אמרינן בכל הבשר (חולין קטו:) על מה הצד פרכינן כל דהו:"]],[]],[["בנשיא שעשוי להשתנות","אלא אמר אביי מהכא מכדי מצות מצות ילפי מהדדי","כיון דילפי מהדדי למה לי דכתיב שלש ידיעות גבי יחיד וגבי נשיא וגבי צבור אם אינו ענין לגופיהן דהא גמרי להן מצות מצות תנהו ענין היכא דמתיידע ליה בתר יום הכיפורים הוא דמייתי חטאת","אימא כי מתיידע ליה בתר יום כפורים הוא דמייתי חטאת משום דיוה\"כ לאו על הדין חטא קא אתי אבל אשם תלוי דעל הדין חטא קאתי אימא הכי נמי דמיכפר דכי מתיידע לבתר דקא מייתי אשם תלוי לא מייתי חטאת","אמר רבא אמר קרא (ויקרא ד, כג) או הודע אליו מכל מקום השתא דאמר כי מתיידע ליה מייתי חטאת אשם תלוי למה בא אמר ר' זירא שאם מת מת בלא עון מתקיף לה רבא מת מיתה ממרקת אלא אמר רבא להגן עליו מן הייסורים:","חטאת העוף הבא על הספק [וכו']: אמר רב וכיפר אי הכי אמאי תקבר","לפי שאינה משתמרת אימת לא משתמרת אי מעיקרא חיה הויא אי לבסוף קמנטר לה","אלא מתניתין בנודע לה דלא ילדה ובדין הוא דמותרת בהנאה ומאי תקבר מדרבנן","וכי איתמר דרב על האשה שהביאה חטאת העוף בספק אם עד שלא נמלקה נודע לה שילדה ודאי תעשה ודאי שממין שהביאה על לא הודע מביאה על הודע","אם משנמלקה נודע שילדה אמר רב מזה דמה ומוצה דמה וכפרה מותרת באכילה ר' יוחנן אמר אסורה באכילה גזירה שמא יאמרו חטאת העוף הבאה על הספק נאכלת","תני לוי כותיה דרב חטאת העוף הבאה על הספק אם משנמלקה נודע שילדה ודאי מזה דמה ומוצה דמה וכפרה מותרת באכילה","תניא כוותיה דר' יוחנן חטאת העוף הבאה על הספק אם עד שלא נמלקה נודע לה שלא ילדה תצא לחולין או תמכר לחברתה אם עד שלא נמלקה נודע לה שילדה ודאי תעשה ודאי שממין שמביאה על לא הודע מביאה על הודע","אם משנמלקה נודע שילדה אסורה אפילו בהנאה שעל הספק באה מתחלתה כפרה ספיקה והלכה לה:","\u0001מתני׳\u0002 המפריש ב' סלעים לאשם ולקח בהן שני אילים לאשם אם היה אחד מהן יפה שתי סלעים יקרב לאשמו והשני ירעה עד שיסתאב וימכר ויפלו דמיו לנדבה","לקח בהן שני אילים לחולין אחד יפה ב' סלעים ואחד יפה עשרה זוז היפה שתי סלעים יקרב לאשמו והשני למעילתו","אחד לאשם ואחד לחולין אם היה של אשם יפה שתי סלעים יקרב לאשמו והשני למעילתו ויביא עמה סלע וחומשה:","\u0001גמ׳\u0002 מאי מעילתו דקתני רישא והשני למעילתו","אילימא איל אשם למימרא דחומש בהדי איל מייתי ליה והכתיב (ויקרא ה, טז) ואת אשר חטא מן הקדש ישלם ואת חמישיתו יוסף עליו אלמא בהדי גזילו מייתי ליה","ועוד קתני סיפא אחד לאשם ואחד לחולין אם היה של אשם יפה שתי סלעים יקרב לאשמו והשני למעילתו ויביא עמה סלע וחומשה אלמא חומש בהדי גזילו מייתי ליה","אלא מעילתו מאי דאיתהני מהקדש וישנו משתי סלעים דאפרישנו לאשם ולקח בהן שני אילים לחולין דיפה שתי סלעים מקריב ליה איל אשם ויפה עשרה זוז יהיב ליה למאי דאיתהני מהקדש דהוה ליה גזילו וחומשו ומאי מעילתו גזילו","במאי אוקימתא למעילתו דרישא גזילו אימא סיפא אחד לאשם ואחד לחולין אם היה של אשם יפה שתי סלעים יקרב לאשמו והשני למעילה ויביא עמה סלע וחומשה","אלמא מעילתו איל אשם רישא קרי ליה למעילתו גזילו"],[[0,"נשיא עשוי להשתנות","דאי עבר מנשיאותו כשאר יחיד הוי:"],[1,"מצות מצות ילפי מהדדי","יחיד ונשיא וצבור דבכולהו כתיב מצות וילפי כולהו בהך גזירה שוה מהדדי במסכת הוריות (דף ח:) לדבר שחייבין על זדונו כרת וחייבין על שגגתו חטאת הילכך להא מילתא נמי לילפו מהדדי:"],[3,"לאו על הדין חטא קאתי","כלומר לא על הדין לחודיה קאתי:"],[5,"אם משנמלקה נודע לה","שלא ילדה:"],[6,"שאינה משתמרת","כיון דעל הספק באה ולא לאכילה הוה קיימא לא שמרוה יפה ונפסלה בהסח הדעת שמא נטמאה:"],[6,"אי מעיקרא","קודם מליקה חיה הוות ובעלי חיין אינן מקבלין טומאה:"],[7,"ובדין הוא דמותרת בהנאה","דחולין גמורין היא ומשום חולין בעזרה נמי ליכא למימר דלא אסרה תורה אלא שחיטה אבל מליקה לא אבל רבנן גזרו דאסור בהנאה שמא יאמרו נהנין מחטאת העוף ספק:"],[8,"וכי איתמר דרב אהא איתמר","דתנן בפרק דם שחיטה (לעיל כריתות כב:) האשה שהביאה כו' ועלה קאי רב ואמר אם משנמלקה נודע לה כן שילדה ודאי מזה ומוצה כמשפט חטאת העוף כדכתיב (ויקרא ה׳:ט׳) והזה מדם החטאת על קיר המזבח והנשאר בדם ימצה וגו'. הזאה שאוחז בראש העוף ומעלה ומוריד והדם ניתז. מיצוי שמקריב ומקיף בית מליקתו לקיר המזבח וסוחט:"],[9,"","אסורה באכילה שמא יאמרו חטאת העוף הבאה על הספק נאכלת:"],[12,"ואסורה בהנאה","כשאר חטאת העוף ספק שאסור באכילה שמא חולין היא ונבלה היא ובהנאה נמי אסורה דשמא קדש היא וקדש שאינו נאכל אסור בהנאה אחרת שהרי לכלבים לא יאכילנו:"],[12,"שעל הספק כו'","הילכך כמי שלא נודע דמי:"],[13,"מתני' שתי סלעים","זהו דין אשם דכתיב בערכך כסף שקלים בשקל הקדש לאשם:"],[13,"והשני ירעה","לפי שנקח ממעות אשם לשם אשם:"],[14,"לקח בהן שני אילים לחולין","לאכילה ומעל במעות ויצאו לחולין ויש עליו לשלם אשם של עשרה זוז לקרן וחומש של אשם ראשון ואשם בשתי סלעים לאשם מעילות אם היה אחד מהן יפה שתי סלעים ואחד מהן עשרה זוז היפה שתי סלעים יקרב לאשם מעילות והשני היפה עשרה זוז יקרב למעילתו מפרש בגמ' יקרב בשביל אשם ראשון והרי נפטר מקרן וחומש. והשתא קרי למעילתו גזילו:"],[15,"אחד לאשם ואחד לחולין","מעל בסלע אם היה של אשם יפה שתי סלעים יקרב לשמו הראשון שהרי לשמו נלקח וממעות שהופרשו לו:"],[15,"והשני","שהוא חולין יקרב למעילתו לאשם מעילתו. והשתא קרי לאיל האשם של אשם מעילות מעילתו:"],[15,"ויביא עמה סלע וחומשה","קרן שמעל בו ויפלו לנדבה שהרי ממותר אשם הראשון בא:"],[15,"יביא סלע וחומשו","מביתו שמה ששיבח אשם בשתי סלעים שבח הקדש הוא:"],[17,"גמ' אילימא איל אשם","של אשם מעילות:"],[17,"למימרא דחומש בהדי איל אשם מייתי ליה","אם הביא אשם שהוא שוה על ב' סלעים כדי חומש הקרן נפטר מן החומש והכתיב כו':"],[18,"ועוד מדקתני סיפא","היכא דמעל בסלע והשני יקרב למעילתו דע\"כ האי למעילתו איל לאשם מעילות הוא דהא קתני ויביא עמה סלע וחומש לקרן וחומש:"],[18,"אלמא חומש בהדי קרן מייתי ליה","והאי דהדר ומקשי ממתני' דלא תימא קרא אישתעי בדנהנה מקדשי בדק הבית או מהקדש עולה הילכך חומשו כי מייתי ליה בהדי איל אשם לא נפיק דחומש כי קרן בעי מהוי אבל האי דקרן גופיה אשם הוה כי מייתי חומש בהדי אשם של מעילה שפיר דמי. תא שמע מסיפא:"],[20,"אלא מאי למעילה דרישא גזילו","הוא האשם הראשון דאיתהני האי מהקדש דידיה בשתי סלעים שהפרישו לשמן וילקח בהן שני אילים לחולין דיפה שתי סלעים מקריב ליה לאיל מעילות והוא לאשמו דקתני במתני' והיפה עשרה זוז יהיב ליה למאי דאיתהני מהקדש כלומר יקריבנו לאשמו הראשון ויהיו תשלומין לקרן וחומש שמעל בהן והיינו לאשמו דקתני מתני':"],[20,"אימא סיפא כו'","על כרחיך לאשמו דסיפא הוא אשם ראשון שהרי איל זה לשמו נלקח ולמעילתו הוא אשם מעילות ולא לתשלומי הקרן דהא קתני יביא סלע וחומשו לתשלומי קרן וחומש:"]],[]],[["סיפא קרי ליה למעילתו איל אשם","רישא דהוה ליה איל רובן קרן וחומשו קרו ליה למעילתו גזילו סיפא דלא הוי איל רובן קרן וחומש קרי ליה איל אשם מעילתו ויביא עמה סלע וחומשה","בעי רב מנשיא בר גדא בכינוס חומשין מהו שיתכפר","מי אמרינן אם תימצי לומר אדם מתכפר בשבח הקדש משום דקטרח קמיה אבל הכא דלא קטרח לא מתכפר","או דלמא אם תימצי לומר אין אדם מתכפר בשבח הקדש משום דלא אפרשיה אבל הדין כינוס חומשין דאפרשיה איכא למימר מתכפר דאיבעי להו מתכפר בשבח הקדש או לא","ת\"ש המפריש שני סלעים לאשם ולקח בהן שני אילים לאשם היה אחד מהן יפה שתי סלעים יקרב לאשמו והשני ירעה עד שיסתאב וימכר ויפלו דמיו לנדבה","מאי לאו דזבן בארבע איל ושבח דשוי תמניא ושמע מינה אדם מתכפר בשבח הקדש לא הכא במאי עסקינן דאוזיל רועה גביה","ת\"ש לקח איל בסלע ופטמו והעמידו על שתים כשר ש\"מ אדם מתכפר בשבח הקדש לא פטמו שאני דהא חסר ליה תמניא","ת\"ש לקח איל בסלע והרי הוא בשתים כשר הכא נמי כשפטמו","א\"ה היינו רישא רישא דזבן בארבע ואשבחיה בארבעה אחרינא דחסר ליה תמניא סיפא דזבין איל בארבע ואשבחיה בתלתא ושוי תמניא","אי הכי אימא סיפא ישלם סלע הא חסר ליה ז' מאי ישלם תשלום דסלע","ואי ס\"ל דאין אדם מתכפר בשבח הקדש כי יהיב תשלום דסלע מאי הוי איל בן שתי סלעים בעינן וליכא לעולם קסבר אדם מתכפר בשבח הקדש","אי הכי תשלום דסלע לא יתן היינו טעמא דקיהיב תשלומין דסלע גזירה שמא יאמרו איל פחות משתי סלעים מכפר","מאי הוי עלה תא שמע בשעת הפרשה יפה סלע בשעת כפרה יפה שתי סלעים לא יצא","בעי רבי אלעזר אדם מתכפר בשבח הקדש או לא א\"ר יוחנן כמה שנים גדל זה בינינו ולא שמע הלכה זו ממני","מכלל דא\"ר יוחנן אין ועל הדא אמרה דתנן ולד תודה ותמורתה וכן המפריש תודתו ואבדה והפריש אחרת תחתיה אין טעונה לחם","ושלח ר' חנינא משמיה דר' יוחנן לא שנו אלא לאחר כפרה דולד אין טעון לחם","אבל לפני כפרה טעון לחם אלמא קסבר מתכפר בשבח הקדש","בעי ר' אלעזר בעלי חיים נדחין או לא א\"ר יוחנן הרי כמה שנים גדל זה בינינו ולא שמע הלכה זו ממני","מכלל דר' יוחנן אמרה אין דאמר ר' יוחנן בהמה של שני שותפין הקדיש חציה וחזר ולקח חציה והקדישה קדושה ואינה קריבה ועושה תמורה ותמורתה כיוצא בה","ש\"מ תלת ש\"מ בעלי חיים נדחין וש\"מ קדושת דמים מדחה וש\"מ יש דיחוי בדמים","בעי ר\"א הוזלו טלאים בעולם מהו מי אמרינן (דברים יב, יא) מבחר נדריכם בעינן והא איכא או דילמא (ויקרא ה, טו) כסף שקלים בעינן וליכא","א\"ר יוחנן כמה שנים גדלנו בבית המדרש ולא שמענו הלכה זו ולא והאמר ר' יוחנן אמר ר' שמעון בן יוחאי מפני מה לא נתנה תורה קצבה במחוסרי כפרה שמא יוזלו טלאים ואין להן תקנה לאכול בקדשים אימא לא לימדנו הלכה זו","והא רבי זירא בר אדא מהדר תלמודיה כל תלתין יומין קמיה אימא לא נתבקשה הלכה זו ממנו בבית המדרש","גופא אמר רבי יוחנן משום רשב\"י מפני מה לא נתנה קצבה במחוסרי כפרה שמא יוזלו טלאים ואין להם תקנה לאכול בקדשים","מתקיף לה אביי אלא מעתה חטאת חלב ינתן לה קצבה דלכפרה אתיא ולאו לאישתרויי באכילת קדשים הוא מתקיף לה רבא אלא מעתה אשם נזיר להוי ליה קצבה דלבטלה הוא דאתי דאמר רבי יוחנן משום רבי שמעון בן יוחאי אין לך דבר שהוא בא לבטלה אלא אשם נזיר בלבד קשיא:"],[[0,"רישא קרי גזילו למעילתו סיפא קרי לאיל אשם מעילתו","בתמיה:"],[1,"ומשני אין רישא דהוה איל רוב כו'","על כרחיך תנא דמתני' הוצרך לחלק בשמותיהן של שני אשמות הללו לפי שהאחד בא לחובת אשמו הראשון והשני לאשם מעילות לפיכך קרא לאחד מהן אשמו ולאחד מהן מעילתו הילכך רישא דהוה איל רובן קרן וחומשו קרא את הקרב לאשמו מעילתו כלומר קרן שמעל בו וחומשו להודיע דמה שהוא מביא אשם בעשרה זוז משום מעילה וחומשה הוא ואת הקרב לאשם מעילות קרא אשמו סיפא דלא הוי איל רובן קרן וחומש דהאיל יפה שתי סלעים והקרן והחומש אינו עולה אלא סלע וחומש ואין האיל קרב בשביל תשלומי גזילתו אלא בשביל איל אשם קורהו מעילתו על שם אשם מעילות:"],[2,"בכינוס חומשין","כגון מעל בב' סלעים דאשם כמה פעמים עד שיעלו החומשים לב' סלעים מהו שיקח מהן אשם למעילתו. בכנוס חומשין כגון הפריש ב' סלעים לאשם ומעל בקרן ד' פעמים שיעלו החומשין לשתי סלעים מהו שיתכפר בחומשין לבדו שיקנה בהן איל והקרן יפול לנדבה דהא מותר הוא מרבי:"],[3,"שבח הקדש","כגון לקח איל בסלע והוקרו טלאים ועמדו על שתים:"],[4,"דלא אפרשיה","בשעת הפרשה לא היה שוה אלא סלע אבל בכינוס חומשין הא אפרשיה זה שהפרישו לשם אשם כל שעה ומכח אשם באו אימא מתכפר:"],[6,"ושמע מינה אדם מתכפר","מדקתני יקרב לאשמו:"],[7,"דהא חסר ליה תמניא זוזי","שהוציאו בפיטומו סלע:"],[8,"ת\"ש","מסיפא דהא ברייתא דפיטום:"],[9,"ואשבחיה בתלתא ושוה תמניא","ולקמן פריך סוף סוף שמע מינה דאדם מתכפר באותו זוז שהשביח ההקדש בלא חסרונו:"],[10,"תשלומי דסלע","זוז אחד להשלים סלע שני. ואי קשיא לוקמה כגון דאוזיל גביה רועה הא ליכא למימר מדקתני ישלם סלע לגזבר מביתו ואי דאוזיל גביה רועה אמאי ישלם הא שוה בשעת הפרשה ב' סלעים ואי דיהביה ניהליה בחנם מאי איכפת לן הא לא בעינן אלא שוה שתי סלעים והרי שוה שתי סלעים והקדש לא השביח בו כלום:"],[11,"איל","שקנו בשתי סלעים ליכא:"],[13,"מאי הוי עלה","דהאי שינוייא דחיקא הוא דאי אדם מתכפר בשבח הקדש תשלום סלע לא הוי:"],[13,"תא שמע","דמתכפר:"],[13,"","ה\"ג בתוספתא בשעת הפרשה יפה סלע ובשעת כפרה יפה שתי סלעים יצא:"],[14,"בעי כו'","רבי אלעזר לא שמיעא ליה הך ברייתא:"],[14,"ולא שמע הלכה זו ממני","בתמיה:"],[15,"ועל הדא אמרה","במסכת מנחות בפרק התודה (מנחות דף עט:):"],[15,"אינן טעונות לחם","התם מפרש טעמיה:"],[16,"לא שנו","דולד אינו טעון לחם אלא לאחר כפרה שכבר הקריב את אמו ויצא ידי נדרו אבל לפני כפרה יקריב זה במקום אמו לחובת נדרו וטעון לחם. אלמא אדם מתכפר בולד דהיינו שבח הקדש:"],[18,"בעלי חיים נדחין","מעל גבי המזבח או לא כגון שעירי יום הכיפורים ומת אחד מהן מהו שיקריב חבירו ויביא אחר עמו מי אמרינן נדחה זה במיתת חבירו או לא. ואי קשיא לפשוט ליה מדקי\"ל (תמורה דף כא:) חטאת שכיפרו בעליה מתה אלמא נדחין הלכה למשה מסיני הוא ואין למידין הימנה:"],[19,"ואינה קריבה","הואיל ומתחלה נדחית שהיתה חציה חולין כשהקדישה לא היתה ראויה לכך:"],[20,"ה\"ג שמע מינה תלת שמע מינה בעלי חיים נדחין ושמע מינה דחוי מעיקרו הוי דחוי וש\"מ יש דחוי בדמים","ותו לא מידי שמע מינה קדושת דמים מדחה בהמה שאינה ראויה ליקרב והקדישה לדמים כיון דאמר תסתאב ונוהג בה מנהג דחוי דשוב אינה חוזרת ונראה דלא תימא אין תורת דיחוי נוהגת אלא בקדושת הגוף שהרי זו כשהוקדשה חציה לא הקדישה אלא לדמיה וקאמר אינה קריבה. קדושת דמים מדחה ויש דחוי בדמים חדא מילתא היא אלא שנשתנה לשון הגירסא:"],[21,"הוזלו טלאים בעולם","ואינו מוצא אלא בפחות משני סלעים:"],[22,"במחוסרי כפרה","כגון זב וזבה ויולדת ומצורע שכפרתן מעכבתן מן הקדשים ואין להם תקנה. אלמא היכא דנתנה תורה קצבה אין לו תקנה עד שיביא באותה קצבה:"],[22,"לא לימדנו","לאחרים:"]],[]],[["\u0001מתני׳\u0002 המפריש חטאתו ומת לא יביאנו בנו תחתיו לא יביאנו מחטא אל חטא אפי' הפריש על חלב שאכל אמש לא יביאנה על חלב שאכל היום שנאמר (ויקרא ד, כג) קרבנו על חטאתו עד שיהא קרבנו לשם חטאתו:","\u0001גמ׳\u0002 מנא ה\"מ דת\"ר קרבנו בקרבנו הוא יוצא ואינו יוצא בקרבן אביו","יכול לא יצא בקרבן אביו בבהמה שהפריש אביו מן הקלה על החמורה או מן החמורה על הקלה אבל יוצא בקרבן שהפריש אביו מן הקלה על הקלה או מן החמורה על החמורה ת\"ל קרבנו בקרבנו הוא יוצא ואינו יוצא בקרבנו של אביו","יכול לא יצא בקרבן אביו בבהמה שהפריש אפילו מן הקלה על הקלה או מן החמורה על החמורה שהרי אין מגלח נזירותו על בהמה שהפריש אביו","אבל יוצא במעות שהפריש אביו אפילו מן הקלה על החמורה או מן החמורה על הקלה שהרי אדם מגלח נזירותיו על מעות שהפריש אביו בזמן שהן סתומים ולא בזמן שהן מפורשין תלמוד לומר קרבנו בקרבנו הוא יוצא ואין יוצא בקרבן אביו","יכול לא יצא אפי' במעות שהפריש אפילו מן הקלה על הקלה או מן החמורה על החמורה אבל יוצא בקרבן שהפריש לעצמו אפילו מן החמורה על הקלה או מן הקלה על החמורה ת\"ל קרבנו על חטאתו עד שיהא לשם חטאת","יכול לא יצא בקרבן עצמו בבהמה שהפריש לעצמו אפילו מן הקלה על הקלה או מן החמורה על החמורה שכן אם הפריש בהמה על החלב והביאה על הדם על הדם והביאה על החלב שהרי לא מעל ולא כיפר","אבל יוצא במעות שהפריש לעצמו מן הקלה על הקלה ומן החמורה על החמורה או מן החמורה על הקלה ומן הקלה על החמורה","שכן אם הפריש לעצמו מעות על החלב והביאן על הדם על הדם והביאן על החלב שהרי מעל וכיפר ת\"ל קרבנו על חטאתו עד שיהא קרבנו לשם חטאו","מאי לא מעל ולא כיפר תרגמא רב שמואל בר שימי קמיה דרב פפא ה\"ק כיון דלא מצי מעיל כפורי נמי לא מכפר הואיל וכך לא מצי משני","אבל מעות כיון דאי משני מעיל ומייתי קרבן מעילה אימא בתחלה נמי מייתי קמ\"ל:","\u0001מתני׳\u0002 מביאין מהקדש כשבה שעירה מהקדש שעירה כשבה ומהקדש כשבה ושעירה תורין ובני יונה ומהקדש תורין ובני יונה עשירית האיפה","כיצד הפריש לכשבה או לשעירה העני יביא עוף העני יביא עשירית האיפה הפריש לעשירית האיפה העשיר יביא עוף העשיר יביא כשבה ושעירה:","\u0001גמ׳\u0002 מנה\"מ דת\"ר (ויקרא ה, ו) מחטאתו מחטאתו על חטאתו מה תלמוד לומר","מנין אתה אומר שמביאין מהקדש כשבה שעירה ומהקדש שעירה כשבה ומהקדש כשבה ושעירה תורים ובני יונה ומהקדש תורין ובני יונה עשירית האיפה","כיצד הפריש לכשבה ולשעירה והעני יביא עוף העני יביא עשירית האיפה הפריש עשירית האיפה והעשיר יביא עוף העשיר יביא כשבה או שעירה","הפריש כשבה או שעירה ונסתאבו יביא בדמיהן עוף הפריש עוף ונסתאב לא יביא בדמיו עשירית האיפה שאין לעוף פדיון","לכן נאמר מחטאתו על חטאתו","ואיצטריך למכתב מחטאתו גבי כשבה או שעירה ואיצטריך למכתב גבי עוף דאי כתיב קרא גבי הקדש כשבה או שעירה ה\"א הפריש כשבה כי מיעני מהלין מעות נחלינון על עוף דנייתי עוף דכשבה ועוף תרוייהו מיני דמים נינהו","אבל עשירית האיפה דלאו מיני דדמים נינהו אי לא כתיב קרא מחטאתו גבי עוף ה\"א כי מפריש מעות לקינו ומיעני לא מייתי עשירית האיפה דלאו מיני דדמים הוא אלא מייתי עשירית האיפה מן ביתיה והלין מעות דאפריש יפלו לנדבה אהכי הדר כתיב קרא מחטאתו גבי עוף למימרא דמהקדש דעוף נמי מייתי עשירית האיפה","וה\"ק כי מפריש לעשירית האיפה ואדמייתי העשיר נוסיף עליהון ונייתי עוף העשיר נוסיף עליהון ונייתי כשבה או שעירה","ומ\"ט כתיב על חטאתו גבי עשירית האיפה דאי כתיב על חטאתו גבי עוף ה\"א כי מפריש מעות לקינו והעשיר הוא דמוסיף עליהון ומייתי כשבה או שעירה דתרוייהו מיני דמים נינהו","אבל הפריש מעות לעשירית האיפה והעשיר הלין דמפריש אי לא העשיר טובא נייתי עוף ואם העשיר טובא נייתי כשבה או שעירה והלין מעות דאפריש יפלו לנדבה אהכי כתיב קרא בהדין חטאת בעשירות ודלות מחטאתו וגבי דלי דלות על חטאתו למדרש כדאמרינן","אמר ר' אלעזר אמר רבי אושעיא מטמא מקדש עשיר שהפריש קן"],[[0,"מתני' לא יביאנו בנו אחריו","על חיוב שלו ואין צריך לומר על חטא האב דאין כפרה לאחר מיתה:"],[2,"גמ' מן הקלה על החמורה","לא יצא זה מידי עבירה קלה כגון נדה וחלב שאין בהן מיתת בית דין:"],[2,"בבהמה שהפריש אביו","על עבירה חמורה כגון חלול שבת:"],[2,"","תלתא זימני כתיב גבי חטאת קרבנו חד בנשיא ותרין ביחיד:"],[3,"אינו מגלח נזירות על בהמת אביו","שהפריש אביו לנזירתו:"],[4,"בזמן שהן סתומין","שלא פירש אלו לקנות חטאת ואלו לקנות עולה והכי מפרש בפרק מי שאמר הריני נזיר ושמע חבירו (נזיר כז:):"],[6,"לא מעל ולא כיפר","מפרש לקמיה:"],[8,"הרי זה מעל","שהוציא מעות הקדש לחולין דשינו לדבר אחר:"],[9,"כיון דלא מצי מעיל","דאינו יכול להוציא לחולין ולא לשנותה אף דמשני לה בקדושתה קיימא דהקדש שאינו בעל מום לא יצא לעולם לחולין:"],[10,"אבל מעות","דשייכא בהו מעילה ונפקי לחולין וכפר אי עבר אימא בתחלה נייתי:"],[10,"קמ\"ל","קרבנו על חטאתו:"],[11,"מתני' מביאין מהקדש כשבה שעירה","שאם הפריש מעות לקנות כשבה (או שעירה) לחטאתו אם רצה יקח מהן שעירה:"],[12,"הפריש כשבה או שעירה","כלומר מעות לכשבה או לשעירה העני יביא בהן עוף והשאר חולין:"],[12,"העשיר יביא כשבה","ויוסיף עוד מביתו על דמי עשירית האיפה:"],[16,"גמ' ונסתאבו אם רצה יביא בדמיו עוף","כגון אם העני:"],[16,"שאין לעוף פדיון","שפדיון לא נאמר אלא בבהמה:"],[17,"מחטאתו על חטאתו","בקרבן עולה ויורד כתיב גבי כשבה ושעירה (ויקרא ה) מחטאתו דמשמע מקצת חטאתו כלומר אם העני יביא עוף ממקצת דמים הללו וגבי עוף כתיב (שם) מחטאתו דמשמע דאם העני יביא במקצת דמי עוף עשירית האיפה וגבי עשירית האיפה כתיב (שם) על חטאתו דמשמע דאם העשיר יוסיף על הדמים הללו ויביא עוף או אם העשיר יותר יביא כשבה או שעירה:"],[18,"הפריש כשבה","כלומר מעות לקנות כשבה:"],[19,"אהכי הדר כתיב מחטאתו גבי עוף","לאשמועינן דממקצת דמי עוף יביא כפרתו כגון עשירית האיפה:"],[21,"ומאי טעמא כתיב על חטאתו גבי עשירית האיפה","ולא כתביה גבי עוף:"],[21,"דאי כתיב על חטאתו גבי עוף","ולא כתביה גבי עשירית האיפה:"],[21,"הוה אמינא כו' אבל הפריש מעות לעשירית האיפה והעשיר אימא אילו העשיר (טובא)","יביא עוף כמשפטו מביתו ואם העשיר טובא יביא כשבה או שעירה מביתו והנך מעות דעשירית האיפה יפלו לנדבת ציבור אהכי כתיב בעשירות כשבה או שעירה:"],[22,"ובדלות","העוף מחטאתו לאשמועינן דאם העני עוד יביא עשירית האיפה במקצת הדמים:"],[22,"גבי דלי דלות","עשירית האיפה על חטאתו למידרש דמוסיף עלייהו וליתי עוף אע\"ג דמין דמים הוא ולא דמי לעשירית האיפה אפי' הכי יביא עוף ואם עוד העשיר יביא כשבה:"],[23,"שהפריש קן","תורין:"]],[]],[["לכבשתו והעני הואיל ונדחה ידחה","אמר רב הונא בריה דרב יהושע שמע מינה תלת שמע מינה בעלי חיים נדחים וקדושת דמים נדחה","ודחוי מעיקרא הוי דחוי","מתיב רב עוקבא בר חמא המפריש נקבה לפסחו קודם הפסח תרעה עד שתסתאב ותמכר ויביא בדמיה פסח ילדה זכר ירעה עד שיסתאב וימכר ויביא בדמיו פסח","ר\"ש אומר הוא עצמו יקרב פסח ש\"מ בעלי חיים אינם נדחים","אמרי דבי רבי אושעיא כי אמרינן לרבנן דר\"ש ס\"ל בעלי חיים אינן נדחין","והגרלה אינה מעכבת דתניא מת אחד מהן מביא חבירו שלא בהגרלה דברי ר\"ש","אלמא קסבר בעלי חיים אינן נידחין והגרלה אינה מעכבת","אמר רב חסדא אין הקינין מתפרשות אלא אי בלקיחת בעלים אי בעשיית כהן","אמר רב שימי בר אשי מאי טעמא דרב חסדא דכתיב (ויקרא יב, ח) ולקחה שתי תורים וגו' (ויקרא טו, ל) ועשה הכהן וגו' או בלקיחת בעלים או בעשיית כהן","מיתיבי (ויקרא טז, ט) ועשהו חטאת הגורל עושהו חטאת ואין השם עושהו חטאת ואין כהן עושה חטאת","שיכול והלא דין הוא ומה במקום שלא קידש הגורל קידש השם מקום שיקדש הגורל אינו דין שיקדש השם","ת\"ל ועשהו חטאת הגורל עושהו חטאת ואין השם עושהו חטאת","קתני שם דומיא דגורל מה גורל לאו בלקיחה ולאו בעשייה אף השם נמי לאו בלקיחה ולאו בעשייה","אמר רב ה\"ק ומה במקום שלא קידש הגורל בלקיחת בעלים ובעשיית הכהן קידש השם אי בלקיחת בעלים אי בעשיית כהן כאן שיקדש הגורל שלא בלקיחה ושלא בעשייה אינו דין שיקדש השם אי בלקיחה אי בעשייה","ת\"ל ועשהו חטאת הגורל עושהו חטאת ואין השם עושהו חטאת","מיתיבי מטמא מקדש עני שהפריש מעות לקינו והעשיר","אמר אלו לחטאתי ואלו לעולתי מוסיף ומביא חובתו מדמי חטאתו ואין מוסיף ומביא מדמי עולתו","והא הכא דליכא לא לקיחה ולא עשייה וקתני מביא חובתו מדמי חטאתו ולא מדמי עולתו","א\"ר ששת ותסברא מתניתא מתקנתא היא דקתני והעשיר והא\"ר אלעזר א\"ר אושעיא מטמא מקדש עשיר שהביא קרבן עני לא יצא","אלא מאי אית לך למימר שכבר אמר משעת ענייתו ה\"נ שכבר אמר משעת הפרשתו","ולר' חגא א\"ר אושעיא דאמר יצא מאי איכא למימר תני ואח\"כ לקח ואמר","מיתיבי מצורע עני שהביא קרבן עשיר יצא עשיר שהביא קרבן עני לא יצא תיובתא דר' חגא א\"ר אושעיא","אמר לך שאני גבי מצורע דמיעט רחמנא (ויקרא יד, ב) זאת","אי הכי אפילו מצורע עני נמי שהביא קרבן עשיר לא יצא לאיי הא אהדריה קרא תורת והתניא תורת לרבות מצורע עני שהביא קרבן עשיר יצא יכול אפילו עשיר שהביא קרבן עני שיצא תלמוד לומר זאת","ולילף מיניה אמר קרא (ויקרא יד, כא) ואם דל הוא ואין ידו משגת מצורע הוא דעשיר שהביא קרבן עני הוא דלא יצא אבל מטמא מקדש עשיר שהביא קרבן עני יצא:","\u0001מתני׳\u0002 ר\"ש אומר כבשים קודמין את העזים בכל מקום יכול מפני שהן מובחרים מהם ת\"ל (ויקרא ד, לב) ואם כבש יביא קרבנו לחטאת מלמד ששניהם שקולין","תורין קודמין לבני יונה בכל מקום יכול מפני שהן מובחרים מהן תלמוד לומר ((ויקרא יב, ו) תור ובני) יונה או תור לחטאת מלמד ששניהם שקולין","האב קודם לאם בכל מקום יכול מפני שכיבוד האב קודם על כיבוד האם ת\"ל (ויקרא יט, ג) איש אמו ואביו תיראו מלמד ששניהם שקולין אבל אמרו חכמים האב קודם לאם בכל מקום מפני שהוא ואמו חייבין בכבוד אביו","וכן בתלמוד תורה אם זכה הבן לפני הרב הרב קודם את האב בכל מקום מפני שהוא ואביו חייבין בכבוד רבו:","\u0001גמ׳\u0002 ת\"ר ד' צווחות צווחה עזרה צווחה אחת הוציאו מיכן בני עלי חפני ופנחס שטימאו את ההיכל","צווחה שניה פתחו שערים ויכנס יוחנן בן נדבאי תלמידו של פינקאי וימלא כרסו מקדשי שמים אמרו על בן נדבאי שהיה אוכל ארבע סאה גוזלות"],[[0,"לכבשתו","כלומר במקום כבשתו שרצה להקריב קרבן עני:"],[0,"והעני הואיל ונדחה","שבשעה שהפרישו לא היה ראוי להקריבו דר' אושעיא לטעמיה דאמר לקמן מטמא מקדש עשיר והביא קרבן עני לא יצא:"],[0,"ידחה","לעולם:"],[1,"קדושת דמים מדחה","משהוקדש בתחלה לדמים כמו זה שתחלתו לא קדש אלא לדמיו דהא עשיר הוה מדחתו קדושת דמים לעולם מקדושת מזבח. וא\"ת הלא אין פדיון דמים לעוף ה\"מ היכא דנראה להקריב בשעת הפרשה כגון אם הפרישו בעניות ונסתאב אבל זה לא חלה עליו קדושת מזבח מעולם:"],[2,"וש\"מ דיחוי מעיקרא","דלא נראה מעולם דלא חל עליו קדושת מזבח מעולם ונדחה הוי דיחוי לעולם וכ\"ש נראה ונדחה פשיטא לן בכל דוכתא דשוב אינו חוזר ונראה:"],[3,"קודם לפסח","כדי נסבא:"],[3,"ילדה","אפילו זכר ירעה דמכח קדושה דחויה בא:"],[4,"שמע מינה","מדר\"ש:"],[6,"מת אחד מהן","משעירי יוה\"כ מביא חבירו מן השוק שלא בהגרלה ויקרב זה הנותר אם של שם הוא דאין בעלי חיים נדחין אע\"ג דאבד בן גילו ונדחה זה חוזר ונראה ואין דיחוי אצל בעלי חיים:"],[8,"אין הקינין מתפרשות","אי זה לעולה ואי זה לחטאת:"],[8,"אלא או בלקיחת בעלים","אם לקח זה לשם עולה וזה לשם חטאת אין הכהן יכול לשנותה בשעת עשיית קרבן דקבעתה השם:"],[8,"או בעשיית כהן","שאם לא הפרישוה הבעלים בשעת לקיחה יכול הכהן לעשות איזה שירצה עולה וחטאת ואף על גב דהפרישוה בין לקיחה לעשייה לא קבעו השם ויכול כהן לשנותן ולעשות את החטאת עולה:"],[9,"ולקחה שתי תורים וגו'","אחד לעולה ואחד לחטאת וגבי עשייה נמי כתיב ועשה הכהן את האחד וגו':"],[10,"ואין השם עושהו חטאת","שאם לא הגריל אלא אמר זה לשם וזה לעזאזל לא קבע עליהן השם ויכול להחליף:"],[11,"במקום שלא קדש הגורל","בכל הקרבנות:"],[13,"אף השם נמי","שקדש השם בשאר הקרבנות אף על גב דלאו שעת לקיחה ועשייה היא וקתני קדש השם סתמא ואפי' קינין שקדש השם:"],[14,"אי בלקיחה אי בעשייה","כגון גבי קינין:"],[17,"ואמר","אחר שהעשיר אלו לחטאת ואלו לעולה וטעה שהואיל והעשיר חייב להביא חטאת בדמיו מוסיף מעות מביתו על דמי חטאת ומביא חובתו בהמה ודמי עולה ילכו לנדבה ואינו מוסיף ומביא חובתו מדמי עולתו דקבע שם עולה על המעות ואינו יכול לשנותן לחטאת. והא הכא כשהפריש המעות לא לקיחה ולא עשייה היה וקתני דקבע עליהן השם:"],[19,"לא יצא","וכיון דלא יצא היכי מצי קבע והא העשיר ולא היה ראוי לקרבן עני:"],[20,"אלא מאי אית לך למימר שכבר אמר","אלו לחטאת ואלו לעולה קודם שהפריש והך מתניתא משבשתא היא דתני העני והעשיר ואמר אלו לחטאת:"],[20,"הכא נמי וכבר אמר משעת הפרשה","שבשעת הפרשה אמר אלו לחטאת ואלו לעולה דה\"ל בשעת לקיחה אבל הקדישן סתם שוב אין השם קובעו עד שעת לקיחה או עד שעת עשייה:"],[21,"ולר' חגא דאמר יצא","מטמא מקדש עשיר בקרבן עני והך מתניתא מתרצתא היא ושפיר קבע לאחר שהעשיר וליכא לתרוצי וכבר אמר:"],[21,"מאי איכא למימר","הדרא קושיין לדוכתיה דלאו שעת לקיחה ועשייה הוא וקבע:"],[23,"זאת","תהיה תורת המצורע:"],[24,"תורת","משמע תורה אחת לכולן ומאחר שאחד מרבה ואחד ממעט מסתמא דעני יוצא בקרבן עשיר דמעלין בקודש ולא עשיר בקרבן עני דאין מורידין:"],[24,"והתניא","בניחותא:"],[25,"ולילף מיניה","דמה מצורע עשיר אינו יוצא בקרבן עני אף מטמא מקדש עשיר נמי לא יצא בקרבן עני:"],[25,"הוא","משמע הוא ולא אחר:"],[26,"מתני' כבשים קודמין לעזים","דבכל דוכתא כתיב מן הכבשים והדר מן העזים תקחו וכן או לשה בכבשים או בעזים:"],[26,"יכול","האומר הרי עלי עולה ויש לו כבש ועז יביא כבש:"],[26,"","ה\"ג \u0003ת\"ל ואם כבש יביא קרבנו לחטאת\u0004 ולא גרסינן\u0003 אם עז\u0004:"],[26,"ת\"ל ואם כבש יביא וגו'","ולעיל מיניה כתיב והביא את קרבנו שעירת עזים כאן הקדים עז לכבש ובחטאת יחיד כתיב. אלמא איזה שירצה יקריב:"],[27,"תורין קודמין לבני יונה","דברוב מקומות כתיב ברישא תורין והדר בני יונה:"]],[]],[["בקינוח סעודה אמרו כל ימיו לא היה נותר בעזרה","צווחה שלישית שאו שערים ראשיכם ויכנס אלישמע בן פיכאי תלמידו של פנחס וישמש בכהונה גדולה","צווחה רביעית פתחו שערים והוציאו יששכר איש כפר ברקאי שמכבד עצמו ומבזה קדשי שמים מאי הוי עביד הוה כריך שיראי על ידיה והוה עביד עבודה","מאי סליקא ליה ינאי מלכא ומלכתא הוו יתבין מלכא אמר גדיא יאי ומלכתא אמרה אימרא יאי אמרו נשייליה ליששכר איש כפר ברקאי דכהן גדול הוא וקים ליה קדירה","שיילוהו א\"ל אי גדיא יאי ייסק לתמידא בהדי דאמר אחוי בידיה אמר להון מלכא הואיל ואחוי בידיה קוצו לידיה דימינא יהיב שוחדא קציוה לידיה שמאלא שמע מלכא אמר ליקצו נמי לידיה דימינא אמר רב יוסף בריך רחמנא דשקליה ליששכר איש כפר ברקאי למטרפסיה","אמר רב אשי ולא הוה תני ליה דתנן כבשים קודמין לעזים בכל מקום יכול מפני שמובחרין ת\"ל (ויקרא ד, לב) ואם כבש מלמד ששניהן שקולין כאחת","רבינא אמר אפילו מקרא נמי לא קרא דכתיב (ויקרא ג, ז\\יב) אם כבש אם עז:","א\"ר אלעזר א\"ר חנינא תלמידי חכמים מרבים שלום בעולם שנאמר (ישעיהו נד, יג) וכל בניך למודי ה' ורב שלום בניך:","\u0001הדרן עלך המביא אשם וסליקא לה מסכת כריתות\u0002"],[[0,"בקינוח סעודה","לאחר אכילתו:"],[2,"כריך ידיה בשיראי","כדי שלא ילכלך ידיו בבשר ובדם:"],[4,"אחוי בידיה","בלשון גסות וליצנות ומרד במלכות:"],[4,"למטרפסיה","לגמולו. לישנא אחרינא למלקותו:"],[5,"לא תנא","לא שנה משנה:"],[5,"ואם כבש","היינו קרא דמתני' דקדריש מיניה ר\"ש ששניהם שקולים דכתיב לעיל מיניה והביא (את) קרבנו שעירת עזים:"]],[]]]};
